/** Tests for {@link HadoopFsFactory#create(URI)}. */
class HadoopFsFactoryCreateTests {

    private static final String TEST_SCHEME = "hadoop-fs-factory-test";

    private HadoopFsFactory factory;

    @BeforeEach
    void setUp() {
        RecordingFileSystem.reset();
        factory = new HadoopFsFactory();
    }

    @Test
    void createRejectsNullUri() {
        assertThatThrownBy(() -> factory.create(null))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("fsUri");
    }

    @Test
    void createRejectsUriWithoutScheme() {
        assertThatThrownBy(() -> factory.create(URI.create("relative/path")))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("file system has null scheme");
    }

    @Test
    void createWrapsAndInitializesHadoopFileSystem() throws Exception {
        final Configuration flinkConfig = configureScheme(RecordingFileSystem.class);
        flinkConfig.setString("flink.hadoop.test-custom-property", "test-custom-value");
        factory.configure(flinkConfig);

        final URI fsUri = URI.create(TEST_SCHEME + "://namenode:8020/data");
        final FileSystem fs = factory.create(fsUri);

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(((HadoopFileSystem) fs).getHadoopFileSystem())
                .isSameAs(RecordingFileSystem.lastInstance);
        assertThat(RecordingFileSystem.initializationCount).isEqualTo(1);
        assertThat(RecordingFileSystem.initializedUri).isEqualTo(fsUri);
        assertThat(RecordingFileSystem.initializationConfig.get("test-custom-property"))
                .isEqualTo("test-custom-value");
    }

    @Test
    void createUsesConfiguredDefaultAuthorityWhenUriHasNoAuthority() throws Exception {
        final Configuration flinkConfig = configureScheme(RecordingFileSystem.class);
        final URI configuredDefault = URI.create(TEST_SCHEME + "://default-namenode:9000/base");
        flinkConfig.setString("flink.hadoop.fs.defaultFS", configuredDefault.toString());
        factory.configure(flinkConfig);

        final URI fsUri = URI.create(TEST_SCHEME + ":/relative/path");
        assertThat(fsUri.getAuthority()).isNull();

        final FileSystem fs = factory.create(fsUri);

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(RecordingFileSystem.initializedUri).isEqualTo(configuredDefault);
    }

    @Test
    void createFallsBackToDeprecatedDefaultNameWhenDefaultFsIsAbsent() throws Exception {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        final URI configuredDefault = URI.create(TEST_SCHEME + "://legacy-namenode:8020/base");
        hadoopConfig.set("fs.default.name", configuredDefault.toString());
        setHadoopConfiguration(factory, hadoopConfig);

        final FileSystem fs = factory.create(URI.create(TEST_SCHEME + ":/relative/path"));

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(RecordingFileSystem.initializedUri).isEqualTo(configuredDefault);
    }

    @Test
    void createFailsWhenDefaultAuthorityIsMissing() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        setHadoopConfiguration(factory, hadoopConfig);

        final URI fsUri = URI.create(TEST_SCHEME + ":/relative/path");
        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(IOException.class)
                .hasMessageContaining(fsUri.toString())
                .hasMessageContaining("did not describe the authority")
                .hasMessageContaining(
                        "Hadoop configuration did not contain an entry for the default file system ('fs.defaultFS')");
        assertThat(RecordingFileSystem.initializationCount).isZero();
    }

    @Test
    void createFailsWhenConfiguredDefaultAuthorityIsInvalidUri() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        final String invalidDefault = "not a valid URI";
        hadoopConfig.set("fs.defaultFS", invalidDefault);
        setHadoopConfiguration(factory, hadoopConfig);

        assertThatThrownBy(() -> factory.create(URI.create(TEST_SCHEME + ":/relative/path")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("The configuration contains an invalid file system default name")
                .hasMessageContaining(invalidDefault);
        assertThat(RecordingFileSystem.initializationCount).isZero();
    }

    @Test
    void createFailsWhenConfiguredDefaultAuthorityHasNoAuthorityComponent() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        final String invalidDefault = TEST_SCHEME + ":/without-authority";
        hadoopConfig.set("fs.defaultFS", invalidDefault);
        setHadoopConfiguration(factory, hadoopConfig);

        assertThatThrownBy(() -> factory.create(URI.create(TEST_SCHEME + ":/relative/path")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("contains no valid authority component");
        assertThat(RecordingFileSystem.initializationCount).isZero();
    }

    @Test
    void createWrapsUnsupportedHadoopScheme() {
        final URI fsUri = URI.create("definitely-unsupported-hadoop-scheme://host/path");

        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("does not support scheme")
                .hasMessageContaining(fsUri.getScheme())
                .hasCauseInstanceOf(IOException.class);
    }

    @Test
    void createTranslatesUnknownHostDuringInitialization() {
        factory.configure(configureScheme(UnknownHostFileSystem.class));

        final URI fsUri = URI.create(TEST_SCHEME + "://unresolvable-host:1234/path");
        assertThatThrownBy(() -> factory.create(fsUri))
