    @Test
    void createWrapsReflectiveInstantiationFailure() {
        factory.configure(configureScheme(PrivateConstructorFileSystem.class));

        final URI fsUri = URI.create(TEST_SCHEME + "://namenode:8020/path");
        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("Cannot support file system for '" + TEST_SCHEME + "' via Hadoop")
                .hasCauseInstanceOf(IllegalAccessException.class);
    }

    @Test
    void createAppliesConfiguredConnectionLimits() throws Exception {
        final Configuration flinkConfig = configureScheme(RecordingFileSystem.class);
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.total", "7");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.input", "3");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.output", "5");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.timeout", "1000");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.stream-timeout", "2000");
        factory.configure(flinkConfig);

        final FileSystem fs = factory.create(URI.create(TEST_SCHEME + "://namenode:8020/path"));

        assertThat(fs).isInstanceOf(LimitedConnectionsFileSystem.class);
        final LimitedConnectionsFileSystem limitedFs = (LimitedConnectionsFileSystem) fs;
        assertThat(limitedFs.getMaxNumOpenStreamsTotal()).isEqualTo(7);
        assertThat(limitedFs.getMaxNumOpenInputStreams()).isEqualTo(3);
        assertThat(limitedFs.getMaxNumOpenOutputStreams()).isEqualTo(5);
        assertThat(limitedFs.getStreamOpenTimeout()).isEqualTo(1000L);
        assertThat(limitedFs.getStreamInactivityTimeout()).isEqualTo(2000L);
        assertThat(RecordingFileSystem.initializationCount).isEqualTo(1);
    }

    @Test
    void createDoesNotApplyConnectionLimitsWhenNoneConfigured() throws Exception {
        factory.configure(configureScheme(RecordingFileSystem.class));

        final FileSystem fs = factory.create(URI.create(TEST_SCHEME + "://namenode:8020/path"));

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(fs).isNotInstanceOf(LimitedConnectionsFileSystem.class);
    }

    private static Configuration configureScheme(
            Class<? extends org.apache.hadoop.fs.FileSystem> fsClass) {
        final Configuration configuration = new Configuration();
        configuration.setString("flink.hadoop.fs." + TEST_SCHEME + ".impl", fsClass.getName());
        return configuration;
    }

    private static org.apache.hadoop.conf.Configuration hadoopConfigurationWithoutDefaults() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                new org.apache.hadoop.conf.Configuration(false);
        hadoopConfig.set(
                "fs." + TEST_SCHEME + ".impl", RecordingFileSystem.class.getName());
        return hadoopConfig;
    }

    private static void setHadoopConfiguration(
            HadoopFsFactory factory, org.apache.hadoop.conf.Configuration hadoopConfig) {
        try {
            final Field field = HadoopFsFactory.class.getDeclaredField("hadoopConfig");
            field.setAccessible(true);
            field.set(factory, hadoopConfig);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to set the test Hadoop configuration", e);
        }
    }

    /** A Hadoop file system implementation that records how it was initialized. */
    public static class RecordingFileSystem extends RawLocalFileSystem {

        private static URI initializedUri;
        private static org.apache.hadoop.conf.Configuration initializationConfig;
        private static RecordingFileSystem lastInstance;
        private static int initializationCount;

        @Override
        public void initialize(URI name, org.apache.hadoop.conf.Configuration conf)
                throws IOException {
            initializedUri = name;
            initializationConfig = conf;
            lastInstance = this;
            initializationCount++;
        }

        private static void reset() {
            initializedUri = null;
            initializationConfig = null;
            lastInstance = null;
            initializationCount = 0;
        }
    }

    /** A Hadoop file system implementation whose initialization reports an unknown host. */
    public static class UnknownHostFileSystem extends RawLocalFileSystem {

        @Override
        public void initialize(URI name, org.apache.hadoop.conf.Configuration conf)
                throws IOException {
            throw new UnknownHostException(name.getHost());
        }
    }

    /** A Hadoop file system implementation whose initialization throws an unexpected exception. */
    public static class ThrowingRuntimeFileSystem extends RawLocalFileSystem {

        @Override
        public void initialize(URI name, org.apache.hadoop.conf.Configuration conf) {
            throw new IllegalStateException("expected test failure");
        }
    }

    /** A Hadoop file system implementation that cannot be instantiated reflectively. */
    public static class PrivateConstructorFileSystem extends RawLocalFileSystem {

        private PrivateConstructorFileSystem() {}
    }
}
