import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link HadoopFsFactory#create(URI)}. */
class HadoopFsFactoryCreateTests {

    private static final String TEST_SCHEME = "hadoop-fs-factory-test";

    private HadoopFsFactory factory;

    @BeforeEach
    void setUp() {
        RecordingFileSystem.reset();
        factory = new HadoopFsFactory();
    }

    @Test
    void createRejectsNullUri() {
        assertThatThrownBy(() -> factory.create(null))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("fsUri");
    }

    @Test
    void createRejectsUriWithoutScheme() {
        assertThatThrownBy(() -> factory.create(URI.create("relative/path")))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("file system has null scheme");
    }

    @Test
    void createWrapsAndInitializesHadoopFileSystem() throws Exception {
        final Configuration flinkConfig = configureScheme(RecordingFileSystem.class);
        flinkConfig.setString("flink.hadoop.test-custom-property", "test-custom-value");
        factory.configure(flinkConfig);

        final URI fsUri = URI.create(TEST_SCHEME + "://namenode:8020/data");
        final FileSystem fs = factory.create(fsUri);

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(((HadoopFileSystem) fs).getHadoopFileSystem())
                .isSameAs(RecordingFileSystem.lastInstance);
        assertThat(RecordingFileSystem.initializationCount).isEqualTo(1);
        assertThat(RecordingFileSystem.initializedUri).isEqualTo(fsUri);
        assertThat(RecordingFileSystem.initializationConfig.get("test-custom-property"))
                .isEqualTo("test-custom-value");
    }

    @Test
    void createUsesConfiguredDefaultAuthorityWhenUriHasNoAuthority() throws Exception {
        final Configuration flinkConfig = configureScheme(RecordingFileSystem.class);
        final URI configuredDefault = URI.create(TEST_SCHEME + "://default-namenode:9000/base");
        flinkConfig.setString("flink.hadoop.fs.defaultFS", configuredDefault.toString());
        factory.configure(flinkConfig);

        final URI fsUri = URI.create(TEST_SCHEME + ":/relative/path");
        assertThat(fsUri.getAuthority()).isNull();

        final FileSystem fs = factory.create(fsUri);

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(RecordingFileSystem.initializedUri).isEqualTo(configuredDefault);
    }

    @Test
    void createFallsBackToDeprecatedDefaultNameWhenDefaultFsIsAbsent() throws Exception {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        final URI configuredDefault = URI.create(TEST_SCHEME + "://legacy-namenode:8020/base");
        hadoopConfig.set("fs.default.name", configuredDefault.toString());
        setHadoopConfiguration(factory, hadoopConfig);

        final FileSystem fs = factory.create(URI.create(TEST_SCHEME + ":/relative/path"));

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(RecordingFileSystem.initializedUri).isEqualTo(configuredDefault);
    }

    @Test
    void createFailsWhenDefaultAuthorityIsMissing() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        setHadoopConfiguration(factory, hadoopConfig);

        final URI fsUri = URI.create(TEST_SCHEME + ":/relative/path");
        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(IOException.class)
                .hasMessageContaining(fsUri.toString())
                .hasMessageContaining("did not describe the authority")
                .hasMessageContaining(
                        "Hadoop configuration did not contain an entry for the default file system ('fs.defaultFS')");
        assertThat(RecordingFileSystem.initializationCount).isZero();
    }

    @Test
    void createFailsWhenConfiguredDefaultAuthorityIsInvalidUri() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        final String invalidDefault = "not a valid URI";
        hadoopConfig.set("fs.defaultFS", invalidDefault);
        setHadoopConfiguration(factory, hadoopConfig);

        assertThatThrownBy(() -> factory.create(URI.create(TEST_SCHEME + ":/relative/path")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining(
                        "The configuration contains an invalid file system default name")
                .hasMessageContaining(invalidDefault);
        assertThat(RecordingFileSystem.initializationCount).isZero();
    }

    @Test
    void createFailsWhenConfiguredDefaultAuthorityHasNoAuthorityComponent() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                hadoopConfigurationWithoutDefaults();
        final String invalidDefault = TEST_SCHEME + ":/without-authority";
        hadoopConfig.set("fs.defaultFS", invalidDefault);
        setHadoopConfiguration(factory, hadoopConfig);

        assertThatThrownBy(() -> factory.create(URI.create(TEST_SCHEME + ":/relative/path")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("contains no valid authority component");
        assertThat(RecordingFileSystem.initializationCount).isZero();
    }

    @Test
    void createWrapsUnsupportedHadoopScheme() {
        final URI fsUri = URI.create("definitely-unsupported-hadoop-scheme://host/path");

        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("does not support scheme")
                .hasMessageContaining(fsUri.getScheme())
                .hasCauseInstanceOf(IOException.class);
    }

    @Test
    void createTranslatesUnknownHostDuringInitialization() {
        factory.configure(configureScheme(UnknownHostFileSystem.class));

        final URI fsUri = URI.create(TEST_SCHEME + "://unresolvable-host:1234/path");
        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(IOException.class)
                .hasMessage(
                        "The Hadoop file system's authority (unresolvable-host:1234), specified by either the file URI or the configuration, cannot be resolved.")
                .hasCauseInstanceOf(UnknownHostException.class);
    }

    @Test
    void createWrapsUnexpectedInitializationFailure() {
        factory.configure(configureScheme(ThrowingRuntimeFileSystem.class));

        final URI fsUri = URI.create(TEST_SCHEME + "://namenode:8020/path");
        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(IOException.class)
                .hasMessage("Cannot instantiate file system for URI: " + fsUri)
                .hasCauseInstanceOf(IllegalStateException.class);
    }

    @Test
    void createWrapsReflectiveInstantiationFailure() {
        factory.configure(configureScheme(PrivateConstructorFileSystem.class));

        final URI fsUri = URI.create(TEST_SCHEME + "://namenode:8020/path");
        assertThatThrownBy(() -> factory.create(fsUri))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining(
                        "Cannot support file system for '" + TEST_SCHEME + "' via Hadoop")
                .hasCauseInstanceOf(IllegalAccessException.class);
    }

    @Test
    void createAppliesConfiguredConnectionLimits() throws Exception {
        final Configuration flinkConfig = configureScheme(RecordingFileSystem.class);
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.total", "7");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.input", "3");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.output", "5");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.timeout", "1000");
        flinkConfig.setString("fs." + TEST_SCHEME + ".limit.stream-timeout", "2000");
        factory.configure(flinkConfig);

        final FileSystem fs = factory.create(URI.create(TEST_SCHEME + "://namenode:8020/path"));

        assertThat(fs).isInstanceOf(LimitedConnectionsFileSystem.class);
        final LimitedConnectionsFileSystem limitedFs = (LimitedConnectionsFileSystem) fs;
        assertThat(limitedFs.getMaxNumOpenStreamsTotal()).isEqualTo(7);
        assertThat(limitedFs.getMaxNumOpenInputStreams()).isEqualTo(3);
        assertThat(limitedFs.getMaxNumOpenOutputStreams()).isEqualTo(5);
        assertThat(limitedFs.getStreamOpenTimeout()).isEqualTo(1000L);
        assertThat(limitedFs.getStreamInactivityTimeout()).isEqualTo(2000L);
        assertThat(RecordingFileSystem.initializationCount).isEqualTo(1);
    }

    @Test
    void createDoesNotApplyConnectionLimitsWhenNoneConfigured() throws Exception {
        factory.configure(configureScheme(RecordingFileSystem.class));

        final FileSystem fs = factory.create(URI.create(TEST_SCHEME + "://namenode:8020/path"));

        assertThat(fs).isInstanceOf(HadoopFileSystem.class);
        assertThat(fs).isNotInstanceOf(LimitedConnectionsFileSystem.class);
    }

    private static Configuration configureScheme(
            Class<? extends org.apache.hadoop.fs.FileSystem> fsClass) {
        final Configuration configuration = new Configuration();
        configuration.setString("flink.hadoop.fs." + TEST_SCHEME + ".impl", fsClass.getName());
        return configuration;
    }

    private static org.apache.hadoop.conf.Configuration hadoopConfigurationWithoutDefaults() {
        final org.apache.hadoop.conf.Configuration hadoopConfig =
                new org.apache.hadoop.conf.Configuration(false);
        hadoopConfig.set("fs." + TEST_SCHEME + ".impl", RecordingFileSystem.class.getName());
        return hadoopConfig;
    }

    private static void setHadoopConfiguration(
            HadoopFsFactory factory, org.apache.hadoop.conf.Configuration hadoopConfig) {
        try {
            final Field field = HadoopFsFactory.class.getDeclaredField("hadoopConfig");
            field.setAccessible(true);
            field.set(factory, hadoopConfig);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError("Unable to set the test Hadoop configuration", e);
        }
    }

    /** A Hadoop file system implementation that records how it was initialized. */
    public static class RecordingFileSystem extends RawLocalFileSystem {

        private static URI initializedUri;
        private static org.apache.hadoop.conf.Configuration initializationConfig;
        private static RecordingFileSystem lastInstance;
        private static int initializationCount;

        @Override
        public void initialize(URI name, org.apache.hadoop.conf.Configuration conf)
                throws IOException {
            initializedUri = name;
            initializationConfig = conf;
            lastInstance = this;
            initializationCount++;
        }

        private static void reset() {
            initializedUri = null;
            initializationConfig = null;
            lastInstance = null;
            initializationCount = 0;
        }
    }

    /** A Hadoop file system implementation whose initialization reports an unknown host. */
    public static class UnknownHostFileSystem extends RawLocalFileSystem {

        @Override
        public void initialize(URI name, org.apache.hadoop.conf.Configuration conf)
                throws IOException {
            throw new UnknownHostException(name.getHost());
        }
    }

    /** A Hadoop file system implementation whose initialization throws an unexpected exception. */
    public static class ThrowingRuntimeFileSystem extends RawLocalFileSystem {

        @Override
        public void initialize(URI name, org.apache.hadoop.conf.Configuration conf) {
            throw new IllegalStateException("expected test failure");
        }
    }

    /** A Hadoop file system implementation that cannot be instantiated reflectively. */
    public static class PrivateConstructorFileSystem extends RawLocalFileSystem {

        private PrivateConstructorFileSystem() {}
    }
}

