                throw new InvalidTypesException(
                        "TypeInfo annotation does not specify a valid TypeInfoFactory.");
            }
        }

        // instantiate
        return (TypeInfoFactory<OUT>) InstantiationUtil.instantiate(factoryClass);
    }

