import org.junit.jupiter.api.Test;

import java.io.ObjectInputStream;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Tests for {@link TypeExtractor#analyzePojo(Type, List, TypeInformation, TypeInformation)}.
 *
 * <p>The method is invoked through its package-private/protected visibility from a class located in
 * the very same package as the production class.
 */
class TypeExtractorAnalyzePojoTests {

    private final TypeExtractor extractor = new TypeExtractor();

    // --------------------------------------------------------------------------------------------
    //  helpers
    // --------------------------------------------------------------------------------------------

    private <T> TypeInformation<T> analyzePojo(Class<T> clazz) {
        return analyzePojo(clazz, new ArrayList<>());
    }

    private <T> TypeInformation<T> analyzePojo(Type type, List<Type> typeHierarchy) {
        return extractor.analyzePojo(type, typeHierarchy, null, null);
    }

    // --------------------------------------------------------------------------------------------
    //  fallback to GenericTypeInfo
    // --------------------------------------------------------------------------------------------

    @Test
    void testNonPublicClassIsTreatedAsGenericType() {
        TypeInformation<NonPublicPojo> typeInfo = analyzePojo(NonPublicPojo.class);

        assertThat(typeInfo).isInstanceOf(GenericTypeInfo.class);
        assertThat(typeInfo.getTypeClass()).isEqualTo(NonPublicPojo.class);
        assertThat(typeInfo.isTupleType()).isFalse();
        assertThat(typeInfo.isBasicType()).isFalse();
    }

    @Test
    void testClassWithoutAnyFieldsIsTreatedAsGenericType() {
        TypeInformation<NoFieldsPojo> typeInfo = analyzePojo(NoFieldsPojo.class);

        assertThat(typeInfo).isInstanceOf(GenericTypeInfo.class);
        assertThat(typeInfo.getTypeClass()).isEqualTo(NoFieldsPojo.class);
    }

    @Test
    void testClassWithOnlyStaticAndTransientFieldsIsTreatedAsGenericType() {
        TypeInformation<OnlyStaticAndTransientFieldsPojo> typeInfo =
                analyzePojo(OnlyStaticAndTransientFieldsPojo.class);

        assertThat(typeInfo).isInstanceOf(GenericTypeInfo.class);
        assertThat(typeInfo.getTypeClass()).isEqualTo(OnlyStaticAndTransientFieldsPojo.class);
    }

    @Test
    void testInterfaceWithoutInstanceFieldsIsTreatedAsGenericType() {
