        TypeInformation<AbstractPojoWithoutDefaultConstructor> typeInfo =
                analyzePojo(AbstractPojoWithoutDefaultConstructor.class);

        assertThat(typeInfo).isInstanceOf(PojoTypeInfo.class);
        assertThat(typeInfo.getTypeClass()).isEqualTo(AbstractPojoWithoutDefaultConstructor.class);
        assertThat(((PojoTypeInfo<?>) typeInfo).getFieldNames()).containsExactly("name");
