    @Test
    void testValidPojoWithPublicFields() {
        TypeInformation<SimplePojo> typeInfo = analyzePojo(SimplePojo.class);

        assertThat(typeInfo).isInstanceOf(PojoTypeInfo.class);
        assertThat(typeInfo.getTypeClass()).isEqualTo(SimplePojo.class);
        assertThat(typeInfo.isTupleType()).isFalse();

        PojoTypeInfo<SimplePojo> pojoTypeInfo = (PojoTypeInfo<SimplePojo>) typeInfo;
        assertThat(pojoTypeInfo.getArity()).isEqualTo(2);
        // fields are sorted by name
        assertThat(pojoTypeInfo.getFieldNames()).containsExactly("age", "name");
        assertThat(pojoTypeInfo.getFieldIndex("name")).isEqualTo(1);
        assertThat(pojoTypeInfo.getFieldIndex("age")).isEqualTo(0);

        TypeInformation<?> nameType = pojoTypeInfo.getTypeAt("name");
        assertThat(nameType).isInstanceOf(BasicTypeInfo.class);
        assertThat(nameType.getTypeClass()).isEqualTo(String.class);

        TypeInformation<?> ageType = pojoTypeInfo.getTypeAt("age");
        assertThat(ageType).isInstanceOf(BasicTypeInfo.class);
        assertThat(ageType.getTypeClass()).isEqualTo(Integer.class);

        assertThat(pojoTypeInfo.getPojoFieldAt(1).getField().getName()).isEqualTo("name");
    }

    @Test
