        assertThat(pojoTypeInfo.getFieldNames()).containsExactly("active", "name");
        assertThat(pojoTypeInfo.getTypeAt("active").getTypeClass()).isEqualTo(Boolean.class);
        assertThat(pojoTypeInfo.getTypeAt("name").getTypeClass()).isEqualTo(String.class);
    }

