        TypeInformation<?> tupleType = pojoTypeInfo.getTypeAt("tuple");
        assertThat(tupleType).isInstanceOf(TupleTypeInfo.class);
        assertThat(tupleType.getTypeClass()).isEqualTo(Tuple2.class);
        assertThat(tupleType.getArity()).isEqualTo(2);
    }

    @Test
    void testNestedPojoFieldIsAnalyzedAsPojoType() {
        TypeInformation<PojoWithNestedPojo> typeInfo = analyzePojo(PojoWithNestedPojo.class);

        assertThat(typeInfo).isInstanceOf(PojoTypeInfo.class);
        PojoTypeInfo<PojoWithNestedPojo> pojoTypeInfo = (PojoTypeInfo<PojoWithNestedPojo>) typeInfo;

        TypeInformation<?> nestedType = pojoTypeInfo.getTypeAt("nested");
        assertThat(nestedType).isInstanceOf(PojoTypeInfo.class);
        assertThat(nestedType.getTypeClass()).isEqualTo(SimplePojo.class);
        assertThat(((PojoTypeInfo<?>) nestedType).getFieldNames()).containsExactly("age", "name");
    }

    @Test
    void testFieldWithUnresolvableTypeFallsBackToGenericTypeInfo() {
        TypeInformation<PojoWithObjectField> typeInfo = analyzePojo(PojoWithObjectField.class);

        assertThat(typeInfo).isInstanceOf(PojoTypeInfo.class);
        PojoTypeInfo<PojoWithObjectField> pojoTypeInfo = (PojoTypeInfo<PojoWithObjectField>) typeInfo;
        assertThat(pojoTypeInfo.getFieldNames()).containsExactly("id", "payload");

        TypeInformation<?> payloadType = pojoTypeInfo.getTypeAt("payload");
        assertThat(payloadType).isInstanceOf(GenericTypeInfo.class);
        assertThat(payloadType.getTypeClass()).isEqualTo(Object.class);
        // other fields are still extracted properly
        assertThat(pojoTypeInfo.getTypeAt("id")).isInstanceOf(BasicTypeInfo.class);
    }

    @Test
