    assertThat(pojoTypeInfo.getFieldNames()).containsExactly("baseValue", "subValue");
    assertThat(pojoTypeInfo.getTypeAt("baseValue").getTypeClass()).isEqualTo(String.class);
    assertThat(pojoTypeInfo.getTypeAt("subValue").getTypeClass()).isEqualTo(Long.class);
}

@Test
void testTupleFieldIsAnalyzedAsTupleType() {
