@Test
void testFieldWithUnresolvableTypeFallsBackToGenericTypeInfo() {
    TypeInformation<PojoWithObjectField> typeInfo = analyzePojo(PojoWithObjectField.class);

    assertThat(typeInfo).isInstanceOf(PojoTypeInfo.class);
    PojoTypeInfo<PojoWithObjectField> pojoTypeInfo =
            (PojoTypeInfo<PojoWithObjectField>) typeInfo;
    assertThat(pojoTypeInfo.getFieldNames()).containsExactly("id", "payload");

    TypeInformation<?> payloadType = pojoTypeInfo.getTypeAt("payload");
    assertThat(payloadType).isInstanceOf(GenericTypeInfo.class);
    assertThat(payloadType.getTypeClass()).isEqualTo(Object.class);
    // other fields are still extracted properly
    assertThat(pojoTypeInfo.getTypeAt("id")).isInstanceOf(BasicTypeInfo.class);
}

@Test
void testArrayFieldsAreAnalyzedWithTheirArrayTypeInformation() {
    TypeInformation<PojoWithArrayFields> typeInfo = analyzePojo(PojoWithArrayFields.class);

    assertThat(typeInfo).isInstanceOf(PojoTypeInfo.class);
    PojoTypeInfo<PojoWithArrayFields> pojoTypeInfo =
            (PojoTypeInfo<PojoWithArrayFields>) typeInfo;
    assertThat(pojoTypeInfo.getFieldNames()).containsExactly("names", "numbers");
    assertThat(pojoTypeInfo.getTypeAt("numbers").getTypeClass()).isEqualTo(int[].class);
    assertThat(pojoTypeInfo.getTypeAt("names").getTypeClass()).isEqualTo(String[].class);
}

@Test
void testTypeHierarchyIsFilledWithPojoHierarchy() {
    List<Type> typeHierarchy = new ArrayList<>();
    TypeInformation<SubPojo> typeInfo = analyzePojo(SubPojo.class, typeHierarchy);

