package org.apache.flink.core.fs;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.configuration.CoreOptions;
import org.apache.flink.core.fs.local.LocalFileSystem;
import org.apache.flink.core.plugin.PluginManager;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.net.URI;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;

/** Tests for {@link FileSystem#getUnguardedFileSystem(URI)}. */
class FileSystemGetUnguardedFileSystemTests {

    @BeforeEach
    void resetFileSystemState() {
        FileSystem.initialize(new Configuration(), pluginManager());
    }

    @AfterEach
    void clearFileSystemState() {
        FileSystem.initialize(new Configuration(), pluginManager());
    }

    @Test
    void nullUriIsRejected() {
        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(null))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("file system URI");
    }

    @Test
    void explicitSchemeUsesRegisteredFactoryWithOriginalUri() throws Exception {
        final TestFileSystemFactory factory = new TestFileSystemFactory("test-fs");
        initializeWithFactories(new Configuration(), factory);

        final URI requestedUri = URI.create("test-fs://host:1234/path/to/data?query=x#fragment");
        final FileSystem fileSystem = FileSystem.getUnguardedFileSystem(requestedUri);

        assertThat(fileSystem).isNotNull();
        assertThat(factory.createCount()).isEqualTo(1);
        assertThat(factory.lastCreatedUri()).isSameAs(requestedUri);
        assertThat(factory.lastCreateContextClassLoader()).isSameAs(factory.getClassLoader());
    }

    @Test
    void defaultSchemeAndAuthorityAreAppliedToUriWithoutScheme() throws Exception {
        final Configuration configuration = new Configuration();
        configuration.set(
                CoreOptions.DEFAULT_FILESYSTEM_SCHEME, "test-fs://default-host:4321/base/path");
        final TestFileSystemFactory factory = new TestFileSystemFactory("test-fs");
        initializeWithFactories(configuration, factory);

        final FileSystem fileSystem = FileSystem.getUnguardedFileSystem(URI.create("/data/input"));

        assertThat(fileSystem).isNotNull();
        assertThat(factory.lastCreatedUri())
                .isEqualTo(URI.create("test-fs://default-host:4321/data/input"));
    }

    @Test
    void uriWithoutSchemeUsesLocalFileSystemByDefault() throws Exception {
        final FileSystem fileSystem =
                FileSystem.getUnguardedFileSystem(URI.create("/tmp/flink-unguarded-test"));

        assertThat(fileSystem).isSameAs(LocalFileSystem.getSharedInstance());
    }

    @Test
    void relativePathWithoutSchemeIsMadeAbsoluteForLocalDefault() throws Exception {
        final TestFileSystemFactory fileFactory = new TestFileSystemFactory("file");
        initializeWithFactories(new Configuration(), fileFactory);

        final FileSystem fileSystem =
                FileSystem.getUnguardedFileSystem(URI.create("relative/path"));

        final URI createdUri = fileFactory.lastCreatedUri();
        assertThat(fileSystem).isNotNull();
        assertThat(createdUri.getScheme()).isEqualTo("file");
        assertThat(createdUri.getAuthority()).isNull();
        assertThat(createdUri.getPath()).startsWith("/");
        assertThat(createdUri.getPath()).endsWith("/relative/path");
    }

    @Test
    void unresolvableRelativeUriWithNonFileDefaultFails() throws Exception {
        final Configuration configuration = new Configuration();
        configuration.set(CoreOptions.DEFAULT_FILESYSTEM_SCHEME, "test-fs://default-host");
        final TestFileSystemFactory factory = new TestFileSystemFactory("test-fs");
        initializeWithFactories(configuration, factory);

        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(URI.create("relative/path")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("declares no scheme and cannot be interpreted")
                .hasMessageContaining("test-fs://default-host");
        assertThat(factory.createCount()).isZero();
    }

    @Test
    void localFileUriWithAuthorityIsRejectedBeforeCreatingFileSystem() throws Exception {
        final TestFileSystemFactory fileFactory = new TestFileSystemFactory("file");
        initializeWithFactories(new Configuration(), fileFactory);

        assertThatThrownBy(
                        () -> FileSystem.getUnguardedFileSystem(URI.create("file://remote-host/tmp")))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("authority 'remote-host'")
                .hasMessageContaining("file:///remote-host/tmp")
                .hasMessageContaining("Did you forget a slash?");
        assertThat(fileFactory.createCount()).isZero();
    }

    @Test
    void fileSystemIsCachedBySchemeAndAuthority() throws Exception {
        final TestFileSystemFactory factory = new TestFileSystemFactory("cache-test");
        initializeWithFactories(new Configuration(), factory);

        final FileSystem first =
                FileSystem.getUnguardedFileSystem(URI.create("cache-test://host/one"));
        final FileSystem second =
                FileSystem.getUnguardedFileSystem(URI.create("cache-test://host/two"));
        final FileSystem otherAuthority =
                FileSystem.getUnguardedFileSystem(URI.create("cache-test://other-host/one"));

        assertThat(second).isSameAs(first);
        assertThat(otherAuthority).isNotSameAs(first);
        assertThat(factory.createCount()).isEqualTo(2);
        assertThat(factory.createdUris())
                .containsExactly(
                        URI.create("cache-test://host/one"),
                        URI.create("cache-test://other-host/one"));
    }

    @Test
    void initializationClearsTheFileSystemCache() throws Exception {
        final TestFileSystemFactory factory = new TestFileSystemFactory("cache-test");
        final URI uri = URI.create("cache-test://host/path");

        initializeWithFactories(new Configuration(), factory);
        final FileSystem first = FileSystem.getUnguardedFileSystem(uri);

        initializeWithFactories(new Configuration(), factory);
        final FileSystem second = FileSystem.getUnguardedFileSystem(uri);

        assertThat(second).isNotSameAs(first);
        assertThat(factory.createCount()).isEqualTo(2);
    }

    @Test
    void suppliedClassLoaderIsUsedAndRestoredForFactoryCreation() throws Exception {
        final ClassLoader factoryClassLoader = new ClassLoader() {};
        final TestFileSystemFactory factory =
                new TestFileSystemFactory("loader-test", factoryClassLoader);
        initializeWithFactories(new Configuration(), factory);
        final ClassLoader originalContextClassLoader =
                Thread.currentThread().getContextClassLoader();

        FileSystem.getUnguardedFileSystem(URI.create("loader-test://host/path"));

        assertThat(factory.lastCreateContextClassLoader()).isSameAs(factoryClassLoader);
        assertThat(Thread.currentThread().getContextClassLoader())
                .isSameAs(originalContextClassLoader);
    }

    @Test
    void factoryFailureIsPropagatedAndNotCached() throws Exception {
        final TestFileSystemFactory factory = new TestFileSystemFactory("failing-test");
        factory.failNextCreate();
        initializeWithFactories(new Configuration(), factory);
        final URI uri = URI.create("failing-test://host/path");

        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(uri))
                .isInstanceOf(IOException.class)
                .hasMessage("expected factory failure");

        final FileSystem fileSystem = FileSystem.getUnguardedFileSystem(uri);
        assertThat(fileSystem).isNotNull();
        assertThat(factory.createCount()).isEqualTo(2);
    }

    @Test
    void directlySupportedSchemeWithoutPluginUsesPluginSpecificError() {
        assertThatThrownBy(() -> FileSystem.getUnguardedFileSystem(URI.create("s3://bucket/key")))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("directly supported by Flink")
                .hasMessageContaining("flink-s3-fs-hadoop")
                .hasMessageContaining("flink-s3-fs-presto")
                .hasMessageContaining("flink-s3-fs-native");
    }

    @Test
    void allowedFallbackForDirectlySupportedSchemeUsesPluginSpecificFallbackError() {
        final Configuration configuration = new Configuration();
        configuration.set(CoreOptions.ALLOWED_FALLBACK_FILESYSTEMS, "s3");
        initializeWithFactories(configuration);

        assertThatThrownBy(
                        () -> FileSystem.getUnguardedFileSystem(URI.create("s3://bucket/key")))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("File system schemes are supported by Flink")
                .hasMessageContaining("flink-s3-fs-hadoop");
    }

    @Test
    void unsupportedSchemeWithoutPluginOrHadoopFailsWithGenericError() {
        assertThatThrownBy(
                        () ->
                                FileSystem.getUnguardedFileSystem(
                                        URI.create("unknown-test-scheme://host/path")))
                .isInstanceOf(UnsupportedFileSystemSchemeException.class)
                .hasMessageContaining("unknown-test-scheme")
                .hasMessageContaining("not directly supported by Flink");
    }

    private static void initializeWithFactories(
            Configuration configuration, FileSystemFactory... factories) {
        FileSystem.initialize(configuration, pluginManager(factories));
    }

    private static PluginManager pluginManager(FileSystemFactory... factories) {
        return new PluginManager() {
            @SuppressWarnings("unchecked")
            @Override
            public <P> Iterator<P> load(Class<P> service) {
                if (service == FileSystemFactory.class) {
                    return (Iterator<P>) Arrays.asList(factories).iterator();
                }
                return Collections.emptyIterator();
            }
        };
    }

    private static final class TestFileSystemFactory implements FileSystemFactory {

        private final String scheme;
        private final ClassLoader classLoader;
        private final AtomicInteger createCount = new AtomicInteger();
        private final AtomicBoolean failNextCreate = new AtomicBoolean();
        private final AtomicReference<URI> lastCreatedUri = new AtomicReference<>();
        private final AtomicReference<ClassLoader> lastCreateContextClassLoader =
                new AtomicReference<>();
        private final AtomicReference<URI> previousCreatedUri = new AtomicReference<>();
        private final java.util.List<URI> createdUris = new java.util.ArrayList<>();

        private TestFileSystemFactory(String scheme) {
            this(scheme, TestFileSystemFactory.class.getClassLoader());
        }

        private TestFileSystemFactory(String scheme, ClassLoader classLoader) {
            this.scheme = scheme;
            this.classLoader = classLoader;
        }

        @Override
        public String getScheme() {
            return scheme;
        }

        @Override
        public ClassLoader getClassLoader() {
            return classLoader;
        }

        @Override
        public FileSystem create(URI fsUri) throws IOException {
            createCount.incrementAndGet();
            lastCreatedUri.set(fsUri);
            createdUris.add(fsUri);
            lastCreateContextClassLoader.set(Thread.currentThread().getContextClassLoader());

            if (failNextCreate.getAndSet(false)) {
                throw new IOException("expected factory failure");
            }
            return mock(FileSystem.class);
        }

        private void failNextCreate() {
            failNextCreate.set(true);
        }

        private int createCount() {
            return createCount.get();
        }

        private URI lastCreatedUri() {
            return lastCreatedUri.get();
        }

        private ClassLoader lastCreateContextClassLoader() {
            return lastCreateContextClassLoader.get();
        }

        private java.util.List<URI> createdUris() {
            return createdUris;
        }
    }
}
