        final URI createdUri = fileFactory.lastCreatedUri();
        assertThat(fileSystem).isNotNull();
        assertThat(createdUri.getScheme()).isEqualTo("file");
        assertThat(createdUri.getAuthority()).isNull();
        assertThat(createdUri.getPath()).startsWith("/");
        assertThat(createdUri.getPath()).endsWith("/relative/path");
    }

