                }
                return Collections.emptyIterator();
            }
        };
    }

    private static final class TestFileSystemFactory implements FileSystemFactory {

        private final String scheme;
        private final ClassLoader classLoader;
        private final AtomicInteger createCount = new AtomicInteger();
        private final AtomicBoolean failNextCreate = new AtomicBoolean();
        private final AtomicReference<URI> lastCreatedUri = new AtomicReference<>();
        private final AtomicReference<ClassLoader> lastCreateContextClassLoader =
                new AtomicReference<>();
        private final AtomicReference<URI> previousCreatedUri = new AtomicReference<>();
        private final java.util.List<URI> createdUris = new java.util.ArrayList<>();

        private TestFileSystemFactory(String scheme) {
            this(scheme, TestFileSystemFactory.class.getClassLoader());
        }

        private TestFileSystemFactory(String scheme, ClassLoader classLoader) {
            this.scheme = scheme;
            this.classLoader = classLoader;
        }

        @Override
        public String getScheme() {
            return scheme;
        }

        @Override
        public ClassLoader getClassLoader() {
            return classLoader;
        }

        @Override
        public FileSystem create(URI fsUri) throws IOException {
            createCount.incrementAndGet();
            lastCreatedUri.set(fsUri);
            createdUris.add(fsUri);
            lastCreateContextClassLoader.set(Thread.currentThread().getContextClassLoader());

            if (failNextCreate.getAndSet(false)) {
                throw new IOException("expected factory failure");
            }
            return mock(FileSystem.class);
        }

        private void failNextCreate() {
            failNextCreate.set(true);
        }

        private int createCount() {
            return createCount.get();
        }

        private URI lastCreatedUri() {
            return lastCreatedUri.get();
        }

        private ClassLoader lastCreateContextClassLoader() {
            return lastCreateContextClassLoader.get();
        }

        private java.util.List<URI> createdUris() {
            return createdUris;
        }
    }
