    // range check
    if (fieldNum < 0 || fieldNum >= this.numFields) {
        throw new IndexOutOfBoundsException();
    }

    // get offset and check for null
    int offset = this.offsets[fieldNum];
    if (offset == NULL_INDICATOR_OFFSET) {
        return false;
