                for (int i = numFields - 1; i > 0; i--) {
                    if (offsets[i] != NULL_INDICATOR_OFFSET) {
                        slp = serializer.position;
                        serializer.writeValLenIntBackwards(offsets[i]);
                        mask |= 0x1;
                    }
                    mask <<= 1;
