                // now the mask. we write it in chucks of 8 bit.
                // the remainder %8 comes first
                int col = numFields - 1;
                int mask = 0;
                int i = numFields & 0x7;

                if (i > 0) {
                    for (; i > 0; i--, col--) {
                        mask <<= 1;
                        mask |= (offsets[col] != NULL_INDICATOR_OFFSET) ? 0x1 : 0x0;
                    }
                    serializer.writeByte(mask);
