class RecordUnionFieldsTests {

    // --------------------------------------------------------------------------------------------
    //  Test: fields contributed by both records
    // --------------------------------------------------------------------------------------------

    @Test
    void unionMergesFieldsOfBothRecords() throws Exception {
        final Record left = syncedInts(1, null);
        final Record right = syncedInts(null, 2);

        left.unionFields(right);

        assertFieldValues(left, 1, 2);
    }

    @Test
    void unionFillsNullFieldsOfThisRecordFromOtherRecord() throws Exception {
        final Record left = syncedInts(null, 5, null, null);
        final Record right = syncedInts(1, 2, 3, 4);

        left.unionFields(right);

        assertFieldValues(left, 1, 5, 3, 4);
    }

    @Test
    void unionPrefersOwnFieldsOverFieldsOfOtherRecord() throws Exception {
        final Record left = syncedInts(11, 12, 13);
        final Record right = syncedInts(21, 22, 23);

        left.unionFields(right);

        assertFieldValues(left, 11, 12, 13);
    }

    @Test
    void unionKeepsFieldNullWhenBothRecordsHaveNullField() throws Exception {
        final Record left = syncedInts(null, 5);
        final Record right = syncedInts(null, 6);

        left.unionFields(right);

        assertFieldValues(left, null, 5);
    }

    @Test
    void unionOfTwoCompletelyNullRecordsStaysNull() throws Exception {
        final Record left = syncedInts(emptyValues(3));
        final Record right = syncedInts(emptyValues(3));

        left.unionFields(right);

        assertFieldValues(left, new Object[] {null, null, null});
    }

    // --------------------------------------------------------------------------------------------
    //  Test: different numbers of fields
    // --------------------------------------------------------------------------------------------

    @Test
    void unionAppendsTrailingFieldsOfLongerOtherRecord() throws Exception {
        final Record left = syncedInts(1);
        final Record right = syncedInts(2, 3, 4);

        left.unionFields(right);

        assertFieldValues(left, 1, 3, 4);
    }

    @Test
    void unionKeepsTrailingFieldsOfLongerThisRecord() throws Exception {
        final Record left = syncedInts(1, 2, 3, 4);
        final Record right = syncedInts(9, 8);

        left.unionFields(right);

        assertFieldValues(left, 1, 2, 3, 4);
    }

    @Test
    void unionAppendsTrailingFieldsOfOtherRecordIncludingGaps() throws Exception {
        final Record left = syncedInts(1);
        final Record right = syncedInts(9, null, 7, null, 5);

        left.unionFields(right);

        assertFieldValues(left, 1, null, 7, null, 5);
    }

    @Test
    void unionWithEmptyRecordAdoptsAllFieldsOfOtherRecord() throws Exception {
        final Record left = emptyRecord();
        final Record right = syncedInts(1, null, 3);

        left.unionFields(right);

        assertFieldValues(left, 1, null, 3);
    }

    @Test
    void unionWithEmptyRecordKeepsAllOwnFields() throws Exception {
        final Record left = syncedInts(1, null, 3);
        final Record right = emptyRecord();

        left.unionFields(right);

        assertFieldValues(left, 1, null, 3);
    }

    @Test
    void unionOfRecordWithItselfKeepsAllFields() throws Exception {
        final Record record = syncedInts(1, 2, 3);

        record.unionFields(record);

        assertFieldValues(record, 1, 2, 3);
