import java.util.List;

public class MiniRunner {
    public static void main(String[] args) throws Exception {
        int passed = 0;
        List<String> failures = new ArrayList<>();
        for (String className : args) {
            Class<?> clazz = Class.forName(className);
            Method[] methods = clazz.getDeclaredMethods();
            List<Method> tests = new ArrayList<>();
            for (Method m : methods) {
                for (java.lang.annotation.Annotation a : m.getAnnotations()) {
                    if (a.annotationType().getName().equals("org.junit.jupiter.api.Test")) {
                        tests.add(m);
                    }
                }
            }
            tests.sort((a, b) -> a.getName().compareTo(b.getName()));
            Constructor<?> ctor = clazz.getDeclaredConstructor();
            ctor.setAccessible(true);
            for (Method t : tests) {
                t.setAccessible(true);
                Object instance = ctor.newInstance();
                try {
                    t.invoke(instance);
                    passed++;
                    System.out.println("PASS " + className + "#" + t.getName());
                } catch (Throwable e) {
                    Throwable cause = e.getCause() == null ? e : e.getCause();
                    failures.add(className + "#" + t.getName() + " -> " + cause);
                    System.out.println("FAIL " + className + "#" + t.getName());
                    cause.printStackTrace(System.out);
                }
            }
        }
        System.out.println();
        System.out.println("passed=" + passed + " failed=" + failures.size());
        for (String f : failures) {
            System.out.println("  " + f);
        }
        if (!failures.isEmpty()) {
            System.exit(1);
        }
    }
}
