    //  Test: error handling
    // --------------------------------------------------------------------------------------------

    @Test
    void unionWrapsSerializationFailureIntoRuntimeException() {
        final Record left = new Record(1);
        left.setField(0, new FailingValue());
        final Record right = syncedInts(5);

        final RuntimeException exception =
                assertThrows(RuntimeException.class, () -> left.unionFields(right));

        assertNotNull(exception.getCause(), "the serialization exception should be the cause");
        assertTrue(
                exception.getCause() instanceof IOException,
                "expected an IOException as cause but got " + exception.getCause());
    }

    // --------------------------------------------------------------------------------------------
    //  Helpers
    // --------------------------------------------------------------------------------------------

    /** Creates a record with the given integer fields which is in sync with its binary form. */
    private static Record syncedInts(Integer... values) {
        final Record record = new Record(values.length);
        for (int i = 0; i < values.length; i++) {
            if (values[i] != null) {
                record.setField(i, new IntValue(values[i]));
            }
        }
        record.updateBinaryRepresenation();
        return record;
    }

    /** Creates a record with the given integer fields which still contains modified fields. */
    private static Record modifiedInts(Integer... values) {
        final Record record = new Record(values.length);
        for (int i = 0; i < values.length; i++) {
            if (values[i] != null) {
                record.setField(i, new IntValue(values[i]));
            }
        }
        return record;
    }

    /** Creates a record without any fields, but with initialized internal arrays. */
    private static Record emptyRecord() {
        final Record record = new Record();
        record.makeSpace(0);
        record.updateBinaryRepresenation();
        return record;
    }

    private static Integer[] emptyValues(int numFields) {
        return new Integer[numFields];
    }

    private static Integer intAt(Record record, int position) {
        final IntValue value = record.getField(position, IntValue.class);
        return value == null ? null : value.getValue();
    }

    private static String stringAt(Record record, int position) {
        final StringValue value = record.getField(position, StringValue.class);
        return value == null ? null : value.getValue();
    }

    private static Record roundTrip(Record record) throws IOException {
        final DataOutputSerializer out = new DataOutputSerializer(32);
        record.write(out);

    final Record copy = new Record();
    copy.read(new DataInputDeserializer(out.getCopyOfBuffer(), 0, out.length()));
    return copy;
}

/**
 * Verifies the field values of the given record, both directly and after a serialization
 * round trip. Expected values are {@link Integer}s, {@link String}s, or {@code null} for null
 * fields.
 */
private static void assertFieldValues(Record record, Object... expected) throws IOException {
    assertFieldValuesOnly(record, "record", expected);
    assertFieldValuesOnly(roundTrip(record), "record after serialization round trip", expected);
}

private static void assertFieldValuesOnly(Record record, String description, Object... expected) {
    assertEquals(
            expected.length,
            record.getNumFields(),
            description + " number of fields for " + describe(expected));

    for (int i = 0; i < expected.length; i++) {
        final String message = description + " field " + i + " of " + describe(expected);
        if (expected[i] == null) {
            assertTrue(record.isNull(i), message + " should be null");
            assertNull(record.getField(i, IntValue.class), message + " should be null");
        } else if (expected[i] instanceof Integer) {
            assertEquals(
                    ((Integer) expected[i]).intValue(),
                    intAt(record, i).intValue(),
                    message);
        } else if (expected[i] instanceof String) {
            assertEquals(expected[i], stringAt(record, i), message);
        } else {
            throw new IllegalArgumentException("Unsupported expected value: " + expected[i]);
        }
    }
}

private static String describe(Object[] expected) {
    final StringBuilder builder = new StringBuilder("fields [");
    for (int i = 0; i < expected.length; i++) {
        if (i > 0) {
            builder.append(", ");
        }
        builder.append(expected[i]);
    }
    return builder.append(']').toString();
}

