import static org.assertj.core.api.Assertions.assertThat;

/**
 * Tests for the {@code doEndElement} implementation of
 * {@link XmlResponsesSaxParser.ListBucketAnalyticsConfigurationHandler}.
 *
 * <p>The handler is package private in its inherited API, so the tests drive it through the public
 * {@link XmlResponsesSaxParser#parseListBucketAnalyticsConfigurationResponse(java.io.InputStream)}
 * entry point and assert on the resulting model object. This verifies the externally observable
 * effect of every branch in {@code doEndElement}.
 */
class XmlResponsesSaxParserDoEndElementTests {

    @Test
    void testParsesIdAndPrefixFilterForSingleConfiguration() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration>"
                                + "  <Id>config-1</Id>"
                                + "  <Filter><Prefix>logs/</Prefix></Filter>"
                                + "</AnalyticsConfiguration>");

        assertThat(result.getAnalyticsConfigurationList()).hasSize(1);
        AnalyticsConfiguration configuration = result.getAnalyticsConfigurationList().get(0);
        assertThat(configuration.getId()).isEqualTo("config-1");
        assertThat(configuration.getFilter()).isNotNull();

        AnalyticsFilterPredicate predicate = configuration.getFilter().getPredicate();
        assertThat(predicate).isInstanceOf(AnalyticsPrefixPredicate.class);
        assertThat(((AnalyticsPrefixPredicate) predicate).getPrefix()).isEqualTo("logs/");
    }

    @Test
    void testParsesMultipleConfigurationsInOrder() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration><Id>first</Id></AnalyticsConfiguration>"
                                + "<AnalyticsConfiguration><Id>second</Id></AnalyticsConfiguration>"
                                + "<AnalyticsConfiguration><Id>third</Id></AnalyticsConfiguration>");

        assertThat(result.getAnalyticsConfigurationList()).hasSize(3);
        assertThat(result.getAnalyticsConfigurationList())
                .extracting(AnalyticsConfiguration::getId)
                .containsExactly("first", "second", "third");
        // Each closing AnalyticsConfiguration must add a distinct instance to the list.
        assertThat(result.getAnalyticsConfigurationList().get(0))
                .isNotSameAs(result.getAnalyticsConfigurationList().get(1));
    }

    @Test
    void testParsesTagFilterPredicate() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration>"
                                + "  <Id>tagged</Id>"
                                + "  <Filter>"
                                + "    <Tag><Key>department</Key><Value>engineering</Value></Tag>"
                                + "  </Filter>"
                                + "</AnalyticsConfiguration>");

        AnalyticsFilterPredicate predicate =
                result.getAnalyticsConfigurationList().get(0).getFilter().getPredicate();
        assertThat(predicate).isInstanceOf(AnalyticsTagPredicate.class);
        Tag tag = ((AnalyticsTagPredicate) predicate).getTag();
        assertThat(tag.getKey()).isEqualTo("department");
        assertThat(tag.getValue()).isEqualTo("engineering");
    }

    @Test
    void testParsesAndFilterPredicateWithPrefixAndTagOperands() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration>"
                                + "  <Id>and-config</Id>"
                                + "  <Filter>"
                                + "    <And>"
                                + "      <Prefix>data/</Prefix>"
                                + "      <Tag><Key>env</Key><Value>prod</Value></Tag>"
                                + "    </And>"
                                + "  </Filter>"
                                + "</AnalyticsConfiguration>");

        AnalyticsFilterPredicate predicate =
                result.getAnalyticsConfigurationList().get(0).getFilter().getPredicate();
        assertThat(predicate).isInstanceOf(AnalyticsAndOperator.class);

        List<AnalyticsFilterPredicate> operands =
                ((AnalyticsAndOperator) predicate).getOperands();
