                                + "      <OutputSchemaVersion>V_1</OutputSchemaVersion>"
                                + "      <Destination>"
                                + "        <S3BucketDestination>"
                                + "          <Format>CSV</Format>"
                                + "          <BucketAccountId>123456789012</BucketAccountId>"
                                + "          <Bucket>arn:aws:s3:::target-bucket</Bucket>"
