        StorageClassAnalysis storageClassAnalysis = configuration.getStorageClassAnalysis();
        assertThat(storageClassAnalysis).isNotNull();

        StorageClassAnalysisDataExport dataExport = storageClassAnalysis.getDataExport();
        assertThat(dataExport).isNotNull();
        assertThat(dataExport.getOutputSchemaVersion()).isEqualTo("V_1");

        AnalyticsExportDestination destination = dataExport.getDestination();
        assertThat(destination).isNotNull();

        AnalyticsS3BucketDestination bucketDestination = destination.getS3BucketDestination();
        assertThat(bucketDestination).isNotNull();
        assertThat(bucketDestination.getFormat()).isEqualTo("CSV");
        assertThat(bucketDestination.getBucketAccountId()).isEqualTo("123456789012");
        assertThat(bucketDestination.getBucketArn()).isEqualTo("arn:aws:s3:::target-bucket");
        assertThat(bucketDestination.getPrefix()).isEqualTo("exports/");
    }

    @Test
    void testParsesStorageClassAnalysisWithoutDataExport() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration>"
                                + "  <Id>no-export</Id>"
                                + "  <StorageClassAnalysis></StorageClassAnalysis>"
                                + "</AnalyticsConfiguration>");

        StorageClassAnalysis storageClassAnalysis =
                result.getAnalyticsConfigurationList().get(0).getStorageClassAnalysis();
        assertThat(storageClassAnalysis).isNotNull();
        assertThat(storageClassAnalysis.getDataExport()).isNull();
    }

    @Test
    void testParsesFilterWithoutRecognizedPredicate() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration>"
                                + "  <Id>empty-filter</Id>"
                                + "  <Filter><Unknown>ignored</Unknown></Filter>"
                                + "</AnalyticsConfiguration>");

        AnalyticsConfiguration configuration = result.getAnalyticsConfigurationList().get(0);
        assertThat(configuration.getFilter()).isNotNull();
        assertThat(configuration.getFilter().getPredicate()).isNull();
    }

    @Test
    void testParsesResultLevelTruncationAndTokens() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<IsTruncated>true</IsTruncated>"
                                + "<ContinuationToken>continue-token</ContinuationToken>"
                                + "<NextContinuationToken>next-token</NextContinuationToken>");

        assertThat(result.isTruncated()).isTrue();
        assertThat(result.getContinuationToken()).isEqualTo("continue-token");
        assertThat(result.getNextContinuationToken()).isEqualTo("next-token");
        assertThat(result.getAnalyticsConfigurationList()).isNull();
    }

    @Test
    void testIsTruncatedOnlyTrueForExactTrueText() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse("<IsTruncated>true</IsTruncated>");
        assertThat(result.isTruncated()).isTrue();
    }

    @ParameterizedTest
    @ValueSource(strings = {"false", "TRUE", "1", "", " true", "true "})
    void testIsTruncatedStaysFalseForNonExactTrueText(String text) throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse("<IsTruncated>" + text + "</IsTruncated>");
        assertThat(result.isTruncated()).isFalse();
    }

    @Test
    void testEmptyResultProducesNoConfigurationsAndNoTokens() throws Exception {
        ListBucketAnalyticsConfigurationsResult result = parse("");

        assertThat(result.getAnalyticsConfigurationList()).isNull();
        assertThat(result.isTruncated()).isFalse();
        assertThat(result.getContinuationToken()).isNull();
        assertThat(result.getNextContinuationToken()).isNull();
    }

    @Test
    void testFilterStateDoesNotLeakBetweenConfigurations() throws Exception {
        ListBucketAnalyticsConfigurationsResult result =
                parse(
                        "<AnalyticsConfiguration>"
                                + "  <Id>with-filter</Id>"
                                + "  <Filter><Prefix>first/</Prefix></Filter>"
                                + "</AnalyticsConfiguration>"
                                + "<AnalyticsConfiguration>"
                                + "  <Id>without-filter</Id>"
                                + "</AnalyticsConfiguration>");

        assertThat(result.getAnalyticsConfigurationList()).hasSize(2);
        AnalyticsConfiguration first = result.getAnalyticsConfigurationList().get(0);
        AnalyticsConfiguration second = result.getAnalyticsConfigurationList().get(1);

        assertThat(first.getFilter()).isNotNull();
        assertThat(((AnalyticsPrefixPredicate) first.getFilter().getPredicate()).getPrefix())
                .isEqualTo("first/");
        assertThat(second.getId()).isEqualTo("without-filter");
        assertThat(second.getFilter()).isNull();
    }

    private static ListBucketAnalyticsConfigurationsResult parse(String body) throws IOException {
        String document =
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
                        + "<ListBucketAnalyticsConfigurationsResult>"
                        + body
                        + "</ListBucketAnalyticsConfigurationsResult>";
        return new XmlResponsesSaxParser()
                .parseListBucketAnalyticsConfigurationResponse(
                        new ByteArrayInputStream(document.getBytes(StandardCharsets.UTF_8)))
                .getResult();
    }
}
