            ClientOverrideConfiguration overrideConfig = overrideConfigBuilder.build();

            S3Client s3Client =
                    buildSyncClient(
                            credentialsProvider, awsRegion, s3Config, overrideConfig, endpointUri);
            S3AsyncClient asyncClient =
                    buildAsyncClient(
                            credentialsProvider, awsRegion, s3Config, overrideConfig, endpointUri);

            S3TransferManager transferManager =
                    S3TransferManager.builder().s3Client(asyncClient).build();

            return new S3ClientProvider(
                    s3Client,
                    asyncClient,
                    transferManager,
                    encryptionConfig,
                    credentialsProvider,
                    stsClient,
                    clientCloseTimeout,
                    connectionTimeout,
                    socketTimeout,
                    connectionMaxIdleTime,
                    pathStyleAccess,
                    chunkedEncoding,
                    checksumValidation,
                    maxConnections,
                    maxRetries,
                    retryBaseDelay,
                    retryThrottleBaseDelay,
                    retryMaxBackoff,
                    retryCircuitBreakerEnabled,
