                            ApacheHttpClient.builder()
                                    .maxConnections(maxConnections)
                                    .connectionTimeout(connectionTimeout)
                                    .socketTimeout(socketTimeout)
                                    .tcpKeepAlive(true)
                                    .connectionMaxIdleTime(connectionMaxIdleTime));
