                                    NettyNioAsyncHttpClient.builder()
                                            .maxConcurrency(maxConnections)
                                            .connectionTimeout(connectionTimeout)
                                            .readTimeout(socketTimeout)
                                            .connectionAcquisitionTimeout(connectionTimeout))
