import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link NativeS3FileSystemFactory#create(URI)}.
 *
 * <p>The tests focus on the observable contract of {@code create}: URI handling, exception
 * behaviour for invalid configuration, propagation of global configuration values into the created
 * file system / client provider, and the application of bucket-specific overrides.
 */
class NativeS3FileSystemFactoryCreateTests {

    private static final String BUCKET_URI = "s3://test-bucket/some/path";

    private final List<FileSystem> createdFileSystems = new ArrayList<>();

    @AfterEach
    void closeCreatedFileSystems() throws Exception {
        for (FileSystem fileSystem : createdFileSystems) {
            if (fileSystem instanceof AutoCloseableAsync) {
                ((AutoCloseableAsync) fileSystem).closeAsync().get(60, TimeUnit.SECONDS);
            }
        }
        createdFileSystems.clear();
    }

    // ------------------------------------------------------------------------
    //  helpers
    // ------------------------------------------------------------------------

    /**
     * Returns a configuration that allows {@code create} to succeed in an offline environment: the
     * region and endpoint are pinned and static credentials are provided so that no region or
     * credential resolution against the environment takes place.
     */
    private static Configuration baseConfig() {
        final Configuration config = new Configuration();
        config.set(NativeS3FileSystemFactory.REGION, "us-east-1");
        config.set(NativeS3FileSystemFactory.ENDPOINT, "http://s3.local:9000");
        config.set(NativeS3FileSystemFactory.ACCESS_KEY, "test-access-key");
        config.set(NativeS3FileSystemFactory.SECRET_KEY, "test-secret-key");
        config.set(NativeS3FileSystemFactory.BULK_COPY_ENABLED, false);
        return config;
    }

    private NativeS3FileSystem createFileSystem(Configuration config, String uri)
            throws IOException {
        return (NativeS3FileSystem) createFileSystemInternal(createFactory(config), uri);
    }

    private NativeS3FileSystemFactory createFactory(Configuration config) {
        final NativeS3FileSystemFactory factory = new NativeS3FileSystemFactory();
        factory.configure(config);
        return factory;
    }

    private FileSystem createFileSystemInternal(NativeS3FileSystemFactory factory, String uri)
            throws IOException {
        final FileSystem fileSystem = factory.create(URI.create(uri));
        createdFileSystems.add(fileSystem);
        return fileSystem;
    }

    private void assertCreateFails(
            Configuration config,
            String uri,
            Class<? extends Throwable> expectedType,
            String... expectedMessageParts) {
        final Throwable thrown = assertThrows(expectedType, () -> createFileSystem(config, uri));
        assertMessageContains(thrown, expectedMessageParts);
    }

    private static void assertMessageContains(Throwable thrown, String... expectedMessageParts) {
        final String message = thrown.getMessage();
        assertNotNull(message, "expected an exception message but none was present");
        for (String expectedPart : expectedMessageParts) {
            assertTrue(
                    message.contains(expectedPart),
                    "expected exception message to contain '"
                            + expectedPart
                            + "' but was: "
                            + message);
        }
    }

    private static Object readField(Object target, String fieldName) {
        try {
            final Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            return field.get(target);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(
                    "Unable to read field '" + fieldName + "' from " + target.getClass(), e);
        }

    }
}

private static long readLongField(Object target, String fieldName) {
    return ((Number) readField(target, fieldName)).longValue();
}

// ------------------------------------------------------------------------
//  happy path / URI handling
// ------------------------------------------------------------------------

@Test
void testCreateReturnsFileSystemBoundToUri() throws Exception {
    final NativeS3FileSystem fileSystem = createFileSystem(baseConfig(), BUCKET_URI);

    assertNotNull(fileSystem);
    assertEquals(URI.create(BUCKET_URI), fileSystem.getUri());
    assertEquals("test-bucket", fileSystem.getUri().getHost());
    assertEquals(new Path(BUCKET_URI), fileSystem.getWorkingDirectory());
    assertEquals(new Path(BUCKET_URI), fileSystem.getHomeDirectory());
    assertTrue(fileSystem.isDistributedFS());
    assertNull(fileSystem.getEntropyInjectionKey());
    assertNotNull(fileSystem.getClientProvider());
}

@Test
void testCreateDerivesBucketNameFromHostIgnoringPort() throws Exception {
    final NativeS3FileSystem fileSystem =
            createFileSystem(baseConfig(), "s3://test-bucket:9000/some/path");

    assertEquals("test-bucket", fileSystem.getUri().getHost());
    assertEquals(9000, fileSystem.getUri().getPort());
}

@Test
void testCreateWithoutConfiguredFactoryUsesDefaultsAndRejectsMissingBucket() {
    final NativeS3FileSystemFactory factory = new NativeS3FileSystemFactory();

    final IOException thrown =
            assertThrows(IOException.class, () -> factory.create(URI.create("s3:/path/only")));

    assertMessageContains(thrown, "missing or empty bucket name");
}

@Test
void testCreateRejectsUriWithoutBucketName() {
    assertCreateFails(
            baseConfig(),
            "s3:///path/to/file",
            IOException.class,
            "Invalid S3 URI",
            "missing or empty bucket name",
            "s3:///path/to/file");
}

@Test
void testCreatePropagatesGlobalClientConfiguration() throws Exception {
    final Configuration config = baseConfig();
    config.set(NativeS3FileSystemFactory.PATH_STYLE_ACCESS, true);
    config.set(NativeS3FileSystemFactory.CHUNKED_ENCODING_ENABLED, false);
    config.set(NativeS3FileSystemFactory.CHECKSUM_VALIDATION_ENABLED, false);
    config.set(NativeS3FileSystemFactory.MAX_CONNECTIONS, 7);
    config.set(NativeS3FileSystemFactory.CONNECTION_TIMEOUT, Duration.ofSeconds(11));
    config.set(NativeS3FileSystemFactory.SOCKET_TIMEOUT, Duration.ofSeconds(22));
    config.set(NativeS3FileSystemFactory.CONNECTION_MAX_IDLE_TIME, Duration.ofSeconds(33));
    config.set(NativeS3FileSystemFactory.CLIENT_CLOSE_TIMEOUT, Duration.ofSeconds(44));
    config.set(NativeS3FileSystemFactory.FS_CLOSE_TIMEOUT, Duration.ofSeconds(55));
    config.set(NativeS3FileSystemFactory.MAX_RETRIES, 9);
    config.set(NativeS3FileSystemFactory.RETRY_BASE_DELAY, Duration.ofMillis(50));
    config.set(NativeS3FileSystemFactory.RETRY_THROTTLE_BASE_DELAY, Duration.ofMillis(60));
    config.set(NativeS3FileSystemFactory.RETRY_MAX_BACKOFF, Duration.ofSeconds(2));
    config.set(NativeS3FileSystemFactory.RETRY_CIRCUIT_BREAKER_ENABLED, false);
    config.set(NativeS3FileSystemFactory.DELETE_BATCH_ENABLED, false);

    final NativeS3FileSystem fileSystem = createFileSystem(config, BUCKET_URI);
    final S3ClientProvider provider = fileSystem.getClientProvider();

    assertTrue(provider.isPathStyleAccess());
    assertFalse(provider.isChunkedEncoding());
    assertFalse(provider.isChecksumValidation());
    assertEquals(7, provider.getMaxConnections());
    assertEquals(Duration.ofSeconds(11), provider.getConnectionTimeout());
    assertEquals(Duration.ofSeconds(22), provider.getSocketTimeout());
    assertEquals(Duration.ofSeconds(33), provider.getConnectionMaxIdleTime());
    assertEquals(Duration.ofSeconds(44), provider.getClientCloseTimeout());
    assertEquals(9, provider.getMaxRetries());
    assertEquals(10, provider.getMaxAttempts());
    assertEquals(Duration.ofMillis(50), provider.getRetryBaseDelay());
    assertEquals(Duration.ofMillis(60), provider.getRetryThrottleBaseDelay());
    assertEquals(Duration.ofSeconds(2), provider.getRetryMaxBackoff());
    assertFalse(provider.isRetryCircuitBreakerEnabled());
    assertEquals("us-east-1", provider.getRegion());
    assertEquals("http://s3.local:9000", provider.getEndpoint());

    assertEquals(Duration.ofSeconds(55), fileSystem.getFsCloseTimeout());
    assertFalse(fileSystem.isDeleteBatchEnabled());
    assertNull(fileSystem.getBulkCopyHelper());
    assertFalse(provider.isUseCrt());
}

@Test
void testCreateUsesDocumentedDefaults() throws Exception {
    final Configuration config = new Configuration();
    config.set(NativeS3FileSystemFactory.REGION, "us-east-1");
    config.set(NativeS3FileSystemFactory.ENDPOINT, "http://s3.local:9000");

    final NativeS3FileSystem fileSystem = createFileSystem(config, BUCKET_URI);
    final S3ClientProvider provider = fileSystem.getClientProvider();

    assertEquals("us-east-1", provider.getRegion());
    assertEquals("http://s3.local:9000", provider.getEndpoint());
    assertEquals(
            NativeS3FileSystemFactory.MAX_CONNECTIONS.defaultValue().intValue(),
            provider.getMaxConnections());
    assertEquals(
            NativeS3FileSystemFactory.MAX_RETRIES.defaultValue().intValue(),
            provider.getMaxRetries());
    assertEquals(
            NativeS3FileSystemFactory.CHUNKED_ENCODING_ENABLED.defaultValue(),
            provider.isChunkedEncoding());
    assertEquals(
            NativeS3FileSystemFactory.CHECKSUM_VALIDATION_ENABLED.defaultValue(),
            provider.isChecksumValidation());
    assertEquals(
            NativeS3FileSystemFactory.PATH_STYLE_ACCESS.defaultValue(),
            provider.isPathStyleAccess());
    assertEquals(
            NativeS3FileSystemFactory.DELETE_BATCH_ENABLED.defaultValue(),
            fileSystem.isDeleteBatchEnabled());
    assertEquals(
            NativeS3FileSystemFactory.FS_CLOSE_TIMEOUT.defaultValue(),
            fileSystem.getFsCloseTimeout());
    assertFalse(provider.isUseCrt());
    // bulk copy is enabled by default, hence a bulk copy helper must be created
    assertNotNull(fileSystem.getBulkCopyHelper());
}

@Test
void testCreatePropagatesStaticCredentialConfiguration() throws Exception {
    final Configuration config = baseConfig();
    config.set(NativeS3FileSystemFactory.ACCESS_KEY, "my-key");
    config.set(NativeS3FileSystemFactory.SECRET_KEY, "my-secret");

    final NativeS3FileSystem fileSystem = createFileSystem(config, BUCKET_URI);
