/**
 * Tests for {@link AvroSchemaConverter#convertToSchema(LogicalType, String, boolean)}.
 *
 * <p>All tests are independent and only rely on the observable Avro {@link Schema} that is
 * derived from a Flink {@link LogicalType}.
 */
class AvroSchemaConverterConvertToSchemaTests {

    private static final String ROW_NAME = "test_record";

    // ------------------------------------------------------------------------------------------
    // Null type
    // ------------------------------------------------------------------------------------------

    @Test
    void testNullType() {
        final Schema schema = convert(DataTypes.NULL(), true);

        assertThat(schema.getType()).isEqualTo(Schema.Type.NULL);
        assertThat(schema.getLogicalType()).isNull();
    }

    // ------------------------------------------------------------------------------------------
    // Primitive types
    // ------------------------------------------------------------------------------------------

    @Test
    void testBooleanType() {
        assertThat(convert(DataTypes.BOOLEAN().notNull(), true).getType())
                .isEqualTo(Schema.Type.BOOLEAN);

        final Schema nullable = convert(DataTypes.BOOLEAN(), true);
        assertNullableUnion(nullable);
        assertThat(nullable.getTypes().get(1).getType()).isEqualTo(Schema.Type.BOOLEAN);
    }

    @Test
    void testIntFamilyTypes() {
        for (DataType dataType :
                new DataType[] {DataTypes.TINYINT(), DataTypes.SMALLINT(), DataTypes.INT()}) {
            final Schema notNull = convert(dataType.notNull(), true);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.INT);
            assertThat(notNull.isNullable()).isFalse();

            final Schema nullable = convert(dataType, true);
            assertNullableUnion(nullable);
            assertThat(nullable.getTypes().get(1).getType()).isEqualTo(Schema.Type.INT);
        }
    }

    @Test
    void testBigIntType() {
        final Schema notNull = convert(DataTypes.BIGINT().notNull(), true);
        assertThat(notNull.getType()).isEqualTo(Schema.Type.LONG);

        final Schema nullable = convert(DataTypes.BIGINT(), true);
        assertNullableUnion(nullable);
        assertThat(nullable.getTypes().get(1).getType()).isEqualTo(Schema.Type.LONG);
    }

    @Test
    void testFloatAndDoubleTypes() {
        assertThat(convert(DataTypes.FLOAT().notNull(), true).getType())
                .isEqualTo(Schema.Type.FLOAT);
        assertThat(convert(DataTypes.DOUBLE().notNull(), true).getType())
                .isEqualTo(Schema.Type.DOUBLE);

        assertNullableUnion(convert(DataTypes.FLOAT(), true));
        assertNullableUnion(convert(DataTypes.DOUBLE(), true));
    }

    @Test
    void testCharAndVarcharTypes() {
        for (DataType dataType : new DataType[] {DataTypes.CHAR(5), DataTypes.STRING()}) {
            final Schema notNull = convert(dataType.notNull(), true);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.STRING);

            final Schema nullable = convert(dataType, true);
            assertNullableUnion(nullable);
            assertThat(nullable.getTypes().get(1).getType()).isEqualTo(Schema.Type.STRING);
        }
    }

    @Test
    void testBinaryAndVarbinaryTypes() {
        for (DataType dataType : new DataType[] {DataTypes.BINARY(3), DataTypes.BYTES()}) {
            final Schema notNull = convert(dataType.notNull(), true);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.BYTES);

            final Schema nullable = convert(dataType, true);
            assertNullableUnion(nullable);
            assertThat(nullable.getTypes().get(1).getType()).isEqualTo(Schema.Type.BYTES);
        }
    }

    // ------------------------------------------------------------------------------------------
    // Timestamp without time zone
    // ------------------------------------------------------------------------------------------

    @Test
    void testLegacyTimestampWithinMillisPrecision() {
        for (int precision = 0; precision <= 3; precision++) {
            final Schema notNull = convert(DataTypes.TIMESTAMP(precision).notNull(), true);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.LONG);
            assertThat(notNull.getLogicalType().getName()).isEqualTo("timestamp-millis");

            final Schema nullable = convert(DataTypes.TIMESTAMP(precision), true);
            assertNullableUnion(nullable);
            final Schema actual = nullable.getTypes().get(1);
            assertThat(actual.getType()).isEqualTo(Schema.Type.LONG);
            assertThat(actual.getLogicalType().getName()).isEqualTo("timestamp-millis");
        }
    }

    @Test
    void testLegacyTimestampRejectsPrecisionAboveMillis() {
        for (int precision = 4; precision <= 9; precision++) {
            final int expectedPrecision = precision;
            assertThatThrownBy(() -> convert(DataTypes.TIMESTAMP(expectedPrecision), true))
                    .isInstanceOf(IllegalArgumentException.class)
                    .hasMessage(
                            "Avro does not support TIMESTAMP type with precision: "
                                    + expectedPrecision
                                    + ", it only supports precision less than 3.");
        }
    }

    @Test
    void testNonLegacyTimestampWithMillisAndMicrosPrecision() {
        for (int precision = 0; precision <= 3; precision++) {
            final Schema notNull = convert(DataTypes.TIMESTAMP(precision).notNull(), false);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.LONG);
            assertThat(notNull.getLogicalType().getName()).isEqualTo("local-timestamp-millis");
        }

        for (int precision = 4; precision <= 6; precision++) {
            final Schema notNull = convert(DataTypes.TIMESTAMP(precision).notNull(), false);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.LONG);
            assertThat(notNull.getLogicalType().getName()).isEqualTo("local-timestamp-micros");
        }

        final Schema nullable = convert(DataTypes.TIMESTAMP(6), false);
        assertNullableUnion(nullable);
        final Schema actual = nullable.getTypes().get(1);
        assertThat(actual.getType()).isEqualTo(Schema.Type.LONG);
        assertThat(actual.getLogicalType().getName()).isEqualTo("local-timestamp-micros");
    }

    @Test
    void testNonLegacyTimestampRejectsPrecisionAboveMicros() {
        for (int precision = 7; precision <= 9; precision++) {
            final int expectedPrecision = precision;
            assertThatThrownBy(() -> convert(DataTypes.TIMESTAMP(expectedPrecision), false))
                    .isInstanceOf(IllegalArgumentException.class)
                    .hasMessage(
                            "Avro does not support LOCAL TIMESTAMP type with precision: "
                                    + expectedPrecision
                                    + ", it only supports precision less than 6.");
        }
    }

