    // ------------------------------------------------------------------------------------------

    @Test
    void testDateType() {
        final Schema notNull = convert(DataTypes.DATE().notNull(), true);
        assertThat(notNull.getType()).isEqualTo(Schema.Type.INT);
        assertThat(notNull.getLogicalType().getName()).isEqualTo("date");

        final Schema nullable = convert(DataTypes.DATE(), true);
        assertNullableUnion(nullable);
        final Schema actual = nullable.getTypes().get(1);
        assertThat(actual.getType()).isEqualTo(Schema.Type.INT);
        assertThat(actual.getLogicalType().getName()).isEqualTo("date");
    }

    @Test
    void testTimeTypeWithinMillisPrecision() {
        for (int precision = 0; precision <= 3; precision++) {
            final Schema notNull = convert(DataTypes.TIME(precision).notNull(), true);
            assertThat(notNull.getType()).isEqualTo(Schema.Type.INT);
            assertThat(notNull.getLogicalType().getName()).isEqualTo("time-millis");
        }

        final Schema nullable = convert(DataTypes.TIME(3), true);
        assertNullableUnion(nullable);
        final Schema actual = nullable.getTypes().get(1);
        assertThat(actual.getType()).isEqualTo(Schema.Type.INT);
        assertThat(actual.getLogicalType().getName()).isEqualTo("time-millis");
