    @Test
    void testTimeTypeRejectsPrecisionAboveMillis() {
        assertThatThrownBy(() -> convert(DataTypes.TIME(4), true))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage(
                        "Avro does not support TIME type with precision: 4, "
                                + "it only supports precision less than 3.");

        assertThatThrownBy(() -> convert(DataTypes.TIME(9).notNull(), true))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage(
                        "Avro does not support TIME type with precision: 9, "
                                + "it only supports precision less than 3.");
    }

    @Test
    void testDecimalType() {
        final Schema notNull = convert(DataTypes.DECIMAL(10, 2).notNull(), true);
        assertThat(notNull.getType()).isEqualTo(Schema.Type.BYTES);
        assertThat(notNull.getLogicalType()).isInstanceOf(LogicalTypes.Decimal.class);
        final LogicalTypes.Decimal decimal = (LogicalTypes.Decimal) notNull.getLogicalType();
        assertThat(decimal.getPrecision()).isEqualTo(10);
        assertThat(decimal.getScale()).isEqualTo(2);

        final Schema nullable = convert(DataTypes.DECIMAL(38, 18), true);
        assertNullableUnion(nullable);
        final Schema actual = nullable.getTypes().get(1);
        assertThat(actual.getType()).isEqualTo(Schema.Type.BYTES);
        final LogicalTypes.Decimal nullableDecimal =
                (LogicalTypes.Decimal) actual.getLogicalType();
        assertThat(nullableDecimal.getPrecision()).isEqualTo(38);
        assertThat(nullableDecimal.getScale()).isEqualTo(18);
    }

    // ------------------------------------------------------------------------------------------
