    // ------------------------------------------------------------------------------------------

    @Test
    void testRowTypeWithMandatoryAndOptionalFields() {
        final DataType rowDataType =
                DataTypes.ROW(
                        DataTypes.FIELD("id", DataTypes.INT().notNull()),
                        DataTypes.FIELD("name", DataTypes.STRING()),
                        DataTypes.FIELD("score", DataTypes.DOUBLE().notNull()));

        final Schema schema = convert(rowDataType.notNull(), true);

        assertThat(schema.getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(schema.getName()).isEqualTo(ROW_NAME);
        assertThat(schema.getFields()).hasSize(3);
        assertThat(schema.getFields().get(0).name()).isEqualTo("id");
        assertThat(schema.getFields().get(1).name()).isEqualTo("name");
        assertThat(schema.getFields().get(2).name()).isEqualTo("score");

        final Schema.Field idField = schema.getField("id");
        assertThat(idField.schema().getType()).isEqualTo(Schema.Type.INT);
        assertThat(idField.hasDefaultValue()).isFalse();

        final Schema.Field nameField = schema.getField("name");
        assertThat(nameField.schema().getType()).isEqualTo(Schema.Type.UNION);
        assertThat(nameField.schema().getTypes().get(0).getType()).isEqualTo(Schema.Type.NULL);
        assertThat(nameField.schema().getTypes().get(1).getType()).isEqualTo(Schema.Type.STRING);
        assertThat(nameField.hasDefaultValue()).isTrue();
        assertThat(nameField.defaultVal()).isNull();

        final Schema.Field scoreField = schema.getField("score");
        assertThat(scoreField.schema().getType()).isEqualTo(Schema.Type.DOUBLE);
        assertThat(scoreField.hasDefaultValue()).isFalse();
    }

    @Test
    void testNullableRowTypeIsWrappedInUnion() {
        final DataType rowDataType =
                DataTypes.ROW(DataTypes.FIELD("id", DataTypes.INT().notNull()));

        final Schema schema = convert(rowDataType, true);

        assertNullableUnion(schema);
        final Schema actual = schema.getTypes().get(1);
        assertThat(actual.getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(actual.getName()).isEqualTo(ROW_NAME);
        assertThat(actual.getFields()).hasSize(1);
        assertThat(actual.getField("id").schema().getType()).isEqualTo(Schema.Type.INT);
