        assertThat(schema.getName()).isEqualTo(ROW_NAME);
        final Schema inner = schema.getField("inner").schema();
        assertThat(inner.getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(inner.getName()).isEqualTo(ROW_NAME + "_inner");
        assertThat(inner.getField("value").schema().getType()).isEqualTo(Schema.Type.LONG);
    }

    @Test
    void testNestedRowPropagatesLegacyTimestampMapping() {
        final DataType rowDataType =
