    @Test
    void testDecimalType() {
        final Schema notNull = convert(DataTypes.DECIMAL(10, 2).notNull(), true);
        assertThat(notNull.getType()).isEqualTo(Schema.Type.BYTES);
        assertThat(notNull.getLogicalType()).isInstanceOf(LogicalTypes.Decimal.class);
        final LogicalTypes.Decimal decimal = (LogicalTypes.Decimal) notNull.getLogicalType();
        assertThat(decimal.getPrecision()).isEqualTo(10);
