    @Test
    void testNestedRowUsesPrefixedRecordName() {
        final DataType rowDataType =
                DataTypes.ROW(
                        DataTypes.FIELD(
                                "inner",
                                DataTypes.ROW(
                                                DataTypes.FIELD(
                                                        "value", DataTypes.BIGINT().notNull()))
                                        .notNull()));

        final Schema schema = convert(rowDataType.notNull(), true);

        assertThat(schema.getName()).isEqualTo(ROW_NAME);
        final Schema inner = schema.getField("inner").schema();
        assertThat(inner.getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(inner.getName()).isEqualTo(ROW_NAME + "_inner");
        assertThat(inner.getField("value").schema().getType()).isEqualTo(Schema.Type.LONG);
    }

    @Test
    void testNestedRowPropagatesLegacyTimestampMapping() {
        final DataType nestedRowDataType =
                DataTypes.ROW(
                        DataTypes.FIELD("ts", DataTypes.TIMESTAMP(3).notNull()),
                        DataTypes.FIELD(
                                "nested",
                                DataTypes.ROW(
                                                DataTypes.FIELD(
                                                        "nested_ts",
                                                        DataTypes.TIMESTAMP(6).notNull()))
                                        .notNull()));

        // with the legal mapping nested timestamps use the (local) timestamp logical types
        final Schema legal = convert(nestedRowDataType.notNull(), false);
        assertThat(legal.getField("ts").schema().getLogicalType().getName())
                .isEqualTo("local-timestamp-millis");
        assertThat(
                        legal.getField("nested")
                                .schema()
                                .getField("nested_ts")
                                .schema()
                                .getLogicalType()
                                .getName())
                .isEqualTo("local-timestamp-micros");

        // with the legacy mapping nested millisecond timestamps are mapped as well
        final DataType legacyRowDataType =
                DataTypes.ROW(
                        DataTypes.FIELD("ts", DataTypes.TIMESTAMP(3).notNull()),
                        DataTypes.FIELD(
                                "nested",
                                DataTypes.ROW(
                                                DataTypes.FIELD(
                                                        "nested_ts",
                                                        DataTypes.TIMESTAMP(3).notNull()))
                                        .notNull()));
        final Schema legacy = convert(legacyRowDataType.notNull(), true);
        assertThat(legacy.getField("ts").schema().getLogicalType().getName())
                .isEqualTo("timestamp-millis");
        assertThat(
                        legacy.getField("nested")
                                .schema()
                                .getField("nested_ts")
                                .schema()
                                .getLogicalType()
                                .getName())
                .isEqualTo("timestamp-millis");

        // the legacy mapping does not support microsecond precision in nested rows either
        assertThatThrownBy(() -> convert(nestedRowDataType.notNull(), true))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage(
                        "Avro does not support TIMESTAMP type with precision: 6, "
                                + "it only supports precision less than 3.");
    }

