import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link ParquetSplitReaderUtil#createWritableColumnVector(int, LogicalType, Type, List,
 * int)}.
 */
class ParquetSplitReaderUtilCreateWritableColumnVectorTests {

    private static final int BATCH_SIZE = 7;

    // ------------------------------------------------------------------------
    //  Helpers
    // ------------------------------------------------------------------------

    private static PrimitiveType primitive(PrimitiveTypeName typeName, String fieldName) {
        return Types.optional(typeName).named(fieldName);
    }

    private static PrimitiveType decimalPrimitive(
            PrimitiveTypeName typeName, int precision, int scale, int length, String fieldName) {
        if (typeName == PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY) {
            return Types.optional(typeName)
                    .length(length)
                    .as(LogicalTypeAnnotation.decimalType(scale, precision))
                    .named(fieldName);
        }
        return Types.optional(typeName)
                .as(LogicalTypeAnnotation.decimalType(scale, precision))
                .named(fieldName);
    }

    private static ColumnDescriptor descriptor(PrimitiveType primitiveType, String... path) {
        return new ColumnDescriptor(path, primitiveType, 0, 0);
    }

    private static WritableColumnVector createVector(
            LogicalType fieldType, Type parquetType, ColumnDescriptor... descriptors) {
        return ParquetSplitReaderUtil.createWritableColumnVector(
                BATCH_SIZE, fieldType, parquetType, Arrays.asList(descriptors), 0);
    }

    private static WritableColumnVector createVector(
            int batchSize,
            LogicalType fieldType,
            Type parquetType,
            List<ColumnDescriptor> descriptors,
            int depth) {
        return ParquetSplitReaderUtil.createWritableColumnVector(
                batchSize, fieldType, parquetType, descriptors, depth);
    }

    private static void assertHeapVector(
            WritableColumnVector vector, Class<? extends WritableColumnVector> expectedClass) {
        assertEquals(expectedClass, vector.getClass());
        assertInstanceOf(AbstractHeapVector.class, vector);
        assertEquals(BATCH_SIZE, ((AbstractHeapVector) vector).getLen());
    }

    private static void assertPrimitiveMapping(
            LogicalType fieldType,
            PrimitiveTypeName parquetTypeName,
            Class<? extends WritableColumnVector> expectedClass) {
        PrimitiveType parquetType = primitive(parquetTypeName, "f");
        WritableColumnVector vector =
                createVector(fieldType, parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, expectedClass);
    }

    private static void assertUnexpectedParquetType(
            LogicalType fieldType, PrimitiveTypeName parquetTypeName) {
        PrimitiveType parquetType = primitive(parquetTypeName, "f");
        IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
                        () ->
                                createVector(
                                        fieldType, parquetType, descriptor(parquetType, "f")));
        assertNotNull(exception.getMessage());
        assertTrue(
                exception.getMessage().contains("Unexpected type: " + parquetTypeName),
                "Unexpected message: " + exception.getMessage());
    }

    // ------------------------------------------------------------------------
    //  Primitive types
    // ------------------------------------------------------------------------

    @Test
    void testBooleanFieldCreatesHeapBooleanVector() {
        assertPrimitiveMapping(
                new BooleanType(), PrimitiveTypeName.BOOLEAN, HeapBooleanVector.class);
    }

    @Test
    void testTinyIntFieldCreatesHeapByteVector() {
        assertPrimitiveMapping(new TinyIntType(), PrimitiveTypeName.INT32, HeapByteVector.class);
    }

    @Test
    void testSmallIntFieldCreatesHeapShortVector() {
        assertPrimitiveMapping(new SmallIntType(), PrimitiveTypeName.INT32, HeapShortVector.class);
    }

    @Test
    void testIntFieldCreatesHeapIntVector() {
        assertPrimitiveMapping(new IntType(), PrimitiveTypeName.INT32, HeapIntVector.class);
    }

    @Test
    void testDateFieldCreatesHeapIntVector() {
        assertPrimitiveMapping(new DateType(), PrimitiveTypeName.INT32, HeapIntVector.class);
    }

    @Test
    void testTimeFieldCreatesHeapIntVector() {
        assertPrimitiveMapping(new TimeType(), PrimitiveTypeName.INT32, HeapIntVector.class);
    }

    @Test
    void testBigIntFieldCreatesHeapLongVector() {
        assertPrimitiveMapping(new BigIntType(), PrimitiveTypeName.INT64, HeapLongVector.class);
    }

    @Test
    void testFloatFieldCreatesHeapFloatVector() {
        assertPrimitiveMapping(new FloatType(), PrimitiveTypeName.FLOAT, HeapFloatVector.class);
    }

    @Test
    void testDoubleFieldCreatesHeapDoubleVector() {
        assertPrimitiveMapping(new DoubleType(), PrimitiveTypeName.DOUBLE, HeapDoubleVector.class);
    }

    @Test
    void testCharFieldCreatesHeapBytesVector() {
        assertPrimitiveMapping(new CharType(3), PrimitiveTypeName.BINARY, HeapBytesVector.class);
    }

    @Test
    void testVarCharFieldCreatesHeapBytesVector() {
        assertPrimitiveMapping(
                new VarCharType(20), PrimitiveTypeName.BINARY, HeapBytesVector.class);
    }

    @Test
    void testBinaryFieldCreatesHeapBytesVector() {
        assertPrimitiveMapping(new BinaryType(8), PrimitiveTypeName.BINARY, HeapBytesVector.class);
    }

    @Test
    void testVarBinaryFieldCreatesHeapBytesVector() {
        assertPrimitiveMapping(
                new VarBinaryType(20), PrimitiveTypeName.BINARY, HeapBytesVector.class);
    }

    @Test
    void testTimestampWithInt64CreatesHeapTimestampVector() {
        assertPrimitiveMapping(
                new TimestampType(), PrimitiveTypeName.INT64, HeapTimestampVector.class);
    }

    @Test
    void testTimestampWithInt96CreatesHeapTimestampVector() {
        assertPrimitiveMapping(
                new TimestampType(), PrimitiveTypeName.INT96, HeapTimestampVector.class);
    }

    @Test
    void testLocalZonedTimestampCreatesHeapTimestampVector() {
        assertPrimitiveMapping(
                new LocalZonedTimestampType(), PrimitiveTypeName.INT64, HeapTimestampVector.class);
    }

    @Test
    void testBatchSizeIsUsedAsVectorCapacity() {
        PrimitiveType parquetType = primitive(PrimitiveTypeName.INT32, "f");
        WritableColumnVector vector =
                createVector(
                        0,
                        new IntType(),
                        parquetType,
                        Collections.singletonList(descriptor(parquetType, "f")),
                        0);
        assertInstanceOf(HeapIntVector.class, vector);
        assertEquals(0, ((AbstractHeapVector) vector).getLen());
    }

    // ------------------------------------------------------------------------
    //  Mismatching parquet types
    // ------------------------------------------------------------------------

    @Test
    void testBooleanFieldRejectsNonBooleanParquetType() {
        assertUnexpectedParquetType(new BooleanType(), PrimitiveTypeName.INT32);
    }

    @Test
    void testTinyIntFieldRejectsNonInt32ParquetType() {
        assertUnexpectedParquetType(new TinyIntType(), PrimitiveTypeName.INT64);
    }

    @Test
    void testSmallIntFieldRejectsNonInt32ParquetType() {
        assertUnexpectedParquetType(new SmallIntType(), PrimitiveTypeName.INT64);
    }

    @Test
    void testIntFieldRejectsNonInt32ParquetType() {
        assertUnexpectedParquetType(new IntType(), PrimitiveTypeName.INT64);
    }

    @Test
    void testBigIntFieldRejectsNonInt64ParquetType() {
        assertUnexpectedParquetType(new BigIntType(), PrimitiveTypeName.INT32);
    }

    @Test
    void testFloatFieldRejectsNonFloatParquetType() {
        assertUnexpectedParquetType(new FloatType(), PrimitiveTypeName.DOUBLE);
    }

    @Test
    void testDoubleFieldRejectsNonDoubleParquetType() {
        assertUnexpectedParquetType(new DoubleType(), PrimitiveTypeName.FLOAT);
    }

    @Test
    void testVarCharFieldRejectsNonBinaryParquetType() {
        assertUnexpectedParquetType(new VarCharType(20), PrimitiveTypeName.INT32);
    }

    @Test
    void testTimestampFieldRejectsBinaryParquetType() {
        assertUnexpectedParquetType(new TimestampType(), PrimitiveTypeName.BINARY);
    }

    // ------------------------------------------------------------------------
    //  Decimal types
    // ------------------------------------------------------------------------

    @Test
    void testDecimalWithInt32StorageCreatesHeapIntVector() {
        PrimitiveType parquetType = decimalPrimitive(PrimitiveTypeName.INT32, 5, 2, 0, "f");
        WritableColumnVector vector =
                createVector(new DecimalType(5, 2), parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, HeapIntVector.class);
    }

    @Test
    void testDecimalWithPrecisionNineAndFixedLenBytesCreatesHeapIntVector() {
        PrimitiveType parquetType =
                decimalPrimitive(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, 9, 0, 4, "f");
        WritableColumnVector vector =
                createVector(new DecimalType(9, 0), parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, HeapIntVector.class);
    }

    @Test
    void testDecimalWithInt64StorageCreatesHeapLongVector() {
        PrimitiveType parquetType = decimalPrimitive(PrimitiveTypeName.INT64, 10, 3, 0, "f");
        WritableColumnVector vector =
                createVector(new DecimalType(10, 3), parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, HeapLongVector.class);
    }

    @Test
    void testDecimalWithPrecisionEighteenAndFixedLenBytesCreatesHeapLongVector() {
        PrimitiveType parquetType =
                decimalPrimitive(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, 18, 0, 8, "f");
        WritableColumnVector vector =
                createVector(new DecimalType(18, 0), parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, HeapLongVector.class);
    }

    @Test
    void testDecimalWithBinaryStorageCreatesHeapBytesVector() {
        PrimitiveType parquetType = decimalPrimitive(PrimitiveTypeName.BINARY, 19, 4, 0, "f");
        WritableColumnVector vector =
                createVector(new DecimalType(19, 4), parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, HeapBytesVector.class);
    }

    @Test
    void testDecimalWithPrecisionThirtyEightAndFixedLenBytesCreatesHeapBytesVector() {
        PrimitiveType parquetType =
                decimalPrimitive(PrimitiveTypeName.FIXED_LEN_BYTE_ARRAY, 38, 18, 16, "f");
        WritableColumnVector vector =
                createVector(new DecimalType(38, 18), parquetType, descriptor(parquetType, "f"));
        assertHeapVector(vector, HeapBytesVector.class);
    }

    @Test
    void testSmallPrecisionDecimalRejectsBinaryParquetType() {
        PrimitiveType parquetType = decimalPrimitive(PrimitiveTypeName.BINARY, 5, 2, 0, "f");
        assertThrows(
                IllegalArgumentException.class,
                () -> createVector(new DecimalType(5, 2), parquetType, descriptor(parquetType, "f")));
    }

    @Test
    void testMediumPrecisionDecimalRejectsInt32ParquetType() {
        PrimitiveType parquetType = decimalPrimitive(PrimitiveTypeName.INT32, 12, 2, 0, "f");
        assertThrows(
                IllegalArgumentException.class,
                () ->
                        createVector(
                                new DecimalType(12, 2), parquetType, descriptor(parquetType, "f")));
    }

    @Test
    void testDecimalParquetTypeWithoutDecimalAnnotationIsRejected() {
        PrimitiveType parquetType = primitive(PrimitiveTypeName.INT32, "f");
        assertThrows(
                IllegalArgumentException.class,
                () -> createVector(new DecimalType(5, 2), parquetType, descriptor(parquetType, "f")));
    }

    // ------------------------------------------------------------------------
    //  Descriptor lookup and depth handling
    // ------------------------------------------------------------------------

    @Test
    void testDescriptorIsSelectedByTypeName() {
        PrimitiveType otherType = primitive(PrimitiveTypeName.INT32, "other");
        PrimitiveType matchingType = primitive(PrimitiveTypeName.INT64, "f");

        WritableColumnVector vector =
                createVector(
                        new BigIntType(),
                        matchingType,
                        descriptor(otherType, "other"),
                        descriptor(matchingType, "f"));

        assertHeapVector(vector, HeapLongVector.class);
    }

    @Test
    void testFirstMatchingDescriptorDeterminesPrimitiveType() {
        PrimitiveType firstMatch = primitive(PrimitiveTypeName.INT64, "f");
        PrimitiveType secondMatch = primitive(PrimitiveTypeName.INT32, "f");

        WritableColumnVector vector =
                createVector(
                        new BigIntType(),
                        firstMatch,
                        descriptor(firstMatch, "f"),
                        descriptor(secondMatch, "f"));

        assertHeapVector(vector, HeapLongVector.class);
    }

    @Test
    void testDescriptorAtGivenDepthIsUsed() {
        PrimitiveType parquetType = primitive(PrimitiveTypeName.INT64, "f");
        List<ColumnDescriptor> descriptors =
                Collections.singletonList(descriptor(parquetType, "r", "f"));

        WritableColumnVector vector =
                createVector(BATCH_SIZE, new BigIntType(), parquetType, descriptors, 1);

        assertHeapVector(vector, HeapLongVector.class);
    }

    @Test
    void testMissingDescriptorThrowsInvalidSchemaException() {
        PrimitiveType parquetType = primitive(PrimitiveTypeName.INT32, "f");

        assertThrows(
                InvalidSchemaException.class,
                () ->
                        createVector(
                                new IntType(),
                                parquetType,
                                descriptor(parquetType, "other")));
    }

    @Test
    void testDepthBeyondDescriptorPathThrowsInvalidSchemaException() {
        PrimitiveType parquetType = primitive(PrimitiveTypeName.INT32, "f");
        List<ColumnDescriptor> descriptors =
                Collections.singletonList(descriptor(parquetType, "f"));

        assertThrows(
                InvalidSchemaException.class,
                () -> createVector(BATCH_SIZE, new IntType(), parquetType, descriptors, 1));
    }

    // ------------------------------------------------------------------------
    //  Nested types
    // ------------------------------------------------------------------------

    @Test
    void testArrayFieldCreatesHeapArrayVectorWithElementVector() {
        Type elementType = Types.optional(PrimitiveTypeName.INT32).named("element");
        Type arrayType =
                Types.optionalGroup()
                        .as(LogicalTypeAnnotation.listType())
                        .addField(Types.repeatedGroup().addField(elementType).named("list"))
                        .named("arr");

        WritableColumnVector vector =
                createVector(
                        new ArrayType(new IntType()),
                        arrayType,
                        descriptor(elementType.asPrimitiveType(), "arr", "list", "element"));

        assertHeapVector(vector, HeapArrayVector.class);
        ColumnVector child = ((HeapArrayVector) vector).getChild();
        assertNotNull(child);
        assertInstanceOf(HeapIntVector.class, child);
        assertEquals(BATCH_SIZE, ((AbstractHeapVector) child).getLen());
    }

    @Test
    void testArrayOfRowsCreatesHeapArrayVectorWithRowElement() {
        PrimitiveType f1 = primitive(PrimitiveTypeName.INT32, "f1");
        PrimitiveType f2 =
                Types.optional(PrimitiveTypeName.BINARY)
                        .as(LogicalTypeAnnotation.stringType())
                        .named("f2");
        Type elementType =
                Types.optionalGroup().addField(f1).addField(f2).named("element");
        Type arrayType =
                Types.optionalGroup()
                        .as(LogicalTypeAnnotation.listType())
                        .addField(Types.repeatedGroup().addField(elementType).named("list"))
                        .named("arr");

        RowType rowType = RowType.of(new LogicalType[] {new IntType(), new VarCharType(20)});
        WritableColumnVector vector =
                createVector(
                        new ArrayType(rowType),
                        arrayType,
                        descriptor(f1, "arr", "list", "element", "f1"),
                        descriptor(f2, "arr", "list", "element", "f2"));

        assertHeapVector(vector, HeapArrayVector.class);
        ColumnVector child = ((HeapArrayVector) vector).getChild();
        assertInstanceOf(HeapRowVector.class, child);
        WritableColumnVector[] fields = ((HeapRowVector) child).getFields();
        assertEquals(2, fields.length);
        assertInstanceOf(HeapIntVector.class, fields[0]);
        assertInstanceOf(HeapBytesVector.class, fields[1]);
    }

    @Test
    void testMapFieldCreatesHeapMapVectorWithKeyAndValueVectors() {
        PrimitiveType keyType =
                Types.optional(PrimitiveTypeName.BINARY)
                        .as(LogicalTypeAnnotation.stringType())
                        .named("key");
        PrimitiveType valueType = primitive(PrimitiveTypeName.INT32, "value");
        Type mapType =
                Types.optionalGroup()
                        .as(LogicalTypeAnnotation.mapType())
                        .addField(
                                Types.repeatedGroup()
                                        .addField(keyType)
                                        .addField(valueType)
                                        .named("key_value"))
                        .named("m");

        WritableColumnVector vector =
                createVector(
                        new MapType(new VarCharType(20), new IntType()),
                        mapType,
                        descriptor(keyType, "m", "key_value", "key"),
                        descriptor(valueType, "m", "key_value", "value"));

        assertHeapVector(vector, HeapMapVector.class);
        ColumnVector keys = ((HeapMapVector) vector).getKeyColumnVector();
        ColumnVector values = ((HeapMapVector) vector).getValueColumnVector();
        assertInstanceOf(HeapBytesVector.class, keys);
        assertInstanceOf(HeapIntVector.class, values);
        assertEquals(BATCH_SIZE, ((AbstractHeapVector) keys).getLen());
        assertEquals(BATCH_SIZE, ((AbstractHeapVector) values).getLen());
    }

    @Test
    void testMapFieldWithListAnnotationResolvesKeyAndValueVectors() {
        PrimitiveType keyType =
                Types.optional(PrimitiveTypeName.BINARY)
                        .as(LogicalTypeAnnotation.stringType())
                        .named("key");
        PrimitiveType valueType = primitive(PrimitiveTypeName.INT32, "value");
        Type mapType =
                Types.optionalGroup()
                        .as(LogicalTypeAnnotation.listType())
                        .addField(
                                Types.repeatedGroup()
                                        .addField(
                                                Types.optionalGroup()
                                                        .as(LogicalTypeAnnotation.mapType())
                                                        .addField(
                                                                Types.repeatedGroup()
                                                                        .addField(keyType)
                                                                        .addField(valueType)
                                                                        .named("key_value"))
                                                        .named("map"))
                                        .named("list"))
                        .named("m");

        WritableColumnVector vector =
                createVector(
                        new MapType(new VarCharType(20), new IntType()),
                        mapType,
                        descriptor(keyType, "m", "list", "map", "key_value", "key"),
                        descriptor(valueType, "m", "list", "map", "key_value", "value"));

        assertHeapVector(vector, HeapMapVector.class);
        assertInstanceOf(HeapBytesVector.class, ((HeapMapVector) vector).getKeyColumnVector());
        assertInstanceOf(HeapIntVector.class, ((HeapMapVector) vector).getValueColumnVector());
    }

    @Test
    void testMultisetFieldCreatesHeapMapVectorWithIntValueVector() {
        PrimitiveType keyType = primitive(PrimitiveTypeName.INT32, "key");
        PrimitiveType valueType = primitive(PrimitiveTypeName.INT32, "value");
        Type multisetType =
                Types.optionalGroup()
                        .as(LogicalTypeAnnotation.mapType())
                        .addField(
                                Types.repeatedGroup()
                                        .addField(keyType)
                                        .addField(valueType)
                                        .named("key_value"))
                        .named("ms");

        WritableColumnVector vector =
                createVector(
                        new MultisetType(new IntType()),
                        multisetType,
                        descriptor(keyType, "ms", "key_value", "key"),
                        descriptor(valueType, "ms", "key_value", "value"));

        assertHeapVector(vector, HeapMapVector.class);
        assertInstanceOf(HeapIntVector.class, ((HeapMapVector) vector).getKeyColumnVector());
        assertInstanceOf(HeapIntVector.class, ((HeapMapVector) vector).getValueColumnVector());
    }

    @Test
    void testRowFieldCreatesHeapRowVectorWithOneVectorPerField() {
        PrimitiveType f1 = primitive(PrimitiveTypeName.INT32, "f1");
        PrimitiveType f2 =
                Types.optional(PrimitiveTypeName.BINARY)
                        .as(LogicalTypeAnnotation.stringType())
                        .named("f2");
        PrimitiveType f3 = primitive(PrimitiveTypeName.DOUBLE, "f3");
        Type rowType =
                Types.optionalGroup().addField(f1).addField(f2).addField(f3).named("r");

        RowType logicalRowType =
                RowType.of(new LogicalType[] {new IntType(), new VarCharType(20), new DoubleType()});

        WritableColumnVector vector =
                createVector(
                        logicalRowType,
                        rowType,
                        descriptor(f1, "r", "f1"),
                        descriptor(f2, "r", "f2"),
                        descriptor(f3, "r", "f3"));

        assertHeapVector(vector, HeapRowVector.class);
        WritableColumnVector[] fields = ((HeapRowVector) vector).getFields();
        assertEquals(3, fields.length);
        assertInstanceOf(HeapIntVector.class, fields[0]);
        assertInstanceOf(HeapBytesVector.class, fields[1]);
        assertInstanceOf(HeapDoubleVector.class, fields[2]);
        for (WritableColumnVector field : fields) {
            assertEquals(BATCH_SIZE, ((AbstractHeapVector) field).getLen());
        }
    }

    @Test
    void testRowFieldWithListAnnotationSkipsListWrapperGroups() {
        PrimitiveType f1 = primitive(PrimitiveTypeName.INT64, "f1");
        Type rowType =
                Types.optionalGroup()
                        .as(LogicalTypeAnnotation.listType())
                        .addField(
                                Types.repeatedGroup()
                                        .addField(
                                                Types.optionalGroup()
                                                        .addField(f1)
                                                        .named("element"))
                                        .named("list"))
                        .named("r");

        WritableColumnVector vector =
                createVector(
                        RowType.of(new LogicalType[] {new BigIntType()}),
                        rowType,
                        descriptor(f1, "r", "list", "element", "f1"));

        assertHeapVector(vector, HeapRowVector.class);
        WritableColumnVector[] fields = ((HeapRowVector) vector).getFields();
        assertEquals(1, fields.length);
        assertInstanceOf(HeapLongVector.class, fields[0]);
    }

    // ------------------------------------------------------------------------
    //  Unsupported types
    // ------------------------------------------------------------------------

    @Test
    void testUnsupportedLogicalTypeThrowsUnsupportedOperationException() {
        PrimitiveType parquetType = primitive(PrimitiveTypeName.INT32, "f");
        UnsupportedOperationException exception =
                assertThrows(
                        UnsupportedOperationException.class,
                        () ->
                                createVector(
                                        new NullType(),
                                        parquetType,
                                        descriptor(parquetType, "f")));
        assertTrue(
                exception.getMessage().contains("is not supported now"),
                "Unexpected message: " + exception.getMessage());
    }

    @Test
    void testRepetitionOfOptionalParquetTypesDoesNotAffectVectorCreation() {
        PrimitiveType required = Types.required(PrimitiveTypeName.INT32).named("f");
        PrimitiveType repeated = Types.repeated(PrimitiveTypeName.INT32).named("f");

        assertHeapVector(
                createVector(new IntType(), required, descriptor(required, "f")),
                HeapIntVector.class);
        assertHeapVector(
                createVector(new IntType(), repeated, descriptor(repeated, "f")),
                HeapIntVector.class);
        assertEquals(Repetition.REPEATED, repeated.getRepetition());
    }
}
