/** Tests for {@link CheckpointCoordinator#receiveAcknowledgeMessage}. */
class CheckpointCoordinatorReceiveAcknowledgeMessageTests {

    private static final JobID JOB_ID = new JobID();
    private static final ExecutionAttemptID TASK_EXECUTION_ID = ExecutionAttemptID.randomId();

    private CheckpointCoordinator checkpointCoordinator;
    private CompletedCheckpointStore completedCheckpointStore;
    private CheckpointStatsTracker statsTracker;
    private CheckpointFailureManager failureManager;
    private SharedStateRegistry sharedStateRegistry;
    private ScheduledExecutor timer;

    @BeforeEach
    void setUp() throws Exception {
        completedCheckpointStore = mock(CompletedCheckpointStore.class);
        sharedStateRegistry = mock(SharedStateRegistry.class);
        when(completedCheckpointStore.getSharedStateRegistry()).thenReturn(sharedStateRegistry);
        statsTracker = mock(CheckpointStatsTracker.class);
        failureManager = mock(CheckpointFailureManager.class);
        timer = mock(ScheduledExecutor.class);

        final CheckpointCoordinatorConfiguration configuration =
                CheckpointCoordinatorConfiguration.builder()
                        .setCheckpointInterval(
                                CheckpointCoordinatorConfiguration.DISABLED_CHECKPOINT_INTERVAL)
                        .setCheckpointTimeout(60_000L)
                        .setMaxConcurrentCheckpoints(1)
                        .build();

        checkpointCoordinator =
                new CheckpointCoordinator(
                        JOB_ID,
                        configuration,
                        Collections.emptyList(),
                        mock(CheckpointIDCounter.class),
                        completedCheckpointStore,
                        mock(CheckpointStorage.class),
                        Runnable::run,
                        mock(CheckpointsCleaner.class),
                        timer,
                        failureManager,
                        mock(CheckpointPlanCalculator.class),
                        SystemClock.getInstance(),
                        statsTracker,
                        (vertices, operatorStates) -> mock(VertexFinishedStateChecker.class));
    }

    @Test
    void testNullMessageIsRejected() throws Exception {
        assertFalse(checkpointCoordinator.receiveAcknowledgeMessage(null, "location"));

        verifyNoInteractions(statsTracker);
        assertTrue(checkpointCoordinator.getPendingCheckpoints().isEmpty());
    }

    @Test
    void testMessageIsRejectedWhenCoordinatorIsShutDown() throws Exception {
        setShutdown(true);

        assertFalse(
                checkpointCoordinator.receiveAcknowledgeMessage(
                        acknowledgeMessage(42L), "location"));

        assertTrue(checkpointCoordinator.isShutdown());
        verifyNoInteractions(statsTracker);
        assertTrue(checkpointCoordinator.getPendingCheckpoints().isEmpty());
    }

    @Test
    void testMessageForDifferentJobIsRejected() throws Exception {
        final AcknowledgeCheckpoint message =
                new AcknowledgeCheckpoint(new JobID(), TASK_EXECUTION_ID, 42L);

        assertFalse(checkpointCoordinator.receiveAcknowledgeMessage(message, "location"));

        verifyNoInteractions(statsTracker);
        verifyNoInteractions(completedCheckpointStore);
    }

    @Test
    void testSuccessAcknowledgementForPendingCheckpointReturnsTrue() throws Exception {
        final long checkpointId = 42L;
        final PendingCheckpoint pendingCheckpoint = mock(PendingCheckpoint.class);
        when(pendingCheckpoint.isDisposed()).thenReturn(false);
        when(pendingCheckpoint.acknowledgeTask(
                        eq(TASK_EXECUTION_ID), isNull(), any(CheckpointMetrics.class)))
                .thenReturn(TaskAcknowledgeResult.SUCCESS);
        when(pendingCheckpoint.isFullyAcknowledged()).thenReturn(false);
        addPendingCheckpoint(checkpointId, pendingCheckpoint);

        assertTrue(
                checkpointCoordinator.receiveAcknowledgeMessage(
                        acknowledgeMessage(checkpointId), "location"));

    verify(pendingCheckpoint)
            .acknowledgeTask(eq(TASK_EXECUTION_ID), isNull(), any(CheckpointMetrics.class));
    verify(pendingCheckpoint).isFullyAcknowledged();
    verifyNoInteractions(statsTracker);
}

@Test
void testDuplicateAcknowledgementForPendingCheckpointReturnsTrue() throws Exception {
    final long checkpointId = 43L;
    final PendingCheckpoint pendingCheckpoint = mock(PendingCheckpoint.class);
    when(pendingCheckpoint.isDisposed()).thenReturn(false);
    when(pendingCheckpoint.acknowledgeTask(
                    eq(TASK_EXECUTION_ID), isNull(), any(CheckpointMetrics.class)))
            .thenReturn(TaskAcknowledgeResult.DUPLICATE);
    addPendingCheckpoint(checkpointId, pendingCheckpoint);

    assertTrue(
            checkpointCoordinator.receiveAcknowledgeMessage(
                    acknowledgeMessage(checkpointId), "location"));

    verify(pendingCheckpoint)
            .acknowledgeTask(eq(TASK_EXECUTION_ID), isNull(), any(CheckpointMetrics.class));
    verify(pendingCheckpoint, never()).isFullyAcknowledged();
    verifyNoInteractions(statsTracker);
}

