@Test
void testFullyAcknowledgedPendingCheckpointIsCompleted() throws Exception {
    final long checkpointId = 52L;
    final PendingCheckpoint pendingCheckpoint = mock(PendingCheckpoint.class);
    final CompletedCheckpoint completedCheckpoint = mock(CompletedCheckpoint.class);
    final CheckpointPlan checkpointPlan = mock(CheckpointPlan.class);
    final CompletableFuture<CompletedCheckpoint> completionFuture = new CompletableFuture<>();

    when(pendingCheckpoint.isDisposed()).thenReturn(false, true);
    when(pendingCheckpoint.getCheckpointID()).thenReturn(checkpointId);
    when(pendingCheckpoint.getProps()).thenReturn(regularCheckpointProperties());
    when(pendingCheckpoint.acknowledgeTask(
                    eq(TASK_EXECUTION_ID), isNull(), any(CheckpointMetrics.class)))
            .thenReturn(TaskAcknowledgeResult.SUCCESS);
    when(pendingCheckpoint.isFullyAcknowledged()).thenReturn(true);
    when(pendingCheckpoint.finalizeCheckpoint(
                    any(CheckpointsCleaner.class), any(Runnable.class), any(Executor.class)))
            .thenReturn(completedCheckpoint);
    when(pendingCheckpoint.getCheckpointPlan()).thenReturn(checkpointPlan);
    when(pendingCheckpoint.getCompletionFuture()).thenReturn(completionFuture);
    when(checkpointPlan.getTasksToCommitTo()).thenReturn(Collections.emptyList());
    when(completedCheckpoint.getCheckpointID()).thenReturn(checkpointId);
    when(completedCheckpoint.getTimestamp()).thenReturn(10L);
    when(completedCheckpoint.getCompletionTimestamp()).thenReturn(20L);
    when(completedCheckpoint.getStatistic()).thenReturn(null);
    when(completedCheckpointStore.addCheckpointAndSubsumeOldestOne(
                    any(CompletedCheckpoint.class),
                    any(CheckpointsCleaner.class),
                    any(Runnable.class)))
            .thenReturn(null);
    addPendingCheckpoint(checkpointId, pendingCheckpoint);

    assertTrue(
            checkpointCoordinator.receiveAcknowledgeMessage(
                    acknowledgeMessage(checkpointId), "location"));

    verify(sharedStateRegistry).checkpointCompleted(checkpointId);
    verify(completedCheckpointStore)
            .addCheckpointAndSubsumeOldestOne(
                    eq(completedCheckpoint),
                    any(CheckpointsCleaner.class),
                    any(Runnable.class));
    verify(failureManager).handleCheckpointSuccess(checkpointId);
    assertTrue(completionFuture.isDone());
    assertEquals(completedCheckpoint, completionFuture.join());
    assertFalse(checkpointCoordinator.getPendingCheckpoints().containsKey(checkpointId));
}

