private void setShutdown(boolean shutdown) throws Exception {
    final Field shutdownField = CheckpointCoordinator.class.getDeclaredField("shutdown");
    shutdownField.setAccessible(true);
    shutdownField.setBoolean(checkpointCoordinator, shutdown);
