@SuppressWarnings("unchecked")
private void addPendingCheckpoint(long checkpointId, PendingCheckpoint pendingCheckpoint)
        throws Exception {
    final Field pendingCheckpointsField =
            CheckpointCoordinator.class.getDeclaredField("pendingCheckpoints");
    pendingCheckpointsField.setAccessible(true);
    final Map<Long, PendingCheckpoint> pendingCheckpoints =
            (Map<Long, PendingCheckpoint>) pendingCheckpointsField.get(checkpointCoordinator);
    pendingCheckpoints.put(checkpointId, pendingCheckpoint);
}

