/**
 * Tests for {@link MetadataV2V3SerializerBase#deserializeKeyedStateHandle(DataInputStream,
 * MetadataV2V3SerializerBase.DeserializationContext)}.
 *
 * <p>The tests build the byte streams by hand, following the on-disk checkpoint metadata layout.
 * This is intentional: it keeps the tests independent of the serialization code and allows to
 * verify that exactly the expected number of bytes is consumed for each handle type.
 */
class MetadataV2V3SerializerBaseDeserializeKeyedStateHandleTests {

    // handle type tags as written into the checkpoint metadata
    private static final byte NULL_HANDLE = 0;
    private static final byte BYTE_STREAM_STATE_HANDLE = 1;
    private static final byte KEY_GROUPS_HANDLE = 3;
    private static final byte INCREMENTAL_KEY_GROUPS_HANDLE = 5;
    private static final byte RELATIVE_STREAM_STATE_HANDLE = 6;
    private static final byte SAVEPOINT_KEY_GROUPS_HANDLE = 7;
    private static final byte CHANGELOG_HANDLE = 8;
    private static final byte CHANGELOG_BYTE_INCREMENT_HANDLE = 9;
    private static final byte CHANGELOG_FILE_INCREMENT_HANDLE = 10;
    private static final byte INCREMENTAL_KEY_GROUPS_HANDLE_V2 = 11;
    private static final byte KEY_GROUPS_HANDLE_V2 = 12;
    private static final byte CHANGELOG_FILE_INCREMENT_HANDLE_V2 = 13;
    private static final byte CHANGELOG_HANDLE_V2 = 14;

    private static final int TRAILING_SENTINEL = 0x0BADF00D;

    // ------------------------------------------------------------------------
    //  null handle
    // ------------------------------------------------------------------------

    @Test
    void testDeserializeNullHandleReturnsNullAndConsumesOnlyTheTypeByte() throws Exception {
        final DataInputStream dis = inputStream(dos -> dos.writeByte(NULL_HANDLE));

        assertThat(MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null)).isNull();
        assertThat(dis.available()).isZero();
    }

    @Test
    void testDeserializeNullHandleDoesNotConsumeFollowingData() throws Exception {
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(NULL_HANDLE);
                            dos.writeInt(TRAILING_SENTINEL);
                        });

        assertThat(MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null)).isNull();
        assertThat(dis.readInt()).isEqualTo(TRAILING_SENTINEL);
    }

    // ------------------------------------------------------------------------
    //  key groups state handles
    // ------------------------------------------------------------------------

    @Test
    void testDeserializeLegacyKeyGroupsHandle() throws Exception {
        final long[] offsets = {11L, 22L, 33L};
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            writeKeyGroupsStateHandle(
                                    dos,
                                    KEY_GROUPS_HANDLE,
                                    4,
                                    3,
                                    offsets,
                                    "legacy-state",
                                    "legacy-payload".getBytes(StandardCharsets.UTF_8));
                            dos.writeInt(TRAILING_SENTINEL);
                        });

        final KeyedStateHandleAssert result =
                KeyedStateHandleAssert.of(
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null));

        assertThat(result.handle).isInstanceOf(KeyGroupsStateHandle.class);
        assertThat(result.handle).isNotInstanceOf(KeyGroupsSavepointStateHandle.class);
        assertThat(result.handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(4, 6));
        assertKeyGroupsOffsets(result.keyGroupsHandle, offsets);
        assertDelegateData(result.keyGroupsHandle, "legacy-state", "legacy-payload");
        // the legacy format does not persist the state handle id, one is generated on restore
        assertThat(result.handle.getStateHandleId()).isNotNull();

        // the legacy format carries no state handle id -> the following bytes must be untouched
        assertThat(dis.readInt()).isEqualTo(TRAILING_SENTINEL);
    }

    @Test
    void testDeserializeKeyGroupsHandleV2RestoresPersistedStateHandleId() throws Exception {
        final long[] offsets = {0L, 42L};
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            writeKeyGroupsStateHandle(
                                    dos,
                                    KEY_GROUPS_HANDLE_V2,
                                    7,
                                    2,
                                    offsets,
                                    "v2-state",
                                    "v2-payload".getBytes(StandardCharsets.UTF_8));
                            dos.writeUTF("persisted-state-handle-id");
                        });

        final KeyedStateHandleAssert result =
                KeyedStateHandleAssert.of(
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null));

        assertThat(result.handle).isInstanceOf(KeyGroupsStateHandle.class);
        assertThat(result.handle).isNotInstanceOf(KeyGroupsSavepointStateHandle.class);
        assertThat(result.handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(7, 8));
        assertKeyGroupsOffsets(result.keyGroupsHandle, offsets);
        assertDelegateData(result.keyGroupsHandle, "v2-state", "v2-payload");
        assertThat(result.handle.getStateHandleId())
                .isEqualTo(new StateHandleID("persisted-state-handle-id"));

        assertThat(dis.available()).isZero();
    }

    @Test
    void testDeserializeKeyGroupsHandleWithSingleKeyGroup() throws Exception {
        final long[] offsets = {99L};
        final DataInputStream dis =
                inputStream(
                        dos ->
                                writeKeyGroupsStateHandle(
                                        dos,
                                        KEY_GROUPS_HANDLE_V2,
                                        10,
                                        1,
                                        offsets,
                                        "single",
                                        new byte[] {1},
                                        "single-group-id"));

        final KeyedStateHandleAssert result =
                KeyedStateHandleAssert.of(
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null));

        assertThat(result.handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(10, 10));
        assertThat(result.keyGroupsHandle.getOffsetForKeyGroup(10)).isEqualTo(99L);
        assertThat(result.handle.getStateHandleId()).isEqualTo(new StateHandleID("single-group-id"));
    }

    @Test
    void testDeserializeSavepointKeyGroupsHandle() throws Exception {
        final long[] offsets = {5L, 6L, 7L, 8L};
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            writeKeyGroupsStateHandle(
                                    dos,
                                    SAVEPOINT_KEY_GROUPS_HANDLE,
                                    1,
                                    4,
                                    offsets,
                                    "savepoint-state",
                                    "savepoint-payload".getBytes(StandardCharsets.UTF_8));
                            dos.writeInt(TRAILING_SENTINEL);
                        });

        final KeyedStateHandleAssert result =
                KeyedStateHandleAssert.of(
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null));

        assertThat(result.handle).isInstanceOf(KeyGroupsSavepointStateHandle.class);
        assertThat(result.handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(1, 4));
        assertKeyGroupsOffsets(result.keyGroupsHandle, offsets);
        assertDelegateData(result.keyGroupsHandle, "savepoint-state", "savepoint-payload");
        assertThat(result.handle.getStateHandleId()).isNotNull();

        // savepoint handles do not persist a state handle id -> nothing else may be consumed
        assertThat(dis.readInt()).isEqualTo(TRAILING_SENTINEL);
    }

    // ------------------------------------------------------------------------
    //  incremental key groups state handles
    // ------------------------------------------------------------------------

    @Test
    void testDeserializeLegacyIncrementalKeyGroupsHandle() throws Exception {
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(INCREMENTAL_KEY_GROUPS_HANDLE);
                            dos.writeLong(123L);
                            dos.writeUTF("non-uuid-backend-id");
                            dos.writeInt(2);
                            dos.writeInt(3);
                            writeByteStreamStateHandle(
                                    dos, "meta", "meta-bytes".getBytes(StandardCharsets.UTF_8));
                            // shared state: empty
                            dos.writeInt(0);
                            // private state: one handle
                            dos.writeInt(1);
                            dos.writeUTF("private-local-path");
                            writeByteStreamStateHandle(
                                    dos, "private", new byte[] {9, 8, 7});
                            dos.writeInt(TRAILING_SENTINEL);
                        });

        final IncrementalRemoteKeyedStateHandle handle =
                (IncrementalRemoteKeyedStateHandle)
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null);

        assertThat(handle.getCheckpointId()).isEqualTo(123L);
        // non-UUID backend ids are converted deterministically for backwards compatibility
        assertThat(handle.getBackendIdentifier())
                .isEqualTo(
                        UUID.nameUUIDFromBytes(
                                "non-uuid-backend-id".getBytes(StandardCharsets.UTF_8)));
        assertThat(handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(2, 4));
        assertThat(handle.getMetaDataStateHandle())
                .isInstanceOf(ByteStreamStateHandle.class)
                .satisfies(
                        h ->
                                assertThat(((ByteStreamStateHandle) h).getData())
                                        .isEqualTo(
                                                "meta-bytes"
                                                        .getBytes(StandardCharsets.UTF_8)));
        assertThat(handle.getSharedState()).isEmpty();
        assertThat(handle.getPrivateState()).hasSize(1);
        assertThat(handle.getPrivateState().get(0).getLocalPath()).isEqualTo("private-local-path");
        assertThat(handle.getPrivateState().get(0).getHandle())
                .isInstanceOf(ByteStreamStateHandle.class);
        assertThat(handle.getStateHandleId()).isNotNull();

        // the legacy format persists neither the checkpointed size nor the state handle id
        assertThat(dis.readInt()).isEqualTo(TRAILING_SENTINEL);
    }

    @Test
    void testDeserializeIncrementalKeyGroupsHandleV2() throws Exception {
        final UUID backendId = UUID.randomUUID();
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(INCREMENTAL_KEY_GROUPS_HANDLE_V2);
                            dos.writeLong(55L);
                            dos.writeUTF(backendId.toString());
                            dos.writeInt(0);
                            dos.writeInt(2);
                            dos.writeLong(4711L);
                            writeByteStreamStateHandle(
                                    dos, "meta", "meta-v2".getBytes(StandardCharsets.UTF_8));
                            // shared state: one handle
                            dos.writeInt(1);
                            dos.writeUTF("shared-local-path");
                            writeByteStreamStateHandle(dos, "shared", new byte[] {1, 2});
                            // private state: empty
                            dos.writeInt(0);
                            dos.writeUTF("incremental-state-handle-id");
                        });

        final IncrementalRemoteKeyedStateHandle handle =
                (IncrementalRemoteKeyedStateHandle)
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null);

        assertThat(handle.getCheckpointId()).isEqualTo(55L);
        assertThat(handle.getBackendIdentifier()).isEqualTo(backendId);
        assertThat(handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(0, 1));
        assertThat(handle.getCheckpointedSize()).isEqualTo(4711L);
        assertThat(handle.getMetaDataStateHandle()).isInstanceOf(ByteStreamStateHandle.class);
        assertThat(handle.getSharedState()).hasSize(1);
        assertThat(handle.getSharedState().get(0).getLocalPath()).isEqualTo("shared-local-path");
        assertThat(handle.getPrivateState()).isEmpty();
        assertThat(handle.getStateHandleId())
                .isEqualTo(new StateHandleID("incremental-state-handle-id"));

        assertThat(dis.available()).isZero();
    }

    // ------------------------------------------------------------------------
    //  changelog state backend handles
    // ------------------------------------------------------------------------

    @Test
    void testDeserializeChangelogHandleV1UsesMaterializationIdAsCheckpointId() throws Exception {
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(CHANGELOG_HANDLE);
                            dos.writeInt(0);
                            dos.writeInt(2);
                            dos.writeLong(1000L);

                            // materialized part: one key groups handle and one null handle, which
                            // is skipped (with a warning) instead of failing the deserialization
                            dos.writeInt(2);
                            writeKeyGroupsStateHandle(
                                    dos,
                                    KEY_GROUPS_HANDLE_V2,
                                    0,
                                    2,
                                    new long[] {1L, 2L},
                                    "materialized",
                                    new byte[] {3},
                                    "materialized-id");
                            dos.writeByte(NULL_HANDLE);

                            // non-materialized part: one in-memory changelog handle
                            dos.writeInt(1);
                            writeInMemoryChangelogHandle(
                                    dos, 0, 2, 1L, 2L, "delta-id");

                            dos.writeLong(77L);
                            // CHANGELOG_HANDLE (v1) does not persist a separate checkpoint id
                            dos.writeUTF("changelog-handle-id");
                        });

        final ChangelogStateBackendHandle handle =
                (ChangelogStateBackendHandle)
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null);

        assertThat(handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(0, 1));
        assertThat(handle.getCheckpointedSize()).isEqualTo(1000L);
        assertThat(handle.getMaterializationID()).isEqualTo(77L);
        assertThat(handle.getCheckpointId()).isEqualTo(77L);

        final List<org.apache.flink.runtime.state.KeyedStateHandle> materialized =
                handle.getMaterializedStateHandles();
        assertThat(materialized).hasSize(1);
        assertThat(materialized.get(0)).isInstanceOf(KeyGroupsStateHandle.class);
        assertThat(materialized.get(0).getStateHandleId())
                .isEqualTo(new StateHandleID("materialized-id"));

        final List<ChangelogStateHandle> delta = handle.getNonMaterializedStateHandles();
        assertThat(delta).hasSize(1);
        assertThat(delta.get(0)).isInstanceOf(InMemoryChangelogStateHandle.class);

        assertThat(handle.getStateHandleId())
                .isEqualTo(new StateHandleID("changelog-handle-id"));
        assertThat(dis.available()).isZero();
    }

    @Test
    void testDeserializeChangelogHandleV2ReadsSeparateCheckpointId() throws Exception {
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(CHANGELOG_HANDLE_V2);
                            dos.writeInt(3);
                            dos.writeInt(2);
                            dos.writeLong(512L);

                            dos.writeInt(1);
                            writeKeyGroupsStateHandle(
                                    dos,
