                                    new long[] {4L, 5L},
                                    "materialized-v2",
                                    new byte[] {6},
                                    "materialized-id-v2");

                            // no non-materialized handles at all
                            dos.writeInt(0);

                            dos.writeLong(100L);
                            dos.writeLong(101L);
                            dos.writeUTF("changelog-handle-id-v2");
