    @Test
    void testDeserializeChangelogByteIncrementHandle() throws Exception {
        final byte[] metadataBytes = "metadata-change".getBytes(StandardCharsets.UTF_8);
        final byte[] dataBytes = {10, 20, 30};
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(CHANGELOG_BYTE_INCREMENT_HANDLE);
                            dos.writeInt(5);
                            dos.writeInt(2);
                            dos.writeLong(13L);
                            dos.writeLong(17L);
                            dos.writeInt(2);

                            dos.writeInt(StateChange.META_KEY_GROUP);
                            dos.writeInt(metadataBytes.length);
                            dos.write(metadataBytes);

                            dos.writeInt(6);
                            dos.writeInt(dataBytes.length);
                            dos.write(dataBytes);

                            dos.writeUTF("byte-increment-id");
                        });

        final InMemoryChangelogStateHandle handle =
                (InMemoryChangelogStateHandle)
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null);

        assertThat(handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(5, 6));
        assertThat(handle.getFrom()).isEqualTo(13L);
        assertThat(handle.getTo()).isEqualTo(17L);
        assertThat(handle.getStateHandleId())
                .isEqualTo(new StateHandleID("byte-increment-id"));

        final List<StateChange> changes = handle.getChanges();
        assertThat(changes).hasSize(2);
        assertThat(changes.get(0).getKeyGroup()).isEqualTo(StateChange.META_KEY_GROUP);
        assertThat(changes.get(0).getChange()).isEqualTo(metadataBytes);
        assertThat(changes.get(1).getKeyGroup()).isEqualTo(6);
        assertThat(changes.get(1).getChange()).isEqualTo(dataBytes);
        assertThat(dis.available()).isZero();
    }

