    @FunctionalInterface
    private interface DataWriter {
        void write(DataOutputStream dos) throws IOException;
    }

    private static DataInputStream inputStream(DataWriter writer) throws IOException {
        final ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (DataOutputStream dos = new DataOutputStream(baos)) {
            writer.write(dos);
        }
        return new DataInputStream(new ByteArrayInputStream(baos.toByteArray()));
    }

    private static void writeByteStreamStateHandle(
            DataOutputStream dos, String name, byte[] payload) throws IOException {
        dos.writeByte(BYTE_STREAM_STATE_HANDLE);
        dos.writeUTF(name);
        dos.writeInt(payload.length);
        dos.write(payload);
    }

    private static void writeKeyGroupsStateHandle(
            DataOutputStream dos,
            byte type,
            int startKeyGroup,
            int numKeyGroups,
            long[] offsets,
            String streamHandleName,
            byte[] payload)
            throws IOException {
        writeKeyGroupsStateHandle(
                dos,
                type,
                startKeyGroup,
                numKeyGroups,
                offsets,
                streamHandleName,
                payload,
                null);
    }

    private static void writeKeyGroupsStateHandle(
            DataOutputStream dos,
            byte type,
            int startKeyGroup,
            int numKeyGroups,
            long[] offsets,
            String streamHandleName,
            byte[] payload,
            @Nullable String stateHandleId)
            throws IOException {
        dos.writeByte(type);
        dos.writeInt(startKeyGroup);
        dos.writeInt(numKeyGroups);
        for (int i = 0; i < numKeyGroups; i++) {
            dos.writeLong(offsets[i]);
        }
        writeByteStreamStateHandle(dos, streamHandleName, payload);
        if (type == KEY_GROUPS_HANDLE_V2) {
            dos.writeUTF(stateHandleId);
        }
    }

    private static void writeInMemoryChangelogHandle(
            DataOutputStream dos,
            int startKeyGroup,
            int numKeyGroups,
            long from,
            long to,
            String stateHandleId)
            throws IOException {
        dos.writeByte(CHANGELOG_BYTE_INCREMENT_HANDLE);
        dos.writeInt(startKeyGroup);
        dos.writeInt(numKeyGroups);
        dos.writeLong(from);
        dos.writeLong(to);
        dos.writeInt(0);
        dos.writeUTF(stateHandleId);
    }

    private static void assertKeyGroupsOffsets(
            KeyGroupsStateHandle handle, long[] expectedOffsets) {
        final KeyGroupRange range = handle.getKeyGroupRange();
        for (int i = 0; i < expectedOffsets.length; i++) {
            assertThat(handle.getOffsetForKeyGroup(range.getStartKeyGroup() + i))
                    .as("offset of key group %d", range.getStartKeyGroup() + i)
                    .isEqualTo(expectedOffsets[i]);
        }
    }

    private static void assertDelegateData(
            KeyGroupsStateHandle handle, String expectedName, String expectedPayload) {
        final StreamStateHandle delegate = handle.getDelegateStateHandle();
        assertThat(delegate).isInstanceOf(ByteStreamStateHandle.class);
        final ByteStreamStateHandle byteStreamStateHandle = (ByteStreamStateHandle) delegate;
        assertThat(byteStreamStateHandle.getHandleName()).isEqualTo(expectedName);
        assertThat(byteStreamStateHandle.getData())
                .isEqualTo(expectedPayload.getBytes(StandardCharsets.UTF_8));
    }

    /** Small holder that keeps the assertions readable while still checking the concrete type. */
    private static final class KeyedStateHandleAssert {

        private final org.apache.flink.runtime.state.KeyedStateHandle handle;
        private final KeyGroupsStateHandle keyGroupsHandle;

        private KeyedStateHandleAssert(
                org.apache.flink.runtime.state.KeyedStateHandle handle,
                KeyGroupsStateHandle keyGroupsHandle) {
            this.handle = handle;
            this.keyGroupsHandle = keyGroupsHandle;
        }

        static KeyedStateHandleAssert of(
                org.apache.flink.runtime.state.KeyedStateHandle handle) {
            assertThat(handle).isInstanceOf(KeyGroupsStateHandle.class);
            return new KeyedStateHandleAssert(handle, (KeyGroupsStateHandle) handle);
        }
    }
