    @Test
    void testDeserializeLegacyChangelogFileIncrementHandleDefaultsStorageIdentifier()
            throws Exception {
        final DataInputStream dis =
                inputStream(
                        dos -> {
                            dos.writeByte(CHANGELOG_FILE_INCREMENT_HANDLE);
                            dos.writeInt(0);
                            dos.writeInt(2);
                            dos.writeInt(2);

                            dos.writeLong(0L);
                            writeByteStreamStateHandle(
                                    dos, "first", "abc".getBytes(StandardCharsets.UTF_8));
                            dos.writeLong(128L);
                            writeByteStreamStateHandle(
                                    dos, "second", "defg".getBytes(StandardCharsets.UTF_8));

                            dos.writeLong(1000L);
                            dos.writeLong(500L);
                            dos.writeUTF("file-increment-id");
                            dos.writeInt(TRAILING_SENTINEL);
                        });

        final ChangelogStateHandleStreamImpl handle =
                (ChangelogStateHandleStreamImpl)
                        MetadataV2V3SerializerBase.deserializeKeyedStateHandle(dis, null);

        assertThat(handle.getKeyGroupRange()).isEqualTo(KeyGroupRange.of(0, 1));
        assertThat(handle.getStateSize()).isEqualTo(1000L);
        assertThat(handle.getCheckpointedSize()).isEqualTo(500L);
        assertThat(handle.getStateHandleId()).isEqualTo(new StateHandleID("file-increment-id"));
        // the legacy format does not persist a storage identifier
        assertThat(handle.getStorageIdentifier()).isEqualTo("filesystem");

        final List<Tuple2<StreamStateHandle, Long>> handlesAndOffsets =
                handle.getHandlesAndOffsets();
        assertThat(handlesAndOffsets).hasSize(2);
        assertThat(handlesAndOffsets.get(0).f1).isEqualTo(0L);
        assertThat(((ByteStreamStateHandle) handlesAndOffsets.get(0).f0).getData())
                .isEqualTo("abc".getBytes(StandardCharsets.UTF_8));
        assertThat(handlesAndOffsets.get(1).f1).isEqualTo(128L);
        assertThat(((ByteStreamStateHandle) handlesAndOffsets.get(1).f0).getData())
                .isEqualTo("defg".getBytes(StandardCharsets.UTF_8));

        // no storage identifier is expected for the legacy format -> trailing bytes remain
        assertThat(dis.readInt()).isEqualTo(TRAILING_SENTINEL);
    }

    @Test
    void testDeserializeChangelogFileIncrementHandleV2ReadsStorageIdentifier() throws Exception {
        final DataInputStream dis =
