            SerializedValue<StateBackend> stateBackend) {
        return new JobCheckpointingSettings(
                CheckpointCoordinatorConfiguration.builder()
                        .setCheckpointInterval(Long.MAX_VALUE)
                        .setCheckpointTimeout(60_000L)
                        .setMinPauseBetweenCheckpoints(0L)
                        .setMaxConcurrentCheckpoints(1)
                        .build(),
                stateBackend);
    }

    private static final class TestGraphBuilder {
        private final JobGraph jobGraph;
        private final Configuration jobManagerConfig = new Configuration();
        private final ScheduledExecutorService futureExecutor =
                mock(ScheduledExecutorService.class);
