                DefaultExecutionGraphBuilderBuildGraphTests.class.getClassLoader();
        private final CompletedCheckpointStore completedCheckpointStore =
                mock(CompletedCheckpointStore.class);
        private final CheckpointsCleaner checkpointsCleaner = mock(CheckpointsCleaner.class);
