        private TestGraphBuilder(JobGraph jobGraph) {
            this.jobGraph = jobGraph;
            when(blobWriter.getMinOffloadingSize()).thenReturn(Integer.MAX_VALUE);
        }

        private void setParallelism(JobVertexID vertexId, int parallelism) {
            vertexParallelismStore.setParallelismInfo(
                    vertexId,
                    new DefaultVertexParallelismInfo(
