        }

        private DefaultExecutionGraph build(boolean dynamicGraph) throws Exception {
            return buildWithJobGraph(jobGraph, dynamicGraph);
        }

        private DefaultExecutionGraph buildWithJobGraph(JobGraph graph, boolean dynamicGraph)
                throws Exception {
            return DefaultExecutionGraphBuilder.buildGraph(
                    graph,
