            when(executionJobVertex.getJobVertex()).thenReturn(jobVertex);
            when(executionJobVertex.getTaskVertices()).thenReturn(new ExecutionVertex[0]);
            when(executionJobVertex.getProducedDataSets()).thenReturn(new IntermediateResult[0]);
            when(executionJobVertex.getOperatorCoordinators()).thenReturn(Collections.emptyList());
            when(executionJobVertex.getSlotSharingGroup()).thenReturn(new SlotSharingGroup());
            when(executionJobVertex.isInitialized()).thenReturn(false);

