class DefaultExecutionGraphBuilderBuildGraphTests {

    private static final Duration RPC_TIMEOUT = Duration.ofSeconds(10);

    @Test
    void buildGraphCreatesGraphWithJobMetadataAndAttachedVertices() throws Exception {
        final RecordingJobVertex vertex = new RecordingJobVertex("test-vertex", 7);
        final JobGraph jobGraph = new JobGraph(new JobID(), "test-job");
        jobGraph.addVertex(vertex);
        final TestGraphBuilder builder = new TestGraphBuilder(jobGraph);
        builder.setParallelism(vertex.getID(), 11);

        final DefaultExecutionGraph executionGraph = builder.build(false);

        assertThat(executionGraph.getJobID()).isEqualTo(jobGraph.getJobID());
        assertThat(executionGraph.getJobName()).isEqualTo("test-job");
        assertThat(executionGraph.getUserClassLoader()).isSameAs(builder.classLoader);
        assertThat(executionGraph.getTaskDeploymentDescriptorFactory()).isNotNull();
        assertThat(executionGraph.getState()).isEqualTo(JobStatus.CREATED);
        assertThat(executionGraph.getCheckpointCoordinator()).isNull();

        assertThat(executionGraph.getAllVertices()).containsOnlyKeys(vertex.getID());
        assertThat(executionGraph.getJobVertex(vertex.getID()))
                .isSameAs(builder.executionJobVertexFactory.created.get(vertex.getID()));

        assertThat(vertex.initializeCalls).isEqualTo(1);
        assertThat(vertex.executionParallelism).isEqualTo(11);
        assertThat(vertex.initializationClassLoader).isSameAs(builder.classLoader);

        assertThat(executionGraph.getPlan()).isNotNull();
        assertThat(executionGraph.getPlan().getJobId()).isEqualTo(jobGraph.getJobID().toString());
        assertThat(executionGraph.getPlan().getName()).isEqualTo("test-job");
        assertThat(executionGraph.getPlan().getNodes()).hasSize(1);

        final VertexParallelismInformation factoryParallelismInfo =
                builder.executionJobVertexFactory.parallelismInfos.get(vertex.getID());
        assertThat(factoryParallelismInfo).isNotNull();
        assertThat(factoryParallelismInfo.getParallelism()).isEqualTo(11);
    }

    @Test
    void buildGraphRejectsNullJobGraph() {
        final TestGraphBuilder builder = new TestGraphBuilder(new JobGraph("unused"));

        assertThatThrownBy(() -> builder.buildWithJobGraph(null, false))
                .isInstanceOf(NullPointerException.class)
                .hasMessageContaining("job graph cannot be null");
    }

    @Test
    void buildGraphFailsWhenVertexHasNoInvokableClass() {
        final JobVertex vertexWithoutInvokable = new JobVertex("vertex-without-invokable");
        final JobGraph jobGraph = new JobGraph("test-job");
        jobGraph.addVertex(vertexWithoutInvokable);
        final TestGraphBuilder builder = new TestGraphBuilder(jobGraph);
        builder.setParallelism(vertexWithoutInvokable.getID(), 1);

        assertThatThrownBy(() -> builder.build(false))
                .isInstanceOf(JobSubmissionException.class)
                .hasMessageContaining(vertexWithoutInvokable.getID().toString())
                .hasMessageContaining("vertex-without-invokable")
                .hasMessageContaining("has no invokable class");
    }

    @Test
    void buildGraphSkipsCheckpointingForDynamicGraph() throws Exception {
        final RecordingJobVertex vertex = new RecordingJobVertex("test-vertex", 1);
        final JobGraph jobGraph = new JobGraph("dynamic-job");
        jobGraph.addVertex(vertex);
        jobGraph.setSnapshotSettings(checkpointingSettings(null));

        final TestGraphBuilder builder = new TestGraphBuilder(jobGraph);
        builder.setParallelism(vertex.getID(), 1);

        final DefaultExecutionGraph executionGraph = builder.build(true);

        assertThat(executionGraph.getCheckpointCoordinator()).isNull();
        assertThat(executionGraph.getCheckpointCoordinatorConfiguration()).isNull();
        verify(builder.log).warn("Skip setting up checkpointing for a job with dynamic graph.");
    }

    @Test
    void buildGraphEnablesCheckpointingWhenSettingsArePresent() throws Exception {
        final RecordingJobVertex vertex = new RecordingJobVertex("test-vertex", 1);
        final JobGraph jobGraph = new JobGraph("checkpointed-job");
        jobGraph.addVertex(vertex);
        final CheckpointCoordinatorConfiguration checkpointConfig =
                CheckpointCoordinatorConfiguration.builder()
                        .setCheckpointInterval(Long.MAX_VALUE)
                        .setCheckpointTimeout(60_000L)
                        .setMinPauseBetweenCheckpoints(0L)
                        .setMaxConcurrentCheckpoints(1)
                        .build();
        jobGraph.setSnapshotSettings(
                new JobCheckpointingSettings(checkpointConfig, null));

        final TestGraphBuilder builder = new TestGraphBuilder(jobGraph);
        builder.setParallelism(vertex.getID(), 1);

        DefaultExecutionGraph executionGraph = null;
        try {
            executionGraph = builder.build(false);

            assertThat(executionGraph.getCheckpointCoordinator()).isNotNull();
            assertThat(executionGraph.getCheckpointCoordinatorConfiguration())
                    .isSameAs(checkpointConfig);
            assertThat(executionGraph.getStateBackendName()).isPresent();
            assertThat(executionGraph.getCheckpointStorageName()).isPresent();
            verify(builder.checkpointIdCounter).start();
        } finally {
            if (executionGraph != null && executionGraph.getCheckpointCoordinator() != null) {
                executionGraph.getCheckpointCoordinator().shutdown();
            }
        }
    }

    @Test
    void buildGraphWrapsUnreadableApplicationStateBackendInJobExecutionException() {
        final RecordingJobVertex vertex = new RecordingJobVertex("test-vertex", 1);
        final JobGraph jobGraph = new JobGraph("invalid-state-backend-job");
        jobGraph.addVertex(vertex);
        final CheckpointCoordinatorConfiguration checkpointConfig =
                CheckpointCoordinatorConfiguration.builder()
                        .setCheckpointInterval(Long.MAX_VALUE)
                        .setCheckpointTimeout(60_000L)
                        .build();
        jobGraph.setSnapshotSettings(
                new JobCheckpointingSettings(
                        checkpointConfig,
                        SerializedValue.fromBytes(new byte[] {0x01, 0x02, 0x03})));

        final TestGraphBuilder builder = new TestGraphBuilder(jobGraph);
        builder.setParallelism(vertex.getID(), 1);

        assertThatThrownBy(() -> builder.build(false))
                .isInstanceOf(JobExecutionException.class)
                .hasMessageContaining("Could not deserialize application-defined state backend")
                .hasCauseInstanceOf(IOException.class);
    }

