        private int initializeCalls;
        private int executionParallelism = -1;
        private ClassLoader initializationClassLoader;

        private RecordingJobVertex(String name, int parallelism) {
            super(name);
            setInvokableClass(TestInvokable.class);
            setParallelism(parallelism);
        }

