        public void initializeOnMaster(InitializeOnMasterContext context) {
            initializeCalls++;
            executionParallelism = context.getExecutionParallelism();
            initializationClassLoader = context.getClassLoader();
        }
    }

    private static final class TestInvokable implements TaskInvokable {
        @Override
        public void invoke() {}

        @Override
        public void restore() {}

        @Override
        public void cleanUp(Throwable throwable) {}

        @Override
        public void cancel() {}

        @Override
        public boolean isUsingNonBlockingInput() {
            return false;
        }

        @Override
        public void maybeInterruptOnCancel(Thread toInterrupt, String taskName, Long timeout) {}
    }
