                () -> {
                    invoked.set(true);
                    return bufferPool;
                };

        ResultPartition partition =
                factory.create(
                        TASK_NAME,
                        PARTITION_INDEX,
                        partitionId,
                        ResultPartitionType.PIPELINED,
                        NUMBER_OF_PARTITIONS,
