                type,
                NUMBER_OF_PARTITIONS,
                numberOfSubpartitions,
                MAX_PARALLELISM,
                false,
                shuffleDescriptor,
                bufferPoolSupplier,
                isNumberOfPartitionConsumerUndefined);
    }

    private static void assertCommonMetadata(
            ResultPartition partition, ResultPartitionType type, int numberOfSubpartitions) {
        assertThat(partition.getOwningTaskName()).isEqualTo(TASK_NAME);
        assertThat(partition.getPartitionIndex()).isEqualTo(PARTITION_INDEX);
        assertThat(partition.getPartitionType()).isEqualTo(type);
        assertThat(partition.getNumberOfSubpartitions()).isEqualTo(numberOfSubpartitions);
        assertThat(partition.getNumTargetKeyGroups()).isEqualTo(MAX_PARALLELISM);
    }

    private void assertSubpartitionMetadata(ResultSubpartition subpartition, int expectedIndex) {
        assertThat(subpartition.getSubPartitionIndex()).isEqualTo(expectedIndex);
        assertThat(subpartition.getSubpartitionInfo().getPartitionIdx())
                .isEqualTo(PARTITION_INDEX);
        assertThat(subpartition.getSubpartitionInfo().getSubPartitionIdx())
                .isEqualTo(expectedIndex);
    }

    private static BufferCompressor readBufferCompressor(ResultPartition partition)
            throws ReflectiveOperationException {
        Field field = ResultPartition.class.getDeclaredField("bufferCompressor");
        field.setAccessible(true);
        return (BufferCompressor) field.get(partition);
    }
