/** Tests for {@link ResultPartitionFactory#create} (the {@code VisibleForTesting} overload). */
class ResultPartitionFactoryCreateTests {

    private static final String TASK_NAME = "test-task (1/1)";
    private static final int PARTITION_INDEX = 3;
    private static final int NUMBER_OF_PARTITIONS = 8;
    private static final int MAX_PARALLELISM = 128;
    private static final int NETWORK_BUFFER_SIZE = 1024;
    private static final int SORT_SHUFFLE_MIN_PARALLELISM = 4;

    @TempDir private Path tempDir;

    private FileChannelManager channelManager;
    private ResultPartitionManager partitionManager;
    private BufferPoolFactory bufferPoolFactory;
    private ScheduledExecutorService batchShuffleReadIOExecutor;
    private BatchShuffleReadBufferPool batchShuffleReadBufferPool;
    private ResultPartitionID partitionId;
    private AtomicBoolean bufferPoolFactoryInvoked;
    private SupplierWithException<BufferPool, IOException> bufferPoolSupplier;

    @BeforeEach
    void setUp() {
        channelManager =
                new FileChannelManagerImpl(
                        new String[] {tempDir.toString()},
                        "ResultPartitionFactoryCreateTests");
        partitionManager = new ResultPartitionManager();
        bufferPoolFactory = new NoopBufferPoolFactory();
        batchShuffleReadIOExecutor = Executors.newSingleThreadScheduledExecutor();
        batchShuffleReadBufferPool = new BatchShuffleReadBufferPool(1024 * 1024, 32 * 1024);
        partitionId = new ResultPartitionID();
        bufferPoolFactoryInvoked = new AtomicBoolean(false);
        bufferPoolSupplier =
                () -> {
                    bufferPoolFactoryInvoked.set(true);
                    return null;
                };
    }

    @AfterEach
    void tearDown() throws Exception {
        batchShuffleReadBufferPool.destroy();
        batchShuffleReadIOExecutor.shutdownNow();
        partitionManager.shutdown();
        channelManager.close();
    }

    // ---------------------------------------------------------------------
    // Pipelined partitions
    // ---------------------------------------------------------------------

    @Test
    void createPipelinedPartition_buildsPipelinedPartitionWithPipelinedSubpartitions() {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(factory, ResultPartitionType.PIPELINED, 3, null, false);

        assertThat(partition).isExactlyInstanceOf(PipelinedResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.PIPELINED, 3);
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isFalse();
        assertThat(bufferPoolFactoryInvoked).isFalse();

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(3);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i]).isExactlyInstanceOf(PipelinedSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    @Test
    void createPipelinedBoundedPartition_buildsPipelinedPartitionWithPipelinedSubpartitions() {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(
                        factory, ResultPartitionType.PIPELINED_BOUNDED, 2, null, true);

        assertThat(partition).isExactlyInstanceOf(PipelinedResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.PIPELINED_BOUNDED, 2);
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isTrue();

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(2);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i]).isExactlyInstanceOf(PipelinedSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    @Test
    void createPipelinedApproximatePartition_buildsApproximateSubpartitions() {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(
                        factory, ResultPartitionType.PIPELINED_APPROXIMATE, 3, null, false);

        assertThat(partition).isExactlyInstanceOf(PipelinedResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.PIPELINED_APPROXIMATE, 3);

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(3);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i])
                    .isExactlyInstanceOf(PipelinedApproximateSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    // ---------------------------------------------------------------------
    // Blocking partitions
    // ---------------------------------------------------------------------

    @Test
    void createBlockingPartition_belowSortShuffleThreshold_buildsBoundedBlockingPartition() {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(
                        factory,
                        ResultPartitionType.BLOCKING,
                        SORT_SHUFFLE_MIN_PARALLELISM - 1,
                        null,
                        false);

        assertThat(partition).isExactlyInstanceOf(BoundedBlockingResultPartition.class);
        assertCommonMetadata(
                partition, ResultPartitionType.BLOCKING, SORT_SHUFFLE_MIN_PARALLELISM - 1);

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(SORT_SHUFFLE_MIN_PARALLELISM - 1);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i]).isExactlyInstanceOf(BoundedBlockingSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    @Test
    void createBlockingPartition_atSortShuffleThreshold_buildsSortMergePartition() {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
