import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link ResultPartitionFactory#create} (the {@code VisibleForTesting} overload). */
class ResultPartitionFactoryCreateTests {

    private static final String TASK_NAME = "test-task (1/1)";
    private static final int PARTITION_INDEX = 3;
    private static final int NUMBER_OF_PARTITIONS = 8;
    private static final int MAX_PARALLELISM = 128;
    private static final int NETWORK_BUFFER_SIZE = 1024;
    private static final int SORT_SHUFFLE_MIN_PARALLELISM = 4;

    @TempDir private Path tempDir;

    private FileChannelManager channelManager;
    private ResultPartitionManager partitionManager;
    private BufferPoolFactory bufferPoolFactory;
    private ScheduledExecutorService batchShuffleReadIOExecutor;
    private BatchShuffleReadBufferPool batchShuffleReadBufferPool;
    private ResultPartitionID partitionId;
    private AtomicBoolean bufferPoolFactoryInvoked;
    private SupplierWithException<BufferPool, IOException> bufferPoolSupplier;

    @BeforeEach
    void setUp() {
        channelManager =
                new FileChannelManagerImpl(
                        new String[] {tempDir.toString()},
                        "ResultPartitionFactoryCreateTests");
        partitionManager = new ResultPartitionManager();
        bufferPoolFactory = new NoopBufferPoolFactory();
        batchShuffleReadIOExecutor = Executors.newSingleThreadScheduledExecutor();
        batchShuffleReadBufferPool = new BatchShuffleReadBufferPool(1024 * 1024, 32 * 1024);
        partitionId = new ResultPartitionID();
        bufferPoolFactoryInvoked = new AtomicBoolean(false);
        bufferPoolSupplier =
                () -> {
                    bufferPoolFactoryInvoked.set(true);
                    return null;
                };
    }

    @AfterEach
    void tearDown() throws Exception {
        batchShuffleReadBufferPool.destroy();
        batchShuffleReadIOExecutor.shutdownNow();
        partitionManager.shutdown();
        channelManager.close();
    }

    // ---------------------------------------------------------------------
    // Pipelined partitions
    // ---------------------------------------------------------------------

    @Test
    void createPipelinedPartition_buildsPipelinedPartitionWithPipelinedSubpartitions() {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(factory, ResultPartitionType.PIPELINED, 3, null, false);

        assertThat(partition).isExactlyInstanceOf(PipelinedResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.PIPELINED, 3);
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isFalse();
        assertThat(bufferPoolFactoryInvoked).isFalse();

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(3);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i]).isExactlyInstanceOf(PipelinedSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    @Test
    void createPipelinedBoundedPartition_buildsPipelinedPartitionWithPipelinedSubpartitions() {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(
                        factory, ResultPartitionType.PIPELINED_BOUNDED, 2, null, true);

        assertThat(partition).isExactlyInstanceOf(PipelinedResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.PIPELINED_BOUNDED, 2);
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isTrue();

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(2);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i]).isExactlyInstanceOf(PipelinedSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    @Test
    void createPipelinedApproximatePartition_buildsApproximateSubpartitions() {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(
                        factory, ResultPartitionType.PIPELINED_APPROXIMATE, 3, null, false);

        assertThat(partition).isExactlyInstanceOf(PipelinedResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.PIPELINED_APPROXIMATE, 3);

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(3);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i])
                    .isExactlyInstanceOf(PipelinedApproximateSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    // ---------------------------------------------------------------------
    // Blocking partitions
    // ---------------------------------------------------------------------

    @Test
    void createBlockingPartition_belowSortShuffleThreshold_buildsBoundedBlockingPartition() {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(
                        factory,
                        ResultPartitionType.BLOCKING,
                        SORT_SHUFFLE_MIN_PARALLELISM - 1,
                        null,
                        false);

        assertThat(partition).isExactlyInstanceOf(BoundedBlockingResultPartition.class);
        assertCommonMetadata(
                partition, ResultPartitionType.BLOCKING, SORT_SHUFFLE_MIN_PARALLELISM - 1);

        ResultSubpartition[] subpartitions =
                ((BufferWritingResultPartition) partition).getAllPartitions();
        assertThat(subpartitions).hasSize(SORT_SHUFFLE_MIN_PARALLELISM - 1);
        for (int i = 0; i < subpartitions.length; i++) {
            assertThat(subpartitions[i]).isExactlyInstanceOf(BoundedBlockingSubpartition.class);
            assertSubpartitionMetadata(subpartitions[i], i);
        }
    }

    @Test
    void createBlockingPartition_atSortShuffleThreshold_buildsSortMergePartition() {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(
                        factory,
                        ResultPartitionType.BLOCKING,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null,
                        true);

        assertThat(partition).isExactlyInstanceOf(SortMergeResultPartition.class);
        assertCommonMetadata(
                partition, ResultPartitionType.BLOCKING, SORT_SHUFFLE_MIN_PARALLELISM);
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isTrue();
    }

    @Test
    void createBlockingPersistentPartition_belowThresholdPreservesPartitionType() {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(
                        factory, ResultPartitionType.BLOCKING_PERSISTENT, 2, null, false);

        assertThat(partition).isExactlyInstanceOf(BoundedBlockingResultPartition.class);
        assertCommonMetadata(partition, ResultPartitionType.BLOCKING_PERSISTENT, 2);
    }

    // ---------------------------------------------------------------------
    // Tiered / hybrid partitions
    // ---------------------------------------------------------------------

    @Test
    void createHybridFullPartition_delegatesToTieredFactoryAndForwardsArguments() {
        RecordingTieredResultPartitionFactory tieredFactory =
                new RecordingTieredResultPartitionFactory();
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        tieredFactory);

        List<TierShuffleDescriptor> tierShuffleDescriptors = Collections.emptyList();
        NettyShuffleDescriptor shuffleDescriptor =
                new NettyShuffleDescriptor(null, null, partitionId, tierShuffleDescriptors);

        ResultPartition partition =
                createPartition(
                        factory,
                        ResultPartitionType.HYBRID_FULL,
                        2,
                        shuffleDescriptor,
                        true);

        assertThat(partition).isExactlyInstanceOf(TieredResultPartition.class);
        assertThat(tieredFactory.invocationCount).isEqualTo(1);
        assertThat(tieredFactory.owningTaskName).isEqualTo(TASK_NAME);
        assertThat(tieredFactory.partitionIndex).isEqualTo(PARTITION_INDEX);
        assertThat(tieredFactory.partitionId).isSameAs(partitionId);
        assertThat(tieredFactory.partitionType).isEqualTo(ResultPartitionType.HYBRID_FULL);
        assertThat(tieredFactory.numPartitions).isEqualTo(NUMBER_OF_PARTITIONS);
        assertThat(tieredFactory.numSubpartitions).isEqualTo(2);
        assertThat(tieredFactory.maxParallelism).isEqualTo(MAX_PARALLELISM);
        assertThat(tieredFactory.bufferSizeBytes).isEqualTo(NETWORK_BUFFER_SIZE);
        assertThat(tieredFactory.isBroadcastOnly).isFalse();
        assertThat(tieredFactory.partitionManager).isSameAs(partitionManager);
        assertThat(tieredFactory.bufferCompressor).isNull();
        assertThat(tieredFactory.tierShuffleDescriptors).isSameAs(tierShuffleDescriptors);
        assertThat(tieredFactory.bufferPoolFactory).isSameAs(bufferPoolSupplier);
        assertThat(tieredFactory.fileChannelManager).isSameAs(channelManager);
        assertThat(tieredFactory.batchShuffleReadBufferPool)
                .isSameAs(batchShuffleReadBufferPool);
        assertThat(tieredFactory.batchShuffleReadIOExecutor)
                .isSameAs(batchShuffleReadIOExecutor);
        assertThat(tieredFactory.isNumberOfPartitionConsumerUndefined).isTrue();
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isTrue();
        assertThat(bufferPoolFactoryInvoked).isFalse();
    }

    @Test
    void createHybridSelectivePartition_delegatesToTieredFactoryWithType() {
        RecordingTieredResultPartitionFactory tieredFactory =
                new RecordingTieredResultPartitionFactory();
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        tieredFactory);

        List<TierShuffleDescriptor> tierShuffleDescriptors = Collections.emptyList();
        NettyShuffleDescriptor shuffleDescriptor =
                new NettyShuffleDescriptor(null, null, partitionId, tierShuffleDescriptors);

        ResultPartition partition =
                createPartition(
                        factory,
                        ResultPartitionType.HYBRID_SELECTIVE,
                        4,
                        shuffleDescriptor,
                        false);

        assertThat(partition).isExactlyInstanceOf(TieredResultPartition.class);
        assertThat(tieredFactory.invocationCount).isEqualTo(1);
        assertThat(tieredFactory.partitionType)
                .isEqualTo(ResultPartitionType.HYBRID_SELECTIVE);
        assertThat(tieredFactory.numSubpartitions).isEqualTo(4);
        assertThat(tieredFactory.tierShuffleDescriptors).isSameAs(tierShuffleDescriptors);
        assertThat(tieredFactory.isNumberOfPartitionConsumerUndefined).isFalse();
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isFalse();
    }

    @Test
    void createBlockingPartition_withTieredStorage_replacesTypeWithHybridFull() {
        RecordingTieredResultPartitionFactory tieredFactory =
                new RecordingTieredResultPartitionFactory();
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        tieredFactory);

        List<TierShuffleDescriptor> tierShuffleDescriptors = Collections.emptyList();
        NettyShuffleDescriptor shuffleDescriptor =
                new NettyShuffleDescriptor(null, null, partitionId, tierShuffleDescriptors);

        ResultPartition partition =
                createPartition(
                        factory, ResultPartitionType.BLOCKING, 2, shuffleDescriptor, false);

        assertThat(partition).isExactlyInstanceOf(TieredResultPartition.class);
        assertThat(tieredFactory.invocationCount).isEqualTo(1);
        assertThat(tieredFactory.partitionType).isEqualTo(ResultPartitionType.HYBRID_FULL);
        assertThat(tieredFactory.tierShuffleDescriptors).isSameAs(tierShuffleDescriptors);
        assertThat(partition.getPartitionType()).isEqualTo(ResultPartitionType.HYBRID_FULL);
        assertThat(partition.isNumberOfPartitionConsumerUndefined()).isFalse();
    }

    @Test
    void createHybridPartition_withNonNettyShuffleDescriptor_throwsIllegalStateException() {
        ResultPartitionFactory factory = createFactory();
        ShuffleDescriptor nonNettyDescriptor = new UnknownShuffleDescriptor(partitionId);

        assertThatThrownBy(
                        () ->
                                createPartition(
                                        factory,
                                        ResultPartitionType.HYBRID_FULL,
                                        2,
                                        nonNettyDescriptor,
                                        false))
                .isInstanceOf(IllegalStateException.class);
    }

    @Test
    void createHybridPartition_withNullShuffleDescriptor_throwsIllegalStateException() {
        ResultPartitionFactory factory = createFactory();

        assertThatThrownBy(
                        () ->
                                createPartition(
                                        factory,
                                        ResultPartitionType.HYBRID_SELECTIVE,
                                        2,
                                        null,
                                        false))
                .isInstanceOf(IllegalStateException.class);
    }

    // ---------------------------------------------------------------------
    // Compression
    // ---------------------------------------------------------------------

    @Test
    void createCompressiblePartitionWithCompressionEnabled_createsBufferCompressor()
            throws Exception {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        true,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(factory, ResultPartitionType.BLOCKING, 2, null, false);

        assertThat(readResultPartitionField(partition, "bufferCompressor"))
                .isInstanceOf(BufferCompressor.class);
    }

    @Test
    void createNonCompressiblePartitionWithCompressionEnabled_hasNoBufferCompressor()
            throws Exception {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        true,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(factory, ResultPartitionType.PIPELINED, 2, null, false);

        assertThat(readResultPartitionField(partition, "bufferCompressor")).isNull();
    }

    @Test
    void createCompressiblePartitionWithCompressionDisabled_hasNoBufferCompressor()
            throws Exception {
        ResultPartitionFactory factory =
                createFactory(
                        BoundedBlockingSubpartitionType.FILE,
                        false,
                        NETWORK_BUFFER_SIZE,
                        SORT_SHUFFLE_MIN_PARALLELISM,
                        null);

        ResultPartition partition =
                createPartition(factory, ResultPartitionType.BLOCKING, 2, null, false);

        assertThat(readResultPartitionField(partition, "bufferCompressor")).isNull();
    }

    // ---------------------------------------------------------------------
    // Buffer pool factory propagation
    // ---------------------------------------------------------------------

    @Test
    void create_passesBufferPoolFactoryToPartitionWithoutInvokingIt() throws Exception {
        ResultPartitionFactory factory = createFactory();

        ResultPartition partition =
                createPartition(factory, ResultPartitionType.PIPELINED, 2, null, false);

        assertThat(bufferPoolFactoryInvoked).isFalse();
        assertThat(readResultPartitionField(partition, "bufferPoolFactory"))
                .isSameAs(bufferPoolSupplier);
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private ResultPartitionFactory createFactory() {
        return createFactory(
                BoundedBlockingSubpartitionType.FILE,
                false,
                NETWORK_BUFFER_SIZE,
                SORT_SHUFFLE_MIN_PARALLELISM,
                null);
    }

    private ResultPartitionFactory createFactory(
            BoundedBlockingSubpartitionType blockingSubpartitionType,
            boolean batchShuffleCompressionEnabled,
            int networkBufferSize,
            int sortShuffleMinParallelism,
            TieredResultPartitionFactory tieredResultPartitionFactory) {
        return new ResultPartitionFactory(
                partitionManager,
                channelManager,
                bufferPoolFactory,
                batchShuffleReadBufferPool,
                batchShuffleReadIOExecutor,
                blockingSubpartitionType,
                2,
                2,
                networkBufferSize,
                networkBufferSize,
                batchShuffleCompressionEnabled,
                CompressionCodec.LZ4,
                2,
                2,
                sortShuffleMinParallelism,
                false,
                0,
                tieredResultPartitionFactory);
    }

    private ResultPartition createPartition(
            ResultPartitionFactory factory,
            ResultPartitionType type,
            int numberOfSubpartitions,
            ShuffleDescriptor shuffleDescriptor,
            boolean isNumberOfPartitionConsumerUndefined) {
        return factory.create(
                TASK_NAME,
                PARTITION_INDEX,
                partitionId,
                type,
                NUMBER_OF_PARTITIONS,
                numberOfSubpartitions,
                MAX_PARALLELISM,
                false,
                shuffleDescriptor,
                bufferPoolSupplier,
                isNumberOfPartitionConsumerUndefined);
    }

    private static void assertCommonMetadata(
            ResultPartition partition, ResultPartitionType type, int numberOfSubpartitions) {
        assertThat(partition.getOwningTaskName()).isEqualTo(TASK_NAME);
        assertThat(partition.getPartitionIndex()).isEqualTo(PARTITION_INDEX);
        assertThat(partition.getPartitionType()).isEqualTo(type);
        assertThat(partition.getNumberOfSubpartitions()).isEqualTo(numberOfSubpartitions);
        assertThat(partition.getNumTargetKeyGroups()).isEqualTo(MAX_PARALLELISM);
    }

    private static void assertSubpartitionMetadata(ResultSubpartition subpartition, int index) {
        assertThat(subpartition.getSubPartitionIndex()).isEqualTo(index);
        assertThat(subpartition.getSubpartitionInfo().getPartitionIdx())
                .isEqualTo(PARTITION_INDEX);
        assertThat(subpartition.getSubpartitionInfo().getSubPartitionIdx()).isEqualTo(index);
    }

    private static Object readResultPartitionField(ResultPartition partition, String fieldName)
            throws ReflectiveOperationException {
        Field field = ResultPartition.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(partition);
    }

    /** A buffer pool factory that fails loudly; {@code create} must not invoke it. */
    private static final class NoopBufferPoolFactory implements BufferPoolFactory {

        @Override
        public BufferPool createBufferPool(int numRequiredBuffers, int maxUsedBuffers) {
            throw new UnsupportedOperationException("Buffer pool must not be created by create().");
        }

        @Override
        public BufferPool createBufferPool(
                int numRequiredBuffers,
                int maxUsedBuffers,
                int numSubpartitions,
                int maxBuffersPerChannel,
                int maxOverdraftBuffersPerGate) {
            throw new UnsupportedOperationException("Buffer pool must not be created by create().");
        }
    }

    /** Records the arguments passed by {@link ResultPartitionFactory#create} to tiered storage. */
    private static final class RecordingTieredResultPartitionFactory
            extends TieredResultPartitionFactory {

        private int invocationCount;
        private String owningTaskName;
        private int partitionIndex;
        private ResultPartitionID partitionId;
        private ResultPartitionType partitionType;
        private int numPartitions;
        private int numSubpartitions;
        private int maxParallelism;
        private int bufferSizeBytes;
        private boolean isBroadcastOnly;
        private ResultPartitionManager partitionManager;
        private BufferCompressor bufferCompressor;
        private List<TierShuffleDescriptor> tierShuffleDescriptors;
        private SupplierWithException<BufferPool, IOException> bufferPoolFactory;
        private FileChannelManager fileChannelManager;
        private BatchShuffleReadBufferPool batchShuffleReadBufferPool;
        private ScheduledExecutorService batchShuffleReadIOExecutor;
        private boolean isNumberOfPartitionConsumerUndefined;

        RecordingTieredResultPartitionFactory() {
            super(null, null, null);
        }

        @Override
        public TieredResultPartition createTieredResultPartition(
                String owningTaskName,
                int partitionIndex,
                ResultPartitionID partitionId,
                ResultPartitionType partitionType,
                int numPartitions,
                int numSubpartitions,
                int maxParallelism,
                int bufferSizeBytes,
                Boolean isBroadCastOnly,
                ResultPartitionManager partitionManager,
                BufferCompressor bufferCompressor,
                List<TierShuffleDescriptor> tierShuffleDescriptors,
                SupplierWithException<BufferPool, IOException> bufferPoolFactory,
                FileChannelManager fileChannelManager,
                BatchShuffleReadBufferPool batchShuffleReadBufferPool,
                ScheduledExecutorService batchShuffleReadIOExecutor,
                boolean isNumberOfPartitionConsumerUndefined) {
            invocationCount++;
            this.owningTaskName = owningTaskName;
            this.partitionIndex = partitionIndex;
            this.partitionId = partitionId;
            this.partitionType = partitionType;
            this.numPartitions = numPartitions;
            this.numSubpartitions = numSubpartitions;
            this.maxParallelism = maxParallelism;
            this.bufferSizeBytes = bufferSizeBytes;
            this.isBroadcastOnly = Boolean.TRUE.equals(isBroadCastOnly);
            this.partitionManager = partitionManager;
            this.bufferCompressor = bufferCompressor;
            this.tierShuffleDescriptors = tierShuffleDescriptors;
            this.bufferPoolFactory = bufferPoolFactory;
            this.fileChannelManager = fileChannelManager;
            this.batchShuffleReadBufferPool = batchShuffleReadBufferPool;
            this.batchShuffleReadIOExecutor = batchShuffleReadIOExecutor;
            this.isNumberOfPartitionConsumerUndefined = isNumberOfPartitionConsumerUndefined;

            return new TieredResultPartition(
                    owningTaskName,
                    partitionIndex,
                    partitionId,
                    partitionType,
                    numSubpartitions,
                    maxParallelism,
                    partitionManager,
                    bufferCompressor,
                    bufferPoolFactory,
                    null,
                    null,
                    null,
                    null,
                    null);
        }
    }
}
