    private Run runJoin(
            DriverStrategy strategy,
            boolean objectReuse,
            TaskConfig taskConfig,
            Configuration taskManagerConfiguration)
            throws Exception {
        return runJoin(
                strategy,
                objectReuse,
                taskConfig,
                taskManagerConfiguration,
                INPUT_1,
                INPUT_2);
    }

    private Run runJoin(
            DriverStrategy strategy,
            boolean objectReuse,
            TaskConfig taskConfig,
            List<Integer> input1,
            List<Integer> input2)
            throws Exception {
        return runJoin(strategy, objectReuse, taskConfig, new Configuration(), input1, input2);
    }

    private Run runJoin(
            DriverStrategy strategy,
            boolean objectReuse,
            TaskConfig taskConfig,
            Configuration taskManagerConfiguration,
            List<Integer> input1,
            List<Integer> input2)
            throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        taskConfig,
                        strategy,
                        objectReuse,
                        input1,
                        input2,
                        taskManagerConfiguration);

        driver.prepare();
        driver.run();

        Run run = new Run();
        run.driver = driver;
        run.collectedOutput = ((TestTaskContext) getTaskContext(driver)).collected;
        run.driver.cleanup();
        return run;
    }

    private JoinDriver<Integer, Integer, String> createDriver(
            TaskConfig taskConfig,
            DriverStrategy strategy,
            boolean objectReuse,
            List<Integer> input1,
            List<Integer> input2,
            Configuration taskManagerConfiguration)
            throws Exception {

        TestTaskContext taskContext =
                new TestTaskContext(taskConfig, objectReuse, taskManagerConfiguration, input1, input2);
        taskContext.metricGroup = metricGroup;
        taskContext.containingTask = containingTask;
        taskContext.memoryManager = memoryManager;
        taskContext.ioManager = ioManager;

        JoinDriver<Integer, Integer, String> driver = new JoinDriver<>();
        driver.setup(taskContext);
        return driver;
    }

    private static TaskConfig configForStrategy(
            @SuppressWarnings("rawtypes") TypePairComparatorFactory pairComparatorFactory) {
        TaskConfig taskConfig = new TaskConfig(new Configuration());
        taskConfig.setRelativeMemoryDriver(MEMORY_FRACTION);
        if (pairComparatorFactory != null) {
            taskConfig.setDriverPairComparator(pairComparatorFactory);
        }
        return taskConfig;
    }

    private static JoinTaskIterator<?, ?, ?> getJoinIterator(JoinDriver<?, ?, ?> driver) {
        try {
            Field field = JoinDriver.class.getDeclaredField("joinIterator");
            field.setAccessible(true);
            return (JoinTaskIterator<?, ?, ?>) field.get(driver);
        } catch (ReflectiveOperationException e) {
            throw new RuntimeException(e);
        }
    }

    private static TaskContext<?, ?> getTaskContext(JoinDriver<?, ?, ?> driver) {
        try {
            Field field = JoinDriver.class.getDeclaredField("taskContext");
            field.setAccessible(true);
            return (TaskContext<?, ?>) field.get(driver);
        } catch (ReflectiveOperationException e) {
            throw new RuntimeException(e);
        }
    }

    private static void assertThatCode(ThrowingRunnable runnable) {
        try {
            runnable.run();
        } catch (Exception e) {
            throw new AssertionError("Unexpected exception", e);
        }
    }

    private interface ThrowingRunnable {
        void run() throws Exception;
    }

