    // --------------------------------------------------------------------------------------------
    //  observable side effects of prepare(): record counting and opened iterator
    // --------------------------------------------------------------------------------------------

    @Test
    void prepareCountsAllConsumedInputRecordsAndProducedOutputRecords() throws Exception {
        for (DriverStrategy strategy :
                Arrays.asList(
                        DriverStrategy.INNER_MERGE,
                        DriverStrategy.HYBRIDHASH_BUILD_FIRST,
                        DriverStrategy.HYBRIDHASH_BUILD_SECOND)) {
            JoinDriver<Integer, Integer, String> driver =
                    createDriver(jobConfig(strategy, true), false, INPUT_1, INPUT_2);

            driver.prepare();
            List<String> output = runAndCollect(driver);

            assertThat(output).as("result for strategy %s", strategy).hasSize(4);
            assertThat(numRecordsIn.getCount())
                    .as("numRecordsIn for strategy %s", strategy)
                    .isEqualTo(INPUT_1.size() + INPUT_2.size());
            assertThat(numRecordsOut.getCount())
                    .as("numRecordsOut for strategy %s", strategy)
                    .isEqualTo(EXPECTED_RESULT.size());

            driver.cleanup();
        }
    }

    @Test
    void prepareLeavesAnOpenedIteratorThatHandlesEmptyInputs() throws Exception {
        // If prepare() did not open the join iterator, run() would not be able to consume the
        // (empty) inputs. An empty input is the boundary case of zero records to join.
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.INNER_MERGE, true),
                        false,
                        Collections.<Integer>emptyList(),
                        Collections.<Integer>emptyList());

        driver.prepare();
        List<String> output = runAndCollect(driver);

        assertThat(output).isEmpty();
        assertThat(numRecordsIn.getCount()).isZero();
        assertThat(numRecordsOut.getCount()).isZero();
    }

    @Test
    void prepareUsesBloomFilterSettingFromTaskManagerConfiguration() throws Exception {
        Configuration taskManagerConfiguration = new Configuration();
        taskManagerConfiguration.set(AlgorithmOptions.HASH_JOIN_BLOOM_FILTERS, true);

        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, true),
                        false,
                        INPUT_1,
                        INPUT_2,
                        taskManagerConfiguration);

        driver.prepare();

        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    @Test
    void prepareCompletesWithoutResultsWhenInputsHaveNoCommonKeys() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_SECOND, true),
                        false,
                        Arrays.asList(1, 2),
                        Arrays.asList(3, 4));

        driver.prepare();
        List<String> output = runAndCollect(driver);

        assertThat(output).isEmpty();
        assertThat(numRecordsIn.getCount()).isEqualTo(4);
    }

