        JoinDriver<Integer, Integer, String> driver =
                createDriver(jobConfig(DriverStrategy.INNER_MERGE, true), true, INPUT_1, INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver)).isInstanceOf(ReusingMergeInnerJoinIterator.class);
