        assertThat(getJoinIterator(driver)).isNull();
    }

    // --------------------------------------------------------------------------------------------
    //  cleanup
    // --------------------------------------------------------------------------------------------

    @Test
    void cleanupReleasesAllMemoryAllocatedByPrepareAndCanBeRepeated() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, true), false, INPUT_1, INPUT_2);

        driver.prepare();
        runAndCollect(driver);

        driver.cleanup();

        assertThat(getJoinIterator(driver)).isNull();
        assertThat(memoryManager.availableMemory())
                .as("all memory allocated by prepare() must be released by cleanup()")
                .isEqualTo(memoryManager.getMemorySize());

        // a second cleanup must be a no-op and must not fail
        driver.cleanup();
        assertThat(getJoinIterator(driver)).isNull();
    }

