    private static final class IntListIterator implements MutableObjectIterator<Integer> {

        private final java.util.Iterator<Integer> iterator;

        private IntListIterator(List<Integer> values) {
            this.iterator = new ArrayList<>(values).iterator();
        }

        @Override
        public Integer next(Integer reuse) {
            return iterator.hasNext() ? iterator.next() : null;
        }

        @Override
        public Integer next() {
            return iterator.hasNext() ? iterator.next() : null;
        }
    }

    private static final class IntSerializerFactory implements TypeSerializerFactory<Integer> {

        private static final IntSerializerFactory INSTANCE = new IntSerializerFactory();

        @Override
        public void writeParametersToConfig(Configuration config) {}

        @Override
        public void readParametersFromConfig(Configuration config, ClassLoader cl) {}

        @Override
        public TypeSerializer<Integer> getSerializer() {
            return IntSerializer.INSTANCE;
        }

        @Override
        public Class<Integer> getDataType() {
            return Integer.class;
        }
    }

    /** Equality of the (integer) key, which is the whole record in these tests. */
    private static final class IntPairComparator extends TypePairComparator<Integer, Integer> {

        private Integer reference;

        @Override
        public void setReference(Integer reference) {
            this.reference = reference;
        }

        @Override
        public boolean equalToReference(Integer candidate) {
            return reference.equals(candidate);
        }

        @Override
        public int compareToReference(Integer candidate) {
            return candidate.compareTo(reference);
        }
    }

