/**
 * Tests for {@link JoinDriver#prepare()}: the strategy selection (with and without object reuse),
 * the record counting that is wrapped around the inputs, the configuration driven fail-fast
 * behavior, the memory sizing, and the fact that {@code prepare()} leaves a fully opened join
 * iterator behind.
 */
class JoinDriverPrepareTests {

    private static final int PAGE_SIZE = MemoryManager.DEFAULT_PAGE_SIZE;
    private static final long MEMORY_SIZE = 8L * 1024 * 1024;
    private static final double MEMORY_FRACTION = 0.5;

    private static final List<Integer> INPUT_1 = Arrays.asList(1, 1, 2, 3);
    private static final List<Integer> INPUT_2 = Arrays.asList(1, 3, 3);

    /** Cross product of the matching keys of {@link #INPUT_1} and {@link #INPUT_2}. */
    private static final List<String> EXPECTED_RESULT = Arrays.asList("1:1", "1:1", "3:3", "3:3");

    private IOManager ioManager;
    private MemoryManager memoryManager;
    private AbstractInvokable containingTask;
    private OperatorMetricGroup metricGroup;
    private Counter numRecordsIn;
    private Counter numRecordsOut;

    @BeforeEach
    void setUp() {
        ioManager = new IOManagerAsync();
        memoryManager = MemoryManager.create(MEMORY_SIZE, PAGE_SIZE);
        containingTask = mock(AbstractInvokable.class);

        numRecordsIn = new SimpleCounter();
        numRecordsOut = new SimpleCounter();

        OperatorIOMetricGroup ioMetricGroup = mock(OperatorIOMetricGroup.class);
        when(ioMetricGroup.getNumRecordsInCounter()).thenReturn(numRecordsIn);
        when(ioMetricGroup.getNumRecordsOutCounter()).thenReturn(numRecordsOut);

        metricGroup = mock(OperatorMetricGroup.class);
        when(metricGroup.getIOMetricGroup()).thenReturn(ioMetricGroup);
    }

    @AfterEach
    void tearDown() {
        if (memoryManager != null) {
            memoryManager.shutdown();
            memoryManager = null;
        }
        if (ioManager != null) {
            ioManager.close();
            ioManager = null;
        }
    }

    // --------------------------------------------------------------------------------------------
    //  happy paths: strategy selection without object reuse
    // --------------------------------------------------------------------------------------------

    @Test
    void prepareCreatesNonReusingMergeInnerJoinIterator() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(jobConfig(DriverStrategy.INNER_MERGE, true), false, INPUT_1, INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver)).isInstanceOf(NonReusingMergeInnerJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    @Test
    void prepareCreatesNonReusingBuildFirstHashJoinIterator() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, true),
                        false,
                        INPUT_1,
                        INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver))
                .isInstanceOf(NonReusingBuildFirstHashJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    @Test
    void prepareCreatesNonReusingBuildSecondHashJoinIterator() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_SECOND, true),
                        false,
                        INPUT_1,
                        INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver))
                .isInstanceOf(NonReusingBuildSecondHashJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    // --------------------------------------------------------------------------------------------
    //  happy paths: strategy selection with object reuse
    // --------------------------------------------------------------------------------------------

    @Test
    void prepareCreatesReusingMergeInnerJoinIteratorWhenObjectReuseIsEnabled() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(jobConfig(DriverStrategy.INNER_MERGE, true), true, INPUT_1, INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver)).isInstanceOf(ReusingMergeInnerJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    @Test
    void prepareCreatesReusingBuildFirstHashJoinIteratorWhenObjectReuseIsEnabled() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, true),
                        true,
                        INPUT_1,
                        INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver)).isInstanceOf(ReusingBuildFirstHashJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    @Test
    void prepareCreatesReusingBuildSecondHashJoinIteratorWhenObjectReuseIsEnabled() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_SECOND, true),
                        true,
                        INPUT_1,
                        INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver)).isInstanceOf(ReusingBuildSecondHashJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    // --------------------------------------------------------------------------------------------
    //  observable side effects of prepare(): record counting and opened iterator
    // --------------------------------------------------------------------------------------------

    @Test
    void prepareCountsAllConsumedInputRecordsAndProducedOutputRecords() throws Exception {
        for (DriverStrategy strategy :
                Arrays.asList(
                        DriverStrategy.INNER_MERGE,
                        DriverStrategy.HYBRIDHASH_BUILD_FIRST,
                        DriverStrategy.HYBRIDHASH_BUILD_SECOND)) {
            JoinDriver<Integer, Integer, String> driver =
                    createDriver(jobConfig(strategy, true), false, INPUT_1, INPUT_2);

            driver.prepare();
            List<String> output = runAndCollect(driver);

            assertThat(output).as("result for strategy %s", strategy).hasSize(4);
            assertThat(numRecordsIn.getCount())
                    .as("numRecordsIn for strategy %s", strategy)
                    .isEqualTo(INPUT_1.size() + INPUT_2.size());
            assertThat(numRecordsOut.getCount())
                    .as("numRecordsOut for strategy %s", strategy)
                    .isEqualTo(EXPECTED_RESULT.size());

            driver.cleanup();
        }
    }

    @Test
    void prepareLeavesAnOpenedIteratorThatHandlesEmptyInputs() throws Exception {
        // If prepare() did not open the join iterator, run() would not be able to consume the
        // (empty) inputs. An empty input is the boundary case of zero records to join.
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.INNER_MERGE, true),
                        false,
                        Collections.<Integer>emptyList(),
                        Collections.<Integer>emptyList());

        driver.prepare();
        List<String> output = runAndCollect(driver);

        assertThat(output).isEmpty();
        assertThat(numRecordsIn.getCount()).isZero();
        assertThat(numRecordsOut.getCount()).isZero();
    }

    @Test
    void prepareUsesBloomFilterSettingFromTaskManagerConfiguration() throws Exception {
        Configuration taskManagerConfiguration = new Configuration();
        taskManagerConfiguration.set(AlgorithmOptions.HASH_JOIN_BLOOM_FILTERS, true);

        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, true),
                        false,
                        INPUT_1,
                        INPUT_2,
                        taskManagerConfiguration);

        driver.prepare();

        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    @Test
    void prepareCompletesWithoutResultsWhenInputsHaveNoCommonKeys() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_SECOND, true),
                        false,
                        Arrays.asList(1, 2),
                        Arrays.asList(3, 4));

        driver.prepare();
        List<String> output = runAndCollect(driver);

        assertThat(output).isEmpty();
        assertThat(numRecordsIn.getCount()).isEqualTo(4);
    }

    // --------------------------------------------------------------------------------------------
    //  memory sizing
    // --------------------------------------------------------------------------------------------

    @Test
    void prepareDerivesNumberOfPagesFromRelativeMemoryDriver() throws Exception {
        // A memory manager of exactly two pages combined with the configured fraction of 0.5
        // yields a single page, which is too little for the sort-merge based join iterator.
        useMemoryManagerWithTwoPages();

        JoinDriver<Integer, Integer, String> driver =
                createDriver(jobConfig(DriverStrategy.INNER_MERGE, true), false, INPUT_1, INPUT_2);

        assertThatThrownBy(driver::prepare)
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("at least 2 memory pages");
        assertThat(getJoinIterator(driver)).isNull();
    }

    @Test
    void prepareSucceedsWhenTheMemoryFractionYieldsEnoughPages() throws Exception {
        // The same memory manager, but this time the whole memory is requested.
        useMemoryManagerWithTwoPages();

        TaskConfig taskConfig = new TaskConfig(new Configuration());
        taskConfig.setDriverStrategy(DriverStrategy.INNER_MERGE);
        taskConfig.setRelativeMemoryDriver(1.0);
        taskConfig.setDriverPairComparator(new IntPairComparatorFactory());

        JoinDriver<Integer, Integer, String> driver = createDriver(taskConfig, false, INPUT_1, INPUT_2);

        driver.prepare();

        assertThat(getJoinIterator(driver)).isInstanceOf(NonReusingMergeInnerJoinIterator.class);
        assertThat(runAndCollect(driver)).containsExactlyInAnyOrderElementsOf(EXPECTED_RESULT);
    }

    // --------------------------------------------------------------------------------------------
    //  invalid configurations
    // --------------------------------------------------------------------------------------------

    @Test
    void prepareThrowsWhenPairComparatorFactoryIsMissing() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(jobConfig(DriverStrategy.INNER_MERGE, false), false, INPUT_1, INPUT_2);

        assertThatThrownBy(driver::prepare)
                .isInstanceOf(Exception.class)
                .hasMessage("Missing pair comparator factory for join driver");
        assertThat(getJoinIterator(driver)).isNull();
        assertThat(numRecordsIn.getCount()).isZero();
        assertThat(memoryManager.availableMemory()).isEqualTo(memoryManager.getMemorySize());
    }

    @Test
    void prepareThrowsWhenPairComparatorFactoryIsMissingForHashStrategy() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, false),
                        false,
                        INPUT_1,
                        INPUT_2);

        assertThatThrownBy(driver::prepare)
                .isInstanceOf(Exception.class)
                .hasMessage("Missing pair comparator factory for join driver");
        assertThat(getJoinIterator(driver)).isNull();
    }

    @Test
    void prepareThrowsForUnsupportedStrategyWithoutObjectReuse() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(jobConfig(DriverStrategy.MAP, true), false, INPUT_1, INPUT_2);

        assertThatThrownBy(driver::prepare)
                .isInstanceOf(Exception.class)
                .hasMessage("Unsupported driver strategy for join driver: MAP");
        assertThat(getJoinIterator(driver)).isNull();
    }

    @Test
    void prepareThrowsForUnsupportedStrategyWithObjectReuse() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.NESTEDLOOP_STREAMED_OUTER_SECOND, true),
                        true,
                        INPUT_1,
                        INPUT_2);

        assertThatThrownBy(driver::prepare)
                .isInstanceOf(Exception.class)
                .hasMessage(
                        "Unsupported driver strategy for join driver: "
                                + "NESTEDLOOP_STREAMED_OUTER_SECOND");
        assertThat(getJoinIterator(driver)).isNull();
    }

    // --------------------------------------------------------------------------------------------
    //  cleanup
    // --------------------------------------------------------------------------------------------

    @Test
    void cleanupReleasesAllMemoryAllocatedByPrepareAndCanBeRepeated() throws Exception {
        JoinDriver<Integer, Integer, String> driver =
                createDriver(
                        jobConfig(DriverStrategy.HYBRIDHASH_BUILD_FIRST, true), false, INPUT_1, INPUT_2);

        driver.prepare();
        runAndCollect(driver);

        driver.cleanup();

        assertThat(getJoinIterator(driver)).isNull();
        assertThat(memoryManager.availableMemory())
                .as("all memory allocated by prepare() must be released by cleanup()")
                .isEqualTo(memoryManager.getMemorySize());

        // a second cleanup must be a no-op and must not fail
        driver.cleanup();
        assertThat(getJoinIterator(driver)).isNull();
    }

    // --------------------------------------------------------------------------------------------
    //  helpers
    // --------------------------------------------------------------------------------------------

    private void useMemoryManagerWithTwoPages() {
        memoryManager.shutdown();
        memoryManager = MemoryManager.create(2L * PAGE_SIZE, PAGE_SIZE);
    }

    private static TaskConfig jobConfig(DriverStrategy strategy, boolean withPairComparatorFactory) {
        TaskConfig taskConfig = new TaskConfig(new Configuration());
        taskConfig.setDriverStrategy(strategy);
        taskConfig.setRelativeMemoryDriver(MEMORY_FRACTION);
        if (withPairComparatorFactory) {
            taskConfig.setDriverPairComparator(new IntPairComparatorFactory());
        }
        return taskConfig;
    }

    private JoinDriver<Integer, Integer, String> createDriver(
            TaskConfig taskConfig,
            boolean objectReuse,
            List<Integer> input1,
            List<Integer> input2)
            throws Exception {
        return createDriver(taskConfig, objectReuse, input1, input2, new Configuration());
    }

    private JoinDriver<Integer, Integer, String> createDriver(
            TaskConfig taskConfig,
            boolean objectReuse,
            List<Integer> input1,
            List<Integer> input2,
            Configuration taskManagerConfiguration)
            throws Exception {

        TestTaskContext taskContext =
                new TestTaskContext(
                        taskConfig, objectReuse, taskManagerConfiguration, input1, input2);
        taskContext.metricGroup = metricGroup;
        taskContext.containingTask = containingTask;
        taskContext.memoryManager = memoryManager;
        taskContext.ioManager = ioManager;

        JoinDriver<Integer, Integer, String> driver = new JoinDriver<>();
        driver.setup(taskContext);
        return driver;
    }

    private static List<String> runAndCollect(JoinDriver<Integer, Integer, String> driver)
            throws Exception {
        driver.run();
        return taskContextOf(driver).collected;
    }

    private static TestTaskContext taskContextOf(JoinDriver<Integer, Integer, String> driver) {
        try {
            Field field = JoinDriver.class.getDeclaredField("taskContext");
            field.setAccessible(true);
            return (TestTaskContext) field.get(driver);
        } catch (ReflectiveOperationException e) {
            throw new RuntimeException(e);
        }
    }

    private static JoinTaskIterator<?, ?, ?> getJoinIterator(JoinDriver<?, ?, ?> driver) {
        try {
            Field field = JoinDriver.class.getDeclaredField("joinIterator");
            field.setAccessible(true);
            return (JoinTaskIterator<?, ?, ?>) field.get(driver);
        } catch (ReflectiveOperationException e) {
            throw new RuntimeException(e);
        }
    }

    // --------------------------------------------------------------------------------------------
    //  test doubles
    // --------------------------------------------------------------------------------------------

    private static final class TestTaskContext
            implements TaskContext<FlatJoinFunction<Integer, Integer, String>, String> {

        private final TaskConfig taskConfig;
        private final ExecutionConfig executionConfig = new ExecutionConfig();
        private final Configuration taskManagerConfiguration;
        private final MutableObjectIterator<Integer> input1;
        private final MutableObjectIterator<Integer> input2;
        private final List<String> collected = new ArrayList<>();

        private MemoryManager memoryManager;
        private IOManager ioManager;
        private AbstractInvokable containingTask;
        private OperatorMetricGroup metricGroup;

        private TestTaskContext(
                TaskConfig taskConfig,
                boolean objectReuse,
                Configuration taskManagerConfiguration,
                List<Integer> input1,
                List<Integer> input2) {
            this.taskConfig = taskConfig;
            this.taskManagerConfiguration = taskManagerConfiguration;
            if (objectReuse) {
                this.executionConfig.enableObjectReuse();
            } else {
                this.executionConfig.disableObjectReuse();
            }
            this.input1 = new IntListIterator(input1);
            this.input2 = new IntListIterator(input2);
        }

        @Override
        public TaskConfig getTaskConfig() {
            return taskConfig;
        }

        @Override
        public TaskManagerRuntimeInfo getTaskManagerInfo() {
            TaskManagerRuntimeInfo info = mock(TaskManagerRuntimeInfo.class);
            when(info.getConfiguration()).thenReturn(taskManagerConfiguration);
            when(info.getTmpDirectories()).thenReturn(new String[0]);
            when(info.getTmpWorkingDirectory()).thenReturn(new File("."));
            when(info.getTaskManagerExternalAddress()).thenReturn("localhost");
            return info;
        }

        @Override
        public ClassLoader getUserCodeClassLoader() {
            return getClass().getClassLoader();
        }

        @Override
        public MemoryManager getMemoryManager() {
            return memoryManager;
        }

        @Override
        public IOManager getIOManager() {
            return ioManager;
        }

        @Override
        @SuppressWarnings("unchecked")
        public <X> MutableObjectIterator<X> getInput(int index) {
            return (MutableObjectIterator<X>) (index == 0 ? input1 : input2);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <X> TypeSerializerFactory<X> getInputSerializer(int index) {
            return (TypeSerializerFactory<X>) IntSerializerFactory.INSTANCE;
        }

        @Override
        @SuppressWarnings("unchecked")
        public <X> TypeComparator<X> getDriverComparator(int index) {
            return (TypeComparator<X>) IntComparator.INSTANCE;
        }

        @Override
        public FlatJoinFunction<Integer, Integer, String> getStub() {
            return (first, second, out) -> out.collect(first + ":" + second);
        }

        @Override
        public ExecutionConfig getExecutionConfig() {
            return executionConfig;
        }

        @Override
        public Collector<String> getOutputCollector() {
            return collected::add;
        }

        @Override
        public AbstractInvokable getContainingTask() {
            return containingTask;
        }

        @Override
        public String formatLogString(String message) {
            return message;
        }

        @Override
        public OperatorMetricGroup getMetricGroup() {
            return metricGroup;
        }
    }

    private static final class IntListIterator implements MutableObjectIterator<Integer> {

        private final java.util.Iterator<Integer> iterator;

        private IntListIterator(List<Integer> values) {
            this.iterator = new ArrayList<>(values).iterator();
        }

        @Override
        public Integer next(Integer reuse) {
            return iterator.hasNext() ? iterator.next() : null;
        }

        @Override
        public Integer next() {
            return iterator.hasNext() ? iterator.next() : null;
        }
    }

    private static final class IntSerializerFactory implements TypeSerializerFactory<Integer> {

        private static final IntSerializerFactory INSTANCE = new IntSerializerFactory();

        @Override
        public void writeParametersToConfig(Configuration config) {}

        @Override
        public void readParametersFromConfig(Configuration config, ClassLoader cl) {}

        @Override
        public TypeSerializer<Integer> getSerializer() {
            return IntSerializer.INSTANCE;
        }

        @Override
        public Class<Integer> getDataType() {
            return Integer.class;
        }
    }

    /** Equality of the (integer) key, which is the whole record in these tests. */
    private static final class IntPairComparator extends TypePairComparator<Integer, Integer> {

        private Integer reference;

        @Override
        public void setReference(Integer reference) {
            this.reference = reference;
        }

        @Override
        public boolean equalToReference(Integer candidate) {
            return reference.equals(candidate);
        }

        @Override
        public int compareToReference(Integer candidate) {
            return candidate.compareTo(reference);
        }
    }

    /** Public so that it can be instantiated reflectively from the {@link TaskConfig}. */
    public static final class IntPairComparatorFactory
            implements TypePairComparatorFactory<Integer, Integer> {

        @Override
        public TypePairComparator<Integer, Integer> createComparator12(
                TypeComparator<Integer> comparator1, TypeComparator<Integer> comparator2) {
            return new IntPairComparator();
        }

        @Override
        public TypePairComparator<Integer, Integer> createComparator21(
                TypeComparator<Integer> comparator1, TypeComparator<Integer> comparator2) {
            return new IntPairComparator();
        }
    }
}
