private void assertBucketStructure() {
    int buckets = numBuckets();
    MemorySegment[] bucketArray = bucketsArray();
    assertThat(bucketArray.length).isEqualTo(ceilDiv(buckets, BUCKETS_PER_SEGMENT));
    int numPartitions = partitions().size();
    for (int b = 0; b < buckets; b++) {
        MemorySegment segment = bucketArray[b / BUCKETS_PER_SEGMENT];
        int offset = (b % BUCKETS_PER_SEGMENT) * HASH_BUCKET_SIZE;
        assertThat(segment.get(offset + HEADER_PARTITION_OFFSET))
            .as("partition of bucket %d", b)
            .isEqualTo((byte) (b % numPartitions));
        int count = segment.getInt(offset + HEADER_COUNT_OFFSET);
        assertThat(count).as("entry count of bucket %d", b).isBetween(0, MAX_ENTRIES_PER_BUCKET);
    }
}
