@Test
void testResizeFailsWithoutSufficientMemory() throws Exception {
    createTable(50);

    assertThat(numBuckets()).isEqualTo(160);
    assertThat(bucketsArray()).hasSize(20);
    assertThat(memory).hasSize(19);

    for (int i = 0; i < 20; i++) {
        table.insert(i);
    }

    // the table needs 20 additional segments but only 19 are available and no partition
    // holds any garbage that could be reclaimed
    assertThat(table.resizeHashTable()).isFalse();

    // the failed attempt must leave the table completely untouched
    assertThat(numBuckets()).isEqualTo(160);
    assertThat(bucketsArray()).hasSize(20);
    assertThat(isResizing()).isFalse();
    assertThat(memory).hasSize(19);
    assertTableIsConsistent();
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 20));

    // providing the missing memory makes the next attempt succeed
    addMemory(10);
    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(320);
    assertThat(bucketsArray()).hasSize(40);
    assertThat(memory).hasSize(9);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 20));
}

@Test
void testResizeReturnsFalseWhenTableIsClosed() throws Exception {
    createTable(100);

    for (int i = 0; i < 10; i++) {
        table.insert(i);
    }

    // enough memory is available, so the resize is refused because of the closed flag only
    assertThat(memory.size()).isGreaterThanOrEqualTo(40);
    setClosed();

    assertThat(table.resizeHashTable()).isFalse();

    assertThat(numBuckets()).isEqualTo(320);
    assertThat(bucketsArray()).hasSize(40);
    assertThat(isResizing()).isFalse();
    assertThat(memory).hasSize(49);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 10));
}

@Test
void testResizeReclaimsMemoryOfPartitionsHoldingGarbage() throws Exception {
    createTable(60);

    assertThat(numBuckets()).isEqualTo(190);
    assertThat(memory).hasSize(25);

    // keys that are spread over distinct buckets of the first partition, so that no overflow
    // bucket is needed and all records stay in that single partition
    final List<Integer> keys = keysForPartition(0, 15);

    // overwrite the records over and over again: this fills the partition with garbage and
    // eats up the available memory, so that the resize has to compact the partition first
    for (int i = 0; i < 67; i++) {
        for (int key : keys) {
            table.insertOrReplaceRecord(key);
        }
    }

    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);
    // not enough memory left for doubling the bucket table
    assertThat(memory.size()).isLessThan(24);

    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(380);
    assertThat(bucketsArray()).hasSize(48);
    assertThat(isResizing()).isFalse();
    assertTableIsConsistent();
    // compaction reclaimed the garbage, hence exactly the segments for the new buckets are
    // missing from the pool afterwards
    assertThat(memory).hasSize(1);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);
}

@Test
void testResizeWithOverflowBucketsInTable() throws Exception {
    createTable(100);

    final int targetBucket = 5;
    final List<Integer> keys = keysForBucket(targetBucket, 30);

    for (int key : keys) {
        table.insert(key);
    }

    // 30 records in one bucket require overflow buckets, i.e. another segment was taken
    assertThat(memory.size()).isLessThan(49);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);

    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(640);
    assertThat(isResizing()).isFalse();
    assertTableIsConsistent();
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);
}

