327	    /** Removes the given number of segments from the free memory of the table. */
328	    private List<MemorySegment> withholdMemory(int numSegments) {
329	        final List<MemorySegment> withheld = new ArrayList<>(numSegments);
330	        for (int i = 0; i < numSegments; i++) {
331	            withheld.add(memory.remove(memory.size() - 1));
332	        }
333	        return withheld;
334	    }
335	
336	    @AfterEach
337	    void tearDown() {
338	        if (table != null) {
339	            if (!(Boolean) fieldValue(table, "closed")) {
340	                table.close();
341	            }
342	            table = null;
343	        }
344	        memory = null;
345	    }
