347	    // ------------------------------------------------------------------------
348	    //  Assertions
349	    // ------------------------------------------------------------------------
350	
351	    /**
352	     * Verifies the invariants every bucket of the table must obey: the bucket is located in the
353	     * expected segment, it belongs to the partition given by the bucket number and its entry count
354	     * is within the format's limits.
355	     */
356	    private void assertTableIsConsistent() {
357	        final int numBuckets = numBuckets();
358	        final MemorySegment[] buckets = bucketsArray();
359	        final int numPartitions = partitions().size();
360	
361	        assertThat(buckets.length)
362	                .isEqualTo((numBuckets + BUCKETS_PER_SEGMENT - 1) / BUCKETS_PER_SEGMENT);
363	        assertThat(numBuckets % numPartitions).isZero();
364	
365	        for (int bucket = 0; bucket < numBuckets; bucket++) {
366	            final MemorySegment segment = buckets[bucket / BUCKETS_PER_SEGMENT];
367	            final int bucketOffset = (bucket % BUCKETS_PER_SEGMENT) * HASH_BUCKET_SIZE;
368	
369	            assertThat(segment.get(bucketOffset + HEADER_PARTITION_OFFSET))
370	                    .as("partition of bucket %d", bucket)
371	                    .isEqualTo((byte) (bucket % numPartitions));
372	
373	            assertThat(segment.getInt(bucketOffset + HEADER_COUNT_OFFSET))
374	                    .as("entry count of bucket %d", bucket)
375	                    .isBetween(0, MAX_ENTRIES_PER_BUCKET);
376	        }
377	    }
378	
379	    /** Verifies that the resize neither leaks nor double counts memory segments. */
380	    private int countOwnedSegments() {
381	        int owned = memory.size() + bucketsArray().length;
382	
383	        for (InMemoryPartition<Integer> partition : partitions()) {
384	            owned += partitionPages(partition).size();
385	            owned += (Integer) fieldValue(partition, "numOverflowSegments");
386	        }
387	
388	        final InMemoryPartition<Integer> compactionMemory =
389	                asPartition(fieldValue(table, "compactionMemory"));
390	        owned += partitionPages(compactionMemory).size();
391	        return owned;
392	    }
