394	    // ------------------------------------------------------------------------
395	    //  Helpers
396	    // ------------------------------------------------------------------------
397	
398	    private Set<Integer> entries() throws IOException {
399	        final MutableObjectIterator<Integer> iterator = table.getEntryIterator();
400	        final Set<Integer> result = new LinkedHashSet<>();
401	        Integer next;
402	        while ((next = iterator.next()) != null) {
403	            assertThat(result.add(next)).as("record %s returned twice", next).isTrue();
404	        }
405	        return result;
406	    }
