408	    /**
409	     * Computes the bucket a record with the given key is mapped to by the hash table.
410	     *
411	     * @param key the record
412	     * @param numBuckets the number of buckets of the table
413	     * @return the bucket index the table uses for the record
414	     */
415	    private int bucketOf(int key, int numBuckets) {
416	        return MathUtils.jenkinsHash(COMPARATOR.hash(key)) % numBuckets;
417	    }
418	
419	    /** Returns keys whose records are stored in the given bucket. */
420	    private List<Integer> keysForBucket(int bucket, int count) {
421	        final int numBuckets = numBuckets();
422	        final List<Integer> keys = new ArrayList<>(count);
423	        for (int candidate = 0; keys.size() < count; candidate++) {
424	            if (bucketOf(candidate, numBuckets) == bucket) {
425	                keys.add(candidate);
426	            }
427	        }
428	        return keys;
429	    }
430	
431	    /** Returns keys whose records are stored in distinct buckets of the given partition. */
432	    private List<Integer> keysForPartition(int partition, int count) {
433	        final int numBuckets = numBuckets();
434	        final int numPartitions = partitions().size();
435	        final Set<Integer> usedBuckets = new HashSet<>();
436	        final List<Integer> keys = new ArrayList<>(count);
437	        for (int candidate = 0; keys.size() < count; candidate++) {
438	            final int bucket = bucketOf(candidate, numBuckets);
439	            if (bucket % numPartitions == partition && usedBuckets.add(bucket)) {
440	                keys.add(candidate);
441	            }
442	        }
443	        return keys;
444	    }
