489	    private static Object fieldValue(Object target, String name) {
490	        try {
491	            return findField(target.getClass(), name).get(target);
492	        } catch (IllegalAccessException e) {
493	            throw new IllegalStateException(e);
494	        }
495	    }
496	
497	    private static void setFieldValue(Object target, String name, Object value) {
498	        try {
499	            findField(target.getClass(), name).set(target, value);
500	        } catch (IllegalAccessException e) {
501	            throw new IllegalStateException(e);
502	        }
503	    }
