505	    /** Minimal pair comparator that allows lookups of integer records through a prober. */
506	    private static final class IntPairComparator extends TypePairComparator<Integer, Integer> {
507	
508	        private int reference;
509	
510	        @Override
511	        public void setReference(Integer reference) {
512	            this.reference = reference;
513	        }
514	
515	        @Override
516	        public boolean equalToReference(Integer candidate) {
517	            return candidate == this.reference;
518	        }
519	
520	        @Override
521	        public int compareToReference(Integer candidate) {
522	            return Integer.compare(candidate, this.reference);
523	        }
524	    }
525	
526	    private static Field findField(Class<?> clazz, String name) {
527	        Class<?> current = clazz;
528	        while (current != null) {
529	            try {
530	                final Field field = current.getDeclaredField(name);
531	                field.setAccessible(true);
532	                return field;
533	            } catch (NoSuchFieldException e) {
534	                current = current.getSuperclass();
535	            }
536	        }
537	        throw new IllegalStateException("No field '" + name + "' in " + clazz);
538	    }
