@Test
void testResizeDoublesNumberOfBuckets() throws Exception {
    createTable(100);

    assertThat(numBuckets()).isEqualTo(1110);
    assertThat(bucketsArray()).hasSize(35);
    assertThat(memory).hasSize(54);

    for (int i = 0; i < 100; i++) {
        table.insert(i);
    }

    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(2220);
    assertThat(bucketsArray()).hasSize(70);
    assertThat(isResizing()).isFalse();
    // the resize consumed exactly the segments needed for the new buckets
    assertThat(memory).hasSize(19);
    assertTableIsConsistent();
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 100));
}

@Test
void testTableRemainsUsableAfterResize() throws Exception {
    createTable(100);

    for (int i = 0; i < 50; i++) {
        table.insert(i);
    }

    assertThat(table.resizeHashTable()).isTrue();
    assertThat(numBuckets()).isEqualTo(2220);

    // records inserted after the resize are placed in the enlarged table
    for (int i = 50; i < 100; i++) {
        table.insert(i);
    }

    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 100));

    // replacing an existing record must not duplicate it
    table.insertOrReplaceRecord(7);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 100));
    assertTableIsConsistent();
}

@Test
void testResizeFailsWithoutSufficientMemory() throws Exception {
    createTable(100);

    assertThat(numBuckets()).isEqualTo(1110);
    assertThat(bucketsArray()).hasSize(35);
    assertThat(memory).hasSize(54);

    for (int i = 0; i < 20; i++) {
        table.insert(i);
    }

    // withhold the memory that would be needed for the doubled bucket array; the partitions
    // are still free of garbage, so compacting them cannot free any memory either
    final List<MemorySegment> withheld = withholdMemory(20);
    assertThat(memory).hasSize(34);
    assertThat(countOwnedSegments()).isEqualTo(80);

    assertThat(table.resizeHashTable()).isFalse();

    // the failed attempt must leave the table completely untouched
    assertThat(numBuckets()).isEqualTo(1110);
    assertThat(bucketsArray()).hasSize(35);
    assertThat(isResizing()).isFalse();
    assertThat(memory).hasSize(34);
    assertThat(countOwnedSegments()).isEqualTo(80);
    assertTableIsConsistent();
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 20));

    // handing the memory back makes the next attempt succeed
    memory.addAll(withheld);
    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(2220);
    assertThat(bucketsArray()).hasSize(70);
    assertThat(memory).hasSize(19);
    assertThat(countOwnedSegments()).isEqualTo(100);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 20));
}

@Test
void testResizeReturnsFalseWhenTableIsClosed() throws Exception {
    createTable(100);

    for (int i = 0; i < 10; i++) {
        table.insert(i);
    }

    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 10));

    // plenty of memory is available, so the resize is refused because of the closed flag only
    assertThat(memory.size()).isGreaterThanOrEqualTo(35);
    setClosed(true);

    assertThat(table.resizeHashTable()).isFalse();

    assertThat(numBuckets()).isEqualTo(1110);
    assertThat(bucketsArray()).hasSize(35);
    assertThat(isResizing()).isFalse();
    assertThat(memory).hasSize(54);
    assertThat(countOwnedSegments()).isEqualTo(100);

    // the content of the table was not touched by the refused resize
    setClosed(false);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(range(0, 10));
}

@Test
void testResizeReclaimsMemoryOfPartitionsHoldingGarbage() throws Exception {
    createTable(40);

    assertThat(numBuckets()).isEqualTo(370);
    assertThat(memory).hasSize(17);

    // keys spread over distinct buckets of the first partition: no overflow buckets are
    // needed and all records stay in that single partition
    final List<Integer> keys = keysForPartition(0, 30);

    // overwrite the records over and over again: the partition first grows beyond its initial
    // page and then fills up with garbage until the available memory is used up, so that the
    // resize has to compact the partition in order to get the memory for the new buckets
    for (int round = 0; round < 200; round++) {
        for (int key : keys) {
            table.insertOrReplaceRecord(key);
        }
    }

    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);
    // not enough memory left for doubling the bucket array
    assertThat(memory.size()).isLessThan(12);

    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(740);
    assertThat(bucketsArray()).hasSize(24);
    assertThat(isResizing()).isFalse();
    assertTableIsConsistent();
    // the garbage was reclaimed, hence exactly the segments of the new buckets are missing
    assertThat(memory).hasSize(5);
    assertThat(countOwnedSegments()).isEqualTo(40);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);
}

@Test
void testResizeWithOverflowBucketsInTable() throws Exception {
    createTable(100);

    final int targetBucket = 5;
    final List<Integer> keys = keysForBucket(targetBucket, 30);

    for (int key : keys) {
        table.insert(key);
    }

    // 30 records in a single bucket require overflow buckets, i.e. another segment was taken
    // from the free memory
    assertThat(memory.size()).isLessThan(54);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);

    assertThat(table.resizeHashTable()).isTrue();

    assertThat(numBuckets()).isEqualTo(2220);
    assertThat(bucketsArray()).hasSize(70);
    assertThat(isResizing()).isFalse();
    assertTableIsConsistent();
    // no segment was lost while re-distributing the overflow buckets
    assertThat(countOwnedSegments()).isEqualTo(100);
    assertThat(entries()).containsExactlyInAnyOrderElementsOf(keys);
}

@Test
void testRecordsAreFoundThroughProberAfterResize() throws Exception {
    createTable(100);

    for (int i = 0; i < 100; i++) {
        table.insert(i);
    }

    assertThat(table.resizeHashTable()).isTrue();

    final AbstractHashTableProber<Integer, Integer> prober =
            table.getProber(COMPARATOR, new IntPairComparator());
    for (int i = 0; i < 100; i++) {
        assertThat(prober.getMatchFor(i)).as("lookup of record %s", i).isEqualTo(i);
    }
    // records that were never inserted are not found
    assertThat(prober.getMatchFor(-1)).isNull();
    assertThat(prober.getMatchFor(4711)).isNull();
}

