private void createTable(int numSegments) {
    memory = new ArrayList<>(numSegments);
    for (int i = 0; i < numSegments; i++) {
        memory.add(MemorySegmentFactory.allocateUnpooledSegment(SEGMENT_SIZE));
    }
    table = new CompactingHashTable<>(SERIALIZER, COMPARATOR, memory);
    table.open();
}

/** Removes the given number of segments from the free memory of the table. */
private List<MemorySegment> withholdMemory(int numSegments) {
    final List<MemorySegment> withheld = new ArrayList<>(numSegments);
    for (int i = 0; i < numSegments; i++) {
        withheld.add(memory.remove(memory.size() - 1));
    }
