/**
 * Verifies the invariants every bucket of the table must obey: the bucket is located in the
 * expected segment, it belongs to the partition given by the bucket number and its entry count
 * is within the format's limits.
 */
private void assertTableIsConsistent() {
    final int numBuckets = numBuckets();
    final MemorySegment[] buckets = bucketsArray();
    final int numPartitions = partitions().size();

    assertThat(buckets.length)
            .isEqualTo((numBuckets + BUCKETS_PER_SEGMENT - 1) / BUCKETS_PER_SEGMENT);
    assertThat(numBuckets % numPartitions).isZero();

    for (int bucket = 0; bucket < numBuckets; bucket++) {
        final MemorySegment segment = buckets[bucket / BUCKETS_PER_SEGMENT];
        final int bucketOffset = (bucket % BUCKETS_PER_SEGMENT) * HASH_BUCKET_SIZE;

        assertThat(segment.get(bucketOffset + HEADER_PARTITION_OFFSET))
                .as("partition of bucket %d", bucket)
                .isEqualTo((byte) (bucket % numPartitions));

        assertThat(segment.getInt(bucketOffset + HEADER_COUNT_OFFSET))
                .as("entry count of bucket %d", bucket)
                .isBetween(0, MAX_ENTRIES_PER_BUCKET);
    }
}

/** Verifies that the resize neither leaks nor double counts memory segments. */
private int countOwnedSegments() {
    int owned = memory.size() + bucketsArray().length;

    for (InMemoryPartition<Integer> partition : partitions()) {
        owned += partitionPages(partition).size();
        owned += (Integer) fieldValue(partition, "numOverflowSegments");
    }

    final InMemoryPartition<Integer> compactionMemory =
            asPartition(fieldValue(table, "compactionMemory"));
    owned += partitionPages(compactionMemory).size();
    return owned;
}

