import java.io.EOFException;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.LinkedBlockingQueue;

/** A simple iterator over the input read though an I/O channel. */
public class ChannelReaderInputViewIterator<E> implements MutableObjectIterator<E> {
    private final AbstractChannelReaderInputView inView;

    private final TypeSerializer<E> accessors;

    private final List<MemorySegment> freeMemTarget;

    public ChannelReaderInputViewIterator(
            IOManager ioAccess,
            FileIOChannel.ID channel,
            List<MemorySegment> segments,
            List<MemorySegment> freeMemTarget,
            TypeSerializer<E> accessors,
            int numBlocks)
            throws IOException {
        this(
                ioAccess,
                channel,
                new LinkedBlockingQueue<MemorySegment>(),
                segments,
                freeMemTarget,
                accessors,
                numBlocks);
    }

    public ChannelReaderInputViewIterator(
            IOManager ioAccess,
            FileIOChannel.ID channel,
            LinkedBlockingQueue<MemorySegment> returnQueue,
            List<MemorySegment> segments,
            List<MemorySegment> freeMemTarget,
            TypeSerializer<E> accessors,
            int numBlocks)
            throws IOException {
        this(
                ioAccess.createBlockChannelReader(channel, returnQueue),
                returnQueue,
                segments,
                freeMemTarget,
                accessors,
                numBlocks);
    }

    public ChannelReaderInputViewIterator(
            BlockChannelReader<MemorySegment> reader,
            LinkedBlockingQueue<MemorySegment> returnQueue,
            List<MemorySegment> segments,
            List<MemorySegment> freeMemTarget,
            TypeSerializer<E> accessors,
            int numBlocks)
            throws IOException {
        this.accessors = accessors;
        this.freeMemTarget = freeMemTarget;
        this.inView = new ChannelReaderInputView(reader, segments, numBlocks, false);
    }

    public ChannelReaderInputViewIterator(
            AbstractChannelReaderInputView inView,
            List<MemorySegment> freeMemTarget,
            TypeSerializer<E> accessors) {
        this.inView = inView;
        this.freeMemTarget = freeMemTarget;
        this.accessors = accessors;
    }

    @Override
    public E next(E reuse) throws IOException {
        try {
            return this.accessors.deserialize(reuse, this.inView);
        } catch (EOFException eofex) {
            final List<MemorySegment> freeMem = this.inView.close();
            if (this.freeMemTarget != null) {
                this.freeMemTarget.addAll(freeMem);
            }
            return null;
        }
    }

    @Override
    public E next() throws IOException {
        try {
            return this.accessors.deserialize(this.inView);
        } catch (EOFException eofex) {
            final List<MemorySegment> freeMem = this.inView.close();
            if (this.freeMemTarget != null) {
                this.freeMemTarget.addAll(freeMem);
            }
            return null;
        }
    }
}

