class MutableHashTableBuildTableFromSpilledPartitionTests {

    /** Mirrors the private constant in {@link MutableHashTable}. */
    private static final int MAX_RECURSION_DEPTH = 3;

    /** Offset of the element count in a bucket header (see the memory layout in MutableHashTable). */
    private static final int BUCKET_HEADER_COUNT_OFFSET = 2;

    private static final int LARGE_SEGMENT_SIZE = 32 * 1024;
