    @Test
    void testDetectsLeakedMemoryBuffer() throws Exception {
        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        // drop one buffer, so that available buffers do not add up to the expected number anymore
        table.availableMemory.remove(table.availableMemory.size() - 1);

        HashPartition<Integer, Integer> partition = createInMemoryPartition(LARGE_SEGMENT_SIZE, 0);

        try {
            RuntimeException exception =
                    assertThrows(
                            RuntimeException.class,
                            () -> table.buildTableFromSpilledPartition(partition));

            assertThat(exception.getMessage()).contains("Memory buffers leaked");
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

