    @Test
    void testSpilledPartitionThatFitsIsReadBackAsSingleInMemoryPartition() throws Exception {
        final int numberOfRecords = 5;

        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        HashPartition<Integer, Integer> partition =
                createSpilledPartition(LARGE_SEGMENT_SIZE, 0, numberOfRecords);
        final int originalBlockCount = partition.getBuildSideBlockCount();

        try {
            table.buildTableFromSpilledPartition(partition);

            assertThat(table.partitionsBeingBuilt).hasSize(1);
            HashPartition<Integer, Integer> newPartition = table.partitionsBeingBuilt.get(0);

            assertThat(newPartition.getPartitionNumber()).isEqualTo(0);
            assertThat(newPartition.getRecursionLevel()).isEqualTo(1);
            assertThat(newPartition.getBuildSideRecordCount()).isEqualTo(numberOfRecords);
            assertThat(newPartition.getBuildSideBlockCount()).isEqualTo(originalBlockCount);
            assertThat(newPartition.isInMemory()).isTrue();

