    @Test
    void testSpilledPartitionThatDoesNotFitIsPartitionedAgain() throws Exception {
        final int numberOfRecords = 2000;

        // 1024-byte segments and 2000 int records make the worst-case buffer estimate exceed the
        // available buffers, so the method has to distribute the records over new partitions.
        MutableHashTable<Integer, Integer> table = createTable(64, SMALL_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        HashPartition<Integer, Integer> partition =
                createSpilledPartition(SMALL_SEGMENT_SIZE, 0, numberOfRecords);

        try {
            table.buildTableFromSpilledPartition(partition);

            // The records were redistributed over several new partitions...
            assertThat(table.partitionsBeingBuilt).hasSizeGreaterThan(1);
            assertThat(table.partitionsBeingBuilt.size()).isLessThanOrEqualTo(Byte.MAX_VALUE);

            long totalRecords = 0L;
            for (HashPartition<Integer, Integer> newPartition : table.partitionsBeingBuilt) {
                assertThat(newPartition.getRecursionLevel()).isEqualTo(1);
                totalRecords += newPartition.getBuildSideRecordCount();
            }

            // ...without losing any record.
            assertThat(totalRecords).isEqualTo((long) numberOfRecords);
            assertThat(table.numBuckets).isGreaterThan(0);
            assertThat(table.buckets).isNotNull();
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
