    private MutableHashTable<Integer, Integer> createTable(int numberOfSegments, int segmentSize) {
        List<MemorySegment> memory = new ArrayList<>(numberOfSegments);
        for (int i = 0; i < numberOfSegments; i++) {
            memory.add(MemorySegmentFactory.allocateUnpooledSegment(segmentSize));
        }

        return new MutableHashTable<>(
                IntSerializer.INSTANCE,
                IntSerializer.INSTANCE,
                new IntComparator(true),
                new IntComparator(true),
                new IntegerPairComparator(),
                memory,
                ioManager,
                false);
    }

    /**
     * Brings the hash table into the state in which {@code buildTableFromSpilledPartition} is
     * normally invoked: all write-behind buffers have been taken out of the free-memory list and
     * all other buffers are free.
     */
    private static void simulateStateAfterPartitionFinalization(
            MutableHashTable<Integer, Integer> table) {
        final int numberOfWriteBehindBuffers =
                MutableHashTable.getNumWriteBehindBuffers(table.availableMemory.size());
        for (int i = 0; i < numberOfWriteBehindBuffers; i++) {
            table.writeBehindBuffers.add(
                    table.availableMemory.remove(table.availableMemory.size() - 1));
        }
    }

    private HashPartition<Integer, Integer> createInMemoryPartition(
            int segmentSize, int recursionLevel) {
        MemorySegmentSource memorySource =
                () -> MemorySegmentFactory.allocateUnpooledSegment(segmentSize);
        return new HashPartition<>(
                IntSerializer.INSTANCE,
                IntSerializer.INSTANCE,
                0,
                recursionLevel,
                MemorySegmentFactory.allocateUnpooledSegment(segmentSize),
                memorySource,
                segmentSize);
    }

    /**
     * Creates a spilled partition whose build-side channel contains the integers {@code 0} to
     * {@code numberOfRecords - 1}.
     */
    private HashPartition<Integer, Integer> createSpilledPartition(
            int segmentSize, int recursionLevel, int numberOfRecords) throws IOException {
        HashPartition<Integer, Integer> partition =
                createInMemoryPartition(segmentSize, recursionLevel);

        for (int i = 0; i < numberOfRecords; i++) {
            partition.insertIntoBuildBuffer(i);
        }

        // A partition can only be spilled if it occupies at least two memory segments. For very
        // small inputs, emulate an additional overflow segment.
        if (partition.getNumOccupiedMemorySegments() < 2) {
            partition.overflowSegments[0] =
                    MemorySegmentFactory.allocateUnpooledSegment(segmentSize);
            partition.numOverflowSegments = 1;
        }

        final LinkedBlockingQueue<MemorySegment> buildSideReturnQueue =
                new LinkedBlockingQueue<>();
        final FileIOChannel.ID buildSideChannelId =
                ioManager.createChannelEnumerator().next();
        partition.spillPartition(
                new ArrayList<>(), ioManager, buildSideChannelId, buildSideReturnQueue);

        final LinkedBlockingQueue<MemorySegment> probeSideReturnQueue =
                new LinkedBlockingQueue<>();
        probeSideReturnQueue.add(MemorySegmentFactory.allocateUnpooledSegment(segmentSize));
        partition.finalizeBuildPhase(
                ioManager, ioManager.createChannelEnumerator(), probeSideReturnQueue);

        return partition;
    }

    private static List<Integer> readRecords(HashPartition<Integer, Integer> partition)
            throws IOException {
        MutableObjectIterator<Integer> iterator =
                partition.getPartitionIterator(new IntComparator(true));

        List<Integer> records = new ArrayList<>();
        Integer record;
        while ((record = iterator.next()) != null) {
            records.add(record);
        }
        return records;
    }

    private static void clearPartition(HashPartition<Integer, Integer> partition) {
        try {
            partition.clearAllMemory(new ArrayList<>());
        } catch (Exception ignored) {
            // best-effort cleanup of test resources
        }
    }

    private static void releaseTable(MutableHashTable<Integer, Integer> table) {
        try {
            table.releaseTable();
            table.clearPartitions();
        } catch (Exception ignored) {
            // best-effort cleanup of test resources
        }
    }

    /** Minimal pair comparator for {@code Integer} records; the hash join only needs equality. */
    private static final class IntegerPairComparator
            extends TypePairComparator<Integer, Integer> {

        private Integer reference;

        @Override
        public void setReference(Integer reference) {
            this.reference = reference;
        }

        @Override
        public boolean equalToReference(Integer candidate) {
            return reference.equals(candidate);
        }

        @Override
        public int compareToReference(Integer candidate) {
            return Integer.compare(candidate, reference);
        }
    }

