package org.apache.flink.runtime.operators.hash;

import org.apache.flink.api.common.typeutils.TypePairComparator;
import org.apache.flink.api.common.typeutils.base.IntComparator;
import org.apache.flink.api.common.typeutils.base.IntSerializer;
import org.apache.flink.core.memory.MemorySegment;
import org.apache.flink.core.memory.MemorySegmentFactory;
import org.apache.flink.core.memory.MemorySegmentSource;
import org.apache.flink.runtime.io.disk.iomanager.FileIOChannel;
import org.apache.flink.runtime.io.disk.iomanager.IOManagerAsync;
import org.apache.flink.util.MutableObjectIterator;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.LinkedBlockingQueue;

import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

/**
 * Tests for {@link MutableHashTable#buildTableFromSpilledPartition(HashPartition)}.
 *
 * <p>The method is protected and relies heavily on package-private hash-table internals, so the
 * tests live in the same package and drive it with real (but small) spilled partitions and an
 * {@link IOManagerAsync}.
 */
class MutableHashTableBuildTableFromSpilledPartitionTests {

    /** Mirrors the private constant in {@link MutableHashTable}. */
    private static final int MAX_RECURSION_DEPTH = 3;

    /**
     * Offset of the element count in a bucket header (see the memory layout in MutableHashTable).
     */
    private static final int BUCKET_HEADER_COUNT_OFFSET = 2;

    private static final int LARGE_SEGMENT_SIZE = 32 * 1024;
    private static final int SMALL_SEGMENT_SIZE = 1024;

    private IOManagerAsync ioManager;

    @BeforeEach
    void setUp() throws Exception {
        ioManager = new IOManagerAsync();
    }

    @AfterEach
    void tearDown() throws Exception {
        if (ioManager != null) {
            ioManager.close();
            ioManager = null;
        }
    }

    // ----------------------------------------------------------------------------------------
    //                              Recursion depth validation
    // ----------------------------------------------------------------------------------------

    @Test
    void testExceedingMaximumRecursionDepthThrowsRuntimeException() throws Exception {
        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        HashPartition<Integer, Integer> partition = createInMemoryPartition(LARGE_SEGMENT_SIZE, 3);

        try {
            RuntimeException exception =
                    assertThrows(
                            RuntimeException.class,
                            () -> table.buildTableFromSpilledPartition(partition));

            assertThat(exception.getMessage()).contains("exceeded maximum number of recursions");
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    @Test
    void testRecursionLevelJustBelowTheLimitIsAccepted() throws Exception {
        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        // recursion level 2 means the next recursion level is 3, which is still allowed
        HashPartition<Integer, Integer> partition =
                createSpilledPartition(LARGE_SEGMENT_SIZE, 2, 3);

        try {
            table.buildTableFromSpilledPartition(partition);

            assertThat(table.partitionsBeingBuilt).hasSize(1);
            HashPartition<Integer, Integer> newPartition = table.partitionsBeingBuilt.get(0);
            assertThat(newPartition.getRecursionLevel()).isEqualTo(MAX_RECURSION_DEPTH);
            assertThat(newPartition.getBuildSideRecordCount()).isEqualTo(3L);
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    // ----------------------------------------------------------------------------------------
    //                              Memory management validation
    // ----------------------------------------------------------------------------------------

    @Test
    void testDetectsLeakedMemoryBuffer() throws Exception {
        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        // drop one buffer, so that available buffers do not add up to the expected number anymore
        table.availableMemory.remove(table.availableMemory.size() - 1);

        HashPartition<Integer, Integer> partition = createInMemoryPartition(LARGE_SEGMENT_SIZE, 0);

        try {
            RuntimeException exception =
                    assertThrows(
                            RuntimeException.class,
                            () -> table.buildTableFromSpilledPartition(partition));

            assertThat(exception.getMessage()).contains("Memory buffers leaked");
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    @Test
    void testDetectsSurplusMemoryBuffer() throws Exception {
        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        // add an unexpected buffer, which must be reported as a memory-management bug as well
        table.availableMemory.add(MemorySegmentFactory.allocateUnpooledSegment(LARGE_SEGMENT_SIZE));

        HashPartition<Integer, Integer> partition = createInMemoryPartition(LARGE_SEGMENT_SIZE, 0);

        try {
            RuntimeException exception =
                    assertThrows(
                            RuntimeException.class,
                            () -> table.buildTableFromSpilledPartition(partition));

            assertThat(exception.getMessage()).contains("Memory buffers leaked");
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    // ----------------------------------------------------------------------------------------
    //                         Partition fits entirely into memory
    // ----------------------------------------------------------------------------------------

    @Test
    void testSpilledPartitionThatFitsIsReadBackAsSingleInMemoryPartition() throws Exception {
        final int numberOfRecords = 5;

        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        HashPartition<Integer, Integer> partition =
                createSpilledPartition(LARGE_SEGMENT_SIZE, 0, numberOfRecords);
        final int originalBlockCount = partition.getBuildSideBlockCount();

        try {
            table.buildTableFromSpilledPartition(partition);

            assertThat(table.partitionsBeingBuilt).hasSize(1);
            HashPartition<Integer, Integer> newPartition = table.partitionsBeingBuilt.get(0);

            assertThat(newPartition.getPartitionNumber()).isEqualTo(0);
            assertThat(newPartition.getRecursionLevel()).isEqualTo(1);
            assertThat(newPartition.getBuildSideRecordCount()).isEqualTo(numberOfRecords);
            assertThat(newPartition.getBuildSideBlockCount()).isEqualTo(originalBlockCount);
            assertThat(newPartition.isInMemory()).isTrue();

            // All records stayed in the single partition and can be read back in insertion order.
            assertThat(readRecords(newPartition)).containsExactly(0, 1, 2, 3, 4);

            // The table structure was erected and contains every record in its only bucket.
            assertThat(table.numBuckets).isEqualTo(1);
            assertThat(table.buckets).hasSize(1);
            assertThat((int) table.buckets[0].getShort(BUCKET_HEADER_COUNT_OFFSET))
                    .isEqualTo(numberOfRecords);
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    @Test
    void testEmptySpilledPartitionProducesEmptyInMemoryPartition() throws Exception {
        MutableHashTable<Integer, Integer> table = createTable(33, LARGE_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        HashPartition<Integer, Integer> partition =
                createSpilledPartition(LARGE_SEGMENT_SIZE, 0, 0);

        try {
            table.buildTableFromSpilledPartition(partition);

            assertThat(table.partitionsBeingBuilt).hasSize(1);
            HashPartition<Integer, Integer> newPartition = table.partitionsBeingBuilt.get(0);

            assertThat(newPartition.getBuildSideRecordCount()).isZero();
            assertThat(readRecords(newPartition)).isEmpty();

            assertThat(table.numBuckets).isEqualTo(1);
            assertThat((int) table.buckets[0].getShort(BUCKET_HEADER_COUNT_OFFSET)).isZero();
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    // ----------------------------------------------------------------------------------------
    //                   Partition does not fit and has to be partitioned again
    // ----------------------------------------------------------------------------------------

    @Test
    void testSpilledPartitionThatDoesNotFitIsPartitionedAgain() throws Exception {
        final int numberOfRecords = 2000;

        // 1024-byte segments and 2000 int records make the worst-case buffer estimate exceed the
        // available buffers, so the method has to distribute the records over new partitions.
        MutableHashTable<Integer, Integer> table = createTable(64, SMALL_SEGMENT_SIZE);
        simulateStateAfterPartitionFinalization(table);

        HashPartition<Integer, Integer> partition =
                createSpilledPartition(SMALL_SEGMENT_SIZE, 0, numberOfRecords);

        try {
            table.buildTableFromSpilledPartition(partition);

            // The records were redistributed over several new partitions...
            assertThat(table.partitionsBeingBuilt).hasSizeGreaterThan(1);
            assertThat(table.partitionsBeingBuilt.size()).isLessThanOrEqualTo(Byte.MAX_VALUE);

            long totalRecords = 0L;
            for (HashPartition<Integer, Integer> newPartition : table.partitionsBeingBuilt) {
                assertThat(newPartition.getRecursionLevel()).isEqualTo(1);
                totalRecords += newPartition.getBuildSideRecordCount();
            }

            // ...without losing any record.
            assertThat(totalRecords).isEqualTo((long) numberOfRecords);
            assertThat(table.numBuckets).isGreaterThan(0);
            assertThat(table.buckets).isNotNull();
        } finally {
            clearPartition(partition);
            releaseTable(table);
        }
    }

    // ----------------------------------------------------------------------------------------
    //                                       Test helpers
    // ----------------------------------------------------------------------------------------

    private MutableHashTable<Integer, Integer> createTable(int numberOfSegments, int segmentSize) {
        List<MemorySegment> memory = new ArrayList<>(numberOfSegments);
        for (int i = 0; i < numberOfSegments; i++) {
            memory.add(MemorySegmentFactory.allocateUnpooledSegment(segmentSize));
        }

        return new MutableHashTable<>(
                IntSerializer.INSTANCE,
                IntSerializer.INSTANCE,
                new IntComparator(true),
                new IntComparator(true),
                new IntegerPairComparator(),
                memory,
                ioManager,
                false);
    }

    /**
     * Brings the hash table into the state in which {@code buildTableFromSpilledPartition} is
     * normally invoked: all write-behind buffers have been taken out of the free-memory list and
     * all other buffers are free.
     */
    private static void simulateStateAfterPartitionFinalization(
            MutableHashTable<Integer, Integer> table) {
        final int numberOfWriteBehindBuffers =
                MutableHashTable.getNumWriteBehindBuffers(table.availableMemory.size());
        for (int i = 0; i < numberOfWriteBehindBuffers; i++) {
            table.writeBehindBuffers.add(
                    table.availableMemory.remove(table.availableMemory.size() - 1));
        }
    }

    private HashPartition<Integer, Integer> createInMemoryPartition(
            int segmentSize, int recursionLevel) {
        MemorySegmentSource memorySource =
                () -> MemorySegmentFactory.allocateUnpooledSegment(segmentSize);
        return new HashPartition<>(
                IntSerializer.INSTANCE,
                IntSerializer.INSTANCE,
                0,
                recursionLevel,
                MemorySegmentFactory.allocateUnpooledSegment(segmentSize),
                memorySource,
                segmentSize);
    }

    /**
     * Creates a spilled partition whose build-side channel contains the integers {@code 0} to
     * {@code numberOfRecords - 1}.
     */
    private HashPartition<Integer, Integer> createSpilledPartition(
            int segmentSize, int recursionLevel, int numberOfRecords) throws IOException {
        HashPartition<Integer, Integer> partition =
                createInMemoryPartition(segmentSize, recursionLevel);

        for (int i = 0; i < numberOfRecords; i++) {
            partition.insertIntoBuildBuffer(i);
        }

        // A partition can only be spilled if it occupies at least two memory segments. For very
        // small inputs, emulate an additional overflow segment.
        if (partition.getNumOccupiedMemorySegments() < 2) {
            partition.overflowSegments[0] =
                    MemorySegmentFactory.allocateUnpooledSegment(segmentSize);
            partition.numOverflowSegments = 1;
        }

        final LinkedBlockingQueue<MemorySegment> buildSideReturnQueue = new LinkedBlockingQueue<>();
        final FileIOChannel.ID buildSideChannelId = ioManager.createChannelEnumerator().next();
        partition.spillPartition(
                new ArrayList<>(), ioManager, buildSideChannelId, buildSideReturnQueue);

        final LinkedBlockingQueue<MemorySegment> probeSideReturnQueue = new LinkedBlockingQueue<>();
        probeSideReturnQueue.add(MemorySegmentFactory.allocateUnpooledSegment(segmentSize));
        partition.finalizeBuildPhase(
                ioManager, ioManager.createChannelEnumerator(), probeSideReturnQueue);

        return partition;
    }

    private static List<Integer> readRecords(HashPartition<Integer, Integer> partition)
            throws IOException {
        MutableObjectIterator<Integer> iterator =
                partition.getPartitionIterator(new IntComparator(true));

        List<Integer> records = new ArrayList<>();
        Integer record;
        while ((record = iterator.next()) != null) {
            records.add(record);
        }
        return records;
    }

    private static void clearPartition(HashPartition<Integer, Integer> partition) {
        try {
            partition.clearAllMemory(new ArrayList<>());
        } catch (Exception ignored) {
            // best-effort cleanup of test resources
        }
    }

    private static void releaseTable(MutableHashTable<Integer, Integer> table) {
        try {
            table.releaseTable();
            table.clearPartitions();
        } catch (Exception ignored) {
            // best-effort cleanup of test resources
        }
    }

    /** Minimal pair comparator for {@code Integer} records; the hash join only needs equality. */
    private static final class IntegerPairComparator extends TypePairComparator<Integer, Integer> {

        private Integer reference;

        @Override
        public void setReference(Integer reference) {
            this.reference = reference;
        }

        @Override
        public boolean equalToReference(Integer candidate) {
            return reference.equals(candidate);
        }

        @Override
        public int compareToReference(Integer candidate) {
            return Integer.compare(candidate, reference);
        }
    }
}
