        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testNonMultipartPostRequestIsForwardedUnchanged() {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final DefaultHttpRequest request =
                    new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, UPLOAD_URI);
            request.headers().set(HttpHeaderNames.CONTENT_TYPE, "application/json");
            request.headers().set(HttpHeaderNames.CONTENT_LENGTH, 2);

            channel.writeInbound(request);

            assertSame(request, channel.readInbound());
            assertNull(channel.readInbound());
            assertNull(channel.readOutbound());
            assertThat(childDirectories()).isEmpty();
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testMultipartPostForUnknownRouteReturnsBadRequest() throws Exception {
        final MultipartRoutes routes = routesFor("/other", UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = attributeBody(REQUEST_ATTRIBUTE, JSON_PAYLOAD);
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);

            assertBadRequestResponse(channel, "POST request not allowed");
            assertNull(channel.readInbound());
            assertThat(childDirectories()).isEmpty();
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testFileUploadForNonUploadRouteReturnsBadRequest() throws Exception {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, "/other");
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = fileBody("upload.txt", "file content");
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);
            channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

            assertBadRequestResponse(channel, "File upload not allowed");
            assertNull(channel.readInbound());
            assertThat(childDirectories()).isEmpty();
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testUnknownAttributeReturnsBadRequest() throws Exception {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = attributeBody("unknown", "value");
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);
            channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

            assertBadRequestResponse(channel, "Received unknown attribute unknown.");
            assertNull(channel.readInbound());
            assertThat(childDirectories()).isEmpty();
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testRequestAttributeIsForwardedAsJsonPayload() throws Exception {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = attributeBody(REQUEST_ATTRIBUTE, JSON_PAYLOAD);
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);
            channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

            assertNoOutbound(channel);

            final HttpRequest forwardedRequest = channel.readInbound();
            assertSame(request, forwardedRequest);
            assertEquals(
                    JSON_PAYLOAD.getBytes(StandardCharsets.UTF_8).length,
                    forwardedRequest.headers().getInt(HttpHeaderNames.CONTENT_LENGTH));
            assertEquals(
                    RestConstants.REST_CONTENT_TYPE,
                    forwardedRequest.headers().get(HttpHeaderNames.CONTENT_TYPE));

            final LastHttpContent forwardedContent = channel.readInbound();
            assertNotNull(forwardedContent);
            assertEquals(JSON_PAYLOAD, contentAsString(forwardedContent));
            assertNull(channel.readInbound());

            final FileUploads uploads = getUploads(channel);
            assertThat(uploads.getUploadedFiles()).isEmpty();
            uploads.close();
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testFileUploadIsStoredAndEmptyLastContentIsForwarded() throws Exception {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = fileBody("upload.txt", "file content");
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);
            channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

            assertNoOutbound(channel);

            final HttpRequest forwardedRequest = channel.readInbound();
            assertSame(request, forwardedRequest);
            assertEquals(0, forwardedRequest.headers().getInt(HttpHeaderNames.CONTENT_LENGTH));
            assertNull(forwardedRequest.headers().get(HttpHeaderNames.CONTENT_TYPE));

            assertSame(LastHttpContent.EMPTY_LAST_CONTENT, channel.readInbound());
            assertNull(channel.readInbound());

            final FileUploads uploads = getUploads(channel);
            final Collection<File> files = uploads.getUploadedFiles();
            assertThat(files).hasSize(1);
            final File uploadedFile = files.iterator().next();
            assertEquals("upload.txt", uploadedFile.getName());
            assertEquals(
