            final HttpRequest firstRequest = multipartRequest(UPLOAD_URI, body.length);
            final HttpRequest secondRequest = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(firstRequest);
            channel.writeInbound(secondRequest);

            assertInternalServerErrorResponse(channel, "File upload failed.");
            assertNull(channel.readInbound());
            assertThat(childDirectories()).isEmpty();
        } finally {
            channel.finishAndReleaseAll();
        }
