    private static MultipartRoutes routesFor(String postRoute, String fileUploadRoute) {
        return new MultipartRoutes.Builder()
                .addPostRoute(postRoute)
                .addFileUploadRoute(fileUploadRoute)
                .build();
    }

    private static HttpRequest multipartRequest(String uri, int contentLength) {
        final DefaultHttpRequest request =
                new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, uri);
        request.headers()
                .set(
                        HttpHeaderNames.CONTENT_TYPE,
                        "multipart/form-data; boundary=" + BOUNDARY);
        request.headers().set(HttpHeaderNames.CONTENT_LENGTH, contentLength);
        return request;
    }

    private static byte[] attributeBody(String name, String value) {
        return body(part(name, null, value));
    }

    private static byte[] fileBody(String filename, String value) {
        return body(filePart("file", filename, value));
    }

    private static byte[] attributeAndFileBody(
            String attributeName,
            String attributeValue,
            String filename,
            String fileValue) {
        return body(part(attributeName, null, attributeValue), filePart("file", filename, fileValue));
    }

    private static byte[] body(String... parts) {
        final StringBuilder builder = new StringBuilder();
        for (String part : parts) {
            builder.append("--").append(BOUNDARY).append("\r\n").append(part).append("\r\n");
        }
        builder.append("--").append(BOUNDARY).append("--\r\n");
        return builder.toString().getBytes(StandardCharsets.UTF_8);
    }

    private static String part(String name, String filename, String value) {
        final StringBuilder header =
                new StringBuilder("Content-Disposition: form-data; name=\"").append(name).append('"');
        if (filename != null) {
            header.append("; filename=\"").append(filename).append('"');
        }
        header.append("\r\n");
        if (filename != null) {
            header.append("Content-Type: application/octet-stream\r\n");
        }
        header.append("\r\n").append(value);
        return header.toString();
    }

    private static String filePart(String name, String filename, String value) {
        return part(name, filename, value);
    }

    private static void assertBadRequestResponse(EmbeddedChannel channel, String expectedMessage) {
        assertErrorResponse(channel, HttpResponseStatus.BAD_REQUEST, expectedMessage);
    }

    private static void assertInternalServerErrorResponse(
            EmbeddedChannel channel, String expectedMessage) {
        assertErrorResponse(channel, HttpResponseStatus.INTERNAL_SERVER_ERROR, expectedMessage);
    }

    private static void assertErrorResponse(
            EmbeddedChannel channel,
            HttpResponseStatus expectedStatus,
            String expectedMessage) {
        final HttpResponse response = channel.readOutbound();
        assertNotNull(response);
        assertEquals(expectedStatus, response.status());
        assertEquals(
                RestConstants.REST_CONTENT_TYPE,
                response.headers().get(HttpHeaderNames.CONTENT_TYPE));

        final ByteBuf body = channel.readOutbound();
        assertNotNull(body);
        final String bodyString = body.toString(StandardCharsets.UTF_8);
        assertTrue(
                bodyString.contains(expectedMessage),
                "Expected response body [" + bodyString + "] to contain [" + expectedMessage + "].");
        body.release();

        assertSame(LastHttpContent.EMPTY_LAST_CONTENT, channel.readOutbound());
    }

    private static void assertNoOutbound(EmbeddedChannel channel) {
        assertNull(channel.readOutbound());
    }

    private static FileUploads getUploads(EmbeddedChannel channel) {
        final ChannelHandlerContext ctx =
                channel.pipeline().context(FileUploadHandler.class);
        assertNotNull(ctx);
        return FileUploadHandler.getMultipartFileUploads(ctx);
    }

    private static String contentAsString(HttpContent content) {
        return content.content().toString(StandardCharsets.UTF_8);
    }

    private List<Path> childDirectories() {
        try (Stream<Path> stream = Files.list(uploadDir)) {
            return stream.filter(Files::isDirectory).collect(Collectors.toList());
        } catch (IOException e) {
            throw new AssertionError("Could not inspect upload directory.", e);
        }
    }
