    @Test
    void testRequestAttributeIsForwardedAsJsonPayload() throws Exception {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = attributeBody(REQUEST_ATTRIBUTE, JSON_PAYLOAD);
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);
            channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

            assertNoOutbound(channel);

            final HttpRequest forwardedRequest = channel.readInbound();
            assertSame(request, forwardedRequest);
            assertEquals(
                    JSON_PAYLOAD.getBytes(StandardCharsets.UTF_8).length,
                    forwardedRequest.headers().getInt(HttpHeaderNames.CONTENT_LENGTH));
            assertEquals(
                    RestConstants.REST_CONTENT_TYPE,
                    forwardedRequest.headers().get(HttpHeaderNames.CONTENT_TYPE));

            final LastHttpContent forwardedContent = channel.readInbound();
            assertNotNull(forwardedContent);
            assertEquals(JSON_PAYLOAD, contentAsString(forwardedContent));
            assertNull(channel.readInbound());

            final FileUploads uploads = getUploads(channel);
            assertThat(uploads.getUploadedFiles()).isEmpty();
            uploads.close();
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void testFileUploadIsStoredAndEmptyLastContentIsForwarded() throws Exception {
        final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
        final EmbeddedChannel channel = newChannel(routes);
        try {
            final byte[] body = fileBody("upload.txt", "file content");
            final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

            channel.writeInbound(request);
            channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

            assertNoOutbound(channel);

            final HttpRequest forwardedRequest = channel.readInbound();
            assertSame(request, forwardedRequest);
            assertEquals(0, forwardedRequest.headers().getInt(HttpHeaderNames.CONTENT_LENGTH));
            assertNull(forwardedRequest.headers().get(HttpHeaderNames.CONTENT_TYPE));

            assertSame(LastHttpContent.EMPTY_LAST_CONTENT, channel.readInbound());

        assertSame(LastHttpContent.EMPTY_LAST_CONTENT, channel.readInbound());
        assertNull(channel.readInbound());

        final FileUploads uploads = getUploads(channel);
        final Collection<File> files = uploads.getUploadedFiles();
        assertThat(files).hasSize(1);
        final File uploadedFile = files.iterator().next();
        assertEquals("upload.txt", uploadedFile.getName());
        assertEquals(
                "file content",
                new String(Files.readAllBytes(uploadedFile.toPath()), StandardCharsets.UTF_8));
        uploads.close();
    } finally {
        channel.finishAndReleaseAll();
    }
}

@Test
void testFileAndRequestAttributeInOneChunkAreBothProcessed() throws Exception {
    final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
    final EmbeddedChannel channel = newChannel(routes);
    try {
        final byte[] body =
                attributeAndFileBody(REQUEST_ATTRIBUTE, JSON_PAYLOAD, "upload.txt", "data");
        final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

        channel.writeInbound(request);
        channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

        assertNoOutbound(channel);

        final HttpRequest forwardedRequest = channel.readInbound();
        assertSame(request, forwardedRequest);
        assertEquals(
                JSON_PAYLOAD.getBytes(StandardCharsets.UTF_8).length,
                forwardedRequest.headers().getInt(HttpHeaderNames.CONTENT_LENGTH));
        assertEquals(
                RestConstants.REST_CONTENT_TYPE,
                forwardedRequest.headers().get(HttpHeaderNames.CONTENT_TYPE));

        final LastHttpContent forwardedContent = channel.readInbound();
        assertEquals(JSON_PAYLOAD, contentAsString(forwardedContent));
        assertNull(channel.readInbound());

        final FileUploads uploads = getUploads(channel);
        final Collection<File> files = uploads.getUploadedFiles();
        assertThat(files).hasSize(1);
        assertEquals("upload.txt", files.iterator().next().getName());
        uploads.close();
    } finally {
        channel.finishAndReleaseAll();
    }
}

@Test
void testContentWithoutActiveMultipartRequestIsForwardedUnchanged() {
    final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
    final EmbeddedChannel channel = newChannel(routes);
    try {
        final HttpContent content =
                new DefaultHttpContent(Unpooled.wrappedBuffer(new byte[] {1}));

        channel.writeInbound(content);

        assertSame(content, channel.readInbound());
        assertNull(channel.readInbound());
        assertNull(channel.readOutbound());
    } finally {
        channel.finishAndReleaseAll();
    }
}

@Test
void testUnexpectedSecondMultipartRequestReturnsInternalServerError() throws Exception {
    final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
    final EmbeddedChannel channel = newChannel(routes);
    try {
        final byte[] body = fileBody("upload.txt", "data");
        final HttpRequest firstRequest = multipartRequest(UPLOAD_URI, body.length);
        final HttpRequest secondRequest = multipartRequest(UPLOAD_URI, body.length);

        channel.writeInbound(firstRequest);
        channel.writeInbound(secondRequest);

        assertInternalServerErrorResponse(channel, "File upload failed.");
        assertNull(channel.readInbound());
        assertThat(childDirectories()).isEmpty();
    } finally {
        channel.finishAndReleaseAll();
    }
}

@Test
void testMultipartBodySplitAcrossHttpContentChunks() throws Exception {
    final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
    final EmbeddedChannel channel = newChannel(routes);
    try {
        final byte[] body = attributeBody(REQUEST_ATTRIBUTE, JSON_PAYLOAD);
        final int split = body.length / 2;
        final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

        channel.writeInbound(request);
        channel.writeInbound(new DefaultHttpContent(Unpooled.wrappedBuffer(body, 0, split)));
        channel.writeInbound(
                new DefaultLastHttpContent(
                        Unpooled.wrappedBuffer(body, split, body.length - split)));

        assertNoOutbound(channel);

        assertSame(request, channel.readInbound());
        final LastHttpContent forwardedContent = channel.readInbound();
        assertEquals(JSON_PAYLOAD, contentAsString(forwardedContent));
        assertNull(channel.readInbound());

        final FileUploads uploads = getUploads(channel);
        assertThat(uploads.getUploadedFiles()).isEmpty();
        uploads.close();
    } finally {
        channel.finishAndReleaseAll();
    }
}

@Test
void testEmptyLastHttpContentFinalizesMultipartRequest() throws Exception {
    final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
    final EmbeddedChannel channel = newChannel(routes);
    try {
        final HttpRequest request = multipartRequest(UPLOAD_URI, 0);

        channel.writeInbound(request);
        channel.writeInbound(LastHttpContent.EMPTY_LAST_CONTENT);

        assertNoOutbound(channel);

        assertSame(request, channel.readInbound());
        assertSame(LastHttpContent.EMPTY_LAST_CONTENT, channel.readInbound());
        assertNull(channel.readInbound());

        final FileUploads uploads = getUploads(channel);
        assertThat(uploads.getUploadedFiles()).isEmpty();
        uploads.close();
    } finally {
        channel.finishAndReleaseAll();
    }
}

@Test
void testFileNameContainingPathIsReducedToFileName() throws Exception {
    final MultipartRoutes routes = routesFor(UPLOAD_URI, UPLOAD_URI);
    final EmbeddedChannel channel = newChannel(routes);
    try {
        final byte[] body = fileBody("../outside.txt", "payload");
        final HttpRequest request = multipartRequest(UPLOAD_URI, body.length);

        channel.writeInbound(request);
        channel.writeInbound(new DefaultLastHttpContent(Unpooled.wrappedBuffer(body)));

        assertNoOutbound(channel);
        channel.readInbound();
        channel.readInbound();

        final FileUploads uploads = getUploads(channel);
        final Collection<File> files = uploads.getUploadedFiles();
        assertThat(files).hasSize(1);
        final File uploadedFile = files.iterator().next();
        assertEquals("outside.txt", uploadedFile.getName());
        assertTrue(uploadedFile.toPath().startsWith(uploadDir));
        assertEquals(
                "payload",
                new String(Files.readAllBytes(uploadedFile.toPath()), StandardCharsets.UTF_8));
        uploads.close();
    } finally {
        channel.finishAndReleaseAll();
    }
}

private EmbeddedChannel newChannel(MultipartRoutes routes) {
    return new EmbeddedChannel(new FileUploadHandler(uploadDir, routes));
}

private static MultipartRoutes routesFor(String postRoute, String fileUploadRoute) {
    return new MultipartRoutes.Builder()
            .addPostRoute(postRoute)
            .addFileUploadRoute(fileUploadRoute)
            .build();
}

private static HttpRequest multipartRequest(String uri, int contentLength) {
    final DefaultHttpRequest request =
            new DefaultHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.POST, uri);
    request.headers()
            .set(HttpHeaderNames.CONTENT_TYPE, "multipart/form-data; boundary=" + BOUNDARY);
    request.headers().set(HttpHeaderNames.CONTENT_LENGTH, contentLength);
    return request;
}

private static byte[] attributeBody(String name, String value) {
    return body(part(name, null, value));
}

private static byte[] fileBody(String filename, String value) {
    return body(filePart("file", filename, value));
}

private static byte[] attributeAndFileBody(
        String attributeName, String attributeValue, String filename, String fileValue) {
    return body(
            part(attributeName, null, attributeValue), filePart("file", filename, fileValue));
}

private static byte[] body(String... parts) {
    final StringBuilder builder = new StringBuilder();
    for (String part : parts) {
        builder.append("--").append(BOUNDARY).append("\r\n").append(part).append("\r\n");
    }
    builder.append("--").append(BOUNDARY).append("--\r\n");
    return builder.toString().getBytes(StandardCharsets.UTF_8);
}

private static String part(String name, String filename, String value) {
    final StringBuilder header =
            new StringBuilder("Content-Disposition: form-data; name=\"")
                    .append(name)
                    .append('"');
    if (filename != null) {
        header.append("; filename=\"").append(filename).append('"');
    }
    header.append("\r\n");
    if (filename != null) {
        header.append("Content-Type: application/octet-stream\r\n");
    }
    header.append("\r\n").append(value);
    return header.toString();
}

private static String filePart(String name, String filename, String value) {
    return part(name, filename, value);
}

private static void assertBadRequestResponse(EmbeddedChannel channel, String expectedMessage) {
    assertErrorResponse(channel, HttpResponseStatus.BAD_REQUEST, expectedMessage);
}

private static void assertInternalServerErrorResponse(
        EmbeddedChannel channel, String expectedMessage) {
    assertErrorResponse(channel, HttpResponseStatus.INTERNAL_SERVER_ERROR, expectedMessage);
}

private static void assertErrorResponse(
        EmbeddedChannel channel, HttpResponseStatus expectedStatus, String expectedMessage) {
    final HttpResponse response = channel.readOutbound();
    assertNotNull(response);
    assertEquals(expectedStatus, response.status());
    assertEquals(
            RestConstants.REST_CONTENT_TYPE,
            response.headers().get(HttpHeaderNames.CONTENT_TYPE));

    final ByteBuf body = channel.readOutbound();
    assertNotNull(body);
    final String bodyString = body.toString(StandardCharsets.UTF_8);
    assertTrue(
            bodyString.contains(expectedMessage),
            "Expected response body ["
                    + bodyString
                    + "] to contain ["
                    + expectedMessage
                    + "].");
    body.release();

    assertSame(LastHttpContent.EMPTY_LAST_CONTENT, channel.readOutbound());
}

private static void assertNoOutbound(EmbeddedChannel channel) {
    assertNull(channel.readOutbound());
}

private static FileUploads getUploads(EmbeddedChannel channel) {
    final ChannelHandlerContext ctx = channel.pipeline().context(FileUploadHandler.class);
    assertNotNull(ctx);
    return FileUploadHandler.getMultipartFileUploads(ctx);
}

