            if (subtask == null) {
                return null;
            }
            return ComponentMetricStore.unmodifiable(subtask.getAttemptsMetricStore(attemptNumber));
        }

        public Collection<? extends MetricStore.ComponentMetricStore> values() {
            return jobs.values();
        }
    }
