    @Test
    void testAddGaugeMeterAndHistogramMetrics() {
        MetricStore store = new MetricStore();
        QueryScopeInfo info = new QueryScopeInfo.JobManagerQueryScopeInfo();

        store.add(new MetricDump.GaugeDump(info, "gauge", "some-value"));
        store.add(new MetricDump.MeterDump(info, "meter", 1.5d));
        store.add(
                new MetricDump.HistogramDump(
                        info, "histogram", 1L, 10L, 5.5d, 5.0d, 1.5d, 7.0d, 8.0d, 8.5d, 9.0d,
                        9.5d, 9.9d));

        MetricStore.ComponentMetricStore jm = store.getJobManagerMetricStore();
        assertThat(jm.getMetric("gauge")).isEqualTo("some-value");
        assertThat(jm.getMetric("meter")).isEqualTo("1.5");
        assertThat(jm.getMetric("histogram_min")).isEqualTo("1");
        assertThat(jm.getMetric("histogram_max")).isEqualTo("10");
        assertThat(jm.getMetric("histogram_mean")).isEqualTo("5.5");
        assertThat(jm.getMetric("histogram_median")).isEqualTo("5.0");
        assertThat(jm.getMetric("histogram_stddev")).isEqualTo("1.5");
        assertThat(jm.getMetric("histogram_p75")).isEqualTo("7.0");
        assertThat(jm.getMetric("histogram_p90")).isEqualTo("8.0");
        assertThat(jm.getMetric("histogram_p95")).isEqualTo("8.5");
        assertThat(jm.getMetric("histogram_p98")).isEqualTo("9.0");
        assertThat(jm.getMetric("histogram_p99")).isEqualTo("9.5");
        assertThat(jm.getMetric("histogram_p999")).isEqualTo("9.9");
    }

