        QueryScopeInfo info = new QueryScopeInfo.JobManagerQueryScopeInfo();

        store.add(new MetricDump.CounterDump(info, "counter", 1L));
        store.add(new MetricDump.CounterDump(info, "counter", 2L));

        assertThat(store.getJobManagerMetricStore().getMetric("counter")).isEqualTo("2");
        assertThat(store.getJobManagerMetricStore().metrics).hasSize(1);
