    private static QueryScopeInfo queryScopeInfoWithCategory(byte category) {
        QueryScopeInfo info = mock(QueryScopeInfo.class, withSettings().useConstructor("scope"));
        when(info.getCategory()).thenReturn(category);
        return info;
    }

    private static MetricDump.CounterDump taskCounter(
            int subtaskIndex, int attemptNumber, long value) {
        return new MetricDump.CounterDump(
                new QueryScopeInfo.TaskQueryScopeInfo(
                        JOB_ID, VERTEX_ID, subtaskIndex, attemptNumber),
                METRIC_NAME,
                value);
    }

    private static MetricDump.CounterDump operatorCounter(
            int subtaskIndex, int attemptNumber, long value) {
        return new MetricDump.CounterDump(
                new QueryScopeInfo.OperatorQueryScopeInfo(
                        JOB_ID, VERTEX_ID, subtaskIndex, attemptNumber, OPERATOR_NAME),
                METRIC_NAME,
                value);
    }

    private static void markRepresentativeAttempt(
            MetricStore store, String jobID, String vertexID, int subtaskIndex, int attemptNumber) {
        store.getRepresentativeAttempts()
                .computeIfAbsent(jobID, k -> new HashMap<>())
                .computeIfAbsent(vertexID, k -> new HashMap<>())
                .put(subtaskIndex, attemptNumber);
    }
