import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Tests for the {@link OperatorStateRestoreOperation#restore()} method, covering the empty /
 * skipped handle cases, the successful restore of operator and broadcast states, the handling of
 * offsets, compression, class loader handling as well as the failure cases for un-restorable
 * serializers.
 */
public class OperatorStateRestoreOperationRestoreTests {

    private static final TypeSerializer<Integer> INT_SERIALIZER = IntSerializer.INSTANCE;

    private static final String OPERATOR_STATE_NAME = "test-operator-state";

    private static final String BROADCAST_STATE_NAME = "test-broadcast-state";

    // ------------------------------------------------------------------------
    //  No-op cases
    // ------------------------------------------------------------------------

    @Test
    public void testRestoreWithoutStateHandlesIsNoOp() throws Exception {
        CloseableRegistry registry = new CloseableRegistry();
        Map<String, PartitionableListState<?>> operatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> broadcastStates = new HashMap<>();

        OperatorStateRestoreOperation restoreOperation =
                createRestoreOperation(
                        registry, Collections.emptyList(), operatorStates, broadcastStates);

        assertThat(restoreOperation.restore()).isNull();

        assertThat(operatorStates).isEmpty();
        assertThat(broadcastStates).isEmpty();
        assertThat(registry.getNumberOfRegisteredCloseables()).isZero();
    }

    @Test
    public void testRestoreWithOnlyNullStateHandlesIsNoOp() throws Exception {
        CloseableRegistry registry = new CloseableRegistry();
        Map<String, PartitionableListState<?>> operatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> broadcastStates = new HashMap<>();

        OperatorStateRestoreOperation restoreOperation =
                createRestoreOperation(
                        registry, Arrays.asList(null, null), operatorStates, broadcastStates);

        assertThat(restoreOperation.restore()).isNull();

        assertThat(operatorStates).isEmpty();
        assertThat(broadcastStates).isEmpty();
        assertThat(registry.getNumberOfRegisteredCloseables()).isZero();
    }

    @Test
    public void testRestoreSkipsEmptyFileMergingStateHandle() throws Exception {
        // an empty file merging handle holds no data at all; its input stream cannot even be
        // opened, so a successful restore proves that it was skipped.
        EmptyFileMergingOperatorStreamStateHandle emptyHandle =
                EmptyFileMergingOperatorStreamStateHandle.create(
                        new DirectoryStreamStateHandle(new Path("file:///tmp/task-owned-dir")),
                        new DirectoryStreamStateHandle(new Path("file:///tmp/shared-dir")));

        StateHandleBuilder builder =
                new StateHandleBuilder(
                        Collections.singletonList(operatorMetaInfoSnapshot(OPERATOR_STATE_NAME)),
                        Collections.<StateMetaInfoSnapshot>emptyList(),
                        false);
        builder.withOperatorState(
                OPERATOR_STATE_NAME, OperatorStateHandle.Mode.SPLIT_DISTRIBUTE, Arrays.asList(1, 2));
        TestOperatorStateHandle dataHandle = builder.build("data-handle");

        CloseableRegistry registry = new CloseableRegistry();
        Map<String, PartitionableListState<?>> operatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> broadcastStates = new HashMap<>();

        OperatorStateRestoreOperation restoreOperation =
                createRestoreOperation(
                        registry,
                        Arrays.asList(null, emptyHandle, dataHandle),
                        operatorStates,
                        broadcastStates);

        assertThat(restoreOperation.restore()).isNull();

        assertThat(operatorStates).containsOnlyKeys(OPERATOR_STATE_NAME);
        assertThat(valuesOf(operatorStates.get(OPERATOR_STATE_NAME))).containsExactly(1, 2);
        assertThat(dataHandle.getOpenedStreams()).hasSize(1);
        assertThat(registry.getNumberOfRegisteredCloseables()).isZero();
    }

    // ------------------------------------------------------------------------
    //  Operator state restore
    // ------------------------------------------------------------------------

    @Test
    public void testRestoreOperatorStateWithMultiplePartitions() throws Exception {
        StateHandleBuilder builder =
                new StateHandleBuilder(
                        Collections.singletonList(operatorMetaInfoSnapshot(OPERATOR_STATE_NAME)),
                        Collections.<StateMetaInfoSnapshot>emptyList(),
                        false);
        // padding between the partitions forces the restore operation to seek to the offsets
        builder.withOperatorState(
                OPERATOR_STATE_NAME,
                OperatorStateHandle.Mode.SPLIT_DISTRIBUTE,
                Arrays.asList(11, 22, 33),
                3);
        TestOperatorStateHandle stateHandle = builder.build("operator-handle");

        CloseableRegistry registry = new CloseableRegistry();
        Map<String, PartitionableListState<?>> operatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> broadcastStates = new HashMap<>();

        assertThat(
                        createRestoreOperation(
                                        registry,
                                        Collections.singletonList(stateHandle),
                                        operatorStates,
                                        broadcastStates)
                                .restore())
                .isNull();

        assertThat(operatorStates).containsOnlyKeys(OPERATOR_STATE_NAME);

        PartitionableListState<?> restoredState = operatorStates.get(OPERATOR_STATE_NAME);
        assertThat(restoredState.getStateMetaInfo().getName()).isEqualTo(OPERATOR_STATE_NAME);
        assertThat(restoredState.getStateMetaInfo().getAssignmentMode())
                .isEqualTo(OperatorStateHandle.Mode.SPLIT_DISTRIBUTE);
        assertThat(restoredState.getStateMetaInfo().getPartitionStateSerializer())
                .isInstanceOf(IntSerializer.class);
        assertThat(valuesOf(restoredState)).containsExactly(11, 22, 33);

        assertThat(broadcastStates).isEmpty();

        // the stream that was opened for the handle must be closed and unregistered again
        assertThat(stateHandle.getOpenedStreams()).hasSize(1);
        assertThat(stateHandle.getOpenedStreams().get(0).isClosed()).isTrue();
        assertThat(registry.getNumberOfRegisteredCloseables()).isZero();
    }

    @Test
    public void testRestoreOperatorStateWithoutPartitionsCreatesEmptyState() throws Exception {
        StateHandleBuilder builder =
                new StateHandleBuilder(
                        Collections.singletonList(operatorMetaInfoSnapshot(OPERATOR_STATE_NAME)),
                        Collections.<StateMetaInfoSnapshot>emptyList(),
                        false);
        builder.withOperatorState(
                OPERATOR_STATE_NAME,
                OperatorStateHandle.Mode.UNION,
                Collections.<Integer>emptyList());
        TestOperatorStateHandle stateHandle = builder.build("operator-handle");

        Map<String, PartitionableListState<?>> operatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> broadcastStates = new HashMap<>();

        createRestoreOperation(
                        new CloseableRegistry(),
                        Collections.singletonList(stateHandle),
                        operatorStates,
                        broadcastStates)
                .restore();

        assertThat(operatorStates).containsOnlyKeys(OPERATOR_STATE_NAME);
        PartitionableListState<?> restoredState = operatorStates.get(OPERATOR_STATE_NAME);
        assertThat(restoredState.getStateMetaInfo().getAssignmentMode())
                .isEqualTo(OperatorStateHandle.Mode.UNION);
        assertThat(valuesOf(restoredState)).isEmpty();
    }

    @Test
    public void testRestoreOperatorStateWithoutOffsetsKeepsStateEmpty() throws Exception {
        // this handle simply does not know any partition offsets for the state, which means that
        // no values can be deserialized, but the state itself is still (re-)created.
