    @Test
    public void testRestoreOperatorStateWithMultiplePartitions() throws Exception {
        StateHandleBuilder builder =
                new StateHandleBuilder(
                        Collections.singletonList(operatorMetaInfoSnapshot(OPERATOR_STATE_NAME)),
                        Collections.<StateMetaInfoSnapshot>emptyList(),
                        false);
        // padding between the partitions forces the restore operation to seek to the offsets
        builder.withOperatorState(
                OPERATOR_STATE_NAME,
                OperatorStateHandle.Mode.SPLIT_DISTRIBUTE,
                Arrays.asList(11, 22, 33),
                3);
        TestOperatorStateHandle stateHandle = builder.build("operator-handle");

        CloseableRegistry registry = new CloseableRegistry();
        Map<String, PartitionableListState<?>> operatorStates = new HashMap<>();
        Map<String, BackendWritableBroadcastState<?, ?>> broadcastStates = new HashMap<>();

        assertThat(
                        createRestoreOperation(
                                        registry,
                                        Collections.singletonList(stateHandle),
                                        operatorStates,
                                        broadcastStates)
                                .restore())
                .isNull();

        assertThat(operatorStates).containsOnlyKeys(OPERATOR_STATE_NAME);

        PartitionableListState<?> restoredState = operatorStates.get(OPERATOR_STATE_NAME);
        assertThat(restoredState.getStateMetaInfo().getName()).isEqualTo(OPERATOR_STATE_NAME);
        assertThat(restoredState.getStateMetaInfo().getAssignmentMode())
                .isEqualTo(OperatorStateHandle.Mode.SPLIT_DISTRIBUTE);
        assertThat(restoredState.getStateMetaInfo().getPartitionStateSerializer())
                .isInstanceOf(IntSerializer.class);
        assertThat(valuesOf(restoredState)).containsExactly(11, 22, 33);

        assertThat(broadcastStates).isEmpty();

        // the stream that was opened for the handle must be closed and unregistered again
        assertThat(stateHandle.getOpenedStreams()).hasSize(1);
        assertThat(stateHandle.getOpenedStreams().get(0).isClosed()).isTrue();
        assertThat(registry.getNumberOfRegisteredCloseables()).isZero();
    }

