    public void testRestoreBroadcastState() throws Exception {
        Map<Integer, Integer> broadcastValues = new LinkedHashMap<>();
        broadcastValues.put(1, 10);
        broadcastValues.put(2, 20);
        broadcastValues.put(3, 30);

        StateHandleBuilder builder =
                new StateHandleBuilder(
