    @Test
    public void testRestoreSetsAndRestoresThreadContextClassLoader() throws Exception {
        ClassLoader originalClassLoader = Thread.currentThread().getContextClassLoader();
        ClassLoader userClassLoader = new ClassLoader(originalClassLoader) {};

        StateHandleBuilder builder =
                new StateHandleBuilder(
                        Collections.singletonList(operatorMetaInfoSnapshot(OPERATOR_STATE_NAME)),
                        Collections.<StateMetaInfoSnapshot>emptyList(),
                        false);
        builder.withOperatorState(
                OPERATOR_STATE_NAME,
                OperatorStateHandle.Mode.SPLIT_DISTRIBUTE,
                Collections.singletonList(3));
        TestOperatorStateHandle stateHandle = builder.build("classloader-handle");

        try {
            new OperatorStateRestoreOperation(
                            new CloseableRegistry(),
                            userClassLoader,
                            new HashMap<>(),
                            new HashMap<>(),
                            Collections.singletonList(stateHandle))
                    .restore();

            // the restore operation must have switched to the user class loader while reading
            assertThat(stateHandle.getOpenedStreams().get(0).getContextClassLoaderAtFirstRead())
                    .isSameAs(userClassLoader);
        } finally {
            assertThat(Thread.currentThread().getContextClassLoader())
                    .isSameAs(originalClassLoader);
        }
    }

