    private static StateMetaInfoSnapshot unloadableOperatorMetaInfoSnapshot(String name) {
        return new StateMetaInfoSnapshot(
                name,
                BackendStateType.OPERATOR,
                Collections.singletonMap(
                        CommonOptionsKeys.OPERATOR_STATE_DISTRIBUTION_MODE.toString(),
                        OperatorStateHandle.Mode.SPLIT_DISTRIBUTE.toString()),
                Collections.singletonMap(
                        CommonSerializerKeys.VALUE_SERIALIZER.toString(),
