    private static StateMetaInfoSnapshot unloadableBroadcastMetaInfoSnapshot(
            String name, boolean keyUnloadable) {
        Map<String, TypeSerializerSnapshot<?>> serializerSnapshots = new HashMap<>();
        serializerSnapshots.put(
                CommonSerializerKeys.KEY_SERIALIZER.toString(),
                keyUnloadable
                        ? new UnloadableTypeSerializerSnapshot()
                        : INT_SERIALIZER.snapshotConfiguration());
        serializerSnapshots.put(
                CommonSerializerKeys.VALUE_SERIALIZER.toString(),
                keyUnloadable
                        ? INT_SERIALIZER.snapshotConfiguration()
                        : new UnloadableTypeSerializerSnapshot());

        return new StateMetaInfoSnapshot(
                name,
                BackendStateType.BROADCAST,
                Collections.singletonMap(
                        CommonOptionsKeys.OPERATOR_STATE_DISTRIBUTION_MODE.toString(),
                        OperatorStateHandle.Mode.BROADCAST.toString()),
