    /**
     * Helper that writes an operator state snapshot (meta information plus state values) in the
     * same format as the operator state backend produces it, and wraps it into a {@link
     * TestOperatorStateHandle} that reports the corresponding partition offsets.
     */
    private static final class StateHandleBuilder {

        private final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        private final Map<String, OperatorStateHandle.StateMetaInfo> stateMetaData =
                new LinkedHashMap<>();
        private final OutputStream valueStream;
        private final DataOutputView valueView;

        StateHandleBuilder(
                List<StateMetaInfoSnapshot> operatorSnapshots,
                List<StateMetaInfoSnapshot> broadcastSnapshots,
                boolean compressed)
                throws IOException {
            DataOutputViewStreamWrapper metadataView = new DataOutputViewStreamWrapper(bytes);
            new OperatorBackendSerializationProxy(
                            operatorSnapshots, broadcastSnapshots, compressed)
                    .write(metadataView);
            metadataView.flush();

            this.valueStream =
                    compressed
                            ? SnappyStreamCompressionDecorator.INSTANCE.decorateWithCompression(
                                    bytes)
                            : bytes;
            this.valueView = new DataOutputViewStreamWrapper(valueStream);
        }

        StateHandleBuilder withOperatorState(
                String name,
                OperatorStateHandle.Mode mode,
                List<Integer> values,
                int paddingPerPartition)
                throws IOException {
            long[] offsets = new long[values.size()];
            for (int i = 0; i < values.size(); i++) {
                offsets[i] = position();
                INT_SERIALIZER.serialize(values.get(i), valueView);
                for (int padding = 0; padding < paddingPerPartition; padding++) {
                    valueView.writeByte(0);
                }
            }
            stateMetaData.put(name, new OperatorStateHandle.StateMetaInfo(offsets, mode));
            return this;
        }

        StateHandleBuilder withOperatorState(
                String name, OperatorStateHandle.Mode mode, List<Integer> values)
                throws IOException {
            return withOperatorState(name, mode, values, 0);
        }

        StateHandleBuilder withBroadcastState(String name, Map<Integer, Integer> values)
                throws IOException {
            stateMetaData.put(
                    name,
                    new OperatorStateHandle.StateMetaInfo(
                            new long[] {position()}, OperatorStateHandle.Mode.BROADCAST));
            valueView.writeInt(values.size());
            for (Map.Entry<Integer, Integer> entry : values.entrySet()) {
                INT_SERIALIZER.serialize(entry.getKey(), valueView);
                INT_SERIALIZER.serialize(entry.getValue(), valueView);
            }
            return this;
        }

        TestOperatorStateHandle build(String handleName) throws IOException {
            // closes only the outer compression stream, the bytes remain readable
            valueStream.close();
            return new TestOperatorStateHandle(stateMetaData, bytes.toByteArray(), handleName);
        }

        private long position() throws IOException {
            valueStream.flush();
            return bytes.size();
        }
    }

    /** A {@link OperatorStateHandle} over an in-memory byte array with capturing streams. */
    private static final class TestOperatorStateHandle implements OperatorStateHandle {

        private static final long serialVersionUID = 1L;

        private final Map<String, StateMetaInfo> stateNameToPartitionOffsets;
        private final byte[] data;
        private final String handleName;
        private final List<TestInputStream> openedStreams = new ArrayList<>();

        TestOperatorStateHandle(
                Map<String, StateMetaInfo> stateNameToPartitionOffsets,
                byte[] data,
                String handleName) {
            this.stateNameToPartitionOffsets = stateNameToPartitionOffsets;
            this.data = data;
            this.handleName = handleName;
        }

        List<TestInputStream> getOpenedStreams() {
            return openedStreams;
        }

        @Override
        public Map<String, StateMetaInfo> getStateNameToPartitionOffsets() {
            return stateNameToPartitionOffsets;
        }

        @Override
        public FSDataInputStream openInputStream() {
            TestInputStream stream = new TestInputStream(data);
            openedStreams.add(stream);
            return stream;
        }

        @Override
        public StreamStateHandle getDelegateStateHandle() {
            return this;
        }

        @Override
        public void discardState() {}

        @Override
        public long getStateSize() {
            return data.length;
        }

        @Override
        public Optional<byte[]> asBytesIfInMemory() {
            return Optional.of(data);
        }

        @Override
        public PhysicalStateHandleID getStreamStateHandleID() {
            return new PhysicalStateHandleID(handleName);
        }
    }

    /** In-memory {@link FSDataInputStream} that records closing and the first reading thread. */
    private static final class TestInputStream extends FSDataInputStream {

        private final byte[] data;
        private int position;
        private boolean closed;
        private ClassLoader contextClassLoaderAtFirstRead;

        TestInputStream(byte[] data) {
            this.data = data;
        }

        boolean isClosed() {
            return closed;
        }

        ClassLoader getContextClassLoaderAtFirstRead() {
            return contextClassLoaderAtFirstRead;
        }

        @Override
        public void seek(long desired) throws IOException {
            if (desired < 0 || desired > data.length) {
                throw new IOException("Position out of bounds: " + desired);
            }
            position = (int) desired;
        }

        @Override
        public long getPos() {
            return position;
        }

        @Override
        public int read() {
            recordContextClassLoader();
            return position < data.length ? data[position++] & 0xFF : -1;
        }

        @Override
        public int read(byte[] buffer, int offset, int length) {
            recordContextClassLoader();
            int bytesLeft = data.length - position;
            if (bytesLeft <= 0) {
                return length == 0 ? 0 : -1;
            }
            int bytesToCopy = Math.min(length, bytesLeft);
            System.arraycopy(data, position, buffer, offset, bytesToCopy);
            position += bytesToCopy;
            return bytesToCopy;
        }

        @Override
        public void close() {
            closed = true;
        }

        private void recordContextClassLoader() {
            if (contextClassLoaderAtFirstRead == null) {
                contextClassLoaderAtFirstRead =
                        Thread.currentThread().getContextClassLoader();
            }
        }
    }

