        final OperatorChainInfo chainInfo = new OperatorChainInfo(0);
        final JobVertex existingVertex = new JobVertex("existing");
        context.addJobVertex(0, existingVertex);

        final List<Integer> visitedNodes = new ArrayList<>();
        final List<StreamEdge> result =
                StreamingJobGraphGenerator.createChain(
                        0,
                        1,
                        chainInfo,
                        new HashMap<>(),
                        true,
                        Runnable::run,
                        context,
                        visitedNodes::add);

        assertTrue(result.isEmpty());
        assertTrue(visitedNodes.isEmpty());
        assertTrue(chainInfo.getAllChainedNodes().isEmpty());
        assertTrue(chainInfo.getChainedNames().isEmpty());
        assertEquals(1, context.getJobVerticesInOrder().size());
        assertSame(existingVertex, context.getJobVertex(0));
        assertEquals(0, context.getJobGraph().getNumberOfVertices());
    }

    @Test
    void testSingleNodeCreatesChainStartAndEndConfig() {
        final StreamGraph streamGraph = createStreamGraph(0);
        final JobVertexBuildContext context = createBuildContext(streamGraph);
        final OperatorChainInfo chainInfo = new OperatorChainInfo(0);
        final Map<Integer, OperatorChainInfo> chainEntryPoints = new HashMap<>();
        chainEntryPoints.put(0, chainInfo);
