                StreamingJobGraphGenerator.createChain(
                        0,
                        1,
                        chainInfo,
                        chainEntryPoints,
                        true,
                        Runnable::run,
                        context,
                        visitedNodes::add);

        assertTrue(result.isEmpty());
        assertEquals(Collections.singletonList(0), visitedNodes);
        assertEquals(1, context.getJobVerticesInOrder().size());
        assertEquals(1, context.getJobGraph().getNumberOfVertices());

        final JobVertex jobVertex = context.getJobVertex(0);
        assertNotNull(jobVertex);
        final StreamConfig config = new StreamConfig(jobVertex.getConfiguration());
        assertTrue(config.isChainStart());
        assertTrue(config.isChainEnd());
        assertEquals(1, config.getChainIndex());
        assertEquals(0, config.getVertexID());
        assertEquals("op-0", config.getOperatorName());
        assertEquals(chainInfo.getOperatorInfo(0).getOperatorId(), config.getOperatorID());
        assertEquals(1, jobVertex.getOperatorIDs().size());
        assertEquals(
                chainInfo.getOperatorInfo(0).getOperatorId(),
                jobVertex.getOperatorIDs().get(0).getGeneratedOperatorID());

        assertEquals(Collections.singletonList(0), idsOf(chainInfo.getAllChainedNodes()));
        assertEquals("op-0", chainInfo.getChainedName(0));
        assertSame(chainInfo, context.getChainInfo(0));
        assertTrue(chainInfo.getTransitiveOutEdges().isEmpty());
        assertTrue(chainInfo.getOperatorInfo(0).getNonChainableOutputs().isEmpty());
