        final List<StreamEdge> result =
                StreamingJobGraphGenerator.createChain(
                        0,
                        1,
                        chainInfo,
                        chainEntryPoints,
                        true,
                        Runnable::run,
                        context,
                        visitedNodes::add);

        assertTrue(result.isEmpty());
        assertEquals(Arrays.asList(0, 1), visitedNodes);

        // A chainable successor must not get a JobVertex of its own.
        assertEquals(1, context.getJobVerticesInOrder().size());
        assertTrue(context.getJobVerticesInOrder().containsKey(0));
        assertFalse(context.getJobVerticesInOrder().containsKey(1));

        assertEquals(Arrays.asList(0, 1), idsOf(chainInfo.getAllChainedNodes()));
        assertEquals("op-0 -> op-1", chainInfo.getChainedName(0));
        assertEquals("op-1", chainInfo.getChainedName(1));
        assertTrue(chainInfo.getOperatorInfo(0).getNonChainableOutputs().isEmpty());
        assertTrue(chainInfo.getOperatorInfo(1).getNonChainableOutputs().isEmpty());

        final StreamConfig startConfig = new StreamConfig(context.getJobVertex(0).getConfiguration());
        assertTrue(startConfig.isChainStart());
        assertFalse(startConfig.isChainEnd());
        assertEquals(1, startConfig.getChainIndex());

        final Map<Integer, StreamConfig> chainedConfigs = context.getChainedConfigs().get(0);
        assertNotNull(chainedConfigs);
        assertEquals(Collections.singleton(1), chainedConfigs.keySet());
        final StreamConfig chainedConfig = chainedConfigs.get(1);
        assertEquals(1, chainedConfig.getVertexID());
        assertEquals(2, chainedConfig.getChainIndex());
        assertEquals("op-1", chainedConfig.getOperatorName());
        assertFalse(chainedConfig.isChainStart());
        assertTrue(chainedConfig.isChainEnd());
        assertEquals(chainInfo.getOperatorInfo(1).getOperatorId(), chainedConfig.getOperatorID());
        assertEquals(Collections.singletonList(edge), startConfig.getChainedOutputs(getClassLoader()));
