    private static StreamOperatorFactory<String> identityOperatorFactory() {
        return SimpleOperatorFactory.of(new StreamMap<>(new IdentityMapFunction()));
    }

    private static JobVertexBuildContext createBuildContext(StreamGraph streamGraph) {
        final Map<Integer, byte[]> hashes = new HashMap<>();
        for (StreamNode node : streamGraph.getStreamNodes()) {
            final byte[] hash = new byte[16];
            hash[0] = (byte) node.getId();
            hashes.put(node.getId(), hash);
        }
        return new JobVertexBuildContext(
                new JobGraph("test-job"),
                streamGraph,
                new AtomicBoolean(false),
                hashes,
                Collections.emptyList(),
                null);
    }

