    @Test
    void testReturnsEmptyListWhenJobVertexAlreadyExists() {
        final StreamGraph streamGraph = createStreamGraph(0);
        final JobVertexBuildContext context = createBuildContext(streamGraph);
        final OperatorChainInfo chainInfo = new OperatorChainInfo(0);
        final JobVertex existingVertex = new JobVertex("existing");
        context.addJobVertex(0, existingVertex);

        final List<Integer> visitedNodes = new ArrayList<>();
        final List<StreamEdge> result =
                StreamingJobGraphGenerator.createChain(
                        0,
                        1,
                        chainInfo,
                        new HashMap<>(),
                        true,
                        Runnable::run,
                        context,
