private static StreamGraph createStreamGraph(int... nodeIds) {
    final StreamGraph streamGraph =
            new StreamGraph(
                    new Configuration(),
                    new ExecutionConfig(),
                    new CheckpointConfig(),
                    SavepointRestoreSettings.none());
    for (int nodeId : nodeIds) {
        streamGraph.addOperator(
                nodeId,
                null,
                null,
                identityOperatorFactory(),
                BasicTypeInfo.STRING_TYPE_INFO,
                BasicTypeInfo.STRING_TYPE_INFO,
                "op-" + nodeId);
        streamGraph.setParallelism(nodeId, 1);
        streamGraph.setMaxParallelism(nodeId, 128);
    }
    return streamGraph;
}

private static StreamOperatorFactory<String> identityOperatorFactory() {
    return SimpleOperatorFactory.of(new StreamMap<>(new IdentityMapFunction()));
}

private static JobVertexBuildContext createBuildContext(StreamGraph streamGraph) {
    final Map<Integer, byte[]> hashes = new HashMap<>();
    final Map<Integer, byte[]> legacyHashes = new HashMap<>();
    for (StreamNode node : streamGraph.getStreamNodes()) {
        final byte[] hash = new byte[16];
        hash[0] = (byte) node.getId();
        hashes.put(node.getId(), hash);

        final byte[] legacyHash = new byte[16];
        legacyHash[0] = (byte) node.getId();
        legacyHash[1] = 1;
        legacyHashes.put(node.getId(), legacyHash);
    }
    return new JobVertexBuildContext(
            new JobGraph("test-job"),
            streamGraph,
            new AtomicBoolean(false),
            hashes,
            Collections.singletonList(legacyHashes),
            null);
}

private static Attribute noOutputAttribute() {
    return new Attribute.Builder().setNoOutputUntilEndOfInput(true).build();
}

private static void assertSameNodeIds(List<Integer> expected, List<Integer> actual) {
    assertEquals(expected.size(), actual.size());
    assertEquals(new HashSet<>(expected), new HashSet<>(actual));
}

private static List<Integer> idsOf(List<StreamNode> nodes) {
    final List<Integer> ids = new ArrayList<>(nodes.size());
    for (StreamNode node : nodes) {
        ids.add(node.getId());
    }
    return ids;
}

