import javax.annotation.Nonnull;

import java.io.Closeable;
import java.io.IOException;
import java.util.Collections;
import java.util.Iterator;

/**
 * This interface represents an iterable that is also closeable.
 *
 * @param <T> type of the iterated objects.
 */
public interface CloseableIterable<T> extends Iterable<T>, Closeable {

    /** Empty iterator. */
    class Empty<T> implements CloseableIterable<T> {

        private Empty() {}

        @Override
        public void close() throws IOException {}

        @Nonnull
        @Override
        public Iterator<T> iterator() {
            return Collections.emptyIterator();
        }
    }

    /** Returns an empty iterator. */
    static <T> CloseableIterable<T> empty() {
        return new CloseableIterable.Empty<>();
    }
}

 * @param parallelism The current parallelism under which the job runs. Must be <=
 *     maxParallelism.
 * @param operatorIndex index of a operatorIndex. 0 <= operatorIndex < parallelism.
 * @return the computed key-group range for the operator.
 */
public static KeyGroupRange computeKeyGroupRangeForOperatorIndex(
        int maxParallelism, int parallelism, int operatorIndex) {

    checkParallelismPreconditions(parallelism);
    checkParallelismPreconditions(maxParallelism);

    Preconditions.checkArgument(
            maxParallelism >= parallelism,
            "Maximum parallelism must not be smaller than parallelism.");

    int start = ((operatorIndex * maxParallelism + parallelism - 1) / parallelism);
    int end = ((operatorIndex + 1) * maxParallelism - 1) / parallelism;
    return new KeyGroupRange(start, end);

