import static org.mockito.Mockito.when;

/**
 * Tests for {@link StreamTaskStateInitializerImpl#streamOperatorStateContext}.
 *
 * <p>These tests drive the public entry point of the initializer and verify the resulting {@link
 * StreamOperatorStateContext}, the arguments that are forwarded to the state backends and timer
 * service, as well as the cleanup behavior when creation fails.
 */
class StreamTaskStateInitializerImplStreamOperatorStateContextTests {

    private static final long RESTORED_CHECKPOINT_ID = 42L;
    private static final String OPERATOR_CLASS_NAME = "TestOperator";
    private static final double MANAGED_MEMORY_FRACTION = 0.4d;
    private static final int MAX_PARALLELISM = 4;
    private static final int PARALLELISM = 4;
    private static final int SUBTASK_INDEX = 2;

    private Environment environment;
    private TaskStateManager taskStateManager;
    private StateBackend stateBackend;
    private TaskInfo taskInfo;
    private TaskMetricGroup taskMetricGroup;
    private TaskIOMetricGroup taskIOMetricGroup;
    private UserCodeClassLoader userCodeClassLoader;
    private TaskKvStateRegistry taskKvStateRegistry;

    private CheckpointableKeyedStateBackend keyedStateBackend;
    private AsyncKeyedStateBackend asyncKeyedStateBackend;
    private OperatorStateBackend operatorStateBackend;
    private InternalTimeServiceManager<?> timeServiceManager;

    private JobID jobID;
    private JobVertexID jobVertexID;
    private OperatorID operatorID;
    private KeyGroupRange expectedKeyGroupRange;
    private ClassLoader testClassLoader;

    private TypeSerializer<?> keySerializer;
    private ProcessingTimeService processingTimeService;
    private KeyContext keyContext;
    private MetricGroup operatorMetricGroup;
    private CloseableRegistry streamTaskCloseableRegistry;
    private StreamTaskCancellationContext cancellationContext;
    private SubTaskInitializationMetricsBuilder initializationMetrics;

    private RecordingTimeServiceManagerProvider timeServiceManagerProvider;

    @BeforeEach
    void setUp() throws Exception {
        jobID = new JobID();
        jobVertexID = new JobVertexID();
        operatorID = new OperatorID();
        testClassLoader = getClass().getClassLoader();
        expectedKeyGroupRange =
                KeyGroupRangeAssignment.computeKeyGroupRangeForOperatorIndex(
                        MAX_PARALLELISM, PARALLELISM, SUBTASK_INDEX);

        taskInfo = mock(TaskInfo.class);
        when(taskInfo.getIndexOfThisSubtask()).thenReturn(SUBTASK_INDEX);
        when(taskInfo.getNumberOfParallelSubtasks()).thenReturn(PARALLELISM);
        when(taskInfo.getMaxNumberOfParallelSubtasks()).thenReturn(MAX_PARALLELISM);

        taskStateManager = mock(TaskStateManager.class);
        when(taskStateManager.prioritizedOperatorState(any()))
                .thenReturn(PrioritizedOperatorSubtaskState.emptyNotRestored());
        when(taskStateManager.getRestoreCheckpointId()).thenReturn(Optional.empty());
        when(taskStateManager.getFileMergingSnapshotManager()).thenReturn(null);

        taskMetricGroup = mock(TaskMetricGroup.class);
        taskIOMetricGroup = mock(TaskIOMetricGroup.class);
        when(taskMetricGroup.getIOMetricGroup()).thenReturn(taskIOMetricGroup);
        userCodeClassLoader = mock(UserCodeClassLoader.class);
        when(userCodeClassLoader.asClassLoader()).thenReturn(testClassLoader);
        taskKvStateRegistry = mock(TaskKvStateRegistry.class);

        environment = mock(Environment.class);
        when(environment.getTaskStateManager()).thenReturn(taskStateManager);
        when(environment.getTaskInfo()).thenReturn(taskInfo);
        when(environment.getJobID()).thenReturn(jobID);
        when(environment.getJobVertexId()).thenReturn(jobVertexID);
        when(environment.getMetricGroup()).thenReturn(taskMetricGroup);
        when(environment.getUserCodeClassLoader()).thenReturn(userCodeClassLoader);
        when(environment.getTaskKvStateRegistry()).thenReturn(taskKvStateRegistry);

        keyedStateBackend = mock(CheckpointableKeyedStateBackend.class);
        when(keyedStateBackend.getKeyGroupRange()).thenReturn(expectedKeyGroupRange);
        asyncKeyedStateBackend = mock(AsyncKeyedStateBackend.class);
        when(asyncKeyedStateBackend.getKeyGroupRange()).thenReturn(expectedKeyGroupRange);
        operatorStateBackend = mock(OperatorStateBackend.class);

        stateBackend = mock(StateBackend.class);
        when(stateBackend.supportsAsyncKeyedStateBackend()).thenReturn(false);
        doReturn(keyedStateBackend).when(stateBackend).createKeyedStateBackend(any());
        doReturn(asyncKeyedStateBackend).when(stateBackend).createAsyncKeyedStateBackend(any());
        doReturn(operatorStateBackend).when(stateBackend).createOperatorStateBackend(any());

        keySerializer = mock(TypeSerializer.class);
        processingTimeService = mock(ProcessingTimeService.class);
        keyContext = mock(KeyContext.class);
        operatorMetricGroup = mock(MetricGroup.class);
        streamTaskCloseableRegistry = new CloseableRegistry();
        cancellationContext = StreamTaskCancellationContext.alwaysRunning();
        initializationMetrics = new SubTaskInitializationMetricsBuilder(0L);

        timeServiceManager = mock(InternalTimeServiceManager.class);
        timeServiceManagerProvider = new RecordingTimeServiceManagerProvider(timeServiceManager);
    }

    @Test
    void testCreatesSynchronousStateContextWithExpectedParameters() throws Exception {
        StreamOperatorStateContext context = createContext(keySerializer, false, false);

        assertSame(keyedStateBackend, context.keyedStateBackend());
        assertNull(context.asyncKeyedStateBackend());
        assertSame(keySerializer, context.keySerializer());
        assertSame(operatorStateBackend, context.operatorStateBackend());
        assertSame(timeServiceManager, context.internalTimerServiceManager());
        assertNull(context.asyncInternalTimerServiceManager());
        assertFalse(context.getRestoredCheckpointId().isPresent());

        assertNotNull(context.rawKeyedStateInputs());
        assertNotNull(context.rawOperatorStateInputs());
        assertTrue(streamTaskCloseableRegistry.isCloseableRegistered(context.rawKeyedStateInputs()));
        assertTrue(
                streamTaskCloseableRegistry.isCloseableRegistered(context.rawOperatorStateInputs()));
        assertTrue(streamTaskCloseableRegistry.isCloseableRegistered(keyedStateBackend));
        assertTrue(streamTaskCloseableRegistry.isCloseableRegistered(operatorStateBackend));
        assertEquals(4, streamTaskCloseableRegistry.getNumberOfRegisteredCloseables());

        ArgumentCaptor<StateBackend.KeyedStateBackendParameters> keyedParametersCaptor =
                ArgumentCaptor.forClass(StateBackend.KeyedStateBackendParameters.class);
        verify(stateBackend).createKeyedStateBackend(keyedParametersCaptor.capture());

        StateBackend.KeyedStateBackendParameters keyedParameters =
                keyedParametersCaptor.getValue();
        assertSame(environment, keyedParameters.getEnv());
        assertEquals(jobID, keyedParameters.getJobID());
        assertEquals(expectedOperatorIdentifier(), keyedParameters.getOperatorIdentifier());
        assertSame(keySerializer, keyedParameters.getKeySerializer());
        assertEquals(MAX_PARALLELISM, keyedParameters.getNumberOfKeyGroups());
        assertEquals(expectedKeyGroupRange, keyedParameters.getKeyGroupRange());
        assertSame(taskKvStateRegistry, keyedParameters.getKvStateRegistry());
        assertSame(operatorMetricGroup, keyedParameters.getMetricGroup());
        assertEquals(
                MANAGED_MEMORY_FRACTION,
                keyedParameters.getManagedMemoryFraction(),
                Double.MIN_VALUE);
        assertTrue(keyedParameters.getStateHandles().isEmpty());
        assertNotNull(keyedParameters.getCancelStreamRegistry());
        assertNotNull(keyedParameters.getTtlTimeProvider());

        ArgumentCaptor<StateBackend.OperatorStateBackendParameters> operatorParametersCaptor =
                ArgumentCaptor.forClass(StateBackend.OperatorStateBackendParameters.class);
        verify(stateBackend).createOperatorStateBackend(operatorParametersCaptor.capture());

        StateBackend.OperatorStateBackendParameters operatorParameters =
                operatorParametersCaptor.getValue();
        assertSame(environment, operatorParameters.getEnv());
        assertEquals(expectedOperatorIdentifier(), operatorParameters.getOperatorIdentifier());
        assertTrue(operatorParameters.getStateHandles().isEmpty());
        assertNotNull(operatorParameters.getCancelStreamRegistry());

        assertEquals(1, timeServiceManagerProvider.invocationCount);
        assertSame(keyedStateBackend, timeServiceManagerProvider.factories.get(0));
        assertSame(taskIOMetricGroup, timeServiceManagerProvider.ioMetricGroups.get(0));
        assertEquals(expectedKeyGroupRange, timeServiceManagerProvider.keyGroupRanges.get(0));
        assertSame(testClassLoader, timeServiceManagerProvider.classLoaders.get(0));
        assertSame(keyContext, timeServiceManagerProvider.keyContexts.get(0));
        assertSame(processingTimeService, timeServiceManagerProvider.processingTimeServices.get(0));
        assertSame(cancellationContext, timeServiceManagerProvider.cancellationContexts.get(0));

        verify(taskStateManager).prioritizedOperatorState(operatorID);
        verify(taskStateManager, never()).getSubtaskJobManagerRestoredState(any());
    }

    @Test
    void testUsesNativeAsyncKeyedStateBackendWhenSupported() throws Exception {
        when(stateBackend.supportsAsyncKeyedStateBackend()).thenReturn(true);

        StreamOperatorStateContext context = createContext(keySerializer, false, true);

        assertSame(asyncKeyedStateBackend, context.asyncKeyedStateBackend());
        assertNull(context.keyedStateBackend());
        assertSame(operatorStateBackend, context.operatorStateBackend());
        assertSame(timeServiceManager, context.asyncInternalTimerServiceManager());
        assertNull(context.internalTimerServiceManager());

        verify(stateBackend).createAsyncKeyedStateBackend(any());
        verify(stateBackend, never()).createKeyedStateBackend(any());

        assertEquals(1, timeServiceManagerProvider.invocationCount);
        assertSame(asyncKeyedStateBackend, timeServiceManagerProvider.factories.get(0));
        assertEquals(expectedKeyGroupRange, timeServiceManagerProvider.keyGroupRanges.get(0));
    }

    @Test
    void testAdaptsKeyedStateBackendForAsyncStateWhenNativeAsyncIsNotSupported() throws Exception {
        StreamOperatorStateContext context = createContext(keySerializer, false, true);

        assertNull(context.keyedStateBackend());
        assertNotNull(context.asyncKeyedStateBackend());
        assertTrue(
                context.asyncKeyedStateBackend() instanceof AsyncKeyedStateBackendAdaptor,
                "Expected the async context to wrap the synchronous keyed state backend");
        assertSame(context.asyncKeyedStateBackend(), timeServiceManagerProvider.factories.get(0));
        assertSame(timeServiceManager, context.asyncInternalTimerServiceManager());
        assertNull(context.internalTimerServiceManager());

        verify(stateBackend).createKeyedStateBackend(any());
        verify(stateBackend, never()).createAsyncKeyedStateBackend(any());
        verify(keyedStateBackend, org.mockito.Mockito.atLeastOnce()).getKeyGroupRange();
    }

    @Test
    void testDoesNotCreateKeyedBackendOrTimerServiceWithoutKeySerializer() throws Exception {
        StreamOperatorStateContext context = createContext(null, false, false);

        assertNull(context.keyedStateBackend());
        assertNull(context.asyncKeyedStateBackend());
        assertNull(context.internalTimerServiceManager());
        assertNull(context.asyncInternalTimerServiceManager());
        assertSame(operatorStateBackend, context.operatorStateBackend());

        verify(stateBackend, never()).createKeyedStateBackend(any());
        verify(stateBackend, never()).createAsyncKeyedStateBackend(any());
        assertEquals(0, timeServiceManagerProvider.invocationCount);
    }

    @Test
    void testRestoredCheckpointIdIsExposed() throws Exception {
        when(taskStateManager.prioritizedOperatorState(operatorID))
                .thenReturn(PrioritizedOperatorSubtaskState.empty(RESTORED_CHECKPOINT_ID));

        StreamOperatorStateContext context = createContext(keySerializer, false, false);

        assertTrue(context.getRestoredCheckpointId().isPresent());
        assertEquals(RESTORED_CHECKPOINT_ID, context.getRestoredCheckpointId().getAsLong());
    }

    @Test
    void testNonRestoredStateExposesEmptyCheckpointId() throws Exception {
        StreamOperatorStateContext context = createContext(keySerializer, false, false);

        assertFalse(context.getRestoredCheckpointId().isPresent());
    }

    @Test
    void testRawKeyedTimersAreNotForwardedWhenOperatorUsesCustomRawKeyedState()
            throws Exception {
        when(taskStateManager.prioritizedOperatorState(operatorID))
                .thenReturn(PrioritizedOperatorSubtaskState.empty(RESTORED_CHECKPOINT_ID));
        TrackingCloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedInputs =
                new TrackingCloseableIterable<>();
        TestableStreamTaskStateInitializer initializer =
                newTestableInitializer(rawKeyedInputs, null, null);

        initializer.streamOperatorStateContext(
                operatorID,
                OPERATOR_CLASS_NAME,
                processingTimeService,
                keyContext,
                keySerializer,
                streamTaskCloseableRegistry,
                operatorMetricGroup,
                MANAGED_MEMORY_FRACTION,
                true,
                false);

        assertEquals(1, timeServiceManagerProvider.invocationCount);
        Iterable<KeyGroupStatePartitionStreamProvider> timersArgument =
                timeServiceManagerProvider.rawKeyedStateArguments.get(0);
        assertFalse(
                timersArgument.iterator().hasNext(),
                "Custom raw keyed state must not be interpreted as internal timers");
        assertFalse(
                timersArgument == rawKeyedInputs,
                "The raw keyed state iterable must not be forwarded when it is custom state");
    }

    @Test
    void testRawKeyedTimersAreForwardedForRestoredStateWithoutCustomRawKeyedState()
            throws Exception {
        when(taskStateManager.prioritizedOperatorState(operatorID))
                .thenReturn(PrioritizedOperatorSubtaskState.empty(RESTORED_CHECKPOINT_ID));
        TrackingCloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedInputs =
                new TrackingCloseableIterable<>();
        TestableStreamTaskStateInitializer initializer =
                newTestableInitializer(rawKeyedInputs, null, null);

        initializer.streamOperatorStateContext(
                operatorID,
                OPERATOR_CLASS_NAME,
