    /**
     * A test initializer that allows replacing the raw state iterables produced by the production
     * implementation.
     */
    private static class TestableStreamTaskStateInitializer extends StreamTaskStateInitializerImpl {

        private final CloseableIterable<KeyGroupStatePartitionStreamProvider>
                rawKeyedStateInputsOverride;
        private final CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputsOverride;
        private final RuntimeException rawOperatorStateInputsFailure;

        TestableStreamTaskStateInitializer(
                Environment environment,
                StateBackend stateBackend,
                SubTaskInitializationMetricsBuilder initializationMetrics,
                TtlTimeProvider ttlTimeProvider,
                InternalTimeServiceManager.Provider timeServiceManagerProvider,
                StreamTaskCancellationContext cancellationContext,
                CloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedStateInputsOverride,
                CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputsOverride,
                RuntimeException rawOperatorStateInputsFailure) {
            super(
                    environment,
                    stateBackend,
                    initializationMetrics,
                    ttlTimeProvider,
                    timeServiceManagerProvider,
                    cancellationContext);
            this.rawKeyedStateInputsOverride = rawKeyedStateInputsOverride;
            this.rawOperatorStateInputsOverride = rawOperatorStateInputsOverride;
            this.rawOperatorStateInputsFailure = rawOperatorStateInputsFailure;
        }

        @Override
        protected CloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedStateInputs(
                Iterator<StateObjectCollection<KeyedStateHandle>> restoreStateAlternatives,
                StateObject.StateObjectSizeStatsCollector statsCollector) {
            if (rawKeyedStateInputsOverride != null) {
                return rawKeyedStateInputsOverride;
            }
            return super.rawKeyedStateInputs(restoreStateAlternatives, statsCollector);
        }

        @Override
        protected CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputs(
                Iterator<StateObjectCollection<OperatorStateHandle>> restoreStateAlternatives,
                StateObject.StateObjectSizeStatsCollector statsCollector) {
            if (rawOperatorStateInputsFailure != null) {
                throw rawOperatorStateInputsFailure;
            }
            if (rawOperatorStateInputsOverride != null) {
                return rawOperatorStateInputsOverride;
            }
            return super.rawOperatorStateInputs(restoreStateAlternatives, statsCollector);
        }
    }

    /** Records the arguments passed to the internal timer service manager provider. */
    private static class RecordingTimeServiceManagerProvider
            implements InternalTimeServiceManager.Provider {

        private static final long serialVersionUID = 1L;

        private final InternalTimeServiceManager<?> timeServiceManager;

        private final List<TaskIOMetricGroup> ioMetricGroups = new ArrayList<>();
        private final List<PriorityQueueSetFactory> factories = new ArrayList<>();
        private final List<KeyGroupRange> keyGroupRanges = new ArrayList<>();
        private final List<ClassLoader> classLoaders = new ArrayList<>();
        private final List<KeyContext> keyContexts = new ArrayList<>();
        private final List<ProcessingTimeService> processingTimeServices = new ArrayList<>();
        private final List<Iterable<KeyGroupStatePartitionStreamProvider>> rawKeyedStateArguments =
                new ArrayList<>();
        private final List<StreamTaskCancellationContext> cancellationContexts = new ArrayList<>();

        private int invocationCount;
        private RuntimeException failure;

        RecordingTimeServiceManagerProvider(InternalTimeServiceManager<?> timeServiceManager) {
            this.timeServiceManager = timeServiceManager;
        }

        @SuppressWarnings("unchecked")
        @Override
        public <K> InternalTimeServiceManager<K> create(
                TaskIOMetricGroup taskIOMetricGroup,
                PriorityQueueSetFactory factory,
                KeyGroupRange keyGroupRange,
                ClassLoader userClassloader,
                KeyContext keyContext,
                ProcessingTimeService processingTimeService,
                Iterable<KeyGroupStatePartitionStreamProvider> rawKeyedStates,
                StreamTaskCancellationContext cancellationContext)
                throws Exception {
            if (failure != null) {
                throw failure;
            }
            invocationCount++;
            ioMetricGroups.add(taskIOMetricGroup);
            factories.add(factory);
            keyGroupRanges.add(keyGroupRange);
            classLoaders.add(userClassloader);
            keyContexts.add(keyContext);
            processingTimeServices.add(processingTimeService);
            rawKeyedStateArguments.add(rawKeyedStates);
            cancellationContexts.add(cancellationContext);
            return (InternalTimeServiceManager<K>) timeServiceManager;
        }
    }

    /** A closeable iterable that records whether it was closed. */
    private static class TrackingCloseableIterable<T> implements CloseableIterable<T> {

        private boolean closed;

        @Override
        public void close() {
            closed = true;
        }

        @Override
        public Iterator<T> iterator() {
            return Collections.emptyIterator();
        }
    }
