        @Override
        protected CloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedStateInputs(
                Iterator<StateObjectCollection<KeyedStateHandle>> restoreStateAlternatives,
                StateObject.StateObjectSizeStatsCollector statsCollector) {
            if (rawKeyedStateInputsOverride != null) {
                return rawKeyedStateInputsOverride;
            }
            return super.rawKeyedStateInputs(restoreStateAlternatives, statsCollector);
        }

        @Override
        protected CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputs(
                Iterator<StateObjectCollection<OperatorStateHandle>> restoreStateAlternatives,
                StateObject.StateObjectSizeStatsCollector statsCollector) {
            if (rawOperatorStateInputsFailure != null) {
                throw rawOperatorStateInputsFailure;
            }
            if (rawOperatorStateInputsOverride != null) {
                return rawOperatorStateInputsOverride;
            }
            return super.rawOperatorStateInputs(restoreStateAlternatives, statsCollector);
        }
    }

