    /** A closeable iterable that records whether it was closed. */
    private static class TrackingCloseableIterable<T> implements CloseableIterable<T> {

        private boolean closed;

        @Override
        public void close() {
            closed = true;
        }

        boolean isClosed() {
            return closed;
        }

        @Override
        public Iterator<T> iterator() {
            return Collections.emptyIterator();
        }
    }

    /** A small recording replacement for mocking frameworks. */
    private static class RecordingInvocationHandler implements InvocationHandler {

        private final Map<String, CallHandler> answers = new HashMap<>();
        private final List<Invocation> invocations = new ArrayList<>();

        RecordingInvocationHandler answer(String methodName, CallHandler answer) {
            answers.put(methodName, answer);
            return this;
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
            invocations.add(new Invocation(method.getName(), args));
            CallHandler answer = answers.get(method.getName());
            if (answer != null) {
                return answer.handle(args);
            }
            return defaultValue(method.getReturnType());
        }

        int invocationCount(String methodName) {
            int count = 0;
            for (Invocation invocation : invocations) {
                if (invocation.methodName.equals(methodName)) {
                    count++;
                }
            }
            return count;
        }

        Object lastArgument(String methodName, int argumentIndex) {
            for (int i = invocations.size() - 1; i >= 0; i--) {
                Invocation invocation = invocations.get(i);
                if (invocation.methodName.equals(methodName)) {
                    return invocation.arguments[argumentIndex];
                }
            }
            throw new AssertionError("Method was not invoked: " + methodName);
        }

        private static Object defaultValue(Class<?> returnType) {
            if (!returnType.isPrimitive() || returnType == void.class) {
                return null;
            }
            if (returnType == boolean.class) {
                return false;
            }
            if (returnType == char.class) {
                return '\0';
            }
            if (returnType == byte.class) {
                return (byte) 0;
            }
            if (returnType == short.class) {
                return (short) 0;
            }
            if (returnType == int.class) {
                return 0;
            }
            if (returnType == long.class) {
                return 0L;
            }
            if (returnType == float.class) {
                return 0f;
            }
            if (returnType == double.class) {
                return 0d;
            }
            return null;
        }
    }

    /** A method invocation recorded by {@link RecordingInvocationHandler}. */
    private static class Invocation {

        private final String methodName;
        private final Object[] arguments;

        Invocation(String methodName, Object[] arguments) {
            this.methodName = methodName;
            this.arguments = arguments;
        }
    }

    /** Functional interface for a recorded method answer. */
    @FunctionalInterface
    private interface CallHandler {
        Object handle(Object[] arguments) throws Throwable;
    }
