    /**
     * A test initializer that allows replacing the raw state iterables produced by the production
     * implementation or making their creation fail.
     */
    private static class TestableStreamTaskStateInitializer extends StreamTaskStateInitializerImpl {

        private final CloseableIterable<KeyGroupStatePartitionStreamProvider>
                rawKeyedStateInputsOverride;
        private final CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputsOverride;
        private final RuntimeException rawOperatorStateInputsFailure;

        TestableStreamTaskStateInitializer(
                Environment environment,
                StateBackend stateBackend,
                SubTaskInitializationMetricsBuilder initializationMetrics,
                TtlTimeProvider ttlTimeProvider,
                InternalTimeServiceManager.Provider timeServiceManagerProvider,
                StreamTaskCancellationContext cancellationContext,
                CloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedStateInputsOverride,
                CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputsOverride,
                RuntimeException rawOperatorStateInputsFailure) {
            super(
                    environment,
                    stateBackend,
                    initializationMetrics,
                    ttlTimeProvider,
                    timeServiceManagerProvider,
                    cancellationContext);
            this.rawKeyedStateInputsOverride = rawKeyedStateInputsOverride;
            this.rawOperatorStateInputsOverride = rawOperatorStateInputsOverride;
            this.rawOperatorStateInputsFailure = rawOperatorStateInputsFailure;
        }

        @Override
        protected CloseableIterable<KeyGroupStatePartitionStreamProvider> rawKeyedStateInputs(
                Iterator<StateObjectCollection<KeyedStateHandle>> restoreStateAlternatives,
                StateObject.StateObjectSizeStatsCollector statsCollector) {
            if (rawKeyedStateInputsOverride != null) {
                return rawKeyedStateInputsOverride;
            }
            return super.rawKeyedStateInputs(restoreStateAlternatives, statsCollector);
        }

        @Override
        protected CloseableIterable<StatePartitionStreamProvider> rawOperatorStateInputs(
                Iterator<StateObjectCollection<OperatorStateHandle>> restoreStateAlternatives,
                StateObject.StateObjectSizeStatsCollector statsCollector) {
            if (rawOperatorStateInputsFailure != null) {
                throw rawOperatorStateInputsFailure;
            }
            if (rawOperatorStateInputsOverride != null) {
                return rawOperatorStateInputsOverride;
            }
            return super.rawOperatorStateInputs(restoreStateAlternatives, statsCollector);
        }
    }

