        assertThat(getInputProcessors(processor)).hasSize(2);
        verify(taskIOMetricGroup).reuseRecordsInputCounter(same(numRecordsIn));
        verify(streamConfig).getTypeSerializerIn(0, USER_CLASSLOADER);
        verify(streamConfig).getTypeSerializerIn(1, USER_CLASSLOADER);
        verify(streamConfig).getInputs(USER_CLASSLOADER);
