        Field field = StreamMultipleInputProcessor.class.getDeclaredField("inputProcessors");
        field.setAccessible(true);
        return (StreamOneInputProcessor<?>[]) field.get(processor);
    }

    private static StreamTaskInput<?> input(StreamMultipleInputProcessor processor, int index)
            throws Exception {
        StreamOneInputProcessor<?> inputProcessor = getInputProcessors(processor)[index];
        Field field = StreamOneInputProcessor.class.getDeclaredField("input");
        field.setAccessible(true);
        return (StreamTaskInput<?>) field.get(inputProcessor);
    }

    @SuppressWarnings("unchecked")
    private static DataOutput<Object> output(StreamMultipleInputProcessor processor, int index)
