        assertThat(getInputProcessors(processor)).hasSize(2);
        verifyThat(taskIOMetricGroup).reuseRecordsInputCounter(sameValue(numRecordsIn));
        verifyThat(streamConfig).getTypeSerializerIn(0, USER_CLASSLOADER);
        verifyThat(streamConfig).getTypeSerializerIn(1, USER_CLASSLOADER);
