            throws Exception {
        StreamOneInputProcessor<?> inputProcessor = getInputProcessors(processor)[index];
        Field field = StreamOneInputProcessor.class.getDeclaredField("output");
        field.setAccessible(true);
        return (DataOutput<Object>) field.get(inputProcessor);
