    private static <T> T mockOf(Class<T> type) {
        return org.mockito.Mockito.mock(type);
    }

    private static <T> T mockOf(Class<T> type, Class<?>... extraInterfaces) {
        return org.mockito.Mockito.mock(
                type, org.mockito.Mockito.withSettings().extraInterfaces(extraInterfaces));
    }

    private static <T> org.mockito.stubbing.OngoingStubbing<T> stubOf(T methodCall) {
        return org.mockito.Mockito.when(methodCall);
    }

    private static <T> T verifyThat(T mockObject) {
        return org.mockito.Mockito.verify(mockObject);
    }

    private static <T> T verifyNoCall(T mockObject) {
        return org.mockito.Mockito.verify(mockObject, org.mockito.Mockito.never());
    }

    private static <T> T anyValue() {
        return org.mockito.ArgumentMatchers.any();
    }

    private static <T> T anyValueOf(Class<T> type) {
        return org.mockito.ArgumentMatchers.any(type);
    }

    private static int anyIntValue() {
        return org.mockito.ArgumentMatchers.anyInt();
    }

    private static double anyDoubleValue() {
        return org.mockito.ArgumentMatchers.anyDouble();
    }

    private static <T> T sameValue(T value) {
        return org.mockito.ArgumentMatchers.same(value);
    }
