    private StreamMultipleInputProcessor createProcessor(
            TwoInputStreamOperator<Object, Object, ?> streamOperator, OperatorChain<?, ?> chain)
            throws Exception {
        currentOperator = streamOperator;
        return StreamTwoInputProcessorFactory.create(
                ownerTask,
                new CheckpointedInputGate[] {inputGate1, inputGate2},
                ioManager,
                memoryManager,
                taskIOMetricGroup,
                streamOperator,
                input1WatermarkGauge,
                input2WatermarkGauge,
                chain,
                streamConfig,
                new Configuration(),
                jobConfig,
                new ExecutionConfig(),
                USER_CLASSLOADER,
                numRecordsIn,
                InflightDataRescalingDescriptor.NO_RESCALE,
                GATE_PARTITIONERS,
                taskInfo,
                CAN_EMIT_BATCH_OF_RECORDS);
    }

