@Test
void testProcessInputReadsBothInputsRoundRobin() throws Exception {
    StreamMultipleInputProcessor processor = createProcessor(plainOperator(), operatorChain);

    // The first read touches the first input, but the second input is still available, hence
    // the processor reports that more data can be read.
    assertThat(processor.processInput()).isEqualTo(DataInputStatus.MORE_AVAILABLE);
    verifyThat(inputGate1).pollNext();
    verifyNoCall(inputGate2).pollNext();

    // The second read is fair and touches the second input. Afterwards nothing is available.
    assertThat(processor.processInput()).isEqualTo(DataInputStatus.NOTHING_AVAILABLE);
    verifyThat(inputGate2).pollNext();
}

