package org.apache.flink.streaming.util.typeutils;

import org.apache.flink.api.common.ExecutionConfig;
import org.apache.flink.api.common.typeinfo.BasicArrayTypeInfo;
import org.apache.flink.api.common.typeinfo.BasicTypeInfo;
import org.apache.flink.api.common.typeinfo.PrimitiveArrayTypeInfo;
import org.apache.flink.api.common.typeinfo.TypeHint;
import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.common.typeutils.CompositeType.InvalidFieldReferenceException;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.typeutils.GenericTypeInfo;
import org.apache.flink.api.java.typeutils.PojoTypeInfo;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link FieldAccessorFactory#getAccessor(TypeInformation, String, ExecutionConfig)}. */
class FieldAccessorFactoryGetAccessorTests {

    private static final ExecutionConfig CONFIG = new ExecutionConfig();

    // ------------------------------------------------------------------------
    // Arrays
    // ------------------------------------------------------------------------

    @Test
    void testBasicArrayFieldAccessByIndex() {
        FieldAccessor<String[], String> accessor =
                FieldAccessorFactory.getAccessor(
                        BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO, "1", CONFIG);

        String[] array = {"zero", "one"};
        assertEquals("one", accessor.get(array));
        assertEquals(BasicTypeInfo.STRING_TYPE_INFO, accessor.getFieldType());

        String[] returned = accessor.set(array, "changed");
        assertSame(array, returned);
        assertArrayEquals(new String[] {"zero", "changed"}, array);
    }

    @Test
    void testPrimitiveArrayFieldAccessByIndex() {
        FieldAccessor<int[], Integer> accessor =
                FieldAccessorFactory.getAccessor(
                        PrimitiveArrayTypeInfo.INT_PRIMITIVE_ARRAY_TYPE_INFO, "2", CONFIG);

        int[] array = {1, 2, 3};
        assertEquals(3, accessor.get(array));
        assertEquals(BasicTypeInfo.INT_TYPE_INFO, accessor.getFieldType());

        int[] returned = accessor.set(array, 42);
        assertSame(array, returned);
        assertArrayEquals(new int[] {1, 2, 42}, array);
    }

    @Test
    void testArrayFieldExpressionMustBeAnInteger() {
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO,
                                        "notAnIndex",
                                        CONFIG));

        assertTrue(exception.getMessage().contains("integer index"));
    }

    @Test
    void testArrayIndexMustNotBeNegative() {
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        PrimitiveArrayTypeInfo.INT_PRIMITIVE_ARRAY_TYPE_INFO,
                                        "-1",
                                        CONFIG));

        assertTrue(exception.getMessage().contains("invalid index"));
    }

    // ------------------------------------------------------------------------
    // Basic types
    // ------------------------------------------------------------------------

    @Test
    void testBasicTypeSelectAllWildcard() {
        FieldAccessor<Integer, Integer> accessor =
                FieldAccessorFactory.getAccessor(BasicTypeInfo.INT_TYPE_INFO, "*", CONFIG);

        assertEquals(7, accessor.get(7));
        assertEquals(11, accessor.set(7, 11));
        assertEquals(BasicTypeInfo.INT_TYPE_INFO, accessor.getFieldType());
    }

    @Test
    void testBasicTypeSelectZero() {
        FieldAccessor<String, String> accessor =
                FieldAccessorFactory.getAccessor(BasicTypeInfo.STRING_TYPE_INFO, "0", CONFIG);

        assertEquals("value", accessor.get("value"));
        assertEquals("replacement", accessor.set("value", "replacement"));
        assertEquals(BasicTypeInfo.STRING_TYPE_INFO, accessor.getFieldType());
    }

    @Test
    void testBasicTypeRejectsNonZeroIndex() {
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        BasicTypeInfo.INT_TYPE_INFO, "1", CONFIG));

        assertTrue(exception.getMessage().contains("0th field"));
    }

    @Test
    void testBasicTypeRejectsNonNumericFieldExpression() {
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        BasicTypeInfo.STRING_TYPE_INFO, "name", CONFIG));

        assertTrue(exception.getMessage().contains("name"));
        assertTrue(exception.getMessage().contains("basic type"));
    }

    // ------------------------------------------------------------------------
    // POJOs
    // ------------------------------------------------------------------------

    @Test
    void testPojoFieldAccess() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        assertTrue(typeInfo instanceof PojoTypeInfo);

        FieldAccessor<TestPojo, Integer> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "id", CONFIG);
        TestPojo pojo = new TestPojo();
        pojo.id = 3;

        assertEquals(3, accessor.get(pojo));
        assertEquals(BasicTypeInfo.INT_TYPE_INFO, accessor.getFieldType());

        TestPojo returned = accessor.set(pojo, 19);
        assertSame(pojo, returned);
        assertEquals(19, pojo.id);
    }

    @Test
    void testNestedPojoFieldAccess() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        FieldAccessor<TestPojo, Long> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "nested.number", CONFIG);
        TestPojo pojo = new TestPojo();
        pojo.nested = new NestedPojo();
        pojo.nested.number = 123L;

        assertEquals(123L, accessor.get(pojo));
        assertEquals(BasicTypeInfo.LONG_TYPE_INFO, accessor.getFieldType());

        TestPojo returned = accessor.set(pojo, 456L);
        assertSame(pojo, returned);
        assertEquals(456L, pojo.nested.number);
    }

    @Test
    void testPojoUnknownField() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "missing", CONFIG));

        assertTrue(exception.getMessage().contains("Unable to find field"));
        assertTrue(exception.getMessage().contains("missing"));
    }

    @Test
    void testPojoUnknownNestedField() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        typeInfo, "nested.missing", CONFIG));

        assertTrue(exception.getMessage().contains("Unable to find field"));
        assertTrue(exception.getMessage().contains("missing"));
    }

    @Test
    void testPojoFieldWithTailOnBasicTypeIsRejected() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "name.tail", CONFIG));

        assertTrue(exception.getMessage().contains("tail"));
        assertTrue(exception.getMessage().contains("basic type"));
    }

    @Test
    void testPojoWildcardIsRejected() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "*", CONFIG));

        assertTrue(exception.getMessage().contains("wildcards"));
    }

    @Test
    void testPojoMalformedFieldExpressionIsRejected() {
        TypeInformation<TestPojo> typeInfo = TypeInformation.of(TestPojo.class);
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () ->
                                FieldAccessorFactory.getAccessor(
                                        typeInfo, "nested.invalid-field", CONFIG));

        assertTrue(exception.getMessage().contains("Invalid field expression"));
    }

    // ------------------------------------------------------------------------
    // Tuples
    // ------------------------------------------------------------------------

    @Test
    void testTupleFieldByFieldName() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        FieldAccessor<Tuple2<Integer, String>, Integer> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "f0", CONFIG);
        Tuple2<Integer, String> tuple = Tuple2.of(1, "one");

        assertEquals(1, accessor.get(tuple));
        assertEquals(BasicTypeInfo.INT_TYPE_INFO, accessor.getFieldType());

        Tuple2<Integer, String> returned = accessor.set(tuple, 5);
        assertSame(tuple, returned);
        assertEquals(5, tuple.f0);
    }

    @Test
    void testTupleFieldByNumericExpression() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        FieldAccessor<Tuple2<Integer, String>, String> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "1", CONFIG);
        Tuple2<Integer, String> tuple = Tuple2.of(1, "one");

        assertEquals("one", accessor.get(tuple));
        assertEquals(BasicTypeInfo.STRING_TYPE_INFO, accessor.getFieldType());

        Tuple2<Integer, String> returned = accessor.set(tuple, "five");
        assertSame(tuple, returned);
        assertEquals("five", tuple.f1);
    }

    @Test
    void testNestedTupleFieldByFieldNames() {
        TypeInformation<Tuple2<Integer, Tuple2<Long, String>>> typeInfo =
                TypeInformation.of(
                        new TypeHint<Tuple2<Integer, Tuple2<Long, String>>>() {});
        FieldAccessor<Tuple2<Integer, Tuple2<Long, String>>, Long> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "f1.f0", CONFIG);
        Tuple2<Integer, Tuple2<Long, String>> tuple =
                Tuple2.of(1, Tuple2.of(2L, "two"));

        assertEquals(2L, accessor.get(tuple));
        assertEquals(BasicTypeInfo.LONG_TYPE_INFO, accessor.getFieldType());

        Tuple2<Integer, Tuple2<Long, String>> returned = accessor.set(tuple, 20L);
        assertSame(tuple, returned);
        assertEquals(20L, tuple.f1.f0);
    }

    @Test
    void testNestedTupleFieldByNumericExpressions() {
        TypeInformation<Tuple2<Tuple2<Integer, String>, String>> typeInfo =
                TypeInformation.of(
                        new TypeHint<Tuple2<Tuple2<Integer, String>, String>>() {});
        FieldAccessor<Tuple2<Tuple2<Integer, String>, String>, String> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "0.1", CONFIG);
        Tuple2<Tuple2<Integer, String>, String> tuple =
                Tuple2.of(Tuple2.of(1, "inner"), "outer");

        assertEquals("inner", accessor.get(tuple));
        accessor.set(tuple, "changed");
        assertEquals("changed", tuple.f0.f1);
    }

    @Test
    void testTupleRejectsUnknownFieldName() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "notAField", CONFIG));

        assertTrue(exception.getMessage().contains("notAField"));
        assertTrue(exception.getMessage().contains("Only integer values are allowed"));
    }

    @Test
    void testTupleRejectsOutOfRangeIndex() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "2", CONFIG));

        assertTrue(exception.getMessage().contains("invalid index"));
    }

    @Test
    void testTupleRejectsNegativeIndex() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "-1", CONFIG));

        assertTrue(exception.getMessage().contains("invalid index"));
    }

    @Test
    void testTupleWildcardIsRejected() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "_", CONFIG));

        assertTrue(exception.getMessage().contains("wildcards"));
    }

    @Test
    void testTupleNestedFieldOnBasicTypeIsRejected() {
        TypeInformation<Tuple2<Integer, String>> typeInfo =
                TypeInformation.of(new TypeHint<Tuple2<Integer, String>>() {});
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "f1.length", CONFIG));

        assertTrue(exception.getMessage().contains("length"));
        assertTrue(exception.getMessage().contains("basic type"));
    }

    // ------------------------------------------------------------------------
    // Unsupported types
    // ------------------------------------------------------------------------

    @Test
    void testUnsupportedTypeIsRejected() {
        TypeInformation<UnsupportedType> typeInfo =
                new GenericTypeInfo<>(UnsupportedType.class);
        InvalidFieldReferenceException exception =
                assertThrows(
                        InvalidFieldReferenceException.class,
                        () -> FieldAccessorFactory.getAccessor(typeInfo, "value", CONFIG));

        assertTrue(exception.getMessage().contains("Cannot reference field"));
        assertTrue(exception.getMessage().contains("POJO types, tuples, and case classes"));
    }

    // ------------------------------------------------------------------------
    // Test data types
    // ------------------------------------------------------------------------

    /** A simple POJO with a directly accessible field and a nested POJO field. */
    public static class TestPojo {
        public int id;
        public String name;
        public NestedPojo nested;

        public TestPojo() {}
    }

    /** A nested POJO used to exercise recursive field access. */
    public static class NestedPojo {
        public long number;
        public String text;

        public NestedPojo() {}
    }

    /** A type that is intentionally not a POJO, tuple, array, or basic type. */
    public static class UnsupportedType {
        public int value;
    }
}
