/** Tests for {@link ScriptExecutor.ResultIterator#hasNext()}. */
class ScriptExecutorHasNextTests {

    private static ExecutorService executorService;
    private static SessionContext sessionContext;

    @BeforeAll
    static void beforeAll() {
        executorService = Executors.newSingleThreadExecutor();
        sessionContext =
                SessionContext.create(
                        new DefaultContext(new Configuration(), Collections.emptyList()),
                        SessionHandle.create(),
                        SessionEnvironment.newBuilder().build(),
                        executorService);
    }

    @AfterAll
    static void afterAll() throws Exception {
        sessionContext.close();
        executorService.shutdownNow();
    }

    // --------------------------------------------------------------------------------------------
    // Empty / blank scripts
    // --------------------------------------------------------------------------------------------

    @Test
    void testEmptyScriptHasNoMoreStatements() {
        ScriptExecutor.ResultIterator iterator = iterator("");

        assertThat(iterator.hasNext()).isFalse();
        assertThat(statementOf(iterator)).isEmpty();
        assertThat(positionOf(iterator)).isZero();
    }

    @Test
    void testWhitespaceOnlyScriptHasNoMoreStatements() {
        String script = "  \n\t \r\n  ";
        ScriptExecutor.ResultIterator iterator = iterator(script);

        assertThat(iterator.hasNext()).isFalse();
        assertThat(statementOf(iterator)).isEmpty();
        assertThat(positionOf(iterator)).isEqualTo(script.length());
    }

    @Test
    void testHasNextIsIdempotentWhenScriptIsExhausted() {
        ScriptExecutor.ResultIterator iterator = iterator("   ");

        assertThat(iterator.hasNext()).isFalse();
        assertThat(iterator.hasNext()).isFalse();
        assertThat(iterator.hasNext()).isFalse();
    }

    // --------------------------------------------------------------------------------------------
    // Single statements
    // --------------------------------------------------------------------------------------------

    @Test
    void testSingleStatementWithoutSemicolon() {
        ScriptExecutor.ResultIterator iterator = iterator("SELECT 1");

        assertThat(iterator.hasNext()).isTrue();
        assertThat(statementOf(iterator)).isEqualTo("SELECT 1");
        assertThat(positionOf(iterator)).isEqualTo("SELECT 1".length());

        assertThat(iterator.hasNext()).isFalse();
    }

    @Test
    void testSingleStatementWithTrailingSemicolon() {
        ScriptExecutor.ResultIterator iterator = iterator("SELECT 1;");

        assertThat(iterator.hasNext()).isTrue();
