    @Test
    void testSingleStatementWithoutSemicolon() {
        ScriptExecutor.ResultIterator iterator = iterator("SELECT 1");

        assertThat(iterator.hasNext()).isTrue();
        assertThat(statementOf(iterator)).isEqualTo("SELECT 1");
        assertThat(positionOf(iterator)).isEqualTo("SELECT 1".length());

        assertThat(iterator.hasNext()).isFalse();
    }

    @Test
    void testSingleStatementWithTrailingSemicolon() {
        ScriptExecutor.ResultIterator iterator = iterator("SELECT 1;");

        assertThat(iterator.hasNext()).isTrue();
        // the terminating semicolon belongs to the statement

    // the terminating semicolon belongs to the statement
    assertThat(statementOf(iterator)).isEqualTo("SELECT 1;");
    assertThat(positionOf(iterator)).isEqualTo("SELECT 1;".length());

    // the trailing semicolon must not produce an additional empty statement
    assertThat(iterator.hasNext()).isFalse();
}

