// Errors
// --------------------------------------------------------------------------------------------

@Test
void testIncompleteLastStatementThrowsEOFException() {
    ScriptExecutor.ResultIterator iterator = iterator("SELECT 1;\nSELECT");

    assertThat(iterator.hasNext()).isTrue();
    assertThat(statementOf(iterator)).isEqualTo("SELECT 1;\n");

    assertThatThrownBy(iterator::hasNext).isInstanceOf(SqlParserEOFException.class);
}

@Test
void testIncompleteLastStatementIsKeptWhenTheEOFExceptionIsRaised() {
    String script = "SELECT * FROM";
    ScriptExecutor.ResultIterator iterator = iterator(script);

    assertThatThrownBy(iterator::hasNext).isInstanceOf(SqlParserEOFException.class);

    // the failing statement is kept and the position points behind the consumed script
    assertThat(statementOf(iterator)).isEqualTo(script);
    assertThat(positionOf(iterator)).isEqualTo(script.length());

    // the script is consumed, so further calls do not report another statement
    assertThat(iterator.hasNext()).isFalse();
}

@Test
void testInvalidLastStatementWithoutSemicolonThrows() {
    ScriptExecutor.ResultIterator iterator = iterator("SELECT 1;\nSELECT FROM");

    assertThat(iterator.hasNext()).isTrue();
    assertThat(statementOf(iterator)).isEqualTo("SELECT 1;\n");

    // unlike the statements terminated by a semicolon, the error of the last statement is not
    // stored in the iterator but propagated to the caller
    assertThatThrownBy(iterator::hasNext).isInstanceOf(SqlParserException.class);
}

@Test
void testParseErrorIsReportedByTheNextResultAndIterationContinues() {
    ScriptExecutor.ResultIterator iterator = iterator("SELECT 1;SELECT FROM;SELECT 2;");

    assertThat(iterator.hasNext()).isTrue();
    assertThat(statementOf(iterator)).isEqualTo("SELECT 1;");

    // the malformed statement does not abort the iteration, the error is attached to the
    // statement instead
    assertThat(iterator.hasNext()).isTrue();
    assertThat(statementOf(iterator)).isEqualTo("SELECT FROM;");
    assertThat(throwableOf(iterator)).isNotNull();

    ScriptExecutor.Result errorResult = iterator.next();
    assertThat(errorResult.statement).isEqualTo("SELECT FROM;");
    assertThat(errorResult.error).isNotNull();
    assertThat(errorResult.fetcher).isNull();
    assertThat(throwableOf(iterator)).isNull();

    // the iteration continues with the remaining statement
    assertThat(iterator.hasNext()).isTrue();
    assertThat(statementOf(iterator)).isEqualTo("SELECT 2;");

    assertThat(iterator.hasNext()).isFalse();
}

