private static ScriptExecutor.ResultIterator iterator(String script) {
    return ScriptExecutor.of(sessionContext).new ResultIterator(script);
}

private static String statementOf(ScriptExecutor.ResultIterator iterator) {
    return (String) readField(iterator, "statement");
}

private static Throwable throwableOf(ScriptExecutor.ResultIterator iterator) {
    return (Throwable) readField(iterator, "throwable");
}

