        assertThat(firstBatch.getResultType()).isEqualTo(ResultSet.ResultType.PAYLOAD);
        assertThat(firstBatch.getNextToken()).isEqualTo(1L);
        assertThat(firstBatch.getData()).containsExactly(first, second);

        ResultSet secondBatch = fetcher.fetchResults(1L, 2);
        assertThat(secondBatch.getResultType()).isEqualTo(ResultSet.ResultType.PAYLOAD);
        assertThat(secondBatch.getNextToken()).isEqualTo(2L);
        assertThat(secondBatch.getData()).containsExactly(third);

        ResultSet eos = fetcher.fetchResults(2L, 2);
        assertThat(eos.getResultType()).isEqualTo(ResultSet.ResultType.EOS);
        assertThat(eos.getNextToken()).isNull();
        assertThat(eos.getData()).isEmpty();
        assertThat(eos.getResultSchema()).isEqualTo(SCHEMA);

        // Once the end of the stream is reached, the same token keeps returning EOS.
        ResultSet eosAgain = fetcher.fetchResults(2L, 2);
        assertThat(eosAgain.getResultType()).isEqualTo(ResultSet.ResultType.EOS);
        assertThat(eosAgain.getNextToken()).isNull();
