        p("null/varchar-nullable", rb.makeLiteral(null, tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.VARCHAR, 5), true), true, false));

        // nullable + allowCast false
        RelDataType nullableInt = tf.createTypeWithNullability(tf.createSqlType(SqlTypeName.INTEGER), true);
        p("nullableInt allowCast=false", rb.makeLiteral(5, nullableInt, false, false));
        p("nullableInt allowCast=true", rb.makeLiteral(5, nullableInt, true, false));

        // CHAR
        RelDataType char5 = tf.createSqlType(SqlTypeName.CHAR, 5);
        p("char5 trim=false 'foo'", rb.makeLiteral(new NlsString("foo", null, null), char5, false, false));
        p("char5 trim=true 'foo '", rb.makeLiteral(new NlsString("foo ", null, null), char5, false, true));
        p("char5 trim=false 'foo '", rb.makeLiteral(new NlsString("foo ", null, null), char5, false, false));
        p("char3 trim=true 'abcdef'", rb.makeLiteral(new NlsString("abcdef", null, null), tf.createSqlType(SqlTypeName.CHAR, 3), false, true));
        p("char5 String value", rb.makeLiteral("ab", char5, false, false));

        // VARCHAR
        RelDataType varchar5 = tf.createSqlType(SqlTypeName.VARCHAR, 5);
