        p("varchar5 allowCast=true", rb.makeLiteral(new NlsString("abc", null, null), varchar5, true, false));
        p("varchar5 nullable allowCast=true", rb.makeLiteral(new NlsString("abc", null, null), tf.createTypeWithNullability(varchar5, true), true, false));

