        p("tsLtz", rb.makeLiteral(new TimestampString("2024-01-02 03:04:05"), tf.createSqlType(SqlTypeName.TIMESTAMP_WITH_LOCAL_TIME_ZONE, 0), false, false));
        p("timeLtz", rb.makeLiteral(new TimeString("12:34:56"), tf.createSqlType(SqlTypeName.TIME_WITH_LOCAL_TIME_ZONE, 0), false, false));

        // interval
        SqlIntervalQualifier dq = new SqlIntervalQualifier(TimeUnit.DAY, null, SqlParserPos.ZERO);
        RelDataType intervalDay = tf.createSqlIntervalType(dq);
        p("interval day", rb.makeLiteral(new BigDecimal(5), intervalDay, false, false));

        // MAP
        RelDataType mapType = tf.createMapType(tf.createSqlType(SqlTypeName.VARCHAR, 10), tf.createSqlType(SqlTypeName.INTEGER));
        Map<Object,Object> map = new LinkedHashMap<>();
        map.put("a", 1);
        map.put("b", 2);
        p("map", rb.makeLiteral(map, mapType, false, false));

        // ARRAY
        RelDataType arrType = tf.createArrayType(tf.createSqlType(SqlTypeName.INTEGER), -1);
        p("array", rb.makeLiteral(Arrays.asList(1,2,3), arrType, false, false));

