import org.apache.calcite.rex.*;
import org.apache.calcite.rel.type.*;
import org.apache.calcite.sql.type.*;
import org.apache.calcite.sql.SqlIntervalQualifier;
import org.apache.calcite.sql.parser.SqlParserPos;
import org.apache.calcite.avatica.util.ByteString;
import org.apache.calcite.avatica.util.TimeUnit;
import org.apache.calcite.util.*;
import java.math.BigDecimal;
import java.util.*;

public class Explore4 {
    static RexBuilder rb;
    static RelDataTypeFactory tf;
    static void p(String label, RexNode n) {
        String extra = "";
        if (n instanceof RexLiteral) {
            RexLiteral l = (RexLiteral) n;
            extra = " valueClass=" + (l.getValue() == null ? "null" : l.getValue().getClass().getName())
                  + " value=" + l.getValue() + " typeName=" + l.getTypeName();
        }
        System.out.println(label + " -> " + n.getClass().getSimpleName() + " type=" + n.getType()
            + " kind=" + n.getKind() + extra
            + (n instanceof RexCall ? " op=" + ((RexCall) n).getOperator().getName() + " operands=" + ((RexCall) n).getOperands().size() : ""));
    }
    public static void main(String[] a) {
        tf = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        rb = new RexBuilder(tf);

        RexLiteral dateLit = (RexLiteral) rb.makeLiteral(new DateString("2024-01-02"), tf.createSqlType(SqlTypeName.DATE), false, false);
        p("date", dateLit);
        System.out.println("  getValueAs(DateString)=" + dateLit.getValueAs(DateString.class));
        RexLiteral timeLit = (RexLiteral) rb.makeLiteral(new TimeString("12:34:56"), tf.createSqlType(SqlTypeName.TIME, 0), false, false);
        p("time", timeLit);
        System.out.println("  getValueAs(TimeString)=" + timeLit.getValueAs(TimeString.class));
        RexLiteral tsLit = (RexLiteral) rb.makeLiteral(new TimestampString("2024-01-02 03:04:05"), tf.createSqlType(SqlTypeName.TIMESTAMP, 3), false, false);
        p("ts", tsLit);
        System.out.println("  getValueAs(TimestampString)=" + tsLit.getValueAs(TimestampString.class));
        p("timeTz", rb.makeLiteral(new TimeWithTimeZoneString("12:34:56 UTC"), tf.createSqlType(SqlTypeName.TIME_TZ, 0), false, false));
        p("tsTz", rb.makeLiteral(new TimestampWithTimeZoneString("2024-01-02 03:04:05 UTC"), tf.createSqlType(SqlTypeName.TIMESTAMP_TZ, 0), false, false));
        p("date from Integer 120", rb.makeLiteral(120, tf.createSqlType(SqlTypeName.DATE), false, false));
        p("time from Integer", rb.makeLiteral(45296000, tf.createSqlType(SqlTypeName.TIME, 0), false, false));
        p("ts from Long 0", rb.makeLiteral(0L, tf.createSqlType(SqlTypeName.TIMESTAMP, 0), false, false));

        SqlIntervalQualifier dq = new SqlIntervalQualifier(TimeUnit.DAY, null, SqlParserPos.ZERO);
        p("interval day 5", rb.makeLiteral(new BigDecimal(5), tf.createSqlIntervalType(dq), false, false));
        SqlIntervalQualifier ym = new SqlIntervalQualifier(TimeUnit.YEAR, TimeUnit.MONTH, SqlParserPos.ZERO);
        p("interval year-month 13", rb.makeLiteral(new BigDecimal("13"), tf.createSqlIntervalType(ym), false, false));

        RelDataType mapType = tf.createMapType(tf.createSqlType(SqlTypeName.VARCHAR, 10), tf.createSqlType(SqlTypeName.INTEGER));
        Map<Object,Object> map = new LinkedHashMap<>(); map.put("a", 1); map.put("b", 2);
        p("map", rb.makeLiteral(map, mapType, false, false));
        p("empty map", rb.makeLiteral(new LinkedHashMap<>(), mapType, false, false));

        RelDataType arrType = tf.createArrayType(tf.createSqlType(SqlTypeName.INTEGER), -1);
        p("array", rb.makeLiteral(Arrays.asList(1,2,3), arrType, false, false));

        RelDataType msType = tf.createMultisetType(tf.createSqlType(SqlTypeName.INTEGER), -1);
        p("multiset noCast", rb.makeLiteral(Arrays.asList(1,2), msType, false, false));
        p("multiset cast", rb.makeLiteral(Arrays.asList(1,2), msType, true, false));

        RelDataType rowType = tf.createStructType(Arrays.asList(tf.createSqlType(SqlTypeName.INTEGER), tf.createSqlType(SqlTypeName.VARCHAR, 3)), Arrays.asList("a","b"));
        p("row", rb.makeLiteral(Arrays.asList(1, new NlsString("xy", null, null)), rowType, false, false));

        org.locationtech.jts.geom.Geometry g = new org.locationtech.jts.geom.GeometryFactory().createPoint(new org.locationtech.jts.geom.Coordinate(1,2));
        p("geometry", rb.makeLiteral(g, tf.createSqlType(SqlTypeName.GEOMETRY), false, false));

        p("any string", rb.makeLiteral("abc", tf.createSqlType(SqlTypeName.ANY), false, false));
        p("any int", rb.makeLiteral(7, tf.createSqlType(SqlTypeName.ANY), false, false));

        for (SqlTypeName tn : new SqlTypeName[]{SqlTypeName.NULL, SqlTypeName.CURSOR, SqlTypeName.COLUMN_LIST, SqlTypeName.OTHER, SqlTypeName.MEASURE, SqlTypeName.VARIANT, SqlTypeName.UUID, SqlTypeName.SYMBOL}) {
            try {
                RelDataType tt = tf.createSqlType(tn);
                Object v = tn == SqlTypeName.COLUMN_LIST ? Arrays.asList("a") : (tn == SqlTypeName.UUID ? java.util.UUID.randomUUID() : "x");
                RexNode n = rb.makeLiteral(v, tt, false, false);
                System.out.println("type " + tn + " -> " + n.getClass().getSimpleName() + " type=" + n.getType() + " kind=" + n.getKind());
            } catch (Throwable e) { System.out.println("type " + tn + " threw " + e.getClass().getName() + ": " + e.getMessage()); }
        }
    }
}
