import org.apache.calcite.rex.*;
import org.apache.calcite.rel.type.*;
import org.apache.calcite.sql.type.*;
import org.apache.calcite.avatica.util.ByteString;
import org.apache.calcite.avatica.util.TimeUnit;
import org.apache.calcite.util.*;
import java.math.BigDecimal;
import java.util.*;

public class Explore5 {
    public static void main(String[] a) {
        RelDataTypeFactory tf = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        RexBuilder rb = new RexBuilder(tf);

        RexLiteral t = (RexLiteral) rb.makeLiteral(new TimeString("12:34:56.789"), tf.createSqlType(SqlTypeName.TIME, 2), false, false);
        System.out.println("time round -> " + t.getType() + " " + t.getValueAs(TimeString.class));
        RexLiteral ts = (RexLiteral) rb.makeLiteral(new TimestampString("2024-01-02 03:04:05.6789"), tf.createSqlType(SqlTypeName.TIMESTAMP, 3), false, false);
        System.out.println("ts round -> " + ts.getType() + " " + ts.getValueAs(TimestampString.class));
        RexLiteral tt = (RexLiteral) rb.makeLiteral(new TimeWithTimeZoneString("12:34:56.789 UTC"), tf.createSqlType(SqlTypeName.TIME_TZ, 1), false, false);
        System.out.println("timeTz round -> " + tt.getType() + " " + tt.getValue());
        RexLiteral tst = (RexLiteral) rb.makeLiteral(new TimestampWithTimeZoneString("2024-01-02 03:04:05.6789 UTC"), tf.createSqlType(SqlTypeName.TIMESTAMP_TZ, 2), false, false);
        System.out.println("tsTz round -> " + tst.getType() + " " + tst.getValue());
        RexLiteral ltz = (RexLiteral) rb.makeLiteral(new TimestampString("2024-01-02 03:04:05.678"), tf.createSqlType(SqlTypeName.TIMESTAMP_WITH_LOCAL_TIME_ZONE, 1), false, false);
        System.out.println("tsLtz -> " + ltz.getType() + " " + ltz.getValueAs(TimestampString.class));

        // symbol
        RexLiteral flag = (RexLiteral) rb.makeFlag(TimeUnit.DAY);
        System.out.println("symbol -> " + flag.getType() + " typeName=" + flag.getTypeName() + " value=" + flag.getValue() + " kind=" + flag.getKind());

        // array operands
        RelDataType arrType = tf.createArrayType(tf.createSqlType(SqlTypeName.INTEGER), -1);
        RexNode arr = rb.makeLiteral(Arrays.asList(1, 2, 3), arrType, false, false);
        RexCall arrCall = (RexCall) arr;
        System.out.println("array call kind=" + arrCall.getKind() + " op=" + arrCall.getOperator().getName() + " type=" + arrCall.getType());
        for (RexNode op : arrCall.getOperands()) {
            System.out.println("   operand " + op.getKind() + " " + op.getType() + " value=" + ((RexLiteral) op).getValue());
        }

        // multiset
        RelDataType msType = tf.createMultisetType(tf.createSqlType(SqlTypeName.INTEGER), -1);
        RexLiteral ms = (RexLiteral) rb.makeLiteral(Arrays.asList(new BigDecimal("1"), new BigDecimal("2")), msType, false, false);
        System.out.println("multiset literal type=" + ms.getType() + " typeName=" + ms.getTypeName() + " value=" + ms.getValue() + " class=" + ms.getValue().getClass());
        RexCall ms2 = (RexCall) rb.makeLiteral(Arrays.asList(1, 2), msType, true, false);
        System.out.println("multiset call kind=" + ms2.getKind() + " op=" + ms2.getOperator().getName());

        // row
        RelDataType rowType = tf.createStructType(Arrays.asList(tf.createSqlType(SqlTypeName.INTEGER), tf.createSqlType(SqlTypeName.VARCHAR, 3)), Arrays.asList("a", "b"));
        RexLiteral row = (RexLiteral) rb.makeLiteral(Arrays.asList(1, new NlsString("xy", null, null)), rowType, false, false);
        System.out.println("row type=" + row.getType() + " typeName=" + row.getTypeName() + " value=" + row.getValue() + " class=" + row.getValue().getClass());

        // byte string literal pad
        RexLiteral bin = (RexLiteral) rb.makeLiteral(new ByteString(new byte[]{1, 2}), tf.createSqlType(SqlTypeName.BINARY, 4), false, false);
        System.out.println("binary value=" + bin.getValue() + " type=" + bin.getType() + " bytes=" + Arrays.toString(((ByteString) bin.getValue()).getBytes()));

        // char value assertions
        RexLiteral ch = (RexLiteral) rb.makeLiteral(new NlsString("foo", null, null), tf.createSqlType(SqlTypeName.CHAR, 5), false, false);
        NlsString ns = ch.getValueAs(NlsString.class);
        System.out.println("char value=[" + ns.getValue() + "] charset=" + ns.getCharsetName() + " coll=" + ns.getCollation() + " type=" + ch.getType() + " prec=" + ch.getType().getPrecision());

        // varchar no cast
        RexLiteral vc = (RexLiteral) rb.makeLiteral(new NlsString("abc", null, null), tf.createSqlType(SqlTypeName.VARCHAR, 5), false, false);
        System.out.println("varchar-nocast type=" + vc.getType() + " typeName=" + vc.getTypeName());
        RexNode vc2 = rb.makeLiteral(new NlsString("abc", null, null), tf.createSqlType(SqlTypeName.VARCHAR, 5), true, false);
        System.out.println("varchar-cast class=" + vc2.getClass().getSimpleName() + " kind=" + vc2.getKind() + " type=" + vc2.getType()
            + " operands=" + ((RexCall) vc2).getOperands());

        // map details
        RelDataType mapType = tf.createMapType(tf.createSqlType(SqlTypeName.VARCHAR, 10), tf.createSqlType(SqlTypeName.INTEGER));
