/**
 * Tests for {@link RexBuilder#makeLiteral(Object, RelDataType, boolean, boolean)}.
 *
 * <p>The literals returned by the method are checked for their observable contract: the Java
 * class of the returned expression, its {@link SqlTypeName}, its nullability, and the value it
 * represents.
 */
class RexBuilderMakeLiteralTests {

    private RelDataTypeFactory typeFactory;
    private RexBuilder rexBuilder;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        rexBuilder = new RexBuilder(typeFactory);
    }

    // ~ helpers --------------------------------------------------------------

    private RelDataType sqlType(SqlTypeName typeName) {
        return typeFactory.createSqlType(typeName);
    }

    private RelDataType nullable(RelDataType type) {
        return typeFactory.createTypeWithNullability(type, true);
    }

    private static BigDecimal decimalValue(RexNode node) {
        return assertInstanceOf(RexLiteral.class, node).getValueAs(BigDecimal.class);
    }

    private static NlsString nlsStringValue(RexNode node) {
        return assertInstanceOf(RexLiteral.class, node).getValueAs(NlsString.class);
    }

    // ~ NULL handling --------------------------------------------------------

    @Test
    void testNullValueProducesTypedNullLiteral() {
        RexNode node = rexBuilder.makeLiteral(null, sqlType(SqlTypeName.INTEGER), false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertTrue(literal.isNull());
        assertNull(literal.getValue());
        assertEquals(SqlTypeName.NULL, literal.getTypeName());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertTrue(literal.getType().isNullable());
    }

    @Test
    void testNullValueKeepsParameterTypeRegardlessOfCastPermission() {
        RelDataType varchar5 = typeFactory.createSqlType(SqlTypeName.VARCHAR, 5);

        RexNode withoutCast = rexBuilder.makeLiteral(null, varchar5, false, false);
        RexNode withCast = rexBuilder.makeLiteral(null, nullable(varchar5), true, false);

        for (RexNode node : Arrays.asList(withoutCast, withCast)) {
            RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
            assertTrue(literal.isNull());
            assertEquals(SqlTypeName.VARCHAR, literal.getType().getSqlTypeName());
            assertEquals(5, literal.getType().getPrecision());
            assertTrue(literal.getType().isNullable());
        }
    }

    // ~ nullability handling -------------------------------------------------

    @Test
    void testNullableTypeIsMadeNotNullableWhenCastIsNotAllowed() {
        RelDataType nullableInteger = nullable(sqlType(SqlTypeName.INTEGER));

        RexNode node = rexBuilder.makeLiteral(5, nullableInteger, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertFalse(literal.getType().isNullable());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertEquals(0, new BigDecimal(5).compareTo(decimalValue(literal)));
    }

    @Test
    void testNullableTypeIsWrappedInCastWhenCastIsAllowed() {
        RelDataType nullableInteger = nullable(sqlType(SqlTypeName.INTEGER));

        RexNode node = rexBuilder.makeLiteral(5, nullableInteger, true, false);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.CAST, call.getKind());
        assertEquals(SqlTypeName.INTEGER, call.getType().getSqlTypeName());
        assertTrue(call.getType().isNullable());

        List<RexNode> operands = call.getOperands();
        assertEquals(1, operands.size());
        RexLiteral operand = assertInstanceOf(RexLiteral.class, operands.get(0));
        assertFalse(operand.getType().isNullable());
        assertEquals(0, new BigDecimal(5).compareTo(operand.getValueAs(BigDecimal.class)));
    }

    @Test
    void testNotNullableTypeIsNeverWrappedInCast() {
        RexNode node =
                rexBuilder.makeLiteral(7, sqlType(SqlTypeName.BIGINT), true, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals(SqlTypeName.BIGINT, literal.getType().getSqlTypeName());
        assertFalse(literal.getType().isNullable());
    }

    // ~ CHAR / VARCHAR -------------------------------------------------------

    @Test
    void testCharLiteralWithoutTrimIsRightPaddedToTypePrecision() {
        RelDataType char5 = typeFactory.createSqlType(SqlTypeName.CHAR, 5);

        RexNode node = rexBuilder.makeLiteral(new NlsString("foo", null, null), char5, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertEquals("foo  ", nlsStringValue(literal).getValue());
    }

    @Test
    void testCharLiteralWithTrimDropsRedundantTrailingBlanks() {
        RelDataType char5 = typeFactory.createSqlType(SqlTypeName.CHAR, 5);

        RexNode trimmed =
                rexBuilder.makeLiteral(new NlsString("foo", null, null), char5, false, true);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, trimmed);
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
        assertEquals("foo", nlsStringValue(literal).getValue());
        assertEquals(3, literal.getType().getPrecision());
    }

    @Test
    void testCharLiteralWithTrimCutsValueDownToTypePrecision() {
        RelDataType char2 = typeFactory.createSqlType(SqlTypeName.CHAR, 2);

        RexNode node = rexBuilder.makeLiteral(new NlsString("ab   ", null, null), char2, false, true);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals("ab", nlsStringValue(literal).getValue());
        assertEquals(2, literal.getType().getPrecision());
    }

    @Test
    void testCharLiteralIsNotTruncatedWhenValueExceedsPrecision() {
        RelDataType char3 = typeFactory.createSqlType(SqlTypeName.CHAR, 3);

        RexNode node =
                rexBuilder.makeLiteral(new NlsString("abcdef", null, null), char3, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals("abcdef", nlsStringValue(literal).getValue());
        assertEquals(6, literal.getType().getPrecision());
    }

    @Test
    void testPlainStringValueIsConvertedToNlsStringForCharType() {
        RelDataType char5 = typeFactory.createSqlType(SqlTypeName.CHAR, 5);

        RexNode node = rexBuilder.makeLiteral("ab", char5, false, false);

        NlsString value = nlsStringValue(node);
        assertEquals(SqlTypeName.CHAR, node.getType().getSqlTypeName());
        assertEquals("ab   ", value.getValue());
        assertNotNull(value.getCharsetName());
        assertEquals(char5.getCharset().name(), value.getCharsetName());
        assertEquals(char5.getCollation(), value.getCollation());
    }

    @Test
    void testVarcharLiteralWithoutCastUsesCharLiteral() {
        RelDataType varchar5 = typeFactory.createSqlType(SqlTypeName.VARCHAR, 5);

        RexNode node = rexBuilder.makeLiteral(new NlsString("abc", null, null), varchar5, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals("abc", nlsStringValue(literal).getValue());
        // without cast permission the result is a plain literal and may not have the exact type
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
    }

    @Test
    void testVarcharLiteralWithCastUsesRequestedType() {
        RelDataType varchar5 = typeFactory.createSqlType(SqlTypeName.VARCHAR, 5);

        RexNode node = rexBuilder.makeLiteral(new NlsString("abc", null, null), varchar5, true, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals("abc", nlsStringValue(literal).getValue());
        assertEquals(SqlTypeName.VARCHAR, literal.getType().getSqlTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertFalse(literal.getType().isNullable());
    }

    @Test
    void testNullableVarcharWithCastProducesCastCall() {
        RelDataType varchar5 = nullable(typeFactory.createSqlType(SqlTypeName.VARCHAR, 5));

        RexNode node = rexBuilder.makeLiteral(new NlsString("abc", null, null), varchar5, true, false);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.CAST, call.getKind());
        assertEquals(SqlTypeName.VARCHAR, call.getType().getSqlTypeName());
        assertTrue(call.getType().isNullable());
        assertEquals(1, call.getOperands().size());
        assertEquals("abc", nlsStringValue(call.getOperands().get(0)).getValue());
    }

    // ~ BINARY / VARBINARY ---------------------------------------------------

    @Test
    void testBinaryLiteralIsPaddedWithZeroBytes() {
        RelDataType binary4 = typeFactory.createSqlType(SqlTypeName.BINARY, 4);

        RexNode node =
                rexBuilder.makeLiteral(new ByteString(new byte[] {1, 2}), binary4, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals(SqlTypeName.BINARY, literal.getTypeName());
        assertEquals(4, literal.getType().getPrecision());
        assertEquals(
                Arrays.toString(new byte[] {1, 2, 0, 0}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
    }

    @Test
    void testBinaryLiteralIsNotTruncatedWhenValueExceedsPrecision() {
        RelDataType binary2 = typeFactory.createSqlType(SqlTypeName.BINARY, 2);

        RexNode node =
                rexBuilder.makeLiteral(new ByteString(new byte[] {1, 2, 3}), binary2, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals(
                Arrays.toString(new byte[] {1, 2, 3}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
        assertEquals(3, literal.getType().getPrecision());
    }

    @Test
    void testVarbinaryLiteralWithoutCastKeepsValue() {
        RelDataType varbinary4 = typeFactory.createSqlType(SqlTypeName.VARBINARY, 4);

        RexNode node =
                rexBuilder.makeLiteral(new ByteString(new byte[] {1, 2}), varbinary4, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals(Arrays.toString(new byte[] {1, 2}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
        assertEquals(SqlTypeName.BINARY, literal.getTypeName());
    }

    @Test
    void testVarbinaryLiteralWithCastUsesRequestedType() {
        RelDataType varbinary4 = typeFactory.createSqlType(SqlTypeName.VARBINARY, 4);

        RexNode node =
                rexBuilder.makeLiteral(new ByteString(new byte[] {1, 2}), varbinary4, true, false);

        assertEquals(SqlTypeName.VARBINARY, node.getType().getSqlTypeName());
        assertEquals(Arrays.toString(new byte[] {1, 2}),
                Arrays.toString(((ByteString) assertInstanceOf(RexLiteral.class, node).getValue()).getBytes()));
    }

    // ~ exact numerics -------------------------------------------------------

    @Test
    void testIntegralTypesArePreservedInNumericLiterals() {
        for (SqlTypeName typeName :
                new SqlTypeName[] {
                    SqlTypeName.TINYINT,
                    SqlTypeName.SMALLINT,
                    SqlTypeName.INTEGER,
                    SqlTypeName.BIGINT
                }) {
            RexNode node = rexBuilder.makeLiteral(3, sqlType(typeName), false, false);

            RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
            assertEquals(typeName, literal.getType().getSqlTypeName(), "type of " + typeName);
            assertEquals(SqlTypeName.DECIMAL, literal.getTypeName());
            assertFalse(literal.getType().isNullable());
            assertEquals(
                    0,
                    new BigDecimal(3).compareTo(literal.getValueAs(BigDecimal.class)),
                    "value of " + typeName);
        }
    }

    @Test
    void testNumericValuesOfVariousJavaTypesAreCleanedToBigDecimal() {
        assertEquals(0, new BigDecimal(3).compareTo(decimalValue(
                rexBuilder.makeLiteral(3, sqlType(SqlTypeName.INTEGER), false, false))));
        assertEquals(0, new BigDecimal(4).compareTo(decimalValue(
                rexBuilder.makeLiteral(4L, sqlType(SqlTypeName.BIGINT), false, false))));
        assertEquals(0, new BigDecimal(5).compareTo(decimalValue(
                rexBuilder.makeLiteral(new BigDecimal("5"), sqlType(SqlTypeName.SMALLINT), false, false))));
    }

    @Test
    void testDecimalLiteralKeepsDeclaredPrecisionAndScale() {
        RelDataType decimalType = typeFactory.createSqlType(SqlTypeName.DECIMAL, 5, 2);

        RexNode node = rexBuilder.makeLiteral(new BigDecimal("1.23"), decimalType, false, false);

        RexLiteral literal = assertInstanceOf(RexLiteral.class, node);
        assertEquals(SqlTypeName.DECIMAL, literal.getType().getSqlTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertEquals(2, literal.getType().getScale());
        assertEquals(new BigDecimal("1.23"), literal.getValueAs(BigDecimal.class));
    }

    @Test
    void testDecimalValueThatDoesNotFitThrowsIllegalArgumentException() {
        RelDataType decimalType = typeFactory.createSqlType(SqlTypeName.DECIMAL, 5, 2);

