package org.apache.calcite.rex;

import com.google.common.collect.ImmutableRangeSet;
import com.google.common.collect.Range;
import org.apache.calcite.avatica.util.ByteString;
import org.apache.calcite.avatica.util.TimeUnit;
import org.apache.calcite.rel.type.RelDataType;
import org.apache.calcite.rel.type.RelDataTypeFactory;
import org.apache.calcite.rel.type.RelDataTypeSystem;
import org.apache.calcite.sql.SqlIntervalQualifier;
import org.apache.calcite.sql.SqlKind;
import org.apache.calcite.sql.parser.SqlParserPos;
import org.apache.calcite.sql.type.SqlTypeFactoryImpl;
import org.apache.calcite.sql.type.SqlTypeName;
import org.apache.calcite.util.DateString;
import org.apache.calcite.util.NlsString;
import org.apache.calcite.util.Sarg;
import org.apache.calcite.util.TimeString;
import org.apache.calcite.util.TimeWithTimeZoneString;
import org.apache.calcite.util.TimestampString;
import org.apache.calcite.util.TimestampWithTimeZoneString;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.locationtech.jts.geom.Coordinate;
import org.locationtech.jts.geom.Geometry;
import org.locationtech.jts.geom.GeometryFactory;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TimeZone;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link RexBuilder#makeLiteral(Object, RelDataType, boolean, boolean)}.
 *
 * <p>The tests verify the observable contract of the method: the kind of expression that is
 * created, the {@link SqlTypeName} of the result, its nullability and the value that it carries.
 */
class RexBuilderMakeLiteralTests {

    private RelDataTypeFactory typeFactory;
    private RexBuilder rexBuilder;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        rexBuilder = new RexBuilder(typeFactory);
    }

    // ~ helpers --------------------------------------------------------------

    /** Creates a literal, disallowing casts and trimming. */
    private RexNode literal(Object value, RelDataType type) {
        return rexBuilder.makeLiteral(value, type, false, false);
    }

    /** Creates a literal, allowing the builder to wrap the value into a cast if necessary. */
    private RexNode castableLiteral(Object value, RelDataType type) {
        return rexBuilder.makeLiteral(value, type, true, false);
    }

    /** Creates a literal, asking the builder to trim redundant trailing blanks. */
    private RexNode trimmedLiteral(Object value, RelDataType type) {
        return rexBuilder.makeLiteral(value, type, false, true);
    }

    private RelDataType sqlType(SqlTypeName typeName) {
        return typeFactory.createSqlType(typeName);
    }

    private RelDataType sqlType(SqlTypeName typeName, int precision) {
        return typeFactory.createSqlType(typeName, precision);
    }

    private RelDataType nullable(RelDataType type) {
        return typeFactory.createTypeWithNullability(type, true);
    }

    private static NlsString nls(String value) {
        return new NlsString(value, null, null);
    }

    private static RexLiteral asLiteral(RexNode node) {
        return assertInstanceOf(RexLiteral.class, node);
    }

    private static BigDecimal decimalOf(RexNode node) {
        return asLiteral(node).getValueAs(BigDecimal.class);
    }

    private static String stringOf(RexNode node) {
        return asLiteral(node).getValueAs(NlsString.class).getValue();
    }

    // ~ null handling --------------------------------------------------------

    @Test
    void testNullValueProducesTypedNullLiteral() {
        RexNode node = literal(null, sqlType(SqlTypeName.INTEGER));

        RexLiteral literal = asLiteral(node);
        assertTrue(literal.isNull());
        assertNull(literal.getValue());
        assertEquals(SqlTypeName.NULL, literal.getTypeName());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertTrue(literal.getType().isNullable());
    }

    @Test
    void testNullValueKeepsParameterTypeRegardlessOfCastPermission() {
        RelDataType varchar5 = sqlType(SqlTypeName.VARCHAR, 5);

        RexNode withoutCast = literal(null, varchar5);
        RexNode withCast = castableLiteral(null, nullable(varchar5));

        for (RexNode node : Arrays.asList(withoutCast, withCast)) {
            RexLiteral literal = asLiteral(node);
            assertTrue(literal.isNull());
            assertEquals(SqlTypeName.VARCHAR, literal.getType().getSqlTypeName());
            assertEquals(5, literal.getType().getPrecision());
            assertTrue(literal.getType().isNullable());
        }
    }

    // ~ nullability handling -------------------------------------------------

    @Test
    void testNullableTypeIsMadeNotNullableWhenCastIsNotAllowed() {
        RelDataType nullableInteger = nullable(sqlType(SqlTypeName.INTEGER));

        RexNode node = literal(5, nullableInteger);

        RexLiteral literal = asLiteral(node);
        assertFalse(literal.getType().isNullable());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertEquals(0, new BigDecimal(5).compareTo(decimalOf(literal)));
    }

    @Test
    void testNullableTypeIsWrappedInCastWhenCastIsAllowed() {
        RelDataType nullableInteger = nullable(sqlType(SqlTypeName.INTEGER));

        RexNode node = castableLiteral(5, nullableInteger);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.CAST, call.getKind());
        assertEquals(SqlTypeName.INTEGER, call.getType().getSqlTypeName());
        assertTrue(call.getType().isNullable());

        List<RexNode> operands = call.getOperands();
        assertEquals(1, operands.size());
        RexLiteral operand = asLiteral(operands.get(0));
        assertFalse(operand.getType().isNullable());
        assertEquals(0, new BigDecimal(5).compareTo(decimalOf(operand)));
    }

    @Test
    void testNotNullableTypeIsNeverWrappedInCast() {
        RexNode node = castableLiteral(7, sqlType(SqlTypeName.BIGINT));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.BIGINT, literal.getType().getSqlTypeName());
        assertFalse(literal.getType().isNullable());
    }

    // ~ CHAR / VARCHAR -------------------------------------------------------

    @Test
    void testCharLiteralWithoutTrimIsRightPaddedToTypePrecision() {
        RexNode node = literal(nls("foo"), sqlType(SqlTypeName.CHAR, 5));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertEquals("foo  ", stringOf(literal));
    }

    @Test
    void testCharLiteralWithTrimDropsRedundantTrailingBlanks() {
        RexNode node = trimmedLiteral(nls("foo"), sqlType(SqlTypeName.CHAR, 5));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
        assertEquals("foo", stringOf(literal));
        assertEquals(3, literal.getType().getPrecision());
    }

    @Test
    void testCharLiteralWithTrimCutsValueDownToTypePrecision() {
        RexNode node = trimmedLiteral(nls("ab   "), sqlType(SqlTypeName.CHAR, 2));

        RexLiteral literal = asLiteral(node);
        assertEquals("ab", stringOf(literal));
        assertEquals(2, literal.getType().getPrecision());
    }

    @Test
    void testCharLiteralIsNotTruncatedWhenValueExceedsPrecision() {
        RexNode node = literal(nls("abcdef"), sqlType(SqlTypeName.CHAR, 3));

        RexLiteral literal = asLiteral(node);
        assertEquals("abcdef", stringOf(literal));
        assertEquals(6, literal.getType().getPrecision());
    }

    @Test
    void testPlainStringValueIsConvertedToNlsStringForCharType() {
        RelDataType char5 = sqlType(SqlTypeName.CHAR, 5);

        RexNode node = literal("ab", char5);

        NlsString value = asLiteral(node).getValueAs(NlsString.class);
        assertEquals(SqlTypeName.CHAR, node.getType().getSqlTypeName());
        assertEquals("ab   ", value.getValue());
        assertNotNull(value.getCharsetName());
        assertEquals(char5.getCharset().name(), value.getCharsetName());
        assertEquals(char5.getCollation(), value.getCollation());
    }

    @Test
    void testVarcharLiteralWithoutCastUsesCharLiteral() {
        RexNode node = literal(nls("abc"), sqlType(SqlTypeName.VARCHAR, 5));

        RexLiteral literal = asLiteral(node);
        assertEquals("abc", stringOf(literal));
        // without cast permission the result is a plain literal but may not have the exact type
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
    }

    @Test
    void testVarcharLiteralWithCastUsesRequestedType() {
        RexNode node = castableLiteral(nls("abc"), sqlType(SqlTypeName.VARCHAR, 5));

        RexLiteral literal = asLiteral(node);
        assertEquals("abc", stringOf(literal));
        assertEquals(SqlTypeName.VARCHAR, literal.getType().getSqlTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertFalse(literal.getType().isNullable());
    }

    @Test
    void testNullableVarcharWithCastProducesCastCall() {
        RelDataType nullableVarchar = nullable(sqlType(SqlTypeName.VARCHAR, 5));

        RexNode node = castableLiteral(nls("abc"), nullableVarchar);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.CAST, call.getKind());
        assertEquals(SqlTypeName.VARCHAR, call.getType().getSqlTypeName());
        assertTrue(call.getType().isNullable());
        assertEquals(1, call.getOperands().size());
        assertEquals("abc", stringOf(call.getOperands().get(0)));
    }

    // ~ BINARY / VARBINARY ---------------------------------------------------

    @Test
    void testBinaryLiteralIsPaddedWithZeroBytes() {
        RexNode node = literal(new ByteString(new byte[] {1, 2}), sqlType(SqlTypeName.BINARY, 4));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.BINARY, literal.getTypeName());
        assertEquals(4, literal.getType().getPrecision());
        assertEquals(
                Arrays.toString(new byte[] {1, 2, 0, 0}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
    }

    @Test
    void testBinaryLiteralIsNotTruncatedWhenValueExceedsPrecision() {
        RexNode node =
                literal(new ByteString(new byte[] {1, 2, 3}), sqlType(SqlTypeName.BINARY, 2));

        RexLiteral literal = asLiteral(node);
        assertEquals(
                Arrays.toString(new byte[] {1, 2, 3}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
        assertEquals(3, literal.getType().getPrecision());
    }

    @Test
    void testVarbinaryLiteralWithoutCastKeepsValue() {
        RexNode node =
                literal(new ByteString(new byte[] {1, 2}), sqlType(SqlTypeName.VARBINARY, 4));

        RexLiteral literal = asLiteral(node);
        assertEquals(
                Arrays.toString(new byte[] {1, 2}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
        assertEquals(SqlTypeName.BINARY, literal.getTypeName());
    }

    @Test
    void testVarbinaryLiteralWithCastUsesRequestedType() {
        RexNode node =
                castableLiteral(new ByteString(new byte[] {1, 2}), sqlType(SqlTypeName.VARBINARY, 4));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.VARBINARY, literal.getType().getSqlTypeName());
        assertEquals(
                Arrays.toString(new byte[] {1, 2}),
                Arrays.toString(((ByteString) literal.getValue()).getBytes()));
    }

    // ~ exact numerics -------------------------------------------------------

    @Test
    void testIntegralTypesArePreservedInNumericLiterals() {
        for (SqlTypeName typeName :
                new SqlTypeName[] {
                    SqlTypeName.TINYINT,
                    SqlTypeName.SMALLINT,
                    SqlTypeName.INTEGER,
                    SqlTypeName.BIGINT
                }) {
            RexNode node = literal(3, sqlType(typeName));

            RexLiteral literal = asLiteral(node);
            assertEquals(typeName, literal.getType().getSqlTypeName(), "type of " + typeName);
            assertEquals(SqlTypeName.DECIMAL, literal.getTypeName());
            assertFalse(literal.getType().isNullable());
            assertEquals(
                    0,
                    new BigDecimal(3).compareTo(literal.getValueAs(BigDecimal.class)),
                    "value of " + typeName);
        }
    }

    @Test
    void testNumericValuesOfVariousJavaTypesAreCleanedToBigDecimal() {
        BigDecimal fromInteger = decimalOf(literal(3, sqlType(SqlTypeName.INTEGER)));
        BigDecimal fromLong = decimalOf(literal(4L, sqlType(SqlTypeName.BIGINT)));
        BigDecimal fromBigDecimal =
                decimalOf(literal(new BigDecimal("5"), sqlType(SqlTypeName.SMALLINT)));

        assertEquals(0, new BigDecimal(3).compareTo(fromInteger));
        assertEquals(0, new BigDecimal(4).compareTo(fromLong));
        assertEquals(0, new BigDecimal(5).compareTo(fromBigDecimal));
    }

    @Test
    void testDecimalLiteralKeepsDeclaredPrecisionAndScale() {
        RelDataType decimalType = typeFactory.createSqlType(SqlTypeName.DECIMAL, 5, 2);

        RexNode node = literal(new BigDecimal("1.23"), decimalType);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.DECIMAL, literal.getType().getSqlTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertEquals(2, literal.getType().getScale());
        assertEquals(new BigDecimal("1.23"), literal.getValueAs(BigDecimal.class));
    }

    @Test
    void testDecimalValueThatDoesNotFitThrowsIllegalArgumentException() {
        RelDataType decimalType = typeFactory.createSqlType(SqlTypeName.DECIMAL, 5, 2);

        IllegalArgumentException exception =
                assertThrows(
                        IllegalArgumentException.class,
                        () -> literal(new BigDecimal("12345.67"), decimalType));

        assertTrue(
                exception.getMessage().contains("Cannot convert"),
                "unexpected message: " + exception.getMessage());
        assertTrue(
                exception.getMessage().contains("overflow"),
                "unexpected message: " + exception.getMessage());
    }

    // ~ approximate numerics -------------------------------------------------

    @Test
    void testApproximateNumericLiteralFromDouble() {
        RexNode node = literal(1.5d, sqlType(SqlTypeName.DOUBLE));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.DOUBLE, literal.getType().getSqlTypeName());
        assertEquals(SqlTypeName.DOUBLE, literal.getTypeName());
        assertEquals(1.5d, literal.getValueAs(Double.class));
    }

    @Test
    void testApproximateNumericLiteralFromBigDecimal() {
        RexNode node = literal(new BigDecimal("2.25"), sqlType(SqlTypeName.DOUBLE));

        assertEquals(2.25d, asLiteral(node).getValueAs(Double.class));
    }

    @Test
    void testApproximateNumericLiteralFromFloatKeepsRealType() {
        RexNode node = literal(1.5f, sqlType(SqlTypeName.REAL));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.REAL, literal.getType().getSqlTypeName());
        assertEquals(1.5d, literal.getValueAs(Double.class));
    }

    // ~ BOOLEAN --------------------------------------------------------------

    @Test
    void testBooleanLiteralsAreCached() {
        RexNode first = literal(Boolean.TRUE, sqlType(SqlTypeName.BOOLEAN));
        RexNode second = castableLiteral(true, sqlType(SqlTypeName.BOOLEAN));
        RexNode third = literal(Boolean.FALSE, sqlType(SqlTypeName.BOOLEAN));

        assertSame(first, second);
        assertEquals(Boolean.TRUE, asLiteral(first).getValue());
        assertEquals(Boolean.FALSE, asLiteral(third).getValue());
        assertEquals(SqlTypeName.BOOLEAN, first.getType().getSqlTypeName());
    }

    // ~ SARG ----------------------------------------------------------------

    @Test
    void testSearchArgumentValueBecomesSargLiteral() {
        Sarg<BigDecimal> sarg =
                Sarg.of(
                        RexUnknownAs.UNKNOWN,
                        ImmutableRangeSet.of(Range.singleton(new BigDecimal("5"))));

        RexNode node = literal(sarg, sqlType(SqlTypeName.INTEGER));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.SARG, literal.getTypeName());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertEquals(sarg, literal.getValue());
    }

    // ~ date/time types ------------------------------------------------------

    @Test
    void testDateLiteral() {
        RexNode node = literal(new DateString("2024-01-02"), sqlType(SqlTypeName.DATE));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.DATE, literal.getType().getSqlTypeName());
        assertEquals(new DateString("2024-01-02"), literal.getValueAs(DateString.class));
    }

    @Test
    void testDateLiteralFromDaysSinceEpoch() {
        RexNode node = literal(120, sqlType(SqlTypeName.DATE));

        assertEquals(DateString.fromDaysSinceEpoch(120), asLiteral(node).getValueAs(DateString.class));
    }

    @Test
    void testTimeLiteralKeepsFractionalSeconds() {
        RexNode node = literal(new TimeString("12:34:56.789"), sqlType(SqlTypeName.TIME, 3));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.TIME, literal.getType().getSqlTypeName());
        assertEquals(3, literal.getType().getPrecision());
        assertEquals(new TimeString("12:34:56.789"), literal.getValueAs(TimeString.class));
    }

    @Test
    void testTimeWithLocalTimeZoneLiteral() {
        RelDataType type = sqlType(SqlTypeName.TIME_WITH_LOCAL_TIME_ZONE, 0);

        RexNode node = literal(new TimeString("12:34:56"), type);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.TIME_WITH_LOCAL_TIME_ZONE, literal.getType().getSqlTypeName());
        assertEquals(new TimeString("12:34:56"), literal.getValueAs(TimeString.class));
    }

    @Test
    void testTimeWithTimeZoneLiteral() {
        TimeWithTimeZoneString time =
                new TimeWithTimeZoneString(new TimeString("12:34:56"), TimeZone.getTimeZone("UTC"));

        RexNode node = literal(time, sqlType(SqlTypeName.TIME_TZ, 0));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.TIME_TZ, literal.getType().getSqlTypeName());
        assertEquals(time, literal.getValue());
    }

    @Test
    void testTimestampLiteralKeepsFractionalSeconds() {
        RelDataType timestamp3 = sqlType(SqlTypeName.TIMESTAMP, 3);

        RexNode node = literal(new TimestampString("2024-01-02 03:04:05.678"), timestamp3);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.TIMESTAMP, literal.getType().getSqlTypeName());
        assertEquals(3, literal.getType().getPrecision());
        assertEquals(
                new TimestampString("2024-01-02 03:04:05.678"),
                literal.getValueAs(TimestampString.class));
    }

    @Test
    void testTimestampLiteralFromMillisSinceEpoch() {
        RexNode node = literal(0L, sqlType(SqlTypeName.TIMESTAMP, 0));

        assertEquals(
                TimestampString.fromMillisSinceEpoch(0L),
                asLiteral(node).getValueAs(TimestampString.class));
    }

    @Test
    void testTimestampWithLocalTimeZoneLiteral() {
        RelDataType type = sqlType(SqlTypeName.TIMESTAMP_WITH_LOCAL_TIME_ZONE, 0);

        RexNode node = literal(new TimestampString("2024-01-02 03:04:05"), type);

        RexLiteral literal = asLiteral(node);
        assertEquals(
                SqlTypeName.TIMESTAMP_WITH_LOCAL_TIME_ZONE, literal.getType().getSqlTypeName());
        assertEquals(
                new TimestampString("2024-01-02 03:04:05"),
                literal.getValueAs(TimestampString.class));
    }

    @Test
    void testTimestampWithTimeZoneLiteral() {
        TimestampWithTimeZoneString timestamp =
                new TimestampWithTimeZoneString(
                        new TimestampString("2024-01-02 03:04:05"), TimeZone.getTimeZone("UTC"));

        RexNode node = literal(timestamp, sqlType(SqlTypeName.TIMESTAMP_TZ, 0));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.TIMESTAMP_TZ, literal.getType().getSqlTypeName());
        assertEquals(timestamp, literal.getValue());
    }

    // ~ intervals ------------------------------------------------------------

    @Test
    void testIntervalDayLiteral() {
        SqlIntervalQualifier qualifier =
                new SqlIntervalQualifier(TimeUnit.DAY, null, SqlParserPos.ZERO);
        RelDataType intervalType = typeFactory.createSqlIntervalType(qualifier);

        RexNode node = literal(new BigDecimal(5), intervalType);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.INTERVAL_DAY, literal.getTypeName());
        assertEquals(SqlTypeName.INTERVAL_DAY, literal.getType().getSqlTypeName());
        assertEquals(0, new BigDecimal(5).compareTo(literal.getValueAs(BigDecimal.class)));
    }

    @Test
    void testIntervalYearToMonthLiteral() {
        SqlIntervalQualifier qualifier =
                new SqlIntervalQualifier(TimeUnit.YEAR, TimeUnit.MONTH, SqlParserPos.ZERO);
        RelDataType intervalType = typeFactory.createSqlIntervalType(qualifier);

        RexNode node = literal(new BigDecimal(13), intervalType);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.INTERVAL_YEAR_MONTH, literal.getTypeName());
        assertEquals(0, new BigDecimal(13).compareTo(literal.getValueAs(BigDecimal.class)));
    }

    // ~ MAP / ARRAY / MULTISET / ROW -----------------------------------------

    @Test
    void testMapValueBecomesMapValueConstructorCall() {
        RelDataType mapType =
                typeFactory.createMapType(
                        sqlType(SqlTypeName.VARCHAR, 10), sqlType(SqlTypeName.INTEGER));
        Map<Object, Object> map = new LinkedHashMap<>();
        map.put("k", 1);
        map.put("l", 2);

        RexNode node = literal(map, mapType);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.MAP_VALUE_CONSTRUCTOR, call.getKind());
        assertEquals(SqlTypeName.MAP, call.getType().getSqlTypeName());
        assertEquals(4, call.getOperands().size());
        assertEquals("k", stringOf(call.getOperands().get(0)));
        assertEquals(0, BigDecimal.ONE.compareTo(decimalOf(call.getOperands().get(1))));
        assertEquals("l", stringOf(call.getOperands().get(2)));
        assertEquals(0, new BigDecimal(2).compareTo(decimalOf(call.getOperands().get(3))));
    }

    @Test
    void testArrayValueBecomesArrayValueConstructorCall() {
        RelDataType arrayType = typeFactory.createArrayType(sqlType(SqlTypeName.INTEGER), -1);

        RexNode node = literal(Arrays.asList(1, 2, 3), arrayType);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.ARRAY_VALUE_CONSTRUCTOR, call.getKind());
        assertEquals(SqlTypeName.ARRAY, call.getType().getSqlTypeName());
        assertEquals(3, call.getOperands().size());
        for (int i = 0; i < call.getOperands().size(); i++) {
            assertEquals(0, new BigDecimal(i + 1).compareTo(decimalOf(call.getOperands().get(i))));
        }
    }

    @Test
    void testEmptyArrayValueCannotBeTurnedIntoLiteral() {
        RelDataType arrayType = typeFactory.createArrayType(sqlType(SqlTypeName.INTEGER), -1);

        // the element type of an array value constructor with no elements cannot be derived
        assertThrows(
                IllegalArgumentException.class,
                () -> literal(Collections.emptyList(), arrayType));
    }

    @Test
    void testMultisetValueWithoutCastProducesLiteral() {
        RelDataType multisetType =
                typeFactory.createMultisetType(sqlType(SqlTypeName.INTEGER), -1);

        RexNode node = literal(Arrays.asList(new BigDecimal(1), new BigDecimal(2)), multisetType);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.MULTISET, literal.getTypeName());
        assertEquals(SqlTypeName.MULTISET, literal.getType().getSqlTypeName());
        List<?> value = assertInstanceOf(List.class, literal.getValue());
        assertEquals(2, value.size());
    }

    @Test
    void testMultisetValueWithCastProducesCall() {
        RelDataType multisetType =
                typeFactory.createMultisetType(sqlType(SqlTypeName.INTEGER), -1);

        RexNode node = castableLiteral(Arrays.asList(1, 2), multisetType);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.MULTISET_VALUE_CONSTRUCTOR, call.getKind());
        assertEquals(2, call.getOperands().size());
    }

    @Test
    void testRowValueProducesRowLiteral() {
        RelDataType rowType =
                typeFactory.createStructType(
                        Arrays.asList(
                                sqlType(SqlTypeName.INTEGER), sqlType(SqlTypeName.VARCHAR, 3)),
                        Arrays.asList("a", "b"));

        RexNode node = literal(Arrays.asList(1, nls("xy")), rowType);

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.ROW, literal.getTypeName());
        assertEquals(2, literal.getType().getFieldCount());
        List<?> value = assertInstanceOf(List.class, literal.getValue());
        assertEquals(2, value.size());
    }

    // ~ GEOMETRY / ANY / SYMBOL ----------------------------------------------

    @Test
    void testGeometryValueProducesGeometryLiteral() {
        Geometry point = new GeometryFactory().createPoint(new Coordinate(1, 2));

        RexNode node = literal(point, sqlType(SqlTypeName.GEOMETRY));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.GEOMETRY, literal.getTypeName());
        assertEquals(SqlTypeName.GEOMETRY, literal.getType().getSqlTypeName());
        assertSame(point, literal.getValue());
    }

    @Test
    void testAnyTypeIsResolvedFromTheValue() {
        RexNode stringLiteral = literal("abc", sqlType(SqlTypeName.ANY));
        assertEquals(SqlTypeName.CHAR, stringLiteral.getType().getSqlTypeName());
        assertEquals("abc", stringOf(stringLiteral));

        RexNode numberLiteral = literal(7, sqlType(SqlTypeName.ANY));
        assertEquals(SqlTypeName.BIGINT, numberLiteral.getType().getSqlTypeName());
        assertEquals(0, new BigDecimal(7).compareTo(decimalOf(numberLiteral)));
    }

    @Test
    void testSymbolTypeProducesFlagLiteral() {
        RexNode node = literal(TimeUnit.DAY, sqlType(SqlTypeName.SYMBOL));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.SYMBOL, literal.getTypeName());
        assertEquals(TimeUnit.DAY, literal.getValue());
    }

    // ~ unsupported types ----------------------------------------------------

    @Test
    void testUnsupportedTypeThrowsIllegalArgumentException() {
        RelDataType otherType = sqlType(SqlTypeName.OTHER);

        IllegalArgumentException exception =
                assertThrows(IllegalArgumentException.class, () -> literal("x", otherType));

        assertTrue(
                exception.getMessage().contains("Cannot create literal for type"),
                "unexpected message: " + exception.getMessage());
        assertTrue(
                exception.getMessage().contains("OTHER"),
                "unexpected message: " + exception.getMessage());
    }
}
