        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.CAST, call.getKind());
        assertEquals(SqlTypeName.VARCHAR, call.getType().getSqlTypeName());
        assertTrue(call.getType().isNullable());
        assertEquals(1, call.getOperands().size());
        assertEquals("abc", stringOf(call.getOperands().get(0)));
