/**
 * Tests for {@link RexBuilder#makeLiteral(Object, RelDataType, boolean, boolean)}.
 *
 * <p>The tests verify the observable contract of the method: the kind of expression that is
 * created, the {@link SqlTypeName} of the result, its nullability and the value that it carries.
 */
class RexBuilderMakeLiteralTests {

    private RelDataTypeFactory typeFactory;
    private RexBuilder rexBuilder;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        rexBuilder = new RexBuilder(typeFactory);
    }

    // ~ helpers --------------------------------------------------------------

    /** Creates a literal, disallowing casts and trimming. */
    private RexNode literal(Object value, RelDataType type) {
        return rexBuilder.makeLiteral(value, type, false, false);
    }

    /** Creates a literal, allowing the builder to wrap the value into a cast if necessary. */
    private RexNode castableLiteral(Object value, RelDataType type) {
        return rexBuilder.makeLiteral(value, type, true, false);
    }

    /** Creates a literal, asking the builder to trim redundant trailing blanks. */
    private RexNode trimmedLiteral(Object value, RelDataType type) {
        return rexBuilder.makeLiteral(value, type, false, true);
    }

    private RelDataType sqlType(SqlTypeName typeName) {
        return typeFactory.createSqlType(typeName);
    }

    private RelDataType sqlType(SqlTypeName typeName, int precision) {
        return typeFactory.createSqlType(typeName, precision);
    }

    private RelDataType nullable(RelDataType type) {
        return typeFactory.createTypeWithNullability(type, true);
    }

    private static NlsString nls(String value) {
        return new NlsString(value, null, null);
    }

    private static RexLiteral asLiteral(RexNode node) {
        return assertInstanceOf(RexLiteral.class, node);
    }

    private static BigDecimal decimalOf(RexNode node) {
        return asLiteral(node).getValueAs(BigDecimal.class);
    }

    private static String stringOf(RexNode node) {
        return asLiteral(node).getValueAs(NlsString.class).getValue();
    }

    // ~ null handling --------------------------------------------------------

    @Test
    void testNullValueProducesTypedNullLiteral() {
        RexNode node = literal(null, sqlType(SqlTypeName.INTEGER));

        RexLiteral literal = asLiteral(node);
        assertTrue(literal.isNull());
        assertNull(literal.getValue());
        assertEquals(SqlTypeName.NULL, literal.getTypeName());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertTrue(literal.getType().isNullable());
    }

    @Test
    void testNullValueKeepsParameterTypeRegardlessOfCastPermission() {
        RelDataType varchar5 = sqlType(SqlTypeName.VARCHAR, 5);

        RexNode withoutCast = literal(null, varchar5);
        RexNode withCast = castableLiteral(null, nullable(varchar5));

        for (RexNode node : Arrays.asList(withoutCast, withCast)) {
            RexLiteral literal = asLiteral(node);
            assertTrue(literal.isNull());
            assertEquals(SqlTypeName.VARCHAR, literal.getType().getSqlTypeName());
            assertEquals(5, literal.getType().getPrecision());
            assertTrue(literal.getType().isNullable());
        }
    }

    // ~ nullability handling -------------------------------------------------

    @Test
    void testNullableTypeIsMadeNotNullableWhenCastIsNotAllowed() {
        RelDataType nullableInteger = nullable(sqlType(SqlTypeName.INTEGER));

        RexNode node = literal(5, nullableInteger);

        RexLiteral literal = asLiteral(node);
        assertFalse(literal.getType().isNullable());
        assertEquals(SqlTypeName.INTEGER, literal.getType().getSqlTypeName());
        assertEquals(0, new BigDecimal(5).compareTo(decimalOf(literal)));
    }

    @Test
    void testNullableTypeIsWrappedInCastWhenCastIsAllowed() {
        RelDataType nullableInteger = nullable(sqlType(SqlTypeName.INTEGER));

        RexNode node = castableLiteral(5, nullableInteger);

        RexCall call = assertInstanceOf(RexCall.class, node);
        assertEquals(SqlKind.CAST, call.getKind());
        assertEquals(SqlTypeName.INTEGER, call.getType().getSqlTypeName());
        assertTrue(call.getType().isNullable());

        List<RexNode> operands = call.getOperands();
        assertEquals(1, operands.size());
        RexLiteral operand = asLiteral(operands.get(0));
        assertFalse(operand.getType().isNullable());
        assertEquals(0, new BigDecimal(5).compareTo(decimalOf(operand)));
    }

    @Test
    void testNotNullableTypeIsNeverWrappedInCast() {
        RexNode node = castableLiteral(7, sqlType(SqlTypeName.BIGINT));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.BIGINT, literal.getType().getSqlTypeName());
        assertFalse(literal.getType().isNullable());
    }

    // ~ CHAR / VARCHAR -------------------------------------------------------

    @Test
    void testCharLiteralWithoutTrimIsRightPaddedToTypePrecision() {
        RexNode node = literal(nls("foo"), sqlType(SqlTypeName.CHAR, 5));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
        assertEquals(5, literal.getType().getPrecision());
        assertEquals("foo  ", stringOf(literal));
    }

    @Test
    void testCharLiteralWithTrimDropsRedundantTrailingBlanks() {
        RexNode node = trimmedLiteral(nls("foo"), sqlType(SqlTypeName.CHAR, 5));

        RexLiteral literal = asLiteral(node);
        assertEquals(SqlTypeName.CHAR, literal.getTypeName());
        assertEquals("foo", stringOf(literal));
        assertEquals(3, literal.getType().getPrecision());
    }

    @Test
    void testCharLiteralWithTrimCutsValueDownToTypePrecision() {
        RexNode node = trimmedLiteral(nls("ab   "), sqlType(SqlTypeName.CHAR, 2));

