/**
 * Tests for {@link SqlValidatorImpl#performUnconditionalRewrites(SqlNode, boolean)}.
 *
 * <p>Verifies the observable rewrites of the method: ORDER BY push-down/wrapping, EXPLICIT TABLE
 * to SELECT conversion, generation of source selects for DELETE/UPDATE/MERGE, operator call
 * rewrites and half-hearted resolution of unresolved functions.
 */
class SqlValidatorImplPerformUnconditionalRewritesTests {

    private static final SqlParserPos POS = SqlParserPos.ZERO;

    // ------------------------------------------------------------------------
    // null / leaf nodes
    // ------------------------------------------------------------------------

    @Test
    void testNullNodeReturnsNull() {
        SqlValidatorImpl validator = newValidator();

        assertNull(validator.performUnconditionalRewrites(null, false));
        assertNull(validator.performUnconditionalRewrites(null, true));
    }

    @Test
    void testLeafNodesAreReturnedUnchanged() {
        SqlValidatorImpl validator = newValidator();

        SqlNode identifier = new SqlIdentifier("a", POS);
        assertSame(identifier, validator.performUnconditionalRewrites(identifier, false));

        SqlNode literal = SqlLiteral.createExactNumeric("42", POS);
        assertSame(literal, validator.performUnconditionalRewrites(literal, false));
    }

    // ------------------------------------------------------------------------
    // VALUES
    // ------------------------------------------------------------------------

    @Test
    void testValuesCallIsNotRewritten() {
        SqlValidatorImpl validator = newValidator();

        SqlNodeList rows =
                list(
                        SqlStdOperatorTable.ROW.createCall(
                                POS, SqlLiteral.createExactNumeric("1", POS)));
        SqlCall values = SqlStdOperatorTable.VALUES.createCall(POS, rows);

        SqlNode result = validator.performUnconditionalRewrites(values, true);

        assertSame(values, result);
        assertEquals(SqlKind.VALUES, result.getKind());
    }

    // ------------------------------------------------------------------------
    // ORDER BY
    // ------------------------------------------------------------------------

    @Test
    void testOrderByIsPushedIntoSelectWithoutOrderBy() {
        SqlValidatorImpl validator = newValidator();

        SqlSelect select = select(starList(), new SqlIdentifier("t", POS), null, null, null);
        SqlNodeList orderList = list(new SqlIdentifier("a", POS));
        SqlNode offset = SqlLiteral.createExactNumeric("1", POS);
        SqlNode fetch = SqlLiteral.createExactNumeric("2", POS);
        SqlOrderBy orderBy = new SqlOrderBy(POS, select, orderList, offset, fetch);

        SqlNode result = validator.performUnconditionalRewrites(orderBy, false);

        assertSame(select, result);
        assertSame(orderList, select.getOrderList());
        assertSame(offset, select.getOffset());
        assertSame(fetch, select.getFetch());
    }

    @Test
