    @Test
    void testValuesCallIsNotRewritten() {
        SqlValidatorImpl validator = newValidator();

        SqlNodeList rows =
                list(
                        SqlStdOperatorTable.ROW.createCall(
                                POS, SqlLiteral.createExactNumeric("1", POS)));
        SqlCall values = SqlStdOperatorTable.VALUES.createCall(POS, rows);

        SqlNode result = validator.performUnconditionalRewrites(values, true);

        assertSame(values, result);
        assertEquals(SqlKind.VALUES, result.getKind());
    }

