    @Test
    void testMergeGetsSourceSelectWithInnerJoin() {
        SqlValidatorImpl validator = newValidator();

        SqlNode target = new SqlIdentifier("t", POS);
        SqlNode sourceTable = new SqlIdentifier("s", POS);
        SqlNode condition =
                SqlStdOperatorTable.EQUALS.createCall(
                        POS,
                        new SqlIdentifier("a", POS),
                        new SqlIdentifier("b", POS));
        SqlMerge merge = new SqlMerge(POS, target, condition, sourceTable, null, null, null, null);

        SqlNode result = validator.performUnconditionalRewrites(merge, false);

        assertSame(merge, result);
        SqlSelect sourceSelect = merge.getSourceSelect();
        assertNotNull(sourceSelect);
        assertEquals(1, sourceSelect.getSelectList().size());
        assertTrue(((SqlIdentifier) sourceSelect.getSelectList().get(0)).isStar());
        SqlJoin join = assertInstanceOf(SqlJoin.class, sourceSelect.getFrom());
        assertEquals(JoinType.INNER, join.getJoinType());
        assertSame(condition, join.getCondition());
        assertSame(target, join.getRight());
        // the source table reference is cloned for the join
        assertNotSame(sourceTable, join.getLeft());
        SqlIdentifier clonedSource = assertInstanceOf(SqlIdentifier.class, join.getLeft());
        assertEquals("s", clonedSource.getSimple());
    }

