@Test
void testOrderByWrapsSelectThatAlreadyHasOrderBy() {
    SqlValidatorImpl validator = newValidator();

    SqlNodeList innerOrderList = list(new SqlIdentifier("a", POS));
    SqlSelect inner =
            select(starList(), new SqlIdentifier("t", POS), null, null, innerOrderList);
    SqlNodeList outerOrderList = list(new SqlIdentifier("b", POS));
    SqlNode offset = SqlLiteral.createExactNumeric("1", POS);
    SqlNode fetch = SqlLiteral.createExactNumeric("5", POS);
    SqlOrderBy orderBy = new SqlOrderBy(POS, inner, outerOrderList, offset, fetch);

    SqlNode result = validator.performUnconditionalRewrites(orderBy, false);

    SqlSelect wrapper = assertInstanceOf(SqlSelect.class, result);
    assertNotSame(inner, wrapper);
    assertSame(inner, wrapper.getFrom());
    assertSame(outerOrderList, wrapper.getOrderList());
    assertSame(offset, wrapper.getOffset());
    assertSame(fetch, wrapper.getFetch());
    assertNull(wrapper.getWhere());
    assertEquals(1, wrapper.getSelectList().size());
    SqlNode star = wrapper.getSelectList().get(0);
    assertInstanceOf(SqlIdentifier.class, star);
    assertTrue(((SqlIdentifier) star).isStar());
    // the original ORDER BY of the inner select is not clobbered
    assertSame(innerOrderList, inner.getOrderList());
}

