        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL JOIN b"));
    }

    @Test
    void testUsingMissingColumnIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a JOIN b USING (missing)"));
