package org.apache.calcite.sql.validate;

import org.apache.calcite.config.CalciteConnectionConfig;
import org.apache.calcite.config.CalciteConnectionConfigImpl;
import org.apache.calcite.jdbc.CalciteSchema;
import org.apache.calcite.jdbc.JavaTypeFactoryImpl;
import org.apache.calcite.prepare.CalciteCatalogReader;
import org.apache.calcite.rel.type.RelDataType;
import org.apache.calcite.rel.type.RelDataTypeFactory;
import org.apache.calcite.rel.type.RelDataTypeSystem;
import org.apache.calcite.schema.impl.AbstractTable;
import org.apache.calcite.sql.SqlNode;
import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.sql.parser.SqlParser;
import org.apache.calcite.sql.type.SqlTypeName;

import org.apache.flink.sql.parser.impl.FlinkSqlParserImpl;
import org.apache.flink.sql.parser.validate.FlinkSqlConformance;

import org.apache.calcite.runtime.CalciteContextException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.Properties;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link SqlValidatorImpl#validateJoin}. */
class SqlValidatorImplValidateJoinTests {

    private TestValidator validator;

    @BeforeEach
    void setUp() {
        final RelDataTypeFactory typeFactory = new JavaTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        final CalciteSchema rootSchema = CalciteSchema.createRootSchema(false);
        rootSchema.add("a", new TestTable("id", "name", "shared"));
        rootSchema.add("b", new TestTable("id", "name", "shared"));

        final Properties properties = new Properties();
        final CalciteConnectionConfig connectionConfig =
                new CalciteConnectionConfigImpl(properties);
        final CalciteCatalogReader catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        typeFactory,
                        connectionConfig);

        validator =
                new TestValidator(
                        SqlStdOperatorTable.instance(),
                        catalogReader,
                        typeFactory,
                        SqlValidator.Config.DEFAULT.withConformance(FlinkSqlConformance.DEFAULT));
    }

    @Test
    void testInnerJoinWithOnConditionIsValid() {
        assertDoesNotThrow(
                () -> validator.validateQuery("SELECT * FROM a JOIN b ON a.id = b.id"));
    }

    @Test
    void testUsingJoinIsValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a JOIN b USING (id)"));
    }

    @Test
    void testNaturalJoinIsValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL JOIN b"));
    }

    @Test
    void testUsingMissingColumnIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a JOIN b USING (missing)"));
        assertTrue(exception.getMessage().contains("missing"));
    }

    @Test
    void testCrossJoinWithConditionIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a CROSS JOIN b ON a.id = b.id"));
        assertTrue(exception.getMessage().toLowerCase().contains("cross"));
    }

    private static final class TestValidator extends SqlValidatorImpl {
        TestValidator(
                org.apache.calcite.sql.SqlOperatorTable operatorTable,
                SqlValidatorCatalogReader catalogReader,
                RelDataTypeFactory typeFactory,
                Config config) {
            super(operatorTable, catalogReader, typeFactory, config);
        }

        SqlNode validateQuery(String sql) {
            final SqlParser.Config parserConfig =
                    SqlParser.config()
                            .withParserFactory(FlinkSqlParserImpl.FACTORY)
                            .withConformance(FlinkSqlConformance.DEFAULT)
                            .withCaseSensitive(false);
            try {
                final SqlNode node = SqlParser.create(sql, parserConfig).parseQuery();
                return validate(node);
            } catch (org.apache.calcite.sql.parser.SqlParseException e) {
                throw new AssertionError("Unable to parse query: " + sql, e);
            }
        }
    }

    private static final class TestTable extends AbstractTable {
        private final String[] columns;

        private TestTable(String... columns) {
            this.columns = columns;
        }

        @Override
        public RelDataType getRowType(RelDataTypeFactory typeFactory) {
            final RelDataTypeFactory.Builder builder = typeFactory.builder();
            for (String column : columns) {
                builder.add(column, SqlTypeName.INTEGER);
            }
            return builder.build();
        }
    }
}
