        assertDoesNotThrow(
                () -> validator.validateQuery("SELECT * FROM a JOIN c USING (shared)"));
    }

    @Test
    void testNaturalJoinIsValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL JOIN b"));
