                                        "SELECT * FROM a ASOF JOIN b "
                                                + "MATCH_CONDITION (a.id) "
                                                + "ON a.id = b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("match condition"),
                exception.getMessage());
    }

