import org.apache.flink.sql.parser.impl.FlinkSqlParserImpl;
import org.apache.flink.sql.parser.validate.FlinkSqlConformance;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.Properties;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link SqlValidatorImpl#validateJoin}. */
class SqlValidatorImplValidateJoinTests {

    private RelDataTypeFactory typeFactory;
    private CalciteSchema rootSchema;
    private CalciteCatalogReader catalogReader;

    private TestValidator validator;

    @BeforeEach
    void setUp() {
        typeFactory = new JavaTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        rootSchema = CalciteSchema.createRootSchema(false);
        rootSchema.add("a", new TestTable("id", "name", "shared"));
        rootSchema.add("b", new TestTable("id", "name", "shared"));
        rootSchema.add(
                "c",
                new TestTable(
                        new SqlTypeName[] {
                            SqlTypeName.BOOLEAN, SqlTypeName.VARCHAR, SqlTypeName.INTEGER
                        },
                        "id",
                        "name",
                        "shared"));
        rootSchema.add("d", new TestTable("unrelated"));

        final Properties properties = new Properties();
        properties.setProperty(CalciteConnectionProperty.CASE_SENSITIVE.camelName(), "false");
        final CalciteConnectionConfig connectionConfig =
                new CalciteConnectionConfigImpl(properties);
        catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        typeFactory,
                        connectionConfig);
        validator = newValidator(FlinkSqlConformance.DEFAULT);
    }

    @Test
    void testInnerJoinWithOnConditionIsValid() {
        assertDoesNotThrow(
                () -> validator.validateQuery("SELECT * FROM a JOIN b ON a.id = b.id"));
    }

    @Test
    void testUsingJoinIsValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a JOIN b USING (id)"));
        assertDoesNotThrow(
                () -> validator.validateQuery("SELECT * FROM a JOIN c USING (shared)"));
    }

    @Test
    void testNaturalJoinIsValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL JOIN b"));
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL LEFT JOIN b"));
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL RIGHT JOIN b"));
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL FULL JOIN b"));
    }

    @Test
    void testNaturalJoinWithoutCommonColumnsIsValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a NATURAL JOIN d"));
    }

    @Test
    void testCommaAndCrossJoinsWithoutConditionsAreValid() {
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a, b"));
        assertDoesNotThrow(() -> validator.validateQuery("SELECT * FROM a CROSS JOIN b"));
    }

    @Test
    void testUsingMissingColumnIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a JOIN b USING (missing)"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("missing"),
                exception.getMessage());
    }

    @Test
    void testUsingIncompatibleColumnTypesIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a JOIN c USING (id)"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("incompatible"),
                exception.getMessage());
    }

    @Test
    void testNaturalJoinWithIncompatibleCommonColumnIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a NATURAL JOIN c"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("incompatible"),
                exception.getMessage());
    }

    @Test
    void testJoinWithoutConditionIsRejected() {
        assertJoinRequiresCondition("SELECT * FROM a JOIN b");
        assertJoinRequiresCondition("SELECT * FROM a LEFT JOIN b");
        assertJoinRequiresCondition("SELECT * FROM a RIGHT JOIN b");
        assertJoinRequiresCondition("SELECT * FROM a FULL JOIN b");
    }

    @Test
    void testNaturalJoinWithOnConditionIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a NATURAL JOIN b ON a.id = b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("natural"),
                exception.getMessage());
    }

    @Test
    void testNaturalJoinWithUsingConditionIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a NATURAL JOIN b USING (id)"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("natural"),
                exception.getMessage());
    }

    @Test
    void testCrossJoinWithOnConditionIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a CROSS JOIN b ON a.id = b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("cross"),
                exception.getMessage());
    }

    @Test
    void testCrossJoinWithUsingConditionIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a CROSS JOIN b USING (id)"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("cross"),
                exception.getMessage());
    }

    @Test
    void testNaturalCrossJoinIsRejected() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a NATURAL CROSS JOIN b"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("cross"),
                exception.getMessage());
    }

    @Test
    void testOnConditionMustBeBoolean() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateQuery("SELECT * FROM a JOIN b ON a.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("condition"),
                exception.getMessage());
    }

    @Test
    void testAggregateIsRejectedInOnCondition() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a JOIN b ON COUNT(*) > 0"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("aggregate"),
                exception.getMessage());
    }

    @Test
    void testAsofJoinWithConjunctiveEqualitiesIsValid() {
        assertDoesNotThrow(
                () ->
                        validator.validateQuery(
                                "SELECT * FROM a ASOF JOIN b "
                                        + "MATCH_CONDITION (a.id >= b.id) "
                                        + "ON a.id = b.id AND a.shared = b.shared"));
        assertDoesNotThrow(
                () ->
                        validator.validateQuery(
                                "SELECT * FROM a LEFT ASOF JOIN b "
                                        + "MATCH_CONDITION (a.id >= b.id) "
                                        + "ON a.id = b.id"));
    }

    @Test
    void testAsofJoinConditionMustBeConjunctionOfEqualities() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a ASOF JOIN b "
                                                + "MATCH_CONDITION (a.id >= b.id) "
                                                + "ON a.id > b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("comparison"),
                exception.getMessage());
    }

    @Test
    void testAsofJoinConditionMustCompareBothSides() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a ASOF JOIN b "
                                                + "MATCH_CONDITION (a.id >= b.id) "
                                                + "ON a.id = a.shared"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("comparison"),
                exception.getMessage());
    }

    @Test
    void testAsofJoinMatchConditionMustBeComparison() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a ASOF JOIN b "
                                                + "MATCH_CONDITION (a.id) "
                                                + "ON a.id = b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("match_condition"),
                exception.getMessage());
    }

    @Test
    void testAsofJoinMatchConditionMustUseOrderComparison() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a ASOF JOIN b "
                                                + "MATCH_CONDITION (a.id = b.id) "
                                                + "ON a.id = b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("match_condition"),
                exception.getMessage());
    }

    @Test
    void testAsofJoinMatchConditionMustCompareBothSides() {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () ->
                                validator.validateQuery(
                                        "SELECT * FROM a ASOF JOIN b "
                                                + "MATCH_CONDITION (a.id >= a.shared) "
                                                + "ON a.id = b.id"));
        assertTrue(
                exception.getMessage().toLowerCase().contains("match_condition"),
                exception.getMessage());
    }

    @Test
    void testAsofJoinWithoutConditionIsRejected() {
        final SqlSelect select =
                parseQuery(
                        "SELECT * FROM a ASOF JOIN b "
                                + "MATCH_CONDITION (a.id >= b.id) ON a.id = b.id");
        final SqlJoin join = (SqlJoin) select.getFrom();
        join.setOperand(4, JoinConditionType.NONE.symbol(SqlParserPos.ZERO));
        join.setOperand(5, null);
        final CalciteContextException exception =
                assertThrows(CalciteContextException.class, () -> validator.validate(select));
        assertTrue(
                exception.getMessage().toLowerCase().contains("condition"),
                exception.getMessage());
    }

    @Test
    void testSemiAndAntiJoinsRequireLiberalConformance() {
        assertUnsupportedJoinType(JoinType.LEFT_SEMI_JOIN);
        assertUnsupportedJoinType(JoinType.LEFT_ANTI_JOIN);
    }

    @Test
    void testSemiAndAntiJoinsAreAcceptedWithLiberalConformance() {
        final TestValidator liberalValidator = newValidator(SqlConformanceEnum.BABEL);
        assertDoesNotThrow(
                () -> liberalValidator.validateMutatedJoin("SELECT * FROM a JOIN b ON a.id = b.id",
                        JoinType.LEFT_SEMI_JOIN));
        assertDoesNotThrow(
                () -> liberalValidator.validateMutatedJoin("SELECT * FROM a JOIN b ON a.id = b.id",
                        JoinType.LEFT_ANTI_JOIN));
    }

    @Test
    void testSemiAndAntiJoinsStillRequireConditionWithLiberalConformance() {
        final TestValidator liberalValidator = newValidator(SqlConformanceEnum.BABEL);
        for (JoinType joinType : new JoinType[] {JoinType.LEFT_SEMI_JOIN, JoinType.LEFT_ANTI_JOIN}) {
            final CalciteContextException exception =
                    assertThrows(
                            CalciteContextException.class,
                            () -> liberalValidator.validateMutatedJoin(
                                    "SELECT * FROM a JOIN b", joinType));
            assertTrue(
                    exception.getMessage().toLowerCase().contains("condition"),
                    exception.getMessage());
        }
    }

    private void assertJoinRequiresCondition(String sql) {
        final CalciteContextException exception =
                assertThrows(CalciteContextException.class, () -> validator.validateQuery(sql));
        assertTrue(
                exception.getMessage().toLowerCase().contains("condition"),
                exception.getMessage());
    }

    private void assertUnsupportedJoinType(JoinType joinType) {
        final CalciteContextException exception =
                assertThrows(
                        CalciteContextException.class,
                        () -> validator.validateMutatedJoin(
                                "SELECT * FROM a JOIN b ON a.id = b.id", joinType));
        assertTrue(
                exception.getMessage().toLowerCase().contains("support"),
                exception.getMessage());
    }

    private TestValidator newValidator(SqlConformance conformance) {
        return new TestValidator(
                SqlStdOperatorTable.instance(),
                catalogReader,
                typeFactory,
                SqlValidator.Config.DEFAULT.withConformance(conformance));
    }

    private static SqlSelect parseQuery(String sql) {
        try {
            return (SqlSelect) SqlParser.create(sql, parserConfig()).parseQuery();
        } catch (org.apache.calcite.sql.parser.SqlParseException e) {
            throw new AssertionError("Unable to parse query: " + sql, e);
        }
    }

    private static SqlParser.Config parserConfig() {
        return SqlParser.config()
                .withParserFactory(FlinkSqlParserImpl.FACTORY)
                .withConformance(FlinkSqlConformance.DEFAULT)
                .withCaseSensitive(false)
                .withUnquotedCasing(Casing.TO_LOWER);
    }

    private static final class TestValidator extends SqlValidatorImpl {
        TestValidator(
                SqlOperatorTable operatorTable,
                SqlValidatorCatalogReader catalogReader,
                RelDataTypeFactory typeFactory,
                Config config) {
            super(operatorTable, catalogReader, typeFactory, config);
        }

        SqlNode validateQuery(String sql) {
            return validate(parseQuery(sql));
        }

        SqlNode validateMutatedJoin(String sql, JoinType joinType) {
            final SqlSelect select = parseQuery(sql);
            final SqlJoin join = (SqlJoin) select.getFrom();
            join.setOperand(2, joinType.symbol(SqlParserPos.ZERO));
            return validate(select);
        }
    }

