import org.apache.calcite.sql.type.SqlTypeFactoryImpl;
import org.apache.calcite.sql.type.SqlTypeName;
import org.apache.calcite.tools.Frameworks;

import org.junit.jupiter.api.Test;

import java.util.Collections;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class SqlValidatorImplValidateMatchRecognizeTests {

    @Test
    void basicMatchRecognizeValidates() {
        final SqlValidatorImpl validator = validator();
        final SqlNode query = parse("SELECT * FROM T MATCH_RECOGNIZE ("
                + "PARTITION BY ID ORDER BY TS "
                + "MEASURES A.ID AS A_ID "
                + "ONE ROW PER MATCH "
                + "PATTERN (A B*) "
                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");
        assertThat(validator.validate(query)).isNotNull();
    }

    private static SqlValidatorImpl validator() {
        final SchemaPlus root = Frameworks.createRootSchema(true);
        root.add("T", new AbstractTable() {
            @Override
            public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                return typeFactory.builder()
                        .add("ID", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .add("TS", typeFactory.createSqlType(SqlTypeName.TIMESTAMP, 3))
                        .add("PRICE", typeFactory.createSqlType(SqlTypeName.DECIMAL, 10, 2))
                        .build();
            }
        });
        final RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        final CalciteCatalogReader catalogReader = new CalciteCatalogReader(
                CalciteSchema.from(root), Collections.emptyList(), typeFactory,
                CalciteConnectionConfig.DEFAULT);
        return (SqlValidatorImpl) SqlValidatorUtil.newValidator(
                SqlStdOperatorTable.instance(), catalogReader, typeFactory);
    }

    private static SqlNode parse(String sql) {
        try {
            return SqlParser.create(sql).parseQuery();
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }
}
