/** Tests for {@link SqlValidatorImpl#validateMatchRecognize}. */
class SqlValidatorImplValidateMatchRecognizeTests {

    private SqlValidatorImpl validator;

    @BeforeEach
    void setUp() {
        final SchemaPlus root = Frameworks.createRootSchema(true);
        root.add(
                "T",
                new AbstractTable() {
                    @Override
                    public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                        return typeFactory
                                .builder()
                                .add("ID", typeFactory.createSqlType(SqlTypeName.INTEGER))
                                .add("TS", typeFactory.createSqlType(SqlTypeName.TIMESTAMP, 3))
                                .add("PRICE", typeFactory.createSqlType(SqlTypeName.DECIMAL, 10, 2))
                                .build();
                    }
                });
        final RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        final CalciteCatalogReader catalogReader =
                new CalciteCatalogReader(
                        CalciteSchema.from(root),
                        Collections.emptyList(),
                        typeFactory,
                        CalciteConnectionConfig.DEFAULT);
        validator =
                (SqlValidatorImpl)
                        SqlValidatorUtil.newValidator(
                                SqlStdOperatorTable.instance(), catalogReader, typeFactory);
    }

    @Test
    void oneRowPerMatchBuildsRowTypeFromPartitionAndMeasureColumns() {
        final SqlNode query =
                validate(
                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                + "PARTITION BY ID "
                                + "ORDER BY TS "
                                + "MEASURES A.ID AS A_ID, A.PRICE AS A_PRICE "
                                + "ONE ROW PER MATCH "
                                + "PATTERN (A B*) "
                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");

        assertThat(fieldNames(query)).containsExactly("ID", "A_ID", "A_PRICE");
        assertThat(fieldType(query, "ID")).isEqualTo(SqlTypeName.INTEGER);
        assertThat(fieldType(query, "A_ID")).isEqualTo(SqlTypeName.INTEGER);
        assertThat(fieldType(query, "A_PRICE")).isEqualTo(SqlTypeName.DECIMAL);
    }

    @Test
    void allRowsPerMatchAddsOrderAndRemainingInputColumnsWithoutDuplicates() {
        final SqlNode query =
                validate(
                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                + "PARTITION BY ID "
                                + "ORDER BY TS DESC "
                                + "MEASURES A.ID AS A_ID "
                                + "ALL ROWS PER MATCH "
                                + "PATTERN (A B*) "
                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");

        // PARTITION BY and ORDER BY columns are added first, then the rest of
        // the input row type, then measures. Existing names are not duplicated.
        assertThat(fieldNames(query)).containsExactly("ID", "TS", "PRICE", "A_ID");
        assertThat(fieldType(query, "TS")).isEqualTo(SqlTypeName.TIMESTAMP);
        assertThat(fieldType(query, "PRICE")).isEqualTo(SqlTypeName.DECIMAL);
    }

    @Test
    void allRowsPerMatchDoesNotDuplicateMeasureNameAlreadyInRowType() {
        final SqlNode query =
                validate(
                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                + "ORDER BY TS "
                                + "MEASURES A.ID AS ID "
                                + "ALL ROWS PER MATCH "
                                + "PATTERN (A B*) "
                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");

        assertThat(fieldNames(query)).containsExactly("TS", "ID", "PRICE");
    }

    @Test
    void allRowsPerMatchWithoutMeasuresKeepsInputRowType() {
        final SqlNode query =
                validate(
                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                + "ORDER BY TS "
                                + "ALL ROWS PER MATCH "
                                + "PATTERN (A B*) "
                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");

        assertThat(fieldNames(query)).containsExactly("ID", "TS", "PRICE");
    }

    @Test
    void withinIntervalAcceptsTimestampFirstOrderByColumn() {
        final SqlNode query =
                validate(
                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                + "ORDER BY TS DESC "
                                + "MEASURES A.ID AS A_ID "
                                + "ONE ROW PER MATCH "
                                + "PATTERN (A B*) WITHIN INTERVAL '10' SECOND "
                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");

        assertThat(fieldNames(query)).containsExactly("A_ID");
    }

    @Test
    void withinIntervalRejectsNegativeInterval() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) WITHIN INTERVAL -'1' SECOND "
                                                + "DEFINE A AS A.ID > 0)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Interval must be non-negative");
    }

    @Test
    void withinIntervalRequiresOrderByClause() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "PARTITION BY ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) WITHIN INTERVAL '10' SECOND "
                                                + "DEFINE A AS A.ID > 0)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Must contain an ORDER BY clause when WITHIN is used");
    }

    @Test
    void withinIntervalRequiresTimestampFirstOrderByColumn() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) WITHIN INTERVAL '10' SECOND "
                                                + "DEFINE A AS A.ID > 0)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("First column of ORDER BY must be of type TIMESTAMP");
    }

    @Test
    void defineAliasesMustBeUnique() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) "
                                                + "DEFINE A AS A.ID > 0, A AS A.PRICE > 0)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Pattern variable 'A' has already been defined");
    }

    @Test
    void subsetMayNotRedefinePatternVariable() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A B*) "
                                                + "SUBSET A = (A, B) "
                                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Pattern variable 'A' has already been defined");
    }

    @Test
    void subsetMustReferenceKnownPatternVariables() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A B*) "
                                                + "SUBSET S = (A, MISSING) "
                                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Unknown pattern 'MISSING'");
    }

    @Test
    void subsetVariableCanBeUsedBySkipTo() {
        final SqlNode query =
                validate(
                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                + "ORDER BY TS "
                                + "MEASURES A.ID AS A_ID "
                                + "ONE ROW PER MATCH "
                                + "AFTER MATCH SKIP TO LAST S "
                                + "PATTERN (A B*) "
                                + "SUBSET S = (A, B) "
                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)");

        assertThat(fieldNames(query)).containsExactly("A_ID");
    }

    @Test
    void skipToMustReferenceKnownPatternVariable() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "AFTER MATCH SKIP TO LAST MISSING "
                                                + "PATTERN (A B*) "
                                                + "DEFINE A AS A.ID > 0, B AS B.ID > A.ID)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("Unknown pattern 'MISSING'");
    }

    @Test
    void duplicateMeasureAliasesAreRejected() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID, A.TS AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) "
                                                + "DEFINE A AS A.ID > 0)"))
                .isInstanceOf(CalciteException.class)
                .hasMessageContaining(
                        "Duplicate name 'A_ID' in MATCH_RECOGNIZE MEASURE alias list");
    }

    @Test
    void defineConditionMustBeBoolean() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) "
                                                + "DEFINE A AS A.ID + 1)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("DEFINE clause must be a condition");
    }

    @Test
    void partitionColumnMustResolve() {
        assertThatThrownBy(
                        () ->
                                validate(
                                        "SELECT * FROM T MATCH_RECOGNIZE ("
                                                + "PARTITION BY UNKNOWN_COLUMN "
                                                + "ORDER BY TS "
                                                + "MEASURES A.ID AS A_ID "
                                                + "ONE ROW PER MATCH "
                                                + "PATTERN (A) "
                                                + "DEFINE A AS A.ID > 0)"))
                .isInstanceOf(CalciteContextException.class)
                .hasMessageContaining("UNKNOWN_COLUMN");
    }

    private SqlNode validate(String sql) {
        final SqlNode query = parse(sql);
        validator.validate(query);
        return query;
    }

    private List<String> fieldNames(SqlNode query) {
        return validator.getValidatedNodeType(query).getFieldNames();
    }

    private SqlTypeName fieldType(SqlNode query, String name) {
        return validator
                .getValidatedNodeType(query)
                .getField(name, false, false)
                .getType()
                .getSqlTypeName();
    }

    private static SqlNode parse(String sql) {
        try {
            return SqlParser.create(sql).parseQuery();
        } catch (Exception e) {
            throw new AssertionError("Unable to parse: " + sql, e);
        }
    }
}
