}

static boolean allLessThan(Collection<Integer> integers, int limit, Litmus ret) {
    for (int value : integers) {
        if (value >= limit) {
            return ret.fail("out of range; value: {}, limit: {}", value, limit);
        }
    }
    return ret.succeed();
}

