        return isFieldNotNullRecursive(project.getInput(), ((RexInputRef) expr).getIndex());
    } else if (rel instanceof Aggregate) {
        Aggregate agg = (Aggregate) rel;
        ImmutableBitSet groupSet = agg.getGroupSet();

        if (index >= groupSet.size()) {
