        assertEquals(Arrays.asList(0, 2, 1), inputRefIndexes(newProject.getProjects()));
        assertEquals(List.of(2), newAggregate.getAggCallList().get(0).getArgList());
        assertEquals(ImmutableSortedMap.of(0, 0), result.oldToNewOutputs);
