        final LogicalProject resultProject = assertInstanceOf(LogicalProject.class, result.r);
        assertEquals(2, resultProject.getRowType().getFieldCount());
        final RexLiteral literal = assertInstanceOf(RexLiteral.class,
                resultProject.getProjects().get(0));
        assertEquals(true, literal.getValueAs(Boolean.class));
        final RexInputRef countRef = assertInstanceOf(RexInputRef.class,
                resultProject.getProjects().get(1));
        assertEquals(0, countRef.getIndex());
        assertInstanceOf(Aggregate.class, resultProject.getInput());
        assertEquals(ImmutableBitSet.of(), ((Aggregate) resultProject.getInput()).getGroupSet());
        assertEquals(ImmutableSortedMap.of(0, 0, 1, 1), result.oldToNewOutputs);
        assertTrue(result.corDefOutputs.isEmpty());
    }

    @Test
    void addsCorrelatedVariablesToEveryGroupingSet() {
        final CorrelationId correlationId = new CorrelationId("corr");
        final RelBuilder inputBuilder = builder();
        inputBuilder.values(new String[] {"deptno", "name", "salary"}, 10, "Alice", 1000,
                20, "Bob", 2000);
        final RelNode input = inputBuilder.build();
        final RelBuilder.GroupKey groupKey =
                inputBuilder.groupKey(
                        ImmutableBitSet.of(1),
                        ImmutableList.of(
                                ImmutableBitSet.of(1), ImmutableBitSet.of()));
        final Aggregate aggregate =
                (Aggregate)
                        inputBuilder
                                .aggregate(groupKey, inputBuilder.countStar("employee_count"))
                                .build();
        assertEquals(Aggregate.Group.OTHER, aggregate.getGroupType());

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        final RelDecorrelator.CorDef corDef =
                new RelDecorrelator.CorDef(correlationId, 0);
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of(corDef, 0));

