                newAggregate.getGroupSets());
        assertEquals(
                ImmutableSortedMap.of(corDef, 0), result.corDefOutputs);
        assertEquals(ImmutableSortedMap.of(0, 0), result.oldToNewOutputs);
    }

    @Test
    void rewritesScalarCountAggregateWhenCorrelatedInputDoesNotPropagateNulls() {
        final CorrelationId correlationId = new CorrelationId("corr");
        final RelBuilder inputBuilder = builder();
        inputBuilder.values(new String[] {"deptno"}, 10, 20);
        final RelNode input = inputBuilder.build();
        final Aggregate aggregate = countAggregate(inputBuilder, input, ImmutableBitSet.of());

        final RelBuilder outerBuilder = builder();
        outerBuilder.values(new String[] {"deptno"}, 10, 20);
        final RelNode outerInput = outerBuilder.build();
        final RelDecorrelator.Frame outerFrame =
                frame(
                        outerInput,
                        outerInput,
                        RelDecorrelator.identityMap(outerInput.getRowType().getFieldCount()),
                        ImmutableSortedMap.of());

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        final RelDecorrelator.CorDef corDef =
                new RelDecorrelator.CorDef(correlationId, 0);
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of(corDef, 0));
        decorrelator.frameStack.push(Pair.of(correlationId, outerFrame));

        final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, true, true);

        assertNotNull(result);
        final LogicalProject resultProject = assertInstanceOf(LogicalProject.class, result.r);
        assertEquals(2, resultProject.getRowType().getFieldCount());
        assertInstanceOf(RexInputRef.class, resultProject.getProjects().get(0));
        final RexCall countCase = assertInstanceOf(RexCall.class,
                resultProject.getProjects().get(1));
        assertEquals(SqlStdOperatorTable.CASE, countCase.getOperator());
        assertEquals(ImmutableSortedMap.of(0, 1), result.oldToNewOutputs);
        assertEquals(ImmutableSortedMap.of(corDef, 0), result.corDefOutputs);
    }

    private static Aggregate countAggregate(
            RelBuilder builder, RelNode input, ImmutableBitSet groupSet) {
        return (Aggregate)
                builder
                        .push(input)
                        .aggregate(
                                builder.groupKey(groupSet),
                                builder.countStar("employee_count"))
                        .build();
    }

    private static RelDecorrelator.Frame frame(
            RelNode oldRel,
            RelNode newRel,
            Map<Integer, Integer> oldToNewOutputs,
            NavigableMap<RelDecorrelator.CorDef, Integer> corDefOutputs) {
        return new RelDecorrelator.Frame(oldRel, newRel, corDefOutputs, oldToNewOutputs);
    }

    private static List<Integer> inputRefIndexes(List<RexNode> projects) {
        final List<Integer> indexes = new ArrayList<>();
        for (RexNode project : projects) {
            indexes.add(((RexInputRef) project).getIndex());
        }
        return indexes;
    }

    /** A decorrelator whose input frame and invocation arguments are controlled by the test. */
    private static final class TestRelDecorrelator extends RelDecorrelator {
        private Frame nextFrame;
        private int invocationCount;
        private RelNode lastInput;
        private boolean lastIsCorVarDefined;
        private boolean lastParentPropagatesNullValues;

        private TestRelDecorrelator() {
            super(new CorelMapBuilder().build(), null, builder());
        }

        @Override
        public Frame getInvoke(
                RelNode r,
                boolean isCorVarDefined,
                RelNode parent,
                boolean parentPropagatesNullValues) {
            invocationCount++;
            lastInput = r;
            lastIsCorVarDefined = isCorVarDefined;
            lastParentPropagatesNullValues = parentPropagatesNullValues;
            return nextFrame;
        }
    }
}
