void returnsNullWhenInputIsNotDecorrelated() {
    final RelBuilder inputBuilder = builder();
    inputBuilder.values(new String[] {"deptno", "name", "salary"}, 10, "Alice", 1000,
            20, "Bob", 2000);
    final Aggregate aggregate =
            (Aggregate)
                    inputBuilder
                            .aggregate(
                                    inputBuilder.groupKey(0),
                                    inputBuilder.countStar("employee_count"))
                            .build();

    final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
    decorrelator.nextFrame = null;

    assertNull(decorrelator.decorrelateRel(aggregate, true, false));
    assertEquals(1, decorrelator.invocationCount);
    assertEquals(aggregate.getInput(), decorrelator.lastInput);
    assertTrue(decorrelator.lastIsCorVarDefined);
    assertEquals(false, decorrelator.lastParentPropagatesNullValues);
}

@Test
void movesGroupKeysToFrontAndRemapsAggregateArguments() {
    final RelBuilder inputBuilder = builder();
    inputBuilder.values(new String[] {"deptno", "name", "salary"}, 10, "Alice", 1000,
            20, "Bob", 2000);
    final Aggregate aggregate =
            (Aggregate)
                    inputBuilder
                            .aggregate(
                                    inputBuilder.groupKey(0, 2),
                                    inputBuilder.count(inputBuilder.field(1)),
                                    inputBuilder.sum(inputBuilder.field(2)))
                            .build();

    System.err.println("OLD INPUT FIELDS=" + aggregate.getInput().getRowType().getFieldCount() + " GROUP=" + aggregate.getGroupSet() + " GROUPLIST=" + aggregate.getGroupSet().asList() + " AGGCALLS=" + aggregate.getAggCallList());
    final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
    decorrelator.nextFrame =
            frame(
                    aggregate.getInput(),
                    aggregate.getInput(),
                    RelDecorrelator.identityMap(
                            aggregate.getInput().getRowType().getFieldCount()),
                    ImmutableSortedMap.of());

    final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, false, true);

    assertNotNull(result);
    System.err.println("OLD INPUT FRAME=" + decorrelator.map.get(aggregate.getInput()).r);
    System.err.println("NEW AGG INPUT=" + result.r.getInputs().get(0));
    final Aggregate newAggregate = assertInstanceOf(Aggregate.class, result.r);
    assertEquals(ImmutableBitSet.of(0, 1), newAggregate.getGroupSet());
    assertEquals(2, newAggregate.getAggCallList().size());

    final LogicalProject newProject =
            assertInstanceOf(LogicalProject.class, newAggregate.getInput());
    assertEquals(Arrays.asList(2, 0, 1), inputRefIndexes(newProject.getProjects()), RelOptUtil.toString(result.r));
    assertEquals(List.of(2, 0), newAggregate.getAggCallList().get(0).getArgList());
    assertEquals(List.of(0), newAggregate.getAggCallList().get(1).getArgList());

    assertEquals(ImmutableSortedMap.of(0, 0, 1, 1, 2, 2, 3, 3), result.oldToNewOutputs);
    assertTrue(result.corDefOutputs.isEmpty());
    assertSame(result, decorrelator.map.get(aggregate));
    assertSame(
            newProject,
            decorrelator.map.get(aggregate.getInput()).r);
}

