        final Aggregate aggregate = aggregate(input, ImmutableBitSet.of(0), null, countCall(input));

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of());

        final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, false, true);

        assertNotNull(result);
        final LogicalProject resultProject = assertInstanceOf(LogicalProject.class, result.r);
        assertEquals(2, resultProject.getRowType().getFieldCount());
        final RexLiteral literal =
                assertInstanceOf(RexLiteral.class, resultProject.getProjects().get(0));
        assertEquals(true, literal.getValueAs(Boolean.class));
        final RexInputRef countRef =
                assertInstanceOf(RexInputRef.class, resultProject.getProjects().get(1));
        assertEquals(0, countRef.getIndex());
        final Aggregate countAggregate =
                assertInstanceOf(Aggregate.class, resultProject.getInput());
        assertEquals(ImmutableBitSet.of(), countAggregate.getGroupSet());
        assertEquals(ImmutableSortedMap.of(0, 0, 1, 1), result.oldToNewOutputs);
        assertTrue(result.corDefOutputs.isEmpty());

        final LogicalProject newInputProject =
                assertInstanceOf(LogicalProject.class, decorrelator.map.get(input).r);
        assertEquals(Arrays.asList(0, 1), inputRefIndexes(newInputProject.getProjects()));
