    @Test
    void omitsConstantGroupKeyAndProjectsItBackAfterAggregation() {
        final RelBuilder inputBuilder = builder();
        inputBuilder.values(new String[] {"deptno", "name"}, 10, "Alice", 20, "Bob");
        inputBuilder.project(inputBuilder.literal(true), inputBuilder.field(0));
        final RelNode input = inputBuilder.build();
        final Aggregate aggregate = aggregate(input, ImmutableBitSet.of(0), null, countCall(input));

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of());

        final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, false, true);

        assertNotNull(result);
        final LogicalProject resultProject = assertInstanceOf(LogicalProject.class, result.r);
        assertEquals(2, resultProject.getRowType().getFieldCount());
        final RexLiteral literal =
                assertInstanceOf(RexLiteral.class, resultProject.getProjects().get(0));
        assertEquals(true, literal.getValueAs(Boolean.class));
        final RexInputRef countRef =
                assertInstanceOf(RexInputRef.class, resultProject.getProjects().get(1));
        assertEquals(0, countRef.getIndex());
        final Aggregate countAggregate =
                assertInstanceOf(Aggregate.class, resultProject.getInput());
        assertEquals(ImmutableBitSet.of(), countAggregate.getGroupSet());
        assertEquals(ImmutableSortedMap.of(0, 0, 1, 1), result.oldToNewOutputs);
        assertTrue(result.corDefOutputs.isEmpty());

    }

    @Test
    void addsCorrelatedVariablesToEveryGroupingSet() {
        final CorrelationId correlationId = new CorrelationId(0);
        final RelBuilder inputBuilder = builder();
        inputBuilder.values(new String[] {"deptno", "name", "salary"}, 10, "Alice", 1000,
                20, "Bob", 2000);
        final RelNode input = inputBuilder.build();
        final Aggregate aggregate =
                aggregate(
                        input,
                        ImmutableBitSet.of(1),
                        ImmutableList.of(ImmutableBitSet.of(1), ImmutableBitSet.of()),
                        countCall(input));
        assertNotEquals(Aggregate.Group.SIMPLE, aggregate.getGroupType());

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        final RelDecorrelator.CorDef corDef =
                new RelDecorrelator.CorDef(correlationId, 0);
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of(corDef, 0));

        final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, true, true);

        assertNotNull(result);
        final LogicalUnion newUnion = assertInstanceOf(LogicalUnion.class, result.r);
        assertEquals(2, newUnion.getInputs().size());
        assertEquals(3, newUnion.getRowType().getFieldCount());
        assertEquals(ImmutableSortedMap.of(0, 0, 1, 2), result.oldToNewOutputs);
        assertEquals(ImmutableSortedMap.of(corDef, 1), result.corDefOutputs);
    }

    @Test
    void rewritesScalarCountAggregateWhenCorrelatedInputDoesNotPropagateNulls() {
        final CorrelationId correlationId = new CorrelationId(0);
        final RelBuilder inputBuilder = builder();
        inputBuilder.values(new String[] {"deptno"}, 10, 20);
        final RelNode input = inputBuilder.build();
        final Aggregate aggregate =
                aggregate(input, ImmutableBitSet.of(), null, countCall(input));

        final RelBuilder outerBuilder = builder();
        outerBuilder.values(new String[] {"deptno"}, 10, 20);
        final RelNode outerInput = outerBuilder.build();
        final RelDecorrelator.Frame outerFrame =
                frame(
                        outerInput,
                        outerInput,
                        RelDecorrelator.identityMap(outerInput.getRowType().getFieldCount()),
                        ImmutableSortedMap.of());

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        final RelDecorrelator.CorDef corDef =
                new RelDecorrelator.CorDef(correlationId, 0);
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of(corDef, 0));
        decorrelator.frameStack.push(Pair.of(correlationId, outerFrame));

        final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, true, true);

        assertNotNull(result);
        final LogicalProject resultProject = assertInstanceOf(LogicalProject.class, result.r);
        assertEquals(2, resultProject.getRowType().getFieldCount());
        assertInstanceOf(RexInputRef.class, resultProject.getProjects().get(0));
        final RexCall countCase =
                assertInstanceOf(RexCall.class, resultProject.getProjects().get(1));
        assertEquals(SqlStdOperatorTable.CASE, countCase.getOperator());
        assertInstanceOf(Join.class, resultProject.getInput());
        assertEquals(ImmutableSortedMap.of(0, 1), result.oldToNewOutputs);
        assertEquals(ImmutableSortedMap.of(corDef, 0), result.corDefOutputs);
    }

    private static RelBuilder builder() {
        final RelOptCluster cluster =
                RelOptCluster.create(
                        new HepPlanner(HepProgram.builder().build()),
                        new RexBuilder(new JavaTypeFactoryImpl()));
        return RelBuilder.proto(Contexts.of(RelBuilder.Config.DEFAULT))
                .create(cluster, null);
    }

    private static Aggregate aggregate(
            RelNode input,
            ImmutableBitSet groupSet,
            List<ImmutableBitSet> groupSets,
            AggregateCall... aggregateCalls) {
        return LogicalAggregate.create(
                input, groupSet, groupSets, Arrays.asList(aggregateCalls));
    }

    private static AggregateCall countCall(RelNode input) {
        return AggregateCall.create(
                SqlStdOperatorTable.COUNT,
                false,
                ImmutableList.of(),
                -1,
                input,
                input.getCluster()
                        .getTypeFactory()
                        .createSqlType(SqlTypeName.BIGINT),
                "employee_count");
    }

    private static AggregateCall sumCall(RelNode input, int field, String name) {
        return AggregateCall.create(
                SqlStdOperatorTable.SUM,
                false,
                ImmutableList.of(field),
                -1,
                input,
                input.getRowType().getFieldList().get(field).getType(),
                name);
    }

    private static RelDecorrelator.Frame frame(
            RelNode oldRel,
            RelNode newRel,
            Map<Integer, Integer> oldToNewOutputs,
            NavigableMap<RelDecorrelator.CorDef, Integer> corDefOutputs) {
        return new RelDecorrelator.Frame(oldRel, newRel, corDefOutputs, oldToNewOutputs);
    }

    private static List<Integer> inputRefIndexes(List<RexNode> projects) {
        final List<Integer> indexes = new ArrayList<>();
        for (RexNode project : projects) {
            indexes.add(((RexInputRef) project).getIndex());
        }
        return indexes;
    }

    /** A decorrelator whose input frame and invocation arguments are controlled by the test. */
    private static final class TestRelDecorrelator extends RelDecorrelator {
        private Frame nextFrame;
        private int invocationCount;
        private RelNode lastInput;
        private boolean lastIsCorVarDefined;
        private boolean lastParentPropagatesNullValues;

        private TestRelDecorrelator() {
            super(new CorelMapBuilder().build(), null, builder());
        }

        @Override
        public Frame getInvoke(
                RelNode r,
                boolean isCorVarDefined,
                RelNode parent,
                boolean parentPropagatesNullValues) {
            invocationCount++;
            lastInput = r;
            lastIsCorVarDefined = isCorVarDefined;
            lastParentPropagatesNullValues = parentPropagatesNullValues;
            return nextFrame;
        }
    }
}

