                new String[] {"deptno", "name", "salary"}, 10, "Alice", 1000, 20, "Bob", 2000);
        final RelNode input = inputBuilder.build();
        final Aggregate aggregate =
                aggregate(
                        input,
                        ImmutableBitSet.of(0, 2),
                        null,
                        countCall(input),
                        sumCall(input, 2, "sum_salary"));

        final TestRelDecorrelator decorrelator = new TestRelDecorrelator();
        decorrelator.nextFrame =
                frame(
                        input,
                        input,
                        RelDecorrelator.identityMap(input.getRowType().getFieldCount()),
                        ImmutableSortedMap.of());

        final RelDecorrelator.Frame result = decorrelator.decorrelateRel(aggregate, false, true);

        assertNotNull(result);
        final Aggregate newAggregate = assertInstanceOf(Aggregate.class, result.r);
        assertEquals(ImmutableBitSet.of(0, 1), newAggregate.getGroupSet());
        assertEquals(2, newAggregate.getAggCallList().size());
        assertTrue(newAggregate.getAggCallList().get(0).getArgList().isEmpty());
        assertEquals(List.of(1), newAggregate.getAggCallList().get(1).getArgList());

        final LogicalProject newProject =
                assertInstanceOf(LogicalProject.class, decorrelator.map.get(input).r);
        assertEquals(Arrays.asList(0, 2, 1), inputRefIndexes(newProject.getProjects()));

        assertEquals(ImmutableSortedMap.of(0, 0, 1, 1, 2, 2, 3, 3), result.oldToNewOutputs);
        assertTrue(result.corDefOutputs.isEmpty());
        assertSame(result, decorrelator.map.get(aggregate));
        assertSame(newProject, decorrelator.map.get(input).r);
    }

