import org.apache.calcite.rel.core.JoinRelType;
import org.apache.calcite.rel.logical.LogicalCorrelate;
import org.apache.calcite.rel.type.RelDataType;
import org.apache.calcite.rel.type.RelDataTypeFactory;
import org.apache.calcite.rel.type.RelDataTypeSystem;
import org.apache.calcite.rex.RexBuilder;
import org.apache.calcite.rex.RexNode;
import org.apache.calcite.sql.type.SqlTypeFactoryImpl;
import org.apache.calcite.sql.type.SqlTypeName;
import org.apache.calcite.tools.RelBuilder;
import org.apache.calcite.util.ImmutableBitSet;

import org.junit.jupiter.api.Test;

/** Exploratory test. */
public class RelDecorrelatorOnMatchTests {

    private RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);

    @Test
    void explore() {
        VolcanoPlanner volcanoPlanner = new VolcanoPlanner(RelOptCostImpl.FACTORY, Contexts.empty());
        volcanoPlanner.addRelTraitDef(ConventionTraitDef.INSTANCE);
        RelOptCluster cluster = RelOptCluster.create(volcanoPlanner, new RexBuilder(typeFactory));
        RelBuilder relBuilder =
                RelBuilder.proto(Contexts.of(RelBuilder.Config.DEFAULT.withSimplify(false)))
                        .create(cluster, null);

        RelNode leftValues = relBuilder.values(new String[]{"a", "b"}, 1, 2, 3, 4).build();
        RelNode left = relBuilder.push(leftValues).aggregate(relBuilder.groupKey(0, 1)).build();

        RelNode rightInput = relBuilder.values(new String[]{"x"}, 10, 20).build();
        CorrelationId corId = cluster.createCorrelateId();
        RelDataType corVarRowType =
                typeFactory.builder().add("$f0", SqlTypeName.BIGINT).build();
        RexNode corVar = relBuilder.getRexBuilder().makeCorrel(corVarRowType, corId);
        RexNode fieldAccess = relBuilder.getRexBuilder().makeFieldAccess(corVar, 0);
        RelNode aggInputProject = relBuilder.push(rightInput).project(fieldAccess).build();
        RelNode aggregate =
                relBuilder
                        .push(aggInputProject)
                        .aggregate(relBuilder.groupKey(), relBuilder.countStar("c"))
                        .build();
        RelNode aggOutputProject = relBuilder.push(aggregate).project(relBuilder.field(0)).build();
        RelNode correlate =
                LogicalCorrelate.create(
                        left, aggOutputProject, corId, ImmutableBitSet.of(0), JoinRelType.LEFT);

        System.out.println("=== INPUT ===");
        System.out.println(RelOptUtil.toString(correlate));

        RelDecorrelator.CorelMap cm =
                new RelDecorrelator.CorelMapBuilder().build(correlate);
        System.out.println("mapRefRelToCorRef = " + cm.mapRefRelToCorRef.keySet());
        System.out.println("mapFieldAccessToCorRef = " + cm.mapFieldAccessToCorRef);
        System.out.println("mapCorToCorRel = " + cm.mapCorToCorRel);

        RelDecorrelator d = new RelDecorrelator(cm, Contexts.empty(), relBuilder);
        HepProgram program =
                HepProgram.builder()
                        .addRuleInstance(
                                RelDecorrelator.RemoveCorrelationForScalarAggregateRule.DEFAULT
                                        .toRule())
                        .build();
        HepPlanner planner = new HepPlanner(program, Contexts.empty(), true, null, RelOptCostImpl.FACTORY);
        planner.setDecorrelator(d);
        planner.setRoot(correlate);
        RelNode out = planner.findBestExp();
        System.out.println("=== OUTPUT ===");
        System.out.println(RelOptUtil.toString(out));
        System.out.println("classes: ");
        out.childrenAccept(
                new org.apache.calcite.rel.RelShuttleImpl() {
                    @Override
                    public RelNode visit(RelNode other) {
                        System.out.println("  " + other.getClass().getSimpleName());
                        return super.visit(other);
                    }
                },
                null);
    }
