/**
 * Tests for {@link RelDecorrelator.RemoveCorrelationForScalarAggregateRule#onMatch}, which rewrites
 * a {@code Correlate} over a "scalar" aggregate (an aggregate without grouping keys, whose input
 * references the correlation variable) into a {@code LEFT OUTER JOIN} followed by an aggregate over
 * the left input columns.
 */
public class RelDecorrelatorOnMatchTests {

    private RelDataTypeFactory typeFactory;
    private RelOptCluster cluster;
    private RexBuilder rexBuilder;
    private RelBuilder relBuilder;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        VolcanoPlanner volcanoPlanner =
                new VolcanoPlanner(RelOptCostImpl.FACTORY, Contexts.empty());
        volcanoPlanner.addRelTraitDef(ConventionTraitDef.INSTANCE);
        cluster = RelOptCluster.create(volcanoPlanner, new RexBuilder(typeFactory));
        relBuilder =
                RelBuilder.proto(Contexts.of(RelBuilder.Config.DEFAULT.withSimplify(false)))
                        .create(cluster, null);
        rexBuilder = relBuilder.getRexBuilder();
    }

    // ------------------------------------------------------------------
    // Tests that expect a rewrite
    // ------------------------------------------------------------------

    /**
     * {@code count(*)} is rewritten into {@code count(nullIndicator)}, where the null indicator is
     * the "true" literal that is projected on the right side of the generated join.
     */
    @Test
    void testCountStarIsRewrittenToCountOfNullIndicator() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RexNode corFieldAccess = corVarFieldAccess(corId, 0);

        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corFieldAccess),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        RelNode out = applyRule(input);
        assertFalse(containsCorrelate(out), () -> "correlation was not removed:\n" + plan(out));

        Project topProject = as(out, Project.class);
        Aggregate aggregate = as(topProject.getInput(), Aggregate.class);
        assertEquals(ImmutableBitSet.range(2), aggregate.getGroupSet());
        assertEquals(1, aggregate.getAggCallList().size());

        AggregateCall aggCall = aggregate.getAggCallList().get(0);
        assertSame(SqlStdOperatorTable.COUNT, aggCall.getAggregation());
        assertEquals(1, aggCall.getArgList().size());

        // the aggregate input is a projection over the join
        Project joinOutputProject = as(aggregate.getInput(), Project.class);
        Join join = as(joinOutputProject.getInput(), Join.class);
        assertEquals(JoinRelType.LEFT, join.getJoinType());
        assertTrue(join.getCondition().isAlwaysTrue(), "join condition should be 'true'");

        // count(*) must count the null indicator of the join, i.e. its last column
        int nullIndicatorIndex = join.getRowType().getFieldCount() - 1;
        RexNode counted = joinOutputProject.getProjects().get(aggCall.getArgList().get(0));
        assertTrue(
                counted instanceof RexInputRef,
                () -> "count argument should be the null indicator, but was " + counted);
        assertEquals(nullIndicatorIndex, ((RexInputRef) counted).getIndex());

        // the right side of the join gets the "true" literal as null indicator
        Project rightProject = as(join.getRight(), Project.class);
        RelDataType rightRowType = rightProject.getRowType();
        assertEquals("nullIndicator", rightRowType.getFieldNames().get(nullIndicatorIndex - 2));
        assertEquals(3, rightRowType.getFieldCount());
        RexLiteral indicator = as(rightProject.getProjects().get(2), RexLiteral.class);
        assertTrue(indicator.isAlwaysTrue());
    }

    /**
     * The rewrite keeps all left input columns as grouping keys and casts the aggregate result to
     * a nullable type, because the aggregate may produce no row at all.
     */
    @Test
    void testRewriteOutputRowTypeMatchesCorrelate() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(corId, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        RelNode out = applyRule(input);

        assertEquals(input.getRowType().getFieldCount(), out.getRowType().getFieldCount());
        assertEquals(input.getRowType().getFieldNames(), out.getRowType().getFieldNames());
        assertTrue(out.getRowType().getFieldList().get(2).getType().isNullable());
        assertSame(
                input.getRowType(),
                org.apache.calcite.plan.RelOptUtil.verifyTypeEquivalence(input, out, input));

        Project topProject = as(out, Project.class);
        assertEquals(3, topProject.getProjects().size());
        RexNode cast = topProject.getProjects().get(2);
        assertTrue(cast instanceof RexCall);
        assertEquals(SqlKind.CAST, ((RexCall) cast).getKind());
    }

    /**
     * A correlated field which is aggregated (instead of merely counted) is rewritten into a
     * {@code CASE} expression which turns the value into {@code NULL} when the join did not match.
     */
    @Test
    void testAggregatedCorrelatedFieldBecomesNullSafeExpression() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(corId, 0)),
                        ImmutableBitSet.of(),
                        sum(0, "s"),
                        JoinRelType.LEFT);

        RelNode out = applyRule(input);
        assertFalse(containsCorrelate(out), () -> "correlation was not removed:\n" + plan(out));

        Aggregate aggregate = as(as(out, Project.class).getInput(), Aggregate.class);
        assertEquals(ImmutableBitSet.range(2), aggregate.getGroupSet());
        assertEquals(1, aggregate.getAggCallList().size());
        AggregateCall aggCall = aggregate.getAggCallList().get(0);
        assertSame(SqlStdOperatorTable.SUM, aggCall.getAggregation());
        assertEquals(1, aggCall.getArgList().size());

        Project joinOutputProject = as(aggregate.getInput(), Project.class);
        Join join = as(joinOutputProject.getInput(), Join.class);
        int nullIndicatorIndex = join.getRowType().getFieldCount() - 1;

        RexNode aggregated = joinOutputProject.getProjects().get(aggCall.getArgList().get(0));
        assertTrue(aggregated instanceof RexCall, () -> "unexpected expression " + aggregated);
        RexCall caseCall = (RexCall) aggregated;
        assertEquals(SqlKind.CASE, caseCall.getKind());

        RexCall isNull = as(caseCall.getOperands().get(0), RexCall.class);
        assertEquals(SqlKind.IS_NULL, isNull.getKind());
        RexInputRef indicatorRef = as(isNull.getOperands().get(0), RexInputRef.class);
        assertEquals(nullIndicatorIndex, indicatorRef.getIndex());
    }

    /** Multiple aggregate calls are all rewritten in one go. */
    @Test
    void testMultipleAggregateCallsAreRewritten() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(corId, 0)),
                        ImmutableBitSet.of(),
                        ImmutableList.of(sum(0, "s"), countStar("c")),
                        JoinRelType.LEFT);

        RelNode out = applyRule(input);
        assertFalse(containsCorrelate(out), () -> "correlation was not removed:\n" + plan(out));

        Aggregate aggregate = as(as(out, Project.class).getInput(), Aggregate.class);
        assertEquals(ImmutableBitSet.range(2), aggregate.getGroupSet());
        assertEquals(2, aggregate.getAggCallList().size());

        Project joinOutputProject = as(aggregate.getInput(), Project.class);
        Join join = as(joinOutputProject.getInput(), Join.class);
        int nullIndicatorIndex = join.getRowType().getFieldCount() - 1;

        AggregateCall sumCall = aggregate.getAggCallList().get(0);
        assertSame(SqlStdOperatorTable.SUM, sumCall.getAggregation());
        assertEquals(SqlKind.CASE, joinOutputProject.getProjects()
                .get(sumCall.getArgList().get(0)).getKind());

        AggregateCall countCall = aggregate.getAggCallList().get(1);
        assertSame(SqlStdOperatorTable.COUNT, countCall.getAggregation());
        RexNode counted = joinOutputProject.getProjects().get(countCall.getArgList().get(0));
        assertTrue(counted instanceof RexInputRef);
        assertEquals(nullIndicatorIndex, ((RexInputRef) counted).getIndex());
    }

    /**
     * When the right input of the aggregate projection is a filter that references the correlation
     * variable, the filter condition is turned into the join condition.
     */
    @Test
    void testCorrelatedFilterBecomesJoinCondition() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RexNode corFieldAccess = corVarFieldAccess(corId, 0);
        RelNode rightInput = values(new String[] {"y"}, 10, 20);
        RelNode filter =
                LogicalFilter.create(
                        rightInput,
                        rexBuilder.makeCall(
                                SqlStdOperatorTable.EQUALS,
                                rexBuilder.makeInputRef(rightInput, 0),
                                corFieldAccess));

        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        filter,
                        ImmutableList.of(rexBuilder.makeInputRef(filter, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        RelNode out = applyRule(input);
        assertFalse(containsCorrelate(out), () -> "correlation was not removed:\n" + plan(out));

        Aggregate aggregate = as(as(out, Project.class).getInput(), Aggregate.class);
        Join join = as(as(aggregate.getInput(), Project.class).getInput(), Join.class);
        assertEquals(JoinRelType.LEFT, join.getJoinType());

        // the correlated filter condition "y = $cor0.f0" became "$2 = $0" (the right input column
        // offset by the number of left input columns, and the correlation replaced by the matching
        // left input column)
        RexNode condition = join.getCondition();
        assertFalse(condition.isAlwaysTrue(), () -> "join condition was not derived: " + condition);
        assertTrue(condition instanceof RexCall);
        RexCall equals = (RexCall) condition;
        assertEquals(SqlKind.EQUALS, equals.getKind());
        assertEquals(2, equals.getOperands().size());
        assertEquals(2, as(equals.getOperands().get(0), RexInputRef.class).getIndex());
        assertEquals(0, as(equals.getOperands().get(1), RexInputRef.class).getIndex());
    }

    // ------------------------------------------------------------------
    // Tests that expect the rule not to fire
    // ------------------------------------------------------------------

    /** An aggregate with grouping keys is not a scalar aggregate. */
    @Test
    void testNoRewriteWhenAggregateHasGroupingKeys() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode rightInput = values(new String[] {"x"}, 10, 20);
        RelNode aggInputProject =
                project(rightInput, ImmutableList.of(corVarFieldAccess(corId, 0)), "$f0");
        AggregateCall aggCall = countStar("c");
        RelNode aggregate =
                LogicalAggregate.create(
                        aggInputProject,
                        ImmutableBitSet.of(0),
                        null,
                        ImmutableList.of(aggCall));
        RelNode aggOutputProject =
                project(aggregate, ImmutableList.of(rexBuilder.makeInputRef(aggregate, 1)), "c");
        RelNode input =
                LogicalCorrelate.create(
                        left, aggOutputProject, corId, ImmutableBitSet.of(0), JoinRelType.LEFT);

        assertNoRewrite(input);
    }

    /** The projection above the aggregate must project exactly one expression. */
    @Test
    void testNoRewriteWhenAggregateOutputProjectionHasTwoExpressions() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode rightInput = values(new String[] {"x"}, 10, 20);
        RelNode aggInputProject =
                project(rightInput, ImmutableList.of(corVarFieldAccess(corId, 0)), "$f0");
        RelNode aggregate =
                LogicalAggregate.create(
                        aggInputProject,
                        ImmutableBitSet.of(0),
                        null,
                        ImmutableList.of(countStar("c")));
        RelNode aggOutputProject =
                project(
                        aggregate,
                        ImmutableList.of(
                                rexBuilder.makeInputRef(aggregate, 0),
                                rexBuilder.makeInputRef(aggregate, 1)),
                        ImmutableList.of("k", "c"));
        RelNode input =
                LogicalCorrelate.create(
                        left, aggOutputProject, corId, ImmutableBitSet.of(0), JoinRelType.LEFT);

        assertNoRewrite(input);
    }

    /** Only left outer (scalar) correlates can be rewritten. */
    @Test
    void testNoRewriteWhenCorrelateIsNotLeftOuter() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(corId, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.INNER);

        assertNoRewrite(input);
    }

    /** Grouping by all left input columns requires them to be unique. */
    @Test
    void testNoRewriteWhenLeftInputIsNotKnownToBeUnique() {
        // the left input is a plain Values; its uniqueness is unknown
        RelNode left = values(new String[] {"a", "b"}, 1, 2, 3, 4);
        CorrelationId corId = cluster.createCorrel();
        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(corId, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        assertNoRewrite(input);
    }

    /** The right input below the correlated projection must not contain correlations itself. */
    @Test
    void testNoRewriteWhenRightInputIsCorrelated() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RexNode corFieldAccess = corVarFieldAccess(corId, 0);
        RelNode rightInput = values(new String[] {"x"}, 10, 20);
        // a correlated projection which is not a filter, hence the "filter" branch is not taken
        RelNode correlatedRight =
                project(
                        rightInput,
                        ImmutableList.of(rexBuilder.makeInputRef(rightInput, 0), corFieldAccess),
                        ImmutableList.of("x", "cor"));

        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        correlatedRight,
                        ImmutableList.of(corFieldAccess),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        assertNoRewrite(input);
    }

    /** The correlation variable must be provided by the matched correlate. */
    @Test
    void testNoRewriteWhenCorrelationVariableComesFromAnotherCorrelate() {
        CorrelationId innerCorId = cluster.createCorrel();
        CorrelationId outerCorId = cluster.createCorrel();

        RelNode innerLeft = values(new String[] {"a", "b"}, 1, 2);
        RelNode innerRight =
                project(
                        values(new String[] {"c"}, 3),
                        ImmutableList.of(rexBuilder.makeInputRef(values(new String[] {"c"}, 3), 0)),
                        "c");
        RelNode innerCorrelate =
                LogicalCorrelate.create(
                        innerLeft,
                        LogicalProject.create(
                                innerLeft,
                                ImmutableList.of(),
                                ImmutableList.of(rexBuilder.makeInputRef(innerLeft, 0)),
                                ImmutableList.of("a")),
                        innerCorId,
                        ImmutableBitSet.of(0),
                        JoinRelType.LEFT);
        // group by all columns of the inner correlate so that uniqueness holds
        RelNode left =
                LogicalAggregate.create(
                        innerCorrelate, ImmutableBitSet.of(0, 1), null, ImmutableList.of());

        RelNode input =
                scalarAggregate(
                        left,
                        outerCorId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(innerCorId, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        assertTrue(innerRight != null);
        assertNoRewrite(input);
    }

    /** Without any correlation variable in the aggregate input there is nothing to rewrite. */
    @Test
    void testNoRewriteWhenAggregateInputIsNotCorrelated() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode rightInput = values(new String[] {"x"}, 10, 20);

        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        rightInput,
                        ImmutableList.of(rexBuilder.makeInputRef(rightInput, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

        assertNoRewrite(input);
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    /** Runs only {@code RemoveCorrelationForScalarAggregateRule} on the given plan. */
    private RelNode applyRule(RelNode root) {
        RelDecorrelator.CorelMap cm = new RelDecorrelator.CorelMapBuilder().build(root);
        RelDecorrelator decorrelator = new RelDecorrelator(cm, Contexts.empty(), relBuilder);
        HepProgram program =
                HepProgram.builder()
                        .addRuleInstance(
                                RelDecorrelator.RemoveCorrelationForScalarAggregateRule.DEFAULT
                                        .toRule())
                        .build();
        HepPlanner planner =
                new HepPlanner(program, Contexts.empty(), true, null, RelOptCostImpl.FACTORY);
        planner.setDecorrelator(decorrelator);
        planner.setRoot(root);
        return planner.findBestExp();
    }

    private void assertNoRewrite(RelNode input) {
        RelNode out = applyRule(input);
        assertNotNull(
                findFirst(out, Correlate.class),
                () -> "rule should not have fired, but plan changed to:\n" + plan(out));
        assertEquals(plan(input), plan(out));
    }

    private RelNode uniqueLeft() {
        RelNode values = values(new String[] {"a", "b"}, 1, 2, 3, 4);
        return LogicalAggregate.create(values, ImmutableBitSet.of(0, 1), null, ImmutableList.of());
    }

    private RelNode values(String[] names, Object... values) {
        RelDataTypeFactory.Builder builder = typeFactory.builder();
        for (String name : names) {
            builder.add(name, SqlTypeName.INTEGER);
        }
        RelDataType rowType = builder.build();
        ImmutableList.Builder<ImmutableList<RexLiteral>> tuples = ImmutableList.builder();
        int fieldCount = names.length;
        for (int i = 0; i < values.length; i += fieldCount) {
            ImmutableList.Builder<RexLiteral> tuple = ImmutableList.builder();
            for (int j = 0; j < fieldCount; j++) {
                tuple.add(
                        rexBuilder.makeExactLiteral(
                                BigDecimal.valueOf(((Integer) values[i + j]).longValue())));
            }
            tuples.add(tuple.build());
        }
        return LogicalValues.create(cluster, rowType, tuples.build());
    }

    private RexNode corVarFieldAccess(CorrelationId corId, int field) {
        RelDataType corVarRowType = typeFactory.builder().add("$f", SqlTypeName.INTEGER).build();
        RexNode corVar = rexBuilder.makeCorrel(corVarRowType, corId);
        return rexBuilder.makeFieldAccess(corVar, field);
    }

    private RelNode project(RelNode input, List<RexNode> projects, String fieldName) {
        return LogicalProject.create(
                input, ImmutableList.of(), projects, ImmutableList.of(fieldName));
    }

    private static AggregateCall countStar(String name) {
        throw new UnsupportedOperationException();
    }

    private AggregateCall countStar(AggregateCall call) {
        return call;
    }

    private AggregateCall sum(int argIndex, String name) {
        return AggregateCall.create(
                SqlStdOperatorTable.SUM,
                false,
                ImmutableList.of(argIndex),
                -1,
                typeFactory.createTypeWithNullability(
                        typeFactory.createSqlType(SqlTypeName.BIGINT), false),
                name);
    }

    /** Builds {@code Correlate(left, Project-A(Aggregate(Project-B(rightInput))))}. */
    private RelNode scalarAggregate(
            RelNode left,
            CorrelationId corId,
            RelNode rightInput,
            List<RexNode> aggInputProjects,
            ImmutableBitSet groupSet,
            AggregateCall aggCall,
            JoinRelType joinType) {
        return scalarAggregate(
                left,
                corId,
                rightInput,
                aggInputProjects,
                groupSet,
                ImmutableList.of(aggCall),
                ImmutableList.of(0),
                joinType);
    }

    private RelNode scalarAggregate(
            RelNode left,
            CorrelationId corId,
            RelNode rightInput,
            List<RexNode> aggInputProjects,
            ImmutableBitSet groupSet,
            List<AggregateCall> aggCalls,
            List<Integer> projectIndexes,
            JoinRelType joinType) {
        List<String> aggInputNames = new ArrayList<>();
        for (int i = 0; i < aggInputProjects.size(); i++) {
            aggInputNames.add("$f" + i);
        }
        RelNode aggInputProject =
                LogicalProject.create(
                        rightInput, ImmutableList.of(), aggInputProjects, aggInputNames);
        RelNode aggregate = LogicalAggregate.create(aggInputProject, groupSet, null, aggCalls);
        List<RexNode> outputProjects = new ArrayList<>();
        List<String> outputNames = new ArrayList<>();
        for (int i : projectIndexes) {
            outputProjects.add(rexBuilder.makeInputRef(aggregate, i));
            outputNames.add("out" + i);
        }
        RelNode aggOutputProject =
                LogicalProject.create(
                        aggregate, ImmutableList.of(), outputProjects, outputNames);
        return LogicalCorrelate.create(
                left, aggOutputProject, corId, ImmutableBitSet.of(0), joinType);
    }

    private static String plan(RelNode rel) {
        return RelOptUtil.toString(rel);
    }

    private static <T extends RelNode> T as(RelNode rel, Class<T> clazz) {
        assertTrue(
                clazz.isInstance(rel),
                () -> "expected " + clazz.getSimpleName() + " but was " + rel.getClass());
        return clazz.cast(rel);
    }

    private static RelNode findFirst(RelNode root, Class<? extends RelNode> clazz) {
        if (clazz.isInstance(root)) {
            return root;
        }
        for (RelNode input : root.getInputs()) {
            RelNode result = findFirst(input, clazz);
            if (result != null) {
                return result;
            }
        }
        return null;
    }

    private static boolean containsCorrelate(RelNode root) {
        return findFirst(root, Correlate.class) != null;
    }
}
