    @Test
    void testCountStarIsRewrittenToCountOfNullIndicator() {
        RelNode left = uniqueLeft();
        CorrelationId corId = cluster.createCorrel();
        RelNode input =
                scalarAggregate(
                        left,
                        corId,
                        values(new String[] {"x"}, 10, 20),
                        ImmutableList.of(corVarFieldAccess(corId, 0)),
                        ImmutableBitSet.of(),
                        countStar("c"),
                        JoinRelType.LEFT);

