    private void checkConvertedType(SqlNode query, RelNode result, boolean unwrapMeasures) {
        if (query.isA(SqlKind.DML)) {
            return;
        }
        // Verify that conversion from SQL to relational algebra did
        // not perturb any type information.  (We can't do this if the
        // SQL statement is something like an INSERT which has no
        // validator type information associated with its result,
        // hence the namespace check above.)
        final List<RelDataTypeField> validatedFields =
                validator().getValidatedNodeType(query).getFieldList();
        final RelDataType validatedRowType =
                validator()
                        .getTypeFactory()
                        .createStructType(
                                transform(
                                        validatedFields,
                                        unwrapMeasures
                                                ? f -> fromMeasure(typeFactory, f.getType())
                                                : RelDataTypeField::getType),
                                SqlValidatorUtil.uniquify(
                                        Pair.left(validatedFields),
                                        catalogReader.nameMatcher().isCaseSensitive()));

        final List<RelDataTypeField> convertedFields =
                result.getRowType().getFieldList().subList(0, validatedFields.size());
        final RelDataType convertedRowType =
                validator().getTypeFactory().createStructType(convertedFields);

        if (!RelOptUtil.equal(
                "validated row type",
                validatedRowType,
                "converted row type",
                convertedRowType,
                Litmus.IGNORE)) {
            throw new AssertionError(
                    "Conversion to relational algebra failed to "
                            + "preserve datatypes:\n"
                            + "validated type:\n"
                            + validatedRowType.getFullTypeString()
                            + "\nconverted type:\n"
                            + convertedRowType.getFullTypeString()
                            + "\nrel:\n"
                            + RelOptUtil.toString(result));
        }
    }

