import java.util.List;

/** Scratch harness. */
public class Harness {

    static RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);

    static CalciteSchema schema() {
        CalciteSchema root = CalciteSchema.createRootSchema(false, false, "root");
        root.add("EMP", emp());
        root.add("DEPT", dept());
        return root;
    }

    static AbstractTable emp() {
        return new AbstractTable() {
            @Override
            public RelDataType getRowType(RelDataTypeFactory tf) {
                return tf.builder()
                        .add("EMPNO", tf.createSqlType(SqlTypeName.INTEGER))
                        .add("ENAME", tf.createSqlType(SqlTypeName.VARCHAR, 10))
                        .add("DEPTNO", tf.createSqlType(SqlTypeName.INTEGER))
                        .build();
            }
        };
    }

    static AbstractTable dept() {
        return new AbstractTable() {
            @Override
            public RelDataType getRowType(RelDataTypeFactory tf) {
                return tf.builder()
                        .add("DEPTNO", tf.createSqlType(SqlTypeName.INTEGER))
                        .add("NAME", tf.createSqlType(SqlTypeName.VARCHAR, 10))
                        .build();
            }
        };
    }

    static class TestConverter extends SqlToRelConverter {
        TestConverter(
                SqlValidator validator, Prepare.CatalogReader catalogReader, RelOptCluster cluster) {
            super(
                    new RelOptTable.ViewExpander() {
                        @Override
                        public RelRoot expandView(
                                RelDataType rowType,
                                String queryString,
                                List<String> schemaPath,
                                List<String> viewPath) {
                            throw new UnsupportedOperationException();
                        }
                    },
                    validator,
                    catalogReader,
                    cluster,
                    SqlToRelConverter.config().getConvertletTable(),
                    SqlToRelConverter.config());
        }

        Blackboard newBlackboard(SqlValidatorScope scope, boolean top) {
            return createBlackboard(scope, null, top);
        }

        void callConvertFrom(Blackboard bb, SqlNode from) {
            convertFrom(bb, from);
        }

        void callConvertFrom(Blackboard bb, SqlNode from, List<String> fieldNames) {
            convertFrom(bb, from, fieldNames);
        }
    }

    static class Ctx {
        final SqlValidator validator;
        final Prepare.CatalogReader catalogReader;
        final TestConverter converter;
        final RelOptCluster cluster;
        final CalciteSchema schema;

        Ctx() {
            schema = schema();
            catalogReader =
                    new CalciteCatalogReader(
                            schema,
                            Collections.emptyList(),
                            typeFactory,
                            CalciteConnectionConfig.DEFAULT);
            validator =
                    SqlValidatorUtil.newValidator(
                            SqlStdOperatorTable.instance(),
                            catalogReader,
                            typeFactory,
                            SqlValidator.Config.DEFAULT);
            cluster =
                    RelOptCluster.create(
                            new HepPlanner(new HepProgramBuilder().build()),
                            new RexBuilder(typeFactory));
            converter = new TestConverter(validator, catalogReader, cluster);
        }

        SqlNode parseAndValidate(String sql) {
            try {
                SqlNode parsed =
                        SqlParser.create(
                                        sql,
                                        SqlParser.config()
                                                .withParserFactory(
                                                        org.apache.flink.sql.parser.impl
                                                                .FlinkSqlParserImpl.FACTORY))
                                .parseQuery();
                return validator.validate(parsed);
            } catch (Exception e) {
                throw new RuntimeException("failed to parse/validate: " + sql, e);
            }
        }
    }

    static void show(String label, RelNode rel) {
        System.out.println("=== " + label + " ===");
        System.out.println(rel == null ? "null" : RelOptUtil.toString(rel));
        System.out.println(rel == null ? "" : "rowType=" + rel.getRowType());
    }

    public static void main(String[] args) throws Exception {
        Ctx ctx = new Ctx();
        System.out.println("harness created");

        // null from
        {
            SqlNode validated = ctx.parseAndValidate("select * from emp");
            org.apache.calcite.sql.SqlSelect select =
                    (org.apache.calcite.sql.SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, true);
            ctx.converter.callConvertFrom(bb, null);
            show("null from", bb.root);
            System.out.println("top=" + bb.top);
        }

        // identifier
        {
            SqlNode validated = ctx.parseAndValidate("select * from emp");
            org.apache.calcite.sql.SqlSelect select =
                    (org.apache.calcite.sql.SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, true);
            ctx.converter.callConvertFrom(bb, select.getFrom());
            show("identifier", bb.root);
        }
    }
}
