import org.apache.calcite.sql.SqlNodeList;
import org.apache.calcite.sql.SqlSelect;
import org.apache.calcite.sql.SqlTableRef;
import org.apache.calcite.sql.SqlWith;
import org.apache.calcite.sql.SqlWithItem;
import org.apache.calcite.sql.parser.SqlParserPos;
import org.apache.calcite.sql.validate.SqlValidatorScope;
import org.apache.calcite.sql2rel.SqlToRelConverter.Blackboard;

import java.util.Collections;

/** Scratch harness 3. */
public class Harness3 {

    static void show(String label, Harness.Ctx ctx, Blackboard bb) {
        RelNode root = bb.root;
        System.out.println(label + " -> " + (root == null ? "null" : RelOptUtil.toString(root)));
        System.out.println("   leaves=" + ctx.converter.leaves.keySet().stream()
                .map(Object::toString).reduce("", (a, b) -> a + "|" + b));
        System.out.println("   rootInLeaves=" + (root != null && ctx.converter.leaves.containsKey(root)));
        if (root instanceof Hintable) {
            System.out.println("   hints=" + ((Hintable) root).getHints());
        }
    }

    public static void main(String[] args) throws Exception {
        Harness.Ctx ctx = new Harness.Ctx();

        // 1. AS + containsQueryHints
        {
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM emp AS e");
            SqlSelect select = (SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.containsQueryHints();
            ctx.converter.callConvertFrom(bb, select.getFrom());
            show("as-with-hints", ctx, bb);
            RelHint h = ((Hintable) bb.root).getHints().get(0);
            System.out.println("   hintName=" + h.hintName + " options=" + h.listOptions);
        }

        // 2. AS + containsQueryHints but root not hintable (VALUES)
        {
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM (VALUES (1)) AS v(id)");
            SqlSelect select = (SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.containsQueryHints();
            ctx.converter.callConvertFrom(bb, select.getFrom());
            show("as-with-hints-on-values", ctx, bb);
        }

        // 3. TableRef
        {
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM emp AS e");
            SqlSelect select = (SqlSelect) validated;
            SqlIdentifier id = (SqlIdentifier) select.getFrom();
            SqlTableRef tableRef = new SqlTableRef(SqlParserPos.ZERO, id, SqlNodeList.EMPTY);
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, tableRef);
            show("table-ref", ctx, bb);
        }

        // 4. WITH item node
        {
            SqlNode validated = ctx.parseAndValidate("WITH t AS (SELECT empno FROM emp) SELECT * FROM t");
            SqlWith with = (SqlWith) validated;
            SqlWithItem item = (SqlWithItem) with.withList.get(0);
            SqlValidatorScope scope = ((SqlSelect) with.body).getFrom() != null
                    ? ctx.validator.getSelectScope((SqlSelect) with.body) : null;
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, item);
            show("with-item", ctx, bb);
        }

        // 5. WITH node
        {
            SqlNode validated = ctx.parseAndValidate("WITH t AS (SELECT empno FROM emp) SELECT * FROM t");
            SqlWith with = (SqlWith) validated;
            SqlSelect body = (SqlSelect) with.body;
            SqlValidatorScope scope = ctx.validator.getSelectScope(body);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, with);
            show("with", ctx, bb);
        }

        // 6. default branch: literal
        {
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM emp");
            SqlSelect select = (SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            SqlLiteral literal = SqlLiteral.createExactNumeric("1", SqlParserPos.ZERO);
            try {
                ctx.converter.callConvertFrom(bb, literal);
                System.out.println("default -> NO EXCEPTION");
            } catch (Throwable t) {
                System.out.println("default -> " + t.getClass().getName() + ": " + t.getMessage());
            }
        }

        // 7. VALUES with explicit fieldNames
        {
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            SqlSelect select = (SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, select.getFrom(), java.util.Arrays.asList("X", "Y"));
            show("values-with-fields", ctx, bb);
        }

        // 8. empty fieldNames list on values
        {
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            SqlSelect select = (SqlSelect) validated;
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, select.getFrom(), Collections.emptyList());
            show("values-empty-fields", ctx, bb);
        }

        // 9. tablesample with calcite parser
        {
            java.util.Properties p = new java.util.Properties();
            org.apache.calcite.sql.SqlNode parsed;
            try {
                parsed = org.apache.calcite.sql.parser.SqlParser.create("SELECT * FROM emp TABLESAMPLE (50 PERCENT)").parseQuery();
                SqlNode validated = ctx.validator.validate(parsed);
                System.out.println("calcite-parsed tablesample from kind=" + ((SqlSelect) validated).getFrom().getKind());
                SqlSelect select = (SqlSelect) validated;
                SqlValidatorScope scope = ctx.validator.getSelectScope(select);
                Blackboard bb = ctx.converter.newBlackboard(scope, false);
                ctx.converter.callConvertFrom(bb, select.getFrom());
                show("tablesample", ctx, bb);
            } catch (Throwable t) {
                System.out.println("tablesample -> " + t.getClass().getName() + ": " + t.getMessage());
            }
        }
        System.out.println("done");
    }
}
