package org.apache.calcite.sql2rel;

import org.apache.calcite.plan.RelOptUtil;
import org.apache.calcite.rel.RelNode;
import org.apache.calcite.rel.hint.Hintable;
import org.apache.calcite.sql.*;
import org.apache.calcite.sql.parser.SqlParserPos;
import org.apache.calcite.sql.validate.SqlValidatorScope;
import org.apache.calcite.sql2rel.SqlToRelConverter.Blackboard;

import java.util.Arrays;
import java.util.Collections;

/** Scratch harness 4. */
public class Harness4 {

    static void show(String label, Harness.Ctx ctx, Blackboard bb) {
        RelNode root = bb.root;
        System.out.println(label + " -> " + (root == null ? "null" : RelOptUtil.toString(root)));
        System.out.println("   rootClass=" + (root == null ? "null" : root.getClass().getSimpleName())
                + " rootInLeaves=" + (root != null && ctx.converter.leaves.containsKey(root))
                + " rootHintable=" + (root instanceof Hintable));
        if (root instanceof Hintable) {
            System.out.println("   hints=" + ((Hintable) root).getHints());
        }
    }

    public static void main(String[] args) throws Exception {
        // TableRef
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlNode validated = ctx.parseAndValidate("SELECT * FROM emp");
            SqlSelect select = (SqlSelect) validated;
            SqlIdentifier id = (SqlIdentifier) select.getFrom();
            SqlTableRef tableRef = new SqlTableRef(SqlParserPos.ZERO, id, SqlNodeList.EMPTY);
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, tableRef);
            show("table-ref", ctx, bb);
        }

        // WITH item
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlWith with = (SqlWith) ctx.parseAndValidate(
                    "WITH t AS (SELECT empno FROM emp) SELECT * FROM t");
            SqlWithItem item = (SqlWithItem) with.withList.get(0);
            SqlSelect body = (SqlSelect) with.body;
            SqlValidatorScope scope = ctx.validator.getSelectScope(body);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            try {
                ctx.converter.callConvertFrom(bb, item);
                show("with-item", ctx, bb);
            } catch (Throwable t) {
                System.out.println("with-item -> " + t);
            }
        }

        // WITH node
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlWith with = (SqlWith) ctx.parseAndValidate(
                    "WITH t AS (SELECT empno FROM emp) SELECT * FROM t");
            SqlSelect body = (SqlSelect) with.body;
            SqlValidatorScope scope = ctx.validator.getSelectScope(body);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, with);
            show("with", ctx, bb);
        }

        // default branch
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM emp");
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            SqlLiteral literal = SqlLiteral.createExactNumeric("1", SqlParserPos.ZERO);
            try {
                ctx.converter.callConvertFrom(bb, literal);
                System.out.println("default -> NO EXCEPTION");
            } catch (Throwable t) {
                System.out.println("default -> " + t.getClass().getName() + ": " + t.getMessage());
            }
        }

        // VALUES with explicit names
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.callConvertFrom(bb, select.getFrom(), Arrays.asList("X", "Y"));
            show("values-fields", ctx, bb);
        }

        // tablesample via calcite parser
        {
            Harness.Ctx ctx = new Harness.Ctx();
            try {
                SqlNode parsed = org.apache.calcite.sql.parser.SqlParser
                        .create("SELECT * FROM emp TABLESAMPLE (50 PERCENT)").parseQuery();
                SqlSelect select = (SqlSelect) ctx.validator.validate(parsed);
                System.out.println("tablesample kind=" + select.getFrom().getKind());
                SqlValidatorScope scope = ctx.validator.getSelectScope(select);
                Blackboard bb = ctx.converter.newBlackboard(scope, false);
                ctx.converter.callConvertFrom(bb, select.getFrom());
                show("tablesample", ctx, bb);
            } catch (Throwable t) {
                System.out.println("tablesample -> " + t);
                t.printStackTrace(System.out);
            }
        }

        // AS over join (root not hintable?)
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate(
                    "SELECT * FROM (emp JOIN dept ON emp.deptno = dept.deptno) AS j");
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.containsQueryHints();
            ctx.converter.callConvertFrom(bb, select.getFrom());
            show("as-over-join", ctx, bb);
        }

        // AS over derived select with hints
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate(
                    "SELECT * FROM (SELECT empno FROM emp) AS s");
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.containsQueryHints();
            ctx.converter.callConvertFrom(bb, select.getFrom());
            show("as-over-select", ctx, bb);
        }

        // AS with column aliases over table: `emp AS e(a,b,c)`?
        {
            Harness.Ctx ctx = new Harness.Ctx();
            try {
                SqlSelect select = (SqlSelect) ctx.parseAndValidate(
                        "SELECT * FROM emp AS e(a, b, c)");
                SqlValidatorScope scope = ctx.validator.getSelectScope(select);
                Blackboard bb = ctx.converter.newBlackboard(scope, false);
                ctx.converter.callConvertFrom(bb, select.getFrom());
                show("as-columns-table", ctx, bb);
            } catch (Throwable t) {
                System.out.println("as-columns-table -> " + t);
            }
        }

        // EXTEND (flink syntax)
        {
            Harness.Ctx ctx = new Harness.Ctx();
            try {
                SqlSelect select = (SqlSelect) ctx.parseAndValidate(
                        "SELECT * FROM emp EXTEND (ename VARCHAR(20))");
                System.out.println("extend kind=" + select.getFrom().getKind());
                SqlValidatorScope scope = ctx.validator.getSelectScope(select);
                Blackboard bb = ctx.converter.newBlackboard(scope, false);
                ctx.converter.callConvertFrom(bb, select.getFrom());
                show("extend", ctx, bb);
            } catch (Throwable t) {
                System.out.println("extend -> " + t);
            }
        }

        // COLLECTION_TABLE
        {
            Harness.Ctx ctx = new Harness.Ctx();
            try {
                SqlSelect select = (SqlSelect) ctx.parseAndValidate(
                        "SELECT * FROM TABLE(emp)");
                System.out.println("collection_table kind=" + select.getFrom().getKind());
            } catch (Throwable t) {
                System.out.println("collection-table -> " + t);
            }
        }
        System.out.println("done");
    }
}
