package org.apache.calcite.sql2rel;

import org.apache.calcite.plan.RelOptUtil;
import org.apache.calcite.rel.RelNode;
import org.apache.calcite.rel.hint.Hintable;
import org.apache.calcite.sql.*;
import org.apache.calcite.sql.validate.SqlValidatorScope;
import org.apache.calcite.sql2rel.SqlToRelConverter.Blackboard;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/** Scratch harness 6. */
public class Harness6 {

    static Blackboard bbFor(Harness.Ctx ctx, String sql) {
        SqlSelect select = (SqlSelect) ctx.parseAndValidate(sql);
        SqlValidatorScope scope = ctx.validator.getSelectScope(select);
        return ctx.converter.newBlackboard(scope, false);
    }

    static void report(String label, Harness.Ctx ctx, Blackboard bb) {
        RelNode root = bb.root;
        System.out.println(label + " -> " + (root == null ? "null" : RelOptUtil.toString(root)));
        System.out.println("   rowType=" + (root == null ? "null" : root.getRowType()));
        System.out.println("   class=" + (root == null ? "null" : root.getClass().getName())
                + " inLeaves=" + (root != null && ctx.converter.leaves.containsKey(root))
                + " leavesSize=" + ctx.converter.leaves.size());
    }

    public static void main(String[] args) {
        // values with null / empty aliases
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            Blackboard bb = bbFor(ctx, "SELECT * FROM (VALUES (1, 'a'))");
            ctx.converter.callConvertFrom(bb, select.getFrom(), null);
            report("values-null-fields", ctx, bb);
        }
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            Blackboard bb = bbFor(ctx, "SELECT * FROM (VALUES (1, 'a'))");
            ctx.converter.callConvertFrom(bb, select.getFrom(), Collections.emptyList());
            report("values-empty-fields", ctx, bb);
        }
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            Blackboard bb = bbFor(ctx, "SELECT * FROM (VALUES (1, 'a'))");
            ctx.converter.callConvertFrom(bb, select.getFrom(), Arrays.asList("X", "Y"));
            report("values-two-fields", ctx, bb);
        }
        // single-arg delegation for values
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a'))");
            Blackboard bb = bbFor(ctx, "SELECT * FROM (VALUES (1, 'a'))");
            try {
                ctx.converter.callConvertFrom(bb, select.getFrom());
                report("values-single-arg", ctx, bb);
            } catch (Throwable t) {
                System.out.println("values-single-arg -> " + t);
            }
        }
        // as with column names on values
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate("SELECT * FROM (VALUES (1, 'a')) AS v(id, name)");
            Blackboard bb = bbFor(ctx, "SELECT * FROM (VALUES (1, 'a')) AS v(id, name)");
            ctx.converter.callConvertFrom(bb, select.getFrom());
            report("as-columns-values", ctx, bb);
        }
        // as over tablesample (non hintable root) with query hints
        {
            Harness.Ctx ctx = new Harness.Ctx();
            try {
                SqlSelect select = (SqlSelect) ctx.parseAndValidate(
