import org.apache.calcite.plan.RelOptUtil;
import org.apache.calcite.rel.RelNode;
import org.apache.calcite.rel.type.RelDataType;
import org.apache.calcite.rel.type.RelDataTypeFactory;
import org.apache.calcite.schema.impl.AbstractTable;
import org.apache.calcite.sql.*;
import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.sql.parser.SqlParserPos;
import org.apache.calcite.sql.validate.SqlValidatorScope;
import org.apache.calcite.sql2rel.SqlToRelConverter.Blackboard;

/** Scratch harness 7. */
public class Harness7 {

    static void report(String label, Harness.Ctx ctx, Blackboard bb) {
        RelNode root = bb.root;
        System.out.println(label + " -> " + (root == null ? "null" : RelOptUtil.toString(root)));
        System.out.println("   rowType=" + (root == null ? "null" : root.getRowType())
                + " class=" + (root == null ? "null" : root.getClass().getName())
                + " inLeaves=" + (root != null && ctx.converter.leaves.containsKey(root)));
    }

    /** Table that supports extension. */
    static class ExtensibleEmp extends AbstractTable {
        @Override
        public RelDataType getRowType(RelDataTypeFactory tf) {
            return tf.builder()
                    .add("EMPNO", tf.createSqlType(org.apache.calcite.sql.type.SqlTypeName.INTEGER))
                    .add("ENAME", tf.createSqlType(org.apache.calcite.sql.type.SqlTypeName.VARCHAR, 10))
                    .build();
        }

        @Override
        public <T> T unwrap(Class<T> clazz) {
            return clazz.isInstance(this) ? clazz.cast(this) : null;
        }
    }

    public static void main(String[] args) {
        // AS over join built manually + query hints
        {
            Harness.Ctx ctx = new Harness.Ctx();
            SqlSelect select = (SqlSelect) ctx.parseAndValidate(
                    "SELECT * FROM emp JOIN dept ON emp.deptno = dept.deptno");
            SqlNode join = select.getFrom();
            SqlCall asCall = SqlStdOperatorTable.AS.createCall(
                    SqlParserPos.ZERO, join, new SqlIdentifier("J", SqlParserPos.ZERO));
            SqlValidatorScope scope = ctx.validator.getSelectScope(select);
            Blackboard bb = ctx.converter.newBlackboard(scope, false);
            ctx.converter.containsQueryHints();
            try {
                ctx.converter.callConvertFrom(bb, asCall);
                report("as-over-join-manual", ctx, bb);
            } catch (Throwable t) {
                System.out.println("as-over-join-manual -> " + t);
            }
        }

        // EXTEND
        {
            org.apache.calcite.jdbc.CalciteSchema schema =
                    org.apache.calcite.jdbc.CalciteSchema.createRootSchema(false, false, "root");
            schema.add("EMP", new ExtensibleEmp());
            org.apache.calcite.prepare.CalciteCatalogReader catalogReader =
                    new org.apache.calcite.prepare.CalciteCatalogReader(
                            schema,
                            java.util.Collections.emptyList(),
                            Harness.typeFactory,
                            org.apache.calcite.config.CalciteConnectionConfig.DEFAULT);
            org.apache.calcite.sql.validate.SqlValidator validator =
                    org.apache.calcite.sql.validate.SqlValidatorUtil.newValidator(
                            SqlStdOperatorTable.instance(),
                            catalogReader,
                            Harness.typeFactory,
                            org.apache.calcite.sql.validate.SqlValidator.Config.DEFAULT);
            org.apache.calcite.plan.RelOptCluster cluster =
                    org.apache.calcite.plan.RelOptCluster.create(
                            new org.apache.calcite.plan.hep.HepPlanner(
                                    new org.apache.calcite.plan.hep.HepProgramBuilder().build()),
                            new org.apache.calcite.rex.RexBuilder(Harness.typeFactory));
            Harness.TestConverter converter = new Harness.TestConverter(validator, catalogReader, cluster);
            try {
                SqlSelect select = (SqlSelect) validator.validate(
                        org.apache.calcite.sql.parser.SqlParser.create(
                                        "SELECT * FROM emp EXTEND (ename VARCHAR(20))",
                                        org.apache.calcite.sql.parser.SqlParser.config()
                                                .withParserFactory(
                                                        org.apache.flink.sql.parser.impl
                                                                .FlinkSqlParserImpl.FACTORY))
                                .parseQuery());
                System.out.println("extend fromKind=" + select.getFrom().getKind());
                SqlValidatorScope scope = validator.getSelectScope(select);
                Blackboard bb = converter.newBlackboard(scope, false);
                converter.callConvertFrom(bb, select.getFrom());
                RelNode root = bb.root;
                System.out.println("extend -> " + RelOptUtil.toString(root));
                System.out.println("   rowType=" + root.getRowType() + " inLeaves="
                        + converter.leaves.containsKey(root));
            } catch (Throwable t) {
                System.out.println("extend -> " + t);
            }
        }
        System.out.println("done");
    }
}
