        final SqlSelect select =
                validateSelect("SELECT * FROM emp TABLESAMPLE BERNOULLI(50) REPEATABLE(42)");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(Sample.class);
        final RelOptSamplingParameters parameters =
                ((Sample) bb.root).getSamplingParameters();
        assertThat(parameters.isRepeatable()).isTrue();
        assertThat(parameters.getRepeatableSeed()).isEqualTo(42);
    }

    @Test
    void testTableSampleSubstitutionKeepsInnerRelation() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp TABLESAMPLE SUBSTITUTE('x')");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO", "ENAME", "DEPTNO");
        assertThat(converter.leaves).containsEntry(bb.root, 3);
    }

    // ~ Tests for unsupported FROM nodes ------------------------------------

    @Test
    void testUnsupportedFromNodeThrowsAssertionError() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");
        final Blackboard bb = newBlackboard(select);
        final SqlLiteral literal = SqlLiteral.createExactNumeric("1", SqlParserPos.ZERO);

        assertThatThrownBy(() -> converter.convertFrom(bb, literal))
                .isInstanceOf(AssertionError.class)
                .hasMessageContaining("not a join operator");
    }
}
