import org.apache.calcite.sql.type.SqlTypeFactoryImpl;
import org.apache.calcite.sql.type.SqlTypeName;
import org.apache.calcite.sql.validate.SqlValidator;
import org.apache.calcite.sql.validate.SqlValidatorScope;
import org.apache.calcite.sql.validate.SqlValidatorUtil;
import org.apache.calcite.sql2rel.SqlToRelConverter.Blackboard;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Tests for {@link SqlToRelConverter#convertFrom(Blackboard, SqlNode, List)}, which translates the
 * FROM clause of a query into a relational expression.
 */
class SqlToRelConverterConvertFromTests {

    private static final RelDataTypeFactory TYPE_FACTORY =
            new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);

    private static final RelOptTable.ViewExpander VIEW_EXPANDER =
            (rowType, queryString, schemaPath, viewPath) -> {
                throw new UnsupportedOperationException("Views are not supported in this test.");
            };

    private SqlValidator validator;
    private SqlToRelConverter converter;

    // ~ Setup ----------------------------------------------------------------

    @BeforeEach
    void beforeEach() {
        final CalciteSchema rootSchema = CalciteSchema.createRootSchema(false, false, "root");
        rootSchema.add("EMP", empTable());
        rootSchema.add("DEPT", deptTable());

        final Prepare.CatalogReader catalogReader =
                new CalciteCatalogReader(
                        rootSchema,
                        Collections.emptyList(),
                        TYPE_FACTORY,
                        CalciteConnectionConfig.DEFAULT);
        validator =
                SqlValidatorUtil.newValidator(
                        SqlStdOperatorTable.instance(),
                        catalogReader,
                        TYPE_FACTORY,
                        SqlValidator.Config.DEFAULT);

        final RelOptCluster cluster =
                RelOptCluster.create(
                        new HepPlanner(new HepProgramBuilder().build()),
                        new RexBuilder(TYPE_FACTORY));
        converter =
                new SqlToRelConverter(
                        VIEW_EXPANDER,
                        validator,
                        catalogReader,
                        cluster,
                        StandardConvertletTable.INSTANCE,
                        SqlToRelConverter.config());
    }

    private static AbstractTable empTable() {
        return new AbstractTable() {
            @Override
            public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                return typeFactory
                        .builder()
                        .add("EMPNO", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .add("ENAME", typeFactory.createSqlType(SqlTypeName.VARCHAR, 10))
                        .add("DEPTNO", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .build();
            }
        };
    }

    private static AbstractTable deptTable() {
        return new AbstractTable() {
            @Override
            public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                return typeFactory
                        .builder()
                        .add("DEPTNO", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .add("NAME", typeFactory.createSqlType(SqlTypeName.VARCHAR, 10))
                        .build();
            }
        };
    }

    // ~ Helpers --------------------------------------------------------------

    private SqlNode parse(String sql) throws SqlParseException {
        return SqlParser.create(sql, SqlParser.config().withParserFactory(FlinkSqlParserImpl.FACTORY))
                .parseQuery();
    }

    private SqlSelect validateSelect(String sql) throws SqlParseException {
        return (SqlSelect) validator.validate(parse(sql));
    }

    private SqlWith validateWith(String sql) throws SqlParseException {
        return (SqlWith) validator.validate(parse(sql));
    }

    private Blackboard newBlackboard(SqlSelect select) {
        final SqlValidatorScope scope = validator.getSelectScope(select);
        return converter.createBlackboard(scope, null, false);
    }

    private Blackboard convertFrom(SqlSelect select, SqlNode from) {
        final Blackboard bb = newBlackboard(select);
        converter.convertFrom(bb, from);
        return bb;
    }

    private Blackboard convertFrom(SqlSelect select, SqlNode from, List<String> fieldNames) {
        final Blackboard bb = newBlackboard(select);
        converter.convertFrom(bb, from, fieldNames);
        return bb;
    }

    private static List<String> fieldNames(RelNode rel) {
        return rel.getRowType().getFieldNames();
    }

    private static RelNode tableScanInput(RelNode rel) {
        assertThat(rel.getInputs()).hasSize(1);
        return rel.getInput(0);
    }

    // ~ Tests for a null FROM clause ----------------------------------------

    @Test
    void testNullFromIsConvertedToSingleRowValues() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");

        final Blackboard bb = convertFrom(select, null);

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        final LogicalValues values = (LogicalValues) bb.root;
        assertThat(values.getTuples()).hasSize(1);
        assertThat(values.getTuples().get(0)).hasSize(1);
        assertThat(values.getRowType().getFieldCount()).isEqualTo(1);
        // the created node is not registered as a leaf
        assertThat(converter.leaves).doesNotContainKey(bb.root);
    }

    @Test
    void testNullFromIgnoresFieldNames() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");

        final Blackboard bb = convertFrom(select, null, Arrays.asList("A", "B"));

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        assertThat(fieldNames(bb.root)).hasSize(1);
    }

    // ~ Tests for table references ------------------------------------------

    @Test
    void testIdentifierIsConvertedToTableScan() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        final LogicalTableScan scan = (LogicalTableScan) bb.root;
        assertThat(scan.getTable().getQualifiedName()).contains("EMP");
        assertThat(fieldNames(scan)).containsExactly("EMPNO", "ENAME", "DEPTNO");
        // a table scan is registered as a leaf together with its field count
        assertThat(converter.leaves).hasSize(1);
        assertThat(converter.leaves).containsEntry(scan, 3);
    }

    @Test
    void testIdentifierIgnoresFieldNames() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");

        final Blackboard bb =
                convertFrom(select, select.getFrom(), Arrays.asList("A", "B", "C"));

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO", "ENAME", "DEPTNO");
    }

    @Test
    void testTableRefIsConvertedToTableScan() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");
        final SqlIdentifier identifier = (SqlIdentifier) select.getFrom();
        final SqlTableRef tableRef =
                new SqlTableRef(SqlParserPos.ZERO, identifier, SqlNodeList.EMPTY);

        final Blackboard bb = convertFrom(select, tableRef);

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO", "ENAME", "DEPTNO");
        assertThat(converter.leaves).containsEntry(bb.root, 3);
    }

    // ~ Tests for the AS branch ---------------------------------------------

    @Test
    void testAsDoesNotAddHintsWithoutQueryHints() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp AS e");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        assertThat(((Hintable) bb.root).getHints()).isEmpty();
        assertThat(converter.leaves).hasSize(1);
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testAsAddsAliasHintWhenQueryHintsAreEnabled() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp AS e");
        converter.containsQueryHints();

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        final List<RelHint> hints = ((Hintable) bb.root).getHints();
        assertThat(hints).hasSize(1);
        assertThat(hints.get(0).hintName).isEqualTo(FlinkHints.HINT_ALIAS);
        assertThat(hints.get(0).listOptions).hasSize(1);
        assertThat(hints.get(0).listOptions.get(0)).isEqualToIgnoringCase("e");
        // the un-hinted root was replaced: only the new root is registered as a leaf
        assertThat(converter.leaves).hasSize(1);
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testAsDoesNotAddHintWhenRootIsNotHintable() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp JOIN dept ON emp.deptno = dept.deptno");
        // wrap the join into an "AS" call, which is what the parser produces for
        // "FROM (<query>) AS alias"
        final SqlCall asCall =
                SqlStdOperatorTable.AS.createCall(
                        SqlParserPos.ZERO,
                        select.getFrom(),
                        new SqlIdentifier("j", SqlParserPos.ZERO));
        converter.containsQueryHints();

        final Blackboard bb = convertFrom(select, asCall);

        assertThat(bb.root).isInstanceOf(LogicalJoin.class);
        assertThat(bb.root).isNotInstanceOf(Hintable.class);
        assertThat(converter.leaves).doesNotContainKey(bb.root);
    }

    @Test
    void testAsWithColumnAliasesRenamesValuesFields() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM (VALUES (1, 'a')) AS v(id, name)");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        assertThat(fieldNames(bb.root)).containsExactly("ID", "NAME");
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testAsWithColumnAliasesRenamesUnnestFields() throws Exception {
        final SqlSelect select =
                validateSelect(
                        "SELECT * FROM UNNEST(ARRAY[1, 2], ARRAY['a', 'b']) AS u(c1, c2)");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(fieldNames(bb.root)).containsExactly("C1", "C2");
        assertThat(tableScanInput(bb.root)).isInstanceOf(Uncollect.class);
    }

    // ~ Tests for the VALUES branch -----------------------------------------

    @Test
    void testValuesWithoutFieldNamesKeepsDefaultNames() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM (VALUES (1, 'a'), (2, 'b'))");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        final LogicalValues values = (LogicalValues) bb.root;
        assertThat(values.getTuples()).hasSize(2);
        assertThat(fieldNames(values)).containsExactly("EXPR$0", "EXPR$1");
        assertThat(converter.leaves).containsKey(values);
    }

    @Test
    void testValuesWithExplicitFieldNamesAreRenamed() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM (VALUES (1, 'a'))");

        final Blackboard bb =
                convertFrom(select, select.getFrom(), Arrays.asList("x", "y"));

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        assertThat(fieldNames(bb.root)).containsExactly("X", "Y");
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testValuesWithEmptyFieldNamesKeepsDefaultNames() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM (VALUES (1, 'a'))");

        final Blackboard bb = convertFrom(select, select.getFrom(), Collections.emptyList());

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        assertThat(fieldNames(bb.root)).containsExactly("EXPR$0", "EXPR$1");
    }

    @Test
    void testSingleArgumentConvertFromDelegatesToThreeArgumentVariant() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM (VALUES (1, 'a'))");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalValues.class);
        assertThat(fieldNames(bb.root)).containsExactly("EXPR$0", "EXPR$1");
        assertThat(converter.leaves).hasSize(1);
    }

    // ~ Tests for queries ----------------------------------------------------

    @Test
    void testSubQueryIsConvertedToProject() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM (SELECT empno FROM emp) AS s");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalProject.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO");
        assertThat(tableScanInput(bb.root)).isInstanceOf(LogicalTableScan.class);
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testSetOperationIsConvertedToSetOp() throws Exception {
        final SqlSelect select =
                validateSelect(
                        "SELECT * FROM (SELECT empno FROM emp UNION ALL "
                                + "SELECT empno FROM emp) AS u");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(SetOp.class);
        final SetOp setOp = (SetOp) bb.root;
        assertThat(setOp.kind).isEqualTo(SqlKind.UNION);
        assertThat(setOp.all).isTrue();
        assertThat(setOp.getInputs()).hasSize(2);
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testJoinIsConvertedToLogicalJoin() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp JOIN dept ON emp.deptno = dept.deptno");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalJoin.class);
        final LogicalJoin join = (LogicalJoin) bb.root;
        assertThat(join.getJoinType()).isEqualTo(JoinRelType.INNER);
        assertThat(join.getCondition().getKind()).isEqualTo(SqlKind.EQUALS);
        assertThat(join.getLeft()).isInstanceOf(LogicalTableScan.class);
        assertThat(join.getRight()).isInstanceOf(LogicalTableScan.class);
        // joins are not registered as leaves
        assertThat(converter.leaves).doesNotContainKey(bb.root);
    }

    @Test
    void testLateralIsConvertedToCorrelate() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp, LATERAL (SELECT emp.empno) AS l");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalCorrelate.class);
        assertThat(((LogicalCorrelate) bb.root).getJoinType()).isEqualTo(JoinRelType.INNER);
        assertThat(converter.leaves).doesNotContainKey(bb.root);
    }

    @Test
    void testWithIsConvertedUsingItsBody() throws Exception {
        final SqlWith with =
                validateWith("WITH t AS (SELECT empno FROM emp) SELECT * FROM t");
        final SqlSelect body = (SqlSelect) with.body;
        final Blackboard bb = newBlackboard(body);
        converter.convertFrom(bb, with);

        assertThat(bb.root).isInstanceOf(LogicalProject.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO");
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testWithItemIsConvertedUsingItsQuery() throws Exception {
        final SqlWith with =
                validateWith("WITH t AS (SELECT empno FROM emp) SELECT * FROM t");
        final SqlWithItem withItem = (SqlWithItem) with.withList.get(0);
        final SqlSelect body = (SqlSelect) with.body;
        final Blackboard bb = newBlackboard(body);
        converter.convertFrom(bb, withItem);

        assertThat(bb.root).isInstanceOf(LogicalProject.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO");
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testMatchRecognizeIsConvertedToLogicalMatch() throws Exception {
        final SqlSelect select =
                validateSelect(
                        "SELECT * FROM emp MATCH_RECOGNIZE (PARTITION BY deptno ORDER BY empno "
                                + "MEASURES FIRST(ename) AS f PATTERN (A) DEFINE A AS TRUE) AS m");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalMatch.class);
        assertThat(fieldNames(bb.root)).containsExactly("DEPTNO", "F");
        assertThat(tableScanInput(bb.root)).isInstanceOf(LogicalTableScan.class);
        assertThat(converter.leaves).doesNotContainKey(bb.root);
    }

    @Test
    void testUnpivotIsConvertedToProjectOverFilter() throws Exception {
        final SqlSelect select =
                validateSelect(
                        "SELECT * FROM (SELECT ename, empno FROM emp) UNPIVOT (v FOR k IN (ename))");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalProject.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO", "K", "V");
        assertThat(tableScanInput(bb.root)).isInstanceOf(LogicalFilter.class);
        assertThat(converter.leaves).containsKey(bb.root);
    }

    @Test
    void testUnnestIsConvertedToUncollect() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM UNNEST(ARRAY[1, 2])");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(Uncollect.class);
        assertThat(((Uncollect) bb.root).withOrdinality).isFalse();
        assertThat(fieldNames(bb.root)).hasSize(1);
        assertThat(converter.leaves).containsKey(bb.root);
    }

    // ~ Tests for TABLESAMPLE -----------------------------------------------

    @Test
    void testTableSampleBernoulliIsConvertedToSample() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp TABLESAMPLE BERNOULLI(50)");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(Sample.class);
        final Sample sample = (Sample) bb.root;
        final RelOptSamplingParameters parameters = sample.getSamplingParameters();
        assertThat(parameters.isBernoulli()).isTrue();
        assertThat(parameters.getSamplingPercentage()).isEqualTo(50.0f);
        assertThat(parameters.isRepeatable()).isFalse();
        assertThat(tableScanInput(sample)).isInstanceOf(LogicalTableScan.class);
        assertThat(converter.leaves).containsKey(sample);
    }

    @Test
    void testTableSampleSystemIsConvertedToSample() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp TABLESAMPLE SYSTEM(10)");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(Sample.class);
        final RelOptSamplingParameters parameters =
                ((Sample) bb.root).getSamplingParameters();
        assertThat(parameters.isBernoulli()).isFalse();
        assertThat(parameters.getSamplingPercentage()).isEqualTo(10.0f);
    }

    @Test
    void testTableSampleWithRepeatableSeed() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp TABLESAMPLE BERNOULLI(50) REPEATABLE(42)");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(Sample.class);
        final RelOptSamplingParameters parameters =
                ((Sample) bb.root).getSamplingParameters();
        assertThat(parameters.isRepeatable()).isTrue();
        assertThat(parameters.getRepeatableSeed()).isEqualTo(42);
    }

    @Test
    void testTableSampleSubstitutionKeepsInnerRelation() throws Exception {
        final SqlSelect select =
                validateSelect("SELECT * FROM emp TABLESAMPLE SUBSTITUTE('x')");

        final Blackboard bb = convertFrom(select, select.getFrom());

        assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
        assertThat(fieldNames(bb.root)).containsExactly("EMPNO", "ENAME", "DEPTNO");
        assertThat(converter.leaves).containsEntry(bb.root, 3);
    }

    // ~ Tests for unsupported FROM nodes ------------------------------------

    @Test
    void testUnsupportedFromNodeThrowsAssertionError() throws Exception {
        final SqlSelect select = validateSelect("SELECT * FROM emp");
        final Blackboard bb = newBlackboard(select);
        final SqlLiteral literal = SqlLiteral.createExactNumeric("1", SqlParserPos.ZERO);

        assertThatThrownBy(() -> converter.convertFrom(bb, literal))
                .isInstanceOf(AssertionError.class)
                .hasMessageContaining("not a join operator");
    }
}
