// ~ Helpers --------------------------------------------------------------

private SqlNode parse(String sql) throws SqlParseException {
    return SqlParser.create(
                    sql, SqlParser.config().withParserFactory(FlinkSqlParserImpl.FACTORY))
            .parseQuery();
}

private SqlSelect validateSelect(String sql) throws SqlParseException {
    return (SqlSelect) validator.validate(parse(sql));
}

private SqlWith validateWith(String sql) throws SqlParseException {
    return (SqlWith) validator.validate(parse(sql));
}

private Blackboard newBlackboard(SqlSelect select) {
    final SqlValidatorScope scope = validator.getSelectScope(select);
    return converter.createBlackboard(scope, null, false);
}

private Blackboard convertFrom(SqlSelect select, SqlNode from) {
    final Blackboard bb = newBlackboard(select);
    converter.convertFrom(bb, from);
    return bb;
}

private Blackboard convertFrom(SqlSelect select, SqlNode from, List<String> fieldNames) {
    final Blackboard bb = newBlackboard(select);
    converter.convertFrom(bb, from, fieldNames);
    return bb;
}

private static List<String> fieldNames(RelNode rel) {
    return rel.getRowType().getFieldNames();
}

private static RelNode tableScanInput(RelNode rel) {
    assertThat(rel.getInputs()).hasSize(1);
    return rel.getInput(0);
}

