void testIdentifierIsConvertedToTableScan() throws Exception {
    final SqlSelect select = validateSelect("SELECT * FROM emp");

    final Blackboard bb = convertFrom(select, select.getFrom());

    assertThat(bb.root).isInstanceOf(LogicalTableScan.class);
    final LogicalTableScan scan = (LogicalTableScan) bb.root;
    assertThat(scan.getTable().getQualifiedName()).contains("EMP");
    assertThat(fieldNames(scan)).containsExactly("EMPNO", "ENAME", "DEPTNO");
    // a table scan is registered as a leaf together with its field count
    assertThat(converter.leaves).hasSize(1);
    assertThat(converter.leaves).containsEntry(scan, 3);
}

