                                .builder()
                                .add("a", SqlTypeName.INTEGER)
                                .add("b", SqlTypeName.INTEGER)
                                .build();
                    }
                });
        return root;
    }

    static class ExposedConverter extends SqlToRelConverter {
        ExposedConverter(
                RelOptTable.ViewExpander viewExpander,
                SqlValidator validator,
                Prepare.CatalogReader catalogReader,
                RelOptCluster cluster,
                SqlRexConvertletTable convertletTable,
                Config config) {
            super(viewExpander, validator, catalogReader, cluster, convertletTable, config);
        }

        Blackboard newBlackboard(SqlValidatorScope scope, RelNode root) {
            Blackboard bb = new Blackboard(scope, null, true);
            bb.root = root;
            return bb;
        }
    }

    static class OverridingConverter extends ExposedConverter {
        OverridingConverter(
                RelOptTable.ViewExpander viewExpander,
                SqlValidator validator,
                Prepare.CatalogReader catalogReader,
                RelOptCluster cluster,
                SqlRexConvertletTable convertletTable,
                Config config) {
            super(viewExpander, validator, catalogReader, cluster, convertletTable, config);
        }

        @Override
        protected RexNode convertExtendedExpression(SqlNode node, Blackboard bb) {
            if (node instanceof SqlIdentifier) {
                return bb.getRexBuilder()
                        .makeExactLiteral(
                                BigDecimal.valueOf(42),
                                bb.getValidator().getValidatedNodeType(node));
            }
            return null;
        }
    }

    @Test
    void directExplore() throws Exception {
        RelDataTypeFactory typeFactory = new org.apache.calcite.jdbc.JavaTypeFactoryImpl();
        CalciteSchema calciteSchema = CalciteSchema.from(schema());
