                new CalciteCatalogReader(
                        calciteSchema,
                        List.of(),
                        typeFactory,
                        CalciteConnectionConfig.DEFAULT);
        SqlValidator validator =
                SqlValidatorUtil.newValidator(
                        SqlStdOperatorTable.instance(),
                        catalogReader,
                        typeFactory,
                        SqlValidator.Config.DEFAULT);
        SqlNode parsed =
                SqlParser.create(
                                "SELECT a + b, a, a IS NULL FROM t",
                                SqlParser.config().withCaseSensitive(false))
                        .parseQuery();
        SqlSelect select = (SqlSelect) validator.validate(parsed);
        SqlValidatorScope scope = validator.getSelectScope(select);
        RelOptPlanner optPlanner = new HepPlanner(new HepProgramBuilder().build());
        RexBuilder rexBuilder = new RexBuilder(typeFactory);
        RelOptCluster cluster = RelOptCluster.create(optPlanner, rexBuilder);
        RelOptTable table = catalogReader.getTable(List.of("t"));
        RelNode scan = LogicalTableScan.create(cluster, table, List.of());
        ExposedConverter converter =
                new ExposedConverter(
                        ViewExpanders.simpleContext(cluster),
                        validator,
                        catalogReader,
                        cluster,
                        StandardConvertletTable.INSTANCE,
                        SqlToRelConverter.config());
        Blackboard bb = converter.newBlackboard(scope, scan);
        for (SqlNode expr : select.getSelectList()) {
            try {
                System.out.println("EXPR " + expr + " -> " + bb.convertExpression(expr));
            } catch (Throwable e) {
                System.out.println("EXPR " + expr + " FAILED: " + e);
                e.printStackTrace(System.out);
            }
        }

        OverridingConverter overriding =
                new OverridingConverter(
                        ViewExpanders.simpleContext(cluster),
                        validator,
                        catalogReader,
                        cluster,
                        StandardConvertletTable.INSTANCE,
                        SqlToRelConverter.config());
        Blackboard bb2 = overriding.newBlackboard(scope, scan);
        System.out.println("OVERRIDE a -> " + bb2.convertExpression(select.getSelectList().get(1)));
    }
}
