            @Nullable SqlNode filter,
            @Nullable SqlNodeList distinctList,
            @Nullable SqlNodeList orderList,
            boolean ignoreNulls,
            SqlCall outerCall) {
        assert bb.agg == this;
        final RexBuilder rexBuilder = bb.getRexBuilder();
        final List<SqlNode> operands = call.getOperandList();
        final SqlParserPos pos = call.getParserPosition();
        final SqlCall call2;
        final List<SqlNode> operands2;
        switch (call.getKind()) {
            case FILTER:
                assert filter == null;
                translateAgg(
                        call.operand(0),
                        call.operand(1),
                        distinctList,
                        orderList,
                        ignoreNulls,
                        outerCall);
                return;
            case WITHIN_DISTINCT:
                assert orderList == null;
                translateAgg(
                        call.operand(0),
                        filter,
                        call.operand(1),
                        orderList,
                        ignoreNulls,
                        outerCall);
                return;
            case WITHIN_GROUP:
                assert orderList == null;
                translateAgg(
                        call.operand(0),
                        filter,
                        distinctList,
                        call.operand(1),
                        ignoreNulls,
                        outerCall);
                return;
