To collect RexNodes:
```java
private static List<RexNode> allRexNodes(RelNode root) {
    List<RexNode> out = new ArrayList<>();
    Deque<RelNode> rels = new ArrayDeque<>();
    rels.add(root);
    while (!rels.isEmpty()) {
        RelNode rel = rels.removeFirst();
        List<RexNode> rexNodes = new ArrayList<>();
        if (rel instanceof Project) rexNodes.addAll(((Project) rel).getProjects());
        if (rel instanceof Filter) rexNodes.add(((Filter) rel).getCondition());
        if (rel instanceof Join) rexNodes.add(((Join) rel).getCondition());
        // Add more if needed
        for (RexNode rex : rexNodes) collectRex(rex, out, rels);
        rels.addAll(rel.getInputs());
    }
    return out;
}
private static void collectRex(RexNode rex, List<RexNode> out, Deque<RelNode> rels) {
    out.add(rex);
    if (rex instanceof RexSubQuery) rels.add(((RexSubQuery) rex).rel);
    if (rex instanceof RexCall) for (RexNode operand : ((RexCall) rex).getOperands()) collectRex(operand, out, rels);
}
