private static List<RexNode> collectRexNodes(RelNode rel) {
    List<RexNode> out = new ArrayList<>();
    Deque<RelNode> queue = new ArrayDeque<>();
    queue.add(rel);
    while (!queue.isEmpty()) {
        RelNode current = queue.removeFirst();
        List<RexNode> roots = new ArrayList<>();
        if (current instanceof Project) roots.addAll(((Project) current).getProjects());
        if (current instanceof Filter) roots.add(((Filter) current).getCondition());
        if (current instanceof Join) roots.add(((Join) current).getCondition());
        for (RexNode rex : roots) {
