    /** A converter that exposes the protected {@link Blackboard} inner class. */
    private static class ExposedConverter extends SqlToRelConverter {

        ExposedConverter(
                RelOptTable.ViewExpander viewExpander,
                SqlValidator validator,
                Prepare.CatalogReader catalogReader,
                RelOptCluster cluster,
                SqlRexConvertletTable convertletTable,
                Config config) {
            super(viewExpander, validator, catalogReader, cluster, convertletTable, config);
        }

        Blackboard newBlackboard(SqlValidatorScope scope, RelNode root) {
            Blackboard blackboard = new Blackboard(scope, null, true);
            blackboard.root = root;
            return blackboard;
        }
    }

    /** A converter that answers every identifier through {@code convertExtendedExpression}. */
    private static class OverridingConverter extends ExposedConverter {

        OverridingConverter(
                RelOptTable.ViewExpander viewExpander,
                SqlValidator validator,
                Prepare.CatalogReader catalogReader,
                RelOptCluster cluster,
                SqlRexConvertletTable convertletTable,
                Config config) {
            super(viewExpander, validator, catalogReader, cluster, convertletTable, config);
        }

        @Override
        protected RexNode convertExtendedExpression(SqlNode node, Blackboard blackboard) {
            if (node instanceof SqlIdentifier) {
                return blackboard
                        .getRexBuilder()
                        .makeExactLiteral(
                                BigDecimal.valueOf(42),
                                blackboard
                                        .getRexBuilder()
                                        .getTypeFactory()
                                        .createSqlType(SqlTypeName.INTEGER));
            }
            return null;
        }
    }

