    @Test
    void standardExpressionIsConvertedByVisitor() throws Exception {
        DirectFixture fixture = directFixture("SELECT A + B, A IS NULL FROM T");
        Blackboard blackboard =
                fixture.newExposedConverter().newBlackboard(fixture.scope, fixture.scan);

        RexNode plus = blackboard.convertExpression(fixture.select.getSelectList().get(0));
        assertInstanceOf(RexCall.class, plus);
        assertEquals(SqlKind.PLUS, plus.getKind());
        assertEquals(2, ((RexCall) plus).getOperands().size());

        RexNode isNull = blackboard.convertExpression(fixture.select.getSelectList().get(1));
        assertInstanceOf(RexCall.class, isNull);
        assertEquals(SqlKind.IS_NULL, isNull.getKind());
    }

    @Test
    void extendedExpressionOverrideWinsBeforeStandardConversion() throws Exception {
        DirectFixture fixture = directFixture("SELECT A + B, A FROM T");
        Blackboard blackboard =
                fixture.newOverridingConverter().newBlackboard(fixture.scope, fixture.scan);

        // A call is not handled by the override, so standard conversion is used.
        RexNode plus = blackboard.convertExpression(fixture.select.getSelectList().get(0));
        assertInstanceOf(RexCall.class, plus);
        assertEquals(SqlKind.PLUS, plus.getKind());

        // An identifier is intercepted by the derived converter.
        RexNode identifier = blackboard.convertExpression(fixture.select.getSelectList().get(1));
        assertInstanceOf(RexLiteral.class, identifier);
        assertEquals(Integer.valueOf(42), ((RexLiteral) identifier).getValueAs(Integer.class));
    }

