    @Test
    void arithmeticExpressionProducesPlusCall() throws Exception {
        RelNode rel = convert("SELECT a + b FROM t", false).rel;

        RexCall plus =
                rexNodes(rel, RexCall.class).stream()
                        .filter(call -> call.getKind() == SqlKind.PLUS)
                        .findFirst()
                        .orElse(null);
        assertNotNull(plus);
        assertEquals(2, plus.getOperands().size());
        assertInstanceOf(RexInputRef.class, plus.getOperands().get(0));
        assertInstanceOf(RexInputRef.class, plus.getOperands().get(1));
        assertEquals(0, ((RexInputRef) plus.getOperands().get(0)).getIndex());
        assertEquals(1, ((RexInputRef) plus.getOperands().get(1)).getIndex());
    }

    @Test
    void groupByAndAggregateAreConvertedToInputReferences() throws Exception {
