        assertNotNull(aggregate);
        assertEquals(ImmutableBitSet.of(0), aggregate.getGroupSet());
        assertEquals(1, aggregate.getAggCallList().size());
        AggregateCall aggregateCall = aggregate.getAggCallList().get(0);
        assertEquals("SUM", aggregateCall.getAggregation().getName());

        assertInstanceOf(Project.class, rel);
        List<RexNode> projects = ((Project) rel).getProjects();
        assertEquals(2, projects.size());
        assertInstanceOf(RexInputRef.class, projects.get(0));
        assertEquals(0, ((RexInputRef) projects.get(0)).getIndex());
        assertInstanceOf(RexInputRef.class, projects.get(1));
        assertEquals(1, ((RexInputRef) projects.get(1)).getIndex());
    }

    @Test
