 * <p>The direct tests exercise the method on a hand-built {@link Blackboard}, while the planner
 * tests verify the RexNodes produced for the individual branches of the method.
 */
class SqlToRelConverterConvertExpressionTests {

    // ---------------------------------------------------------------------
    // Planner based helpers
    // ---------------------------------------------------------------------

    private static SchemaPlus schema() {
        SchemaPlus root = Frameworks.createRootSchema(true);
        root.add(
                "t",
                new AbstractTable() {
                    @Override
                    public RelDataType getRowType(RelDataTypeFactory typeFactory) {
                        return typeFactory
                                .builder()
                                .add("a", SqlTypeName.INTEGER)
                                .add("b", SqlTypeName.INTEGER)
                                .build();
                    }
                });
        return root;
    }

    private static FrameworkConfig frameworkConfig(boolean expand) {
        return Frameworks.newConfigBuilder()
                .defaultSchema(schema())
                .parserConfig(SqlParser.config().withCaseSensitive(false))
                .sqlToRelConverterConfig(SqlToRelConverter.config().withExpand(expand))
                .build();
    }

    private static RelRoot convert(String sql, boolean expand) throws Exception {
        Planner planner = Frameworks.getPlanner(frameworkConfig(expand));
        SqlNode validated = planner.validate(planner.parse(sql));
        return planner.rel(validated);
    }

    private static List<RelNode> allRels(RelNode root) {
        List<RelNode> result = new ArrayList<>();
        Deque<RelNode> queue = new ArrayDeque<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            RelNode rel = queue.removeFirst();
            result.add(rel);
            queue.addAll(rel.getInputs());
        }
        return result;
    }

    private static List<RexNode> allRexNodes(RelNode root) {
        List<RexNode> result = new ArrayList<>();
        Deque<RelNode> queue = new ArrayDeque<>(allRels(root));
        while (!queue.isEmpty()) {
            RelNode rel = queue.removeFirst();
            List<RexNode> topLevel = new ArrayList<>();
            if (rel instanceof Project) {
                topLevel.addAll(((Project) rel).getProjects());
            }
            if (rel instanceof Filter) {
                topLevel.add(((Filter) rel).getCondition());
            }
            if (rel instanceof Join) {
                topLevel.add(((Join) rel).getCondition());
            }
            for (RexNode rex : topLevel) {
                collectRexNode(rex, result, queue);
            }
        }
        return result;
    }

    private static void collectRexNode(RexNode rex, List<RexNode> result, Deque<RelNode> queue) {
        result.add(rex);
        if (rex instanceof RexSubQuery) {
            queue.add(((RexSubQuery) rex).rel);
        }
        if (rex instanceof RexCall) {
            for (RexNode operand : ((RexCall) rex).getOperands()) {
                collectRexNode(operand, result, queue);
            }
        }
    }

    private static <T extends RexNode> List<T> rexNodes(RelNode root, Class<T> type) {
        return allRexNodes(root).stream()
                .filter(type::isInstance)
                .map(type::cast)
                .collect(Collectors.toList());
    }

    private static <T extends RelNode> T findRel(RelNode root, Class<T> type) {
        for (RelNode rel : allRels(root)) {
            if (type.isInstance(rel)) {
                return type.cast(rel);
            }
        }
        return null;
    }

    private static RexSubQuery findSubQuery(RelNode root, SqlKind kind) {
        for (RexSubQuery subQuery : rexNodes(root, RexSubQuery.class)) {
            if (subQuery.getKind() == kind) {
                return subQuery;
            }
        }
        return null;
    }

