private static List<RexNode> allRexNodes(RelNode root) {
    List<RexNode> result = new ArrayList<>();
    Deque<RelNode> queue = new ArrayDeque<>(allRels(root));
    while (!queue.isEmpty()) {
        RelNode rel = queue.removeFirst();
        List<RexNode> topLevel = new ArrayList<>();
        if (rel instanceof Project) topLevel.addAll(((Project) rel).getProjects());
        if (rel instanceof Filter) topLevel.add(((Filter) rel).getCondition());
        if (rel instanceof Join) topLevel.add(((Join) rel).getCondition());
        for (RexNode rex : topLevel) {
            collectRexNode(rex, result, queue);
        }
    }
    return result;
}
private static void collectRexNode(RexNode rex, List<RexNode> result, Deque<RelNode> queue) {
    result.add(rex);
    if (rex instanceof RexSubQuery) queue.add(((RexSubQuery) rex).rel);
    if (rex instanceof RexCall) {
        for (RexNode operand : ((RexCall) rex).getOperands()) {
            collectRexNode(operand, result, queue);
        }
    }
}
```
