    private OneInputTransformation<RowData, RowData> translate(
            OverSpec overSpec, RowType inputRowType, TableConfig tableConfig) {
        final StreamExecOverAggregate node =
                new StreamExecOverAggregate(
                        tableConfig, overSpec, InputProperty.DEFAULT, OUTPUT_ROW_TYPE, DESCRIPTION);
        final ExecEdge inputEdge = mock(ExecEdge.class);
        when(inputEdge.getOutputType()).thenReturn(inputRowType);
        when(inputEdge.translateToPlan(planner)).thenReturn(inputTransform);
        node.setInputEdges(Collections.singletonList(inputEdge));

        final Transformation<RowData> transformation =
                node.translateToPlanInternal(
                        planner, ExecNodeConfig.ofTableConfig(tableConfig, true));
        assertThat(transformation).isInstanceOf(OneInputTransformation.class);
        @SuppressWarnings("unchecked")
        final OneInputTransformation<RowData, RowData> oneInputTransformation =
                (OneInputTransformation<RowData, RowData>) transformation;
        return oneInputTransformation;
    }

    private static Object processFunctionOf(
            OneInputTransformation<RowData, RowData> transformation) {
        final OneInputStreamOperator<RowData, RowData> operator = transformation.getOperator();
        assertThat(operator).isInstanceOf(KeyedProcessOperator.class);
        return ((KeyedProcessOperator<?, RowData, RowData>) operator).getUserFunction();
    }

    private static RowType rowType(LogicalType orderKeyType) {
        return RowType.of(
                new LogicalType[] {LONG_TYPE, orderKeyType, STRING_TYPE},
                new String[] {"partitionKey", "orderKey", "payload"});
    }

    private static OverSpec overSpec(
            PartitionSpec partitionSpec, List<RexLiteral> constants, OverSpec.GroupSpec... groups) {
        final List<OverSpec.GroupSpec> groupList = new ArrayList<>();
        Collections.addAll(groupList, groups);
        return new OverSpec(partitionSpec, groupList, constants, ORIGINAL_INPUT_FIELDS);
    }

    private static OverSpec.GroupSpec group(
            RexWindowBound lowerBound, RexWindowBound upperBound) {
        return group(
                SortSpec.builder().addField(ORDER_KEY_INDEX, true, true).build(),
                true,
                lowerBound,
                upperBound);
    }

    private static OverSpec.GroupSpec group(
            SortSpec sortSpec,
            boolean isRows,
            RexWindowBound lowerBound,
            RexWindowBound upperBound) {
        return new OverSpec.GroupSpec(
                sortSpec, isRows, lowerBound, upperBound, Collections.emptyList());
    }

    private static RexWindowBound boundPrecedingUnbounded() {
        final RexWindowBound bound = mock(RexWindowBound.class);
        when(bound.isPreceding()).thenReturn(true);
        when(bound.isUnbounded()).thenReturn(true);
        when(bound.isCurrentRow()).thenReturn(false);
        when(bound.isFollowing()).thenReturn(false);
        return bound;
    }

    private static RexWindowBound boundFollowingUnbounded() {
        final RexWindowBound bound = mock(RexWindowBound.class);
        when(bound.isPreceding()).thenReturn(false);
        when(bound.isUnbounded()).thenReturn(true);
        when(bound.isCurrentRow()).thenReturn(false);
        when(bound.isFollowing()).thenReturn(true);
        return bound;
    }

    private static RexWindowBound boundCurrentRow() {
        final RexWindowBound bound = mock(RexWindowBound.class);
        when(bound.isPreceding()).thenReturn(false);
        when(bound.isUnbounded()).thenReturn(false);
        when(bound.isCurrentRow()).thenReturn(true);
        when(bound.isFollowing()).thenReturn(false);
        return bound;
    }

    /**
     * Creates a preceding bound which references the constant at the given position of the inputs.
     */
    private static RexWindowBound boundPreceding(int constantIndex) {
        final RexInputRef offset =
                REX_BUILDER.makeInputRef(
                        CALCITE_TYPE_FACTORY.createSqlType(SqlTypeName.BIGINT), constantIndex);
        final RexWindowBound bound = mock(RexWindowBound.class);
        when(bound.isPreceding()).thenReturn(true);
        when(bound.isUnbounded()).thenReturn(false);
        when(bound.isCurrentRow()).thenReturn(false);
        when(bound.isFollowing()).thenReturn(false);
        when(bound.getOffset()).thenReturn(offset);
        return bound;
    }

    private static RexLiteral longConstant(long value) {
        return (RexLiteral)
                REX_BUILDER.makeExactLiteral(
                        BigDecimal.valueOf(value),
                        CALCITE_TYPE_FACTORY.createSqlType(SqlTypeName.BIGINT));
    }

    private static List<String> collectLogMessages(Runnable action) {
        final LoggerContext loggerContext = (LoggerContext) LogManager.getContext(false);
        final Configuration configuration = loggerContext.getConfiguration();
        final LoggerConfig loggerConfig =
                configuration.getLoggerConfig(StreamExecOverAggregate.class.getName());
        final Queue<String> messages = new ConcurrentLinkedQueue<>();
        final AbstractAppender appender =
                new AbstractAppender(
                        "stream-exec-over-aggregate-test-appender", null, null, false, null) {
                    @Override
                    public void append(LogEvent event) {
                        messages.add(event.getMessage().getFormattedMessage());
                    }
                };
        appender.start();
        final Level previousLevel = loggerConfig.getLevel();
        loggerConfig.setLevel(Level.WARN);
        loggerConfig.addAppender(appender, Level.WARN, null);
        try {
            action.run();
        } finally {
            loggerConfig.removeAppender(appender.getName());
            loggerConfig.setLevel(previousLevel);
            appender.stop();
        }
        return new ArrayList<>(messages);
    }
