    @Test
    void testMultipleGroupsAreRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        Collections.singletonList(group(boundPrecedingUnbounded(), boundCurrentRow())),
                        group(boundPrecedingUnbounded(), boundCurrentRow()));

        assertThatThrownBy(
                        () -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("All aggregates must be computed on the same window.");
    }

