/**
 * Tests for {@link StreamExecOverAggregate#translateToPlanInternal(PlannerBase, ExecNodeConfig)}.
 */
class StreamExecOverAggregateTranslateToPlanInternalTests {

    private static final String DESCRIPTION = "over-aggregate-node";
    private static final int INPUT_PARALLELISM = 8;
    private static final int ORIGINAL_INPUT_FIELDS = 2;
    private static final int ORDER_KEY_INDEX = 1;
    private static final int PARTITION_KEY_INDEX = 0;

    private static final LogicalType LONG_TYPE = new BigIntType(false);
    private static final LogicalType ROWTIME_TYPE =
            new TimestampType(false, TimestampKind.ROWTIME, 3);
    private static final LogicalType PROCTIME_TYPE =
            new LocalZonedTimestampType(false, TimestampKind.PROCTIME, 3);
    private static final LogicalType STRING_TYPE = new VarCharType(false, 100);

    private static final RowType OUTPUT_ROW_TYPE =
            RowType.of(new LogicalType[] {LONG_TYPE}, new String[] {"aggResult"});

    private static final RelDataTypeFactory CALCITE_TYPE_FACTORY =
            new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    private static final RexBuilder REX_BUILDER = new RexBuilder(CALCITE_TYPE_FACTORY);

    private StreamPlanner planner;
    private Transformation<RowData> inputTransform;

    @BeforeEach
    void setUp() {
        final ClassLoader classLoader = getClass().getClassLoader();
        final Configuration configuration = new Configuration();

        final CatalogStoreHolder catalogStoreHolder =
                CatalogStoreHolder.newBuilder()
                        .catalogStore(new GenericInMemoryCatalogStore())
                        .config(configuration)
                        .classloader(classLoader)
                        .build();
        final CatalogManager catalogManager =
                CatalogManager.newBuilder()
                        .classLoader(classLoader)
                        .config(configuration)
                        .defaultCatalog(
                                "default_catalog",
                                new GenericInMemoryCatalog("default_catalog", "default_database"))
                        .catalogStoreHolder(catalogStoreHolder)
                        .build();
        final ModuleManager moduleManager = new ModuleManager();
        final ResourceManager resourceManager =
                new ResourceManager(
                        configuration,
                        FlinkUserCodeClassLoaders.parentFirst(new URL[0], classLoader, t -> {}, false));
        final FunctionCatalog functionCatalog =
                new FunctionCatalog(configuration, resourceManager, catalogManager, moduleManager);

        planner =
                new StreamPlanner(
                        Mockito.mock(Executor.class),
                        TableConfig.getDefault(),
                        moduleManager,
                        functionCatalog,
                        catalogManager,
                        classLoader);

        inputTransform = Mockito.mock(Transformation.class);
        Mockito.when(inputTransform.getParallelism()).thenReturn(INPUT_PARALLELISM);
    }

    @AfterEach
    void tearDown() {
        planner = null;
        inputTransform = null;
    }

    // ------------------------------------------------------------------------
    //  validation failures
    // ------------------------------------------------------------------------

    @Test
    void testMultipleGroupsAreRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        group(boundPrecedingUnbounded(), boundCurrentRow()),
                        group(boundPrecedingUnbounded(), boundCurrentRow()));

        assertThatThrownBy(() -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("All aggregates must be computed on the same window.");
    }

    @Test
    void testOrderByMultipleColumnsIsRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final SortSpec sortSpec =
                SortSpec.builder()
                        .addField(PARTITION_KEY_INDEX, true, true)
                        .addField(ORDER_KEY_INDEX, true, true)
                        .build();
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        group(sortSpec, true, boundPrecedingUnbounded(), boundCurrentRow()));

        assertThatThrownBy(() -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("The window can only be ordered by a single time column.");
    }

    @Test
    void testOrderByNoColumnIsRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        group(SortSpec.ANY, true, boundPrecedingUnbounded(), boundCurrentRow()));

        assertThatThrownBy(() -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("The window can only be ordered by a single time column.");
    }

    @Test
    void testDescendingOrderIsRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final SortSpec sortSpec = SortSpec.builder().addField(ORDER_KEY_INDEX, false, true).build();
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        group(sortSpec, true, boundPrecedingUnbounded(), boundCurrentRow()));

        assertThatThrownBy(() -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("The window can only be ordered in ASCENDING mode.");
    }

    @Test
    void testUnboundedFollowingUpperBoundIsRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        ascendingSingleOrderKeyGroup(
                                false, boundPrecedingUnbounded(), boundFollowingUnbounded()));

        assertThatThrownBy(() -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("OVER RANGE FOLLOWING windows are not supported yet.");
    }

    @Test
    void testCurrentRowLowerBoundIsRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
