    }

    @Test
    void testBoundedWindowWithDecimalBoundaryIsRejected() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final RexLiteral decimalConstant =
                (RexLiteral)
                        REX_BUILDER.makeExactLiteral(
                                new BigDecimal("2.5"),
                                CALCITE_TYPE_FACTORY.createSqlType(SqlTypeName.DECIMAL, 5, 2));
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.singletonList(decimalConstant),
                        ascendingSingleOrderKeyGroup(
                                true,
                                boundPreceding(ORIGINAL_INPUT_FIELDS),
                                boundCurrentRow()));

        assertThatThrownBy(() -> translate(overSpec, inputRowType, TableConfig.getDefault()))
                .isInstanceOf(TableException.class)
                .hasMessage("the specific value is decimal which haven not supported yet.");
    }

    @Test
    void testBoundedWindowOnNonTimeAttributeIsRejected() {
        final RowType inputRowType = rowType(STRING_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.singletonList(longConstant(2L)),
                        ascendingSingleOrderKeyGroup(
