    @Test
    void testUnboundedRowTimeRowsWindowUsesVersionTwoFunction() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.singletonList(longConstant(0L)),
                        ascendingSingleOrderKeyGroup(
                                true, boundPrecedingUnbounded(), boundCurrentRow()));

        final OneInputTransformation<RowData, RowData> transformation =
                translate(overSpec, inputRowType, TableConfig.getDefault());

        assertThat(transformation.getName()).startsWith("OverAggregate[");
        assertThat(transformation.getParallelism()).isEqualTo(INPUT_PARALLELISM);
        assertThat(transformation.getInputs()).containsExactly(inputTransform);
        assertThat(transformation.getOutputType()).isEqualTo(InternalTypeInfo.of(OUTPUT_ROW_TYPE));
        assertThat(processFunctionOf(transformation))
                .isInstanceOf(RowTimeUnboundedPrecedingOverFunctionV2.class);
    }

