                                .toRowType()
                                .getFieldCount())
                .isZero();
    }

    // ------------------------------------------------------------------------
    //  state retention warning
    // ------------------------------------------------------------------------

    @Test
    void testStateRetentionWarningIsLoggedForPartitionedWindow() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        new PartitionSpec(new int[] {PARTITION_KEY_INDEX}),
                        Collections.emptyList(),
                        ascendingSingleOrderKeyGroup(
                                true, boundPrecedingUnbounded(), boundCurrentRow()));

        final TableConfig tableConfig = TableConfig.getDefault();
        tableConfig.set(ExecutionConfigOptions.IDLE_STATE_RETENTION, Duration.ofMillis(-1));

        final List<String> messages =
                collectLogMessages(() -> translate(overSpec, inputRowType, tableConfig));

        assertThat(messages)
                .anyMatch(
                        message ->
                                message.contains(
                                        "No state retention interval configured for a query"));
    }

    @Test
    void testNoStateRetentionWarningForUnpartitionedWindow() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        PartitionSpec.ALL_IN_ONE,
                        Collections.emptyList(),
                        ascendingSingleOrderKeyGroup(
                                true, boundPrecedingUnbounded(), boundCurrentRow()));

        final TableConfig tableConfig = TableConfig.getDefault();
        tableConfig.set(ExecutionConfigOptions.IDLE_STATE_RETENTION, Duration.ofMillis(-1));

