                collectLogMessages(() -> translate(overSpec, inputRowType, tableConfig));

        assertThat(messages)
                .noneMatch(
                        message ->
                                message.contains(
                                        "No state retention interval configured for a query"));
    }

    @Test
    void testNoStateRetentionWarningForConfiguredRetention() {
        final RowType inputRowType = rowType(ROWTIME_TYPE);
        final OverSpec overSpec =
                overSpec(
                        new PartitionSpec(new int[] {PARTITION_KEY_INDEX}),
                        Collections.emptyList(),
                        ascendingSingleOrderKeyGroup(
