    @Test
    void testNegativeRetentionWithCountWindowAndGroupingLogsWarning() {
        TumblingGroupWindow window =
                tumblingWindow(procTimeField(0), rowIntervalLiteral(5L));
        Configuration nodeConfig = new Configuration();
        nodeConfig.set(ExecutionConfigOptions.IDLE_STATE_RETENTION, Duration.ofMillis(-1000));
        ExecNodeConfig config = ExecNodeConfig.ofNodeConfig(nodeConfig, false);

        CollectingAppender appender = new CollectingAppender();
        appender.start();
        Logger logger =
                (Logger) LogManager.getLogger(StreamExecPythonGroupWindowAggregate.class);
        logger.addAppender(appender);
        try {
            translate(window, new int[] {0}, config, new AggregateCall[0]);
        } finally {
            logger.removeAppender(appender);
            appender.stop();
        }

        assertThat(appender.warnings())
                .anyMatch(
                        message ->
                                message.contains("No state retention interval configured")
                                        && message.contains("excessive state size"));
    }

