    /** Appender that only retains warning messages emitted during a test. */
    private static class CollectingAppender extends AbstractAppender {
        private final List<LogEvent> events = new java.util.concurrent.CopyOnWriteArrayList<>();

        private CollectingAppender() {
            super("collecting-appender", null, null, true, null);
        }

        @Override
        public void append(LogEvent event) {
            events.add(event.toImmutable());
        }

        private List<String> warnings() {
            return events.stream()
                    .filter(event -> event.getLevel().name().equals("WARN"))
                    .map(event -> event.getMessage().getFormattedMessage())
                    .collect(Collectors.toList());
        }
    }
