    private Transformation<RowData> translate(
            LogicalWindow window,
            int[] grouping,
            ExecNodeConfig config,
            AggregateCall[] aggCalls) {
        return translate(window, grouping, config, aggCalls, false);
    }

    @SuppressWarnings("unchecked")
    private Transformation<RowData> translate(
            LogicalWindow window,
            int[] grouping,
            ExecNodeConfig config,
            AggregateCall[] aggCalls,
            boolean pythonWorkerUsesManagedMemory) {
        TableConfig tableConfig = new TableConfig();
        PlannerBase planner = mock(PlannerBase.class);
        when(planner.getTableConfig()).thenReturn(tableConfig);
        FlinkContext flinkContext = mock(FlinkContext.class);
        when(flinkContext.getClassLoader()).thenReturn(getClass().getClassLoader());
        when(planner.getFlinkContext()).thenReturn(flinkContext);

        Transformation<RowData> inputTransform = mock(Transformation.class);
        when(inputTransform.getParallelism()).thenReturn(4);
        ExecEdge inputEdge = mock(ExecEdge.class);
        doReturn(inputTransform).when(inputEdge).translateToPlan(any());
        when(inputEdge.getOutputType()).thenReturn(INPUT_ROW_TYPE);

        StreamExecPythonGroupWindowAggregate node =
                new StreamExecPythonGroupWindowAggregate(
                        tableConfig,
                        grouping,
                        aggCalls,
                        window,
                        new NamedWindowProperty[0],
                        false,
                        false,
                        InputProperty.DEFAULT,
                        OUTPUT_ROW_TYPE,
                        "test-window-aggregate");
        node.setInputEdges(Collections.singletonList(inputEdge));

        try (MockedStatic<CommonPythonUtil> commonPythonUtil = mockStatic(CommonPythonUtil.class)) {
            commonPythonUtil
                    .when(
                            () ->
                                    CommonPythonUtil.extractPythonConfiguration(
                                            any(ReadableConfig.class), any(ClassLoader.class)))
                    .thenReturn(new Configuration());
            commonPythonUtil
                    .when(
                            () ->
                                    CommonPythonUtil.isPythonWorkerUsingManagedMemory(
                                            any(Configuration.class), any(ClassLoader.class)))
                    .thenReturn(pythonWorkerUsesManagedMemory);
            commonPythonUtil
                    .when(() -> CommonPythonUtil.loadClass(anyString(), any(ClassLoader.class)))
                    .thenReturn(TestingPandasPythonOperator.class);
            commonPythonUtil
                    .when(
                            () ->
                                    CommonPythonUtil
                                            .extractPythonAggregateFunctionInfosFromAggregateCall(
                                                    any(AggregateCall[].class)))
                    .thenReturn(
                            Tuple2.of(
                                    new int[] {1}, new PythonFunctionInfo[0]));

            return node.translateToPlanInternal(planner, config);
        }
    }

    private static ExecNodeConfig defaultConfig() {
        return ExecNodeConfig.ofNodeConfig(new Configuration(), false);
    }

    private static TumblingGroupWindow tumblingWindow(
            FieldReferenceExpression timeField, ValueLiteralExpression size) {
        return new TumblingGroupWindow(new WindowReference("w", null), timeField, size);
    }

    private static FieldReferenceExpression procTimeField(int fieldIndex) {
        DataType type =
                TypeConversions.fromLogicalToDataType(
                        new LocalZonedTimestampType(false, TimestampKind.PROCTIME, 3));
        return new FieldReferenceExpression("ts", type, 0, fieldIndex);
    }

    private static FieldReferenceExpression rowTimeField(int fieldIndex) {
        DataType type =
                TypeConversions.fromLogicalToDataType(
                        new TimestampType(true, TimestampKind.ROWTIME, 3));
        return new FieldReferenceExpression("ts", type, 0, fieldIndex);
    }

    private static ValueLiteralExpression intervalLiteral(Duration duration) {
        return new ValueLiteralExpression(
                duration, DataTypes.INTERVAL(DataTypes.SECOND(3)));
    }

    private static ValueLiteralExpression rowIntervalLiteral(long count) {
        return new ValueLiteralExpression(count, DataTypes.BIGINT());
    }

    /** A window kind that the target method does not know how to translate. */
    private static class UnsupportedLogicalWindow extends LogicalWindow {
        UnsupportedLogicalWindow(FieldReferenceExpression timeField) {
            super(new WindowReference("w", null), timeField);
        }

        @Override
        public LogicalWindow copy(FieldReferenceExpression newTimeAttribute) {
            return new UnsupportedLogicalWindow(newTimeAttribute);
        }
    }

    /**
     * Minimal operator implementation used by the tests. It mirrors the constructor that the
     * production code discovers reflectively for the pandas Python group-window operator.
     */
    public static class TestingPandasPythonOperator extends AbstractStreamOperator<RowData>
            implements OneInputStreamOperator<RowData, RowData> {

        private static Captured captured;

        public TestingPandasPythonOperator(
                Configuration config,
                PythonFunctionInfo[] pandasAggFunctions,
                RowType inputType,
                RowType udfInputType,
                RowType udfOutputType,
                int inputTimeFieldIndex,
                GroupWindowAssigner<?> windowAssigner,
                Trigger<?> trigger,
                long allowedLateness,
                NamedWindowProperty[] namedProperties,
                ZoneId shiftTimeZone,
                GeneratedProjection generatedProjection) {
            captured =
                    new Captured(
                            inputTimeFieldIndex,
                            windowAssigner,
                            trigger,
                            udfInputType,
                            udfOutputType,
                            allowedLateness,
                            shiftTimeZone,
                            generatedProjection);
        }

        @Override
        public void processElement(StreamRecord<RowData> element) {}

        static void reset() {
            captured = null;
        }

        private static class Captured {
            private final int inputTimeFieldIndex;
            private final GroupWindowAssigner<?> windowAssigner;
            private final Trigger<?> trigger;
            private final RowType udfInputType;
            private final RowType udfOutputType;
            private final long allowedLateness;
            private final ZoneId shiftTimeZone;
            private final GeneratedProjection generatedProjection;

            private Captured(
                    int inputTimeFieldIndex,
                    GroupWindowAssigner<?> windowAssigner,
                    Trigger<?> trigger,
                    RowType udfInputType,
                    RowType udfOutputType,
                    long allowedLateness,
                    ZoneId shiftTimeZone,
                    GeneratedProjection generatedProjection) {
                this.inputTimeFieldIndex = inputTimeFieldIndex;
                this.windowAssigner = windowAssigner;
                this.trigger = trigger;
                this.udfInputType = udfInputType;
                this.udfOutputType = udfOutputType;
                this.allowedLateness = allowedLateness;
                this.shiftTimeZone = shiftTimeZone;
                this.generatedProjection = generatedProjection;
            }
        }
    }

    /** Appender that only retains warning messages emitted during a test. */
    private static class CollectingAppender extends AbstractAppender {
        private final List<LogEvent> events = new java.util.concurrent.CopyOnWriteArrayList<>();

        private CollectingAppender() {
            super("collecting-appender", null, null, true, null);
        }

        @Override
        public void append(LogEvent event) {
            events.add(event.toImmutable());
        }

        private List<String> warnings() {
            return events.stream()
                    .filter(event -> event.getLevel().name().equals("WARN"))
                    .map(event -> event.getMessage().getFormattedMessage())
                    .collect(Collectors.toList());
        }
    }
