/** Tests for {@link StreamExecPythonGroupWindowAggregate#translateToPlanInternal}. */
class StreamExecPythonGroupWindowAggregateTranslateToPlanInternalTests {

    private static final RowType INPUT_ROW_TYPE = RowType.of(new IntType(), new BigIntType());
    private static final RowType OUTPUT_ROW_TYPE = RowType.of(new IntType(), new BigIntType());

    @AfterEach
    void clearCapturedState() {
        TestingPandasPythonOperator.reset();
        TestingGeneralPythonOperator.reset();
    }

    @Test
    void testProcTimeTumblingIntervalCreatesExpectedTransformation() {
        TumblingGroupWindow window =
                tumblingWindow(procTimeField(0), intervalLiteral(Duration.ofSeconds(10)));

        Transformation<RowData> transform =
                translate(window, new int[] {0}, defaultConfig(), new AggregateCall[0]);

        assertThat(transform).isInstanceOf(OneInputTransformation.class);
        assertThat(transform.getParallelism()).isEqualTo(4);
        assertThat(transform.getOutputType()).isEqualTo(InternalTypeInfo.of(OUTPUT_ROW_TYPE));
        assertThat(transform.getInputs()).hasSize(1);
        assertThat(transform.getManagedMemorySlotScopeUseCases())
                .doesNotContain(ManagedMemoryUseCase.PYTHON);

        OneInputTransformation<?, ?> oneInput = (OneInputTransformation<?, ?>) transform;
        assertThat(oneInput.getStateKeySelector()).isNotNull();
        assertThat(oneInput.getStateKeyType())
                .isEqualTo(InternalTypeInfo.of(RowType.of(new IntType())));

        TestingPandasPythonOperator.Captured captured = TestingPandasPythonOperator.captured;
        assertThat(captured).isNotNull();
        assertThat(captured.inputTimeFieldIndex).isEqualTo(-1);
        assertThat(captured.windowAssigner).isInstanceOf(TumblingWindowAssigner.class);
        assertThat(captured.windowAssigner.isEventTime()).isFalse();
        assertThat(captured.trigger.toString()).contains("ProcessingTime.afterEndOfWindow");
        assertThat(captured.udfInputType.getFieldCount()).isEqualTo(1);
        assertThat(captured.udfOutputType.getFieldCount()).isEqualTo(1);
    }

    @Test
    void testRowtimeTumblingIntervalUsesTimeFieldIndexAndEventTimeTrigger() {
