    Logger rootLogger = (Logger) LogManager.getRootLogger();
    Level previousRootLevel = rootLogger.getLevel();
    logger.addAppender(appender);
    rootLogger.addAppender(appender);
    logger.setLevel(Level.WARN);
    rootLogger.setLevel(Level.WARN);
    try {
        translate(window, new int[] {0}, config, new AggregateCall[0]);
    } finally {
        logger.removeAppender(appender);
        rootLogger.removeAppender(appender);
        logger.setLevel(previousLevel);
        rootLogger.setLevel(previousRootLevel);
        appender.stop();
    }
    assertThat(appender.warnings())
            .anyMatch(
                    message ->
                            message.contains("No state retention interval configured")
                                    && message.contains("excessive state size"));
}

