    @Test
    void testRowNumberTranslationBuildsKeyedProcessOperator() {
        TableConfig tableConfig = TableConfig.getDefault();
        StreamExecRank node =
                createNode(
                        tableConfig,
                        RankType.ROW_NUMBER,
                        PARTITION_SPEC,
                        SORT_SPEC,
                        TOP_1,
                        new RankProcessStrategy.AppendFastStrategy(),
                        false,
                        false);

        Transformation<RowData> result = translate(node, tableConfig);

        assertThat(result).isInstanceOf(OneInputTransformation.class);
        StreamOperator<RowData> operator = getOperator(result);
        assertThat(operator).isInstanceOf(KeyedProcessOperator.class);
        assertThat(getUserFunction(operator)).isInstanceOf(FastTop1Function.class);
    }

