    @Test
    void testFallsBackToJoinWhenDistinctCallHasFilter() {
        final AggregateCall distinctCount =
                aggCall(SqlStdOperatorTable.COUNT, true, false, args(1), 3, "distinct_count");
        final AggregateCall nonDistinctSum =
                aggCall(SqlStdOperatorTable.SUM, false, false, args(2), -1, "sum_y");
        final LogicalAggregate aggregate = simpleAggregate(groupSet(0), distinctCount, nonDistinctSum);
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.JOIN.onMatch(call);

        assertNotNull(call.transformed);
        assertEquals(aggregate.getRowType(), call.transformed.getRowType());
        assertEquals(1, findNodes(call.transformed, LogicalJoin.class).size());
    }

    private LogicalAggregate simpleAggregate(
            ImmutableBitSet groupSet, AggregateCall... aggregateCalls) {
        return LogicalAggregate.create(
                input,
                groupSet,
                Collections.singletonList(groupSet),
                Arrays.asList(aggregateCalls));
    }

    private AggregateCall aggCall(
            SqlAggFunction function,
            boolean distinct,
            boolean approximate,
            List<Integer> arguments,
            int filterArg,
            String name) {
        return AggregateCall.create(
                function,
                distinct,
                approximate,
                arguments,
                filterArg,
                RelCollations.EMPTY,
                bigintType,
                name);
    }

    private static ImmutableBitSet groupSet(int... columns) {
        return ImmutableBitSet.of(columns);
    }

    private static List<Integer> args(Integer... arguments) {
        return Arrays.asList(arguments);
    }

    private static <T extends RelNode> List<T> findNodes(RelNode root, Class<T> nodeClass) {
        final List<T> result = new ArrayList<>();
        collectNodes(root, nodeClass, result);
        return result;
    }

    private static <T extends RelNode> void collectNodes(
            RelNode node, Class<T> nodeClass, List<T> result) {
        if (nodeClass.isInstance(node)) {
            result.add(nodeClass.cast(node));
        }
        for (RelNode child : node.getInputs()) {
            collectNodes(child, nodeClass, result);
        }
    }

    /** A rule call that records the node passed to {@code transformTo}. */
    private final class RecordingCall extends RelOptRuleCall {
        private final RelBuilder callBuilder;
        private RelNode transformed;

        private RecordingCall(LogicalAggregate aggregate) {
            super(
                    aggregate.getCluster().getPlanner(),
                    FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.getOperand(),
                    new RelNode[] {aggregate},
                    Collections.emptyMap());
            this.callBuilder = relBuilder;
        }

        @Override
        public RelBuilder builder() {
            return callBuilder;
        }

        @Override
        public void transformTo(
                RelNode rel,
                Map<RelNode, RelNode> equiv,
                RelHintsPropagator relHintsPropagator) {
            this.transformed = rel;
        }
    }
}
