import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link FlinkAggregateExpandDistinctAggregatesRule#onMatch}. */
class FlinkAggregateExpandDistinctAggregatesRuleOnMatchTests {

    private static final String MIXED_DISTINCT_ERROR =
            "There are both Distinct AggCall and Approximate Distinct AggCall in one sql statement, "
                    + "it is not supported yet.\nPlease choose one of them.";

    private RelOptCluster cluster;
    private RelDataTypeFactory typeFactory;
    private RelDataType bigintType;
    private RelDataType intType;
    private LogicalValues input;
    private RelBuilder relBuilder;

    @BeforeEach
    void setUp() {
        typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        final RelOptPlanner planner = new HepPlanner(new HepProgramBuilder().build());
        cluster = RelOptCluster.create(planner, new RexBuilder(typeFactory));
        bigintType = typeFactory.createSqlType(SqlTypeName.BIGINT);
        intType = typeFactory.createSqlType(SqlTypeName.INTEGER);

        final RelDataType inputRowType =
                typeFactory
                        .builder()
                        .add("g", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .add("x", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .add("y", typeFactory.createSqlType(SqlTypeName.INTEGER))
                        .add("flag", typeFactory.createSqlType(SqlTypeName.BOOLEAN))
                        .build();
        input = LogicalValues.create(cluster, inputRowType, com.google.common.collect.ImmutableList.of());
        relBuilder = RelBuilder.proto(RelFactories.LOGICAL_BUILDER).create(cluster, null);
    }

    @Test
    void testIgnoresAggregateWithoutAccurateDistinctCall() {
        final AggregateCall count =
                aggCall(SqlStdOperatorTable.COUNT, false, false, args(1), -1, "cnt");
        final LogicalAggregate aggregate = simpleAggregate(groupSet(0), count);
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(call);

        assertNull(call.transformed, "the rule must not transform an ordinary aggregate");
    }

    @Test
    void testIgnoresAggregateWithOnlyApproximateDistinctCall() {
        final AggregateCall approxCount =
                aggCall(SqlStdOperatorTable.APPROX_COUNT_DISTINCT, true, true, args(1), -1, "approx");
        final LogicalAggregate aggregate = simpleAggregate(groupSet(0), approxCount);
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(call);

        assertNull(call.transformed, "approximate distinct calls are handled by a different rule");
    }

    @Test
    void testRejectsAccurateAndApproximateDistinctCallsTogether() {
        final AggregateCall accurate =
                aggCall(SqlStdOperatorTable.COUNT, true, false, args(1), -1, "distinct_count");
        final AggregateCall approximate =
                aggCall(
                        SqlStdOperatorTable.APPROX_COUNT_DISTINCT,
                        true,
                        true,
                        args(2),
                        -1,
                        "approx_count");
        final LogicalAggregate aggregate = simpleAggregate(groupSet(0), accurate, approximate);
        final RecordingCall call = new RecordingCall(aggregate);

        final TableException exception =
                assertThrows(
                        TableException.class,
                        () -> FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(call));
        assertEquals(MIXED_DISTINCT_ERROR, exception.getMessage());
        assertNull(call.transformed);
    }

    @Test
    void testDefersNonSimpleAggregateToDecomposeGroupingSetsRule() {
        final AggregateCall distinctCount =
                aggCall(SqlStdOperatorTable.COUNT, true, false, args(1), -1, "distinct_count");
        final ImmutableBitSet groupSet = groupSet(0);
        final LogicalAggregate aggregate =
                LogicalAggregate.create(
                        input,
                        groupSet,
                        Arrays.asList(groupSet, ImmutableBitSet.of()),
                        Collections.singletonList(distinctCount));
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(call);

        assertNull(call.transformed, "multi-grouping-set aggregates must be decomposed first");
    }

    @Test
    void testUsesMonopoleRewriteForOneDistinctArgumentSet() {
        final AggregateCall distinctCount =
                aggCall(SqlStdOperatorTable.COUNT, true, false, args(1), -1, "distinct_count");
        final LogicalAggregate aggregate = simpleAggregate(groupSet(0), distinctCount);
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(call);

        assertNotNull(call.transformed);
        final LogicalAggregate top = assertInstanceOf(LogicalAggregate.class, call.transformed);
        assertEquals(aggregate.getRowType(), top.getRowType());
        assertEquals(1, top.getGroupCount());
        assertEquals(1, top.getAggCallList().size());
        assertFalse(top.getAggCallList().get(0).isDistinct());
        assertEquals(args(1), top.getAggCallList().get(0).getArgList());

        final LogicalAggregate distinct = assertInstanceOf(LogicalAggregate.class, top.getInput());
        assertEquals(groupSet(0, 1), distinct.getGroupSet());
        assertTrue(distinct.getAggCallList().isEmpty());
        assertInstanceOf(LogicalProject.class, distinct.getInput());
    }

    @Test
    void testUsesGroupingSetsRewriteWhenEnabled() {
        final AggregateCall distinctCount =
                aggCall(SqlStdOperatorTable.COUNT, true, false, args(1), -1, "distinct_count");
        final AggregateCall distinctSum =
                aggCall(SqlStdOperatorTable.SUM, true, false, args(2), -1, "distinct_sum");
        final LogicalAggregate aggregate =
                simpleAggregate(groupSet(0), distinctCount, distinctSum);
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.INSTANCE.onMatch(call);

        assertNotNull(call.transformed);
        assertEquals(aggregate.getRowType(), call.transformed.getRowType());
        final List<LogicalAggregate> aggregates = findNodes(call.transformed, LogicalAggregate.class);
        assertTrue(aggregates.size() >= 2, "expected an inner and an outer aggregate");
        assertTrue(
                aggregates.stream().anyMatch(a -> a.getGroupSets().size() == 2),
                "the inner aggregate should expand the two distinct argument sets");
        assertTrue(
                findNodes(call.transformed, LogicalJoin.class).isEmpty(),
