                simpleAggregate(groupSet(0), distinctCount, nonDistinctSum);
        final RecordingCall call = new RecordingCall(aggregate);

        FlinkAggregateExpandDistinctAggregatesRule.JOIN.onMatch(call);

        assertNotNull(call.transformed);
        final LogicalAggregate top = assertInstanceOf(LogicalAggregate.class, call.transformed);
        assertEquals(aggregate.getRowType(), top.getRowType());
        assertEquals(2, top.getAggCallList().size());
        assertFalse(top.getAggCallList().get(0).isDistinct());
        assertFalse(top.getAggCallList().get(1).isDistinct());

        final LogicalAggregate bottom = assertInstanceOf(LogicalAggregate.class, top.getInput());
        assertEquals(groupSet(0, 1), bottom.getGroupSet());
        assertEquals(1, bottom.getAggCallList().size());
        assertEquals("sum_y", bottom.getAggCallList().get(0).getName());
        assertTrue(findNodes(call.transformed, LogicalJoin.class).isEmpty());
    }

    @Test
    void testFallsBackToJoinForDifferentDistinctArgumentSets() {
        final AggregateCall distinctCount =
                aggCall(SqlStdOperatorTable.COUNT, true, false, args(1), -1, "distinct_count");
        final AggregateCall distinctSum =
                aggCall(SqlStdOperatorTable.SUM, true, false, args(2), -1, "distinct_sum");
        final LogicalAggregate aggregate =
                simpleAggregate(groupSet(0), distinctCount, distinctSum);
        final RecordingCall call = new RecordingCall(aggregate);

