    @Test
    void testProducesJoinAndAggregateTreeWithCompatibleRowType() {
        final RelBuilder builder = newBuilder();
        final RelationFixture fixture = buildFixture(builder, JoinRelType.INNER);
        final RelDataType intType =
                fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        final AggregateCall sum =
                AggregateCall.create(
                        SqlStdOperatorTable.SUM,
                        false,
                        ImmutableList.of(3),
                        -1,
                        fixture.join,
                        intType,
                        "total");
        final RelAggregate aggregate =
                createAggregate(fixture.join, ImmutableBitSet.of(1), ImmutableList.of(sum));

        final RelNode result = fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

        assertNotNull(result);
        assertEquals(aggregate.getRowType().getFieldCount(), result.getRowType().getFieldCount());
        assertEquals("b", result.getRowType().getFieldList().get(0).getName());
        assertEquals("total", result.getRowType().getFieldList().get(1).getName());
        assertEquals(
                intType,
                result.getRowType().getFieldList().get(1).getType());
    }

    private static RelBuilder newBuilder() {
        final FrameworkConfig config =
                Frameworks.newConfigBuilder()
                        .defaultSchema(Frameworks.createRootSchema(true))
                        .build();
        return RelBuilder.create(config);
    }

    private static RelationFixture buildFixture(RelBuilder builder, JoinRelType joinType) {
        final RelNode left =
                builder.values(new String[] {"a", "b"}, 1, "x", 2, "y").build();
        final RelNode right =
                builder.values(new String[] {"c", "d"}, 1, 10, 2, 20).build();
        final RelNode join =
                builder.push(left)
                        .push(right)
                        .join(
                                joinType,
                                builder.equals(
                                        builder.field(2, 0, "a"), builder.field(1, 0, "c")))
                        .build();
        return new RelationFixture(join);
    }

    private static RelAggregate createAggregate(
            RelNode input, ImmutableBitSet groupSet, List<AggregateCall> calls) {
        return (RelAggregate)
                LogicalAggregate.create(
                        input, groupSet, ImmutableList.of(groupSet), calls);
    }

    private static RelNode fire(RelOptRule rule, Aggregate aggregate, Join join) {
        final CapturingRuleCall call = new CapturingRuleCall(rule, aggregate, join);
        rule.onMatch(call);
        return call.transformed;
    }

    private static boolean containsAuxiliaryGroup(RelNode node) {
        if (node instanceof Aggregate) {
            for (AggregateCall call : ((Aggregate) node).getAggCallList()) {
                if (call.getAggregation() == FlinkSqlOperatorTable.AUXILIARY_GROUP) {
                    return true;
                }
            }
        }
        for (RelNode input : node.getInputs()) {
            if (containsAuxiliaryGroup(input)) {
                return true;
            }
        }
        return false;
    }

    private static void assertRowTypeLike(RelNode expected, RelNode actual) {
        final List<RelDataTypeField> expectedFields = expected.getRowType().getFieldList();
        final List<RelDataTypeField> actualFields = actual.getRowType().getFieldList();
        assertEquals(expectedFields.size(), actualFields.size());
        for (int i = 0; i < expectedFields.size(); i++) {
            assertEquals(expectedFields.get(i).getName(), actualFields.get(i).getName());
            assertEquals(expectedFields.get(i).getType(), actualFields.get(i).getType());
        }
    }

    private static <T extends RelNode> T findSingleNode(RelNode root, Class<T> type) {
        final List<T> nodes = findNodes(root, type);
        assertEquals(1, nodes.size(), () -> "expected one " + type.getSimpleName());
        return nodes.get(0);
    }

    private static <T extends RelNode> List<T> findNodes(RelNode root, Class<T> type) {
        final List<T> result = new ArrayList<>();
        collectNodes(root, type, result);
        return result;
    }

    private static <T extends RelNode> void collectNodes(
            RelNode node, Class<T> type, List<T> result) {
        if (type.isInstance(node)) {
            result.add(type.cast(node));
        }
        for (RelNode input : node.getInputs()) {
            collectNodes(input, type, result);
        }
    }

    private static final class RelationFixture {
        private final Join join;

        private RelationFixture(RelNode join) {
            this.join = (Join) join;
        }
    }

    private static final class CapturingRuleCall extends RelOptRuleCall {
        private RelNode transformed;

        private CapturingRuleCall(RelOptRule rule, Aggregate aggregate, Join join) {
            super(
                    new VolcanoPlanner(),
                    rule.getOperand(),
                    new RelNode[] {aggregate, join},
                    Collections.emptyMap());
        }

        @Override
        public void transformTo(
                RelNode rel,
                Map<RelNode, RelNode> equiv,
                RelHintsPropagator relHintsPropagator) {
            transformed = rel;
        }
    }
}
