    @Test
    void testHandlesUniqueInputWithoutAggregatingIt() {
        final RelBuilder builder = newBuilder();
        final RelNode left =
                builder.values(new String[] {"a", "b", "flag"}, 1, "x", true).build();
        // c is not unique, so the right input must be pre-aggregated.
        final RelNode right =
                builder.values(new String[] {"c", "d"}, 1, 10, 1, 20).build();
        final Join join =
                (Join)
                        builder.push(left)
                                .push(right)
                                .join(
