    @Test
    void testHandlesUniqueInputWithoutAggregatingIt() {
        final RelBuilder builder = newBuilder();
        final RelNode left =
                builder.values(new String[] {"a", "b", "flag"}, 1, "x", true).build();
        // c is not unique, so the right input must be pre-aggregated.
        final RelNode right =
                builder.values(new String[] {"c", "d"}, 1, 10, 1, 20).build();
        final Join join =
                (Join)
                        builder.push(left)
                                .push(right)
                                .join(
                                        JoinRelType.INNER,
                                        builder.equals(
                                                builder.field(2, 0, "a"),
                                                builder.field(1, 0, "c")))
                                .build();
        final RelDataType intType =
                join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        final AggregateCall sum =
                AggregateCall.create(
                        SqlStdOperatorTable.SUM,
                        false,
                        ImmutableList.of(4),
                        -1,
                        join,
                        intType,
                        "total");
        final Aggregate aggregate =
                createAggregate(join, ImmutableBitSet.of(1), ImmutableList.of(sum));

        final RelNode result = fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, join);

        assertNotNull(result);
        assertRowTypeLike(aggregate, result);
        final Join newJoin = findSingleNode(result, Join.class);
        final boolean leftAggregated = newJoin.getLeft() instanceof Aggregate;
        final boolean rightAggregated = newJoin.getRight() instanceof Aggregate;
        assertFalse(
                leftAggregated,
                () -> "the unique left input should be projected rather than aggregated:\n"
                        + RelOptUtil.toString(result));
        assertTrue(
                rightAggregated,
                () -> "the non-unique right input should be aggregated:\n"
                        + RelOptUtil.toString(result));
