/** Tests for {@link FlinkAggregateJoinTransposeRule#onMatch(RelOptRuleCall)}. */
class FlinkAggregateJoinTransposeRuleOnMatchTests {

    @Test
    void testTransposesCountAndSumThroughInnerJoin() {
        final RelBuilder builder = newBuilder();
        final RelationFixture fixture = buildFixture(builder, JoinRelType.INNER);
        final RelDataType bigint =
                fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.BIGINT);
        final RelDataType intType =
                fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        final AggregateCall count =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        false,
                        ImmutableList.of(),
                        -1,
                        fixture.join,
                        bigint,
                        "cnt");
        final AggregateCall sum =
                AggregateCall.create(
                        SqlStdOperatorTable.SUM,
                        false,
                        ImmutableList.of(4),
                        -1,
                        fixture.join,
                        intType,
                        "total");
        final Aggregate aggregate =
                createAggregate(fixture.join, ImmutableBitSet.of(1), ImmutableList.of(count, sum));

        final RelNode result =
                fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

        assertNotNull(
                result, "the rule should transpose a splittable aggregate over an inner join");
        assertRowTypeLike(aggregate, result);
        final List<LogicalAggregate> aggregates = findNodes(result, LogicalAggregate.class);
        assertTrue(
                aggregates.size() >= 3,
                () ->
                        "expected the original aggregate to be split below and above the join:\n"
                                + RelOptUtil.toString(result));
        final Join newJoin = findSingleNode(result, Join.class);
        assertNotSame(fixture.join, newJoin);
        assertTrue(
                newJoin.getLeft() instanceof Aggregate && newJoin.getRight() instanceof Aggregate,
                () ->
                        "both join inputs should have been pre-aggregated:\n"
                                + RelOptUtil.toString(result));
        assertEquals(JoinRelType.INNER, newJoin.getJoinType());
    }

