@Test
void testTransposesWhenJoinColumnsArePartOfAggregateGroupSet() {
    final RelBuilder builder = newBuilder();
    final RelationFixture fixture = buildFixture(builder, JoinRelType.INNER);
    final RelDataType intType =
            fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
    final AggregateCall sum =
            AggregateCall.create(
                    SqlStdOperatorTable.SUM,
                    false,
                    ImmutableList.of(4),
                    -1,
                    fixture.join,
                    intType,
                    "total");
    final Aggregate aggregate =
            createAggregate(fixture.join, ImmutableBitSet.of(0, 1), ImmutableList.of(sum));

    final RelNode result =
            fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

    assertNotNull(result);
    assertRowTypeLike(aggregate, result);
    assertTrue(
            result instanceof LogicalProject,
            () ->
                    "the top aggregate should have been converted to a projection:\n"
                            + RelOptUtil.toString(result));
    assertTrue(
            findNodes(result, Join.class).size() == 1,
            () -> "expected exactly one new join:\n" + RelOptUtil.toString(result));
    assertEquals(
            2,
            findNodes(result, LogicalAggregate.class).size(),
            () ->
                    "only the two join inputs should remain aggregated:\n"
                            + RelOptUtil.toString(result));
}

@Test
void testConvertsAuxiliaryGroupAggregateToRegularAggregate() {
    final RelBuilder builder = newBuilder();
    final RelationFixture fixture = buildFixture(builder, JoinRelType.INNER);
    final RelDataType intType =
            fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
    final RelDataType bigint =
            fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.BIGINT);
    final AggregateCall auxiliaryGroup =
            AggregateCall.create(
                    FlinkSqlOperatorTable.AUXILIARY_GROUP,
                    false,
                    ImmutableList.of(4),
                    -1,
                    fixture.join,
                    intType,
                    "d");
    final AggregateCall count =
            AggregateCall.create(
                    SqlStdOperatorTable.COUNT,
                    false,
                    ImmutableList.of(4),
                    -1,
                    fixture.join,
                    bigint,
                    "cnt");
    final Aggregate aggregate =
            createAggregate(
                    fixture.join,
                    ImmutableBitSet.of(1),
                    ImmutableList.of(auxiliaryGroup, count));

    final RelNode result =
            fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

    assertNotNull(
            result, "AUXILIARY_GROUP must be converted before pushing down the aggregate");
    assertRowTypeLike(aggregate, result);
    assertEquals(ImmutableList.of("b", "d", "cnt"), result.getRowType().getFieldNames());
    assertFalse(
            containsAuxiliaryGroup(result),
            () ->
                    "AUXILIARY_GROUP must not survive the transposition:\n"
                            + RelOptUtil.toString(result));
}

