    final RelNode result =
            fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

    assertNull(result, "an outer join must not be transposed");
}

@Test
void testDoesNothingForNonEquiJoin() {
    final RelBuilder builder = newBuilder();
    final RelNode left = builder.values(new String[] {"a", "b"}, 1, "x", 2, "y").build();
    final RelNode right = builder.values(new String[] {"c", "d"}, 1, 10, 2, 20).build();
    final Join join =
            (Join)
                    builder.push(left)
                            .push(right)
                            .join(JoinRelType.INNER, nonEquiCondition(builder, left, right))
                            .build();
    final RelDataType bigint =
            join.getCluster().getTypeFactory().createSqlType(SqlTypeName.BIGINT);
    final AggregateCall count =
            AggregateCall.create(
                    SqlStdOperatorTable.COUNT,
                    false,
                    ImmutableList.of(),
                    -1,
                    join,
                    bigint,
                    "cnt");
    final Aggregate aggregate =
            createAggregate(join, ImmutableBitSet.of(1), ImmutableList.of(count));

    final RelNode result = fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, join);

    assertNull(result, "a non-equi condition must make the rule bail out");
}

