                "when no functions are allowed both inputs are treated as unique and the rule "
                        + "must avoid creating a duplicate plan");
    }

    @Test
    void testProducesJoinAndAggregateTreeWithCompatibleRowType() {
        final RelBuilder builder = newBuilder();
        final RelationFixture fixture = buildFixture(builder, JoinRelType.INNER);
        final RelDataType intType =
                fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        final AggregateCall sum =
                AggregateCall.create(
                        SqlStdOperatorTable.SUM,
                        false,
                        ImmutableList.of(4),
                        -1,
                        fixture.join,
                        intType,
                        "total");
        final Aggregate aggregate =
                createAggregate(fixture.join, ImmutableBitSet.of(1), ImmutableList.of(sum));

        final RelNode result =
                fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

        assertNotNull(result);
        assertEquals(aggregate.getRowType().getFieldCount(), result.getRowType().getFieldCount());
        assertEquals(intType, result.getRowType().getFieldList().get(1).getType());
    }

    @Test
    void testDoesNothingWhenBothJoinInputsAreUnique() {
        final RelBuilder builder = newBuilder();
        final RelNode left = builder.values(new String[] {"a", "b", "flag"}, 1, "x", true).build();
        final RelNode right = builder.values(new String[] {"c", "d"}, 1, 10).build();
        final Join join =
