    @Test
    void testHandlesUniqueInputWithoutAggregatingIt() {
        final RelBuilder builder = newBuilder();
        final RelNode left = builder.values(new String[] {"a", "b", "flag"}, 1, "x", true).build();
        // c is not unique, so the right input must be pre-aggregated.
        final RelNode right = builder.values(new String[] {"c", "d"}, 1, 10, 1, 20).build();
        final Join join =
                (Join)
                        builder.push(left)
                                .push(right)
                                .join(JoinRelType.INNER, equiCondition(builder, left, right))
                                .build();
        final RelDataType intType =
                join.getCluster().getTypeFactory().createSqlType(SqlTypeName.INTEGER);
        final AggregateCall sum =
                AggregateCall.create(
                        SqlStdOperatorTable.SUM,
                        false,
                        ImmutableList.of(4),
                        -1,
                        join,
                        intType,
                        "total");
        final Aggregate aggregate =
                createAggregate(join, ImmutableBitSet.of(1), ImmutableList.of(sum));

        final RelNode result = fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, join);

        assertNotNull(result);
        assertRowTypeLike(aggregate, result);
        final Join newJoin = findSingleNode(result, Join.class);
        final boolean leftAggregated = newJoin.getLeft() instanceof Aggregate;
        final boolean rightAggregated = newJoin.getRight() instanceof Aggregate;
        assertFalse(
                leftAggregated,
                () ->
                        "the unique left input should be projected rather than aggregated:\n"
                                + RelOptUtil.toString(result));
        assertTrue(
                rightAggregated,
                () ->
                        "the non-unique right input should be aggregated:\n"
                                + RelOptUtil.toString(result));
    }

    @Test
    void testPreservesGroupingSets() {
        final RelBuilder builder = newBuilder();
        final RelationFixture fixture = buildFixture(builder, JoinRelType.INNER);
        final RelDataType bigint =
                fixture.join.getCluster().getTypeFactory().createSqlType(SqlTypeName.BIGINT);
        final AggregateCall count =
                AggregateCall.create(
                        SqlStdOperatorTable.COUNT,
                        false,
                        ImmutableList.of(),
                        -1,
                        fixture.join,
                        bigint,
                        "cnt");
        final Aggregate aggregate =
                (Aggregate)
                        LogicalAggregate.create(
                                fixture.join,
                                ImmutableBitSet.of(1),
                                ImmutableList.of(ImmutableBitSet.of(1), ImmutableBitSet.of()),
                                ImmutableList.of(count));

        final RelNode result =
                fire(FlinkAggregateJoinTransposeRule.EXTENDED, aggregate, fixture.join);

        assertNotNull(result, "grouping sets aggregate should also be transposed");
        assertRowTypeLike(aggregate, result);
        final Aggregate topAggregate = findNodes(result, Aggregate.class).get(0);
        assertEquals(2, topAggregate.getGroupSets().size());
        assertEquals(topAggregate.getGroupSet(), topAggregate.getGroupSets().get(0));
        assertEquals(1, topAggregate.getGroupSet().cardinality());
        assertTrue(
                topAggregate.getGroupSets().contains(ImmutableBitSet.of()),
                "the empty grouping set should be preserved");
    }

    private static SqlAggFunction nonSplittableAggFunction() {
        return new SqlAggFunction(
                "NON_SPLITTABLE",
                SqlKind.OTHER_FUNCTION,
                ReturnTypes.ARG0,
                null,
                OperandTypes.ANY,
                SqlFunctionCategory.SYSTEM) {
            @Override
            public <T> T unwrap(Class<T> clazz) {
                return null;
            }
        };
    }

    private static RexNode equiCondition(RelBuilder builder, RelNode left, RelNode right) {
        return builder.equals(
                inputRef(builder, left, 0, 0),
                inputRef(builder, right, 0, left.getRowType().getFieldCount()));
    }

    private static RexNode nonEquiCondition(RelBuilder builder, RelNode left, RelNode right) {
        return builder.lessThan(
                inputRef(builder, left, 0, 0),
                inputRef(builder, right, 0, left.getRowType().getFieldCount()));
    }

    private static RexNode inputRef(
            RelBuilder builder, RelNode input, int fieldIndex, int absoluteIndex) {
        return builder.getRexBuilder()
                .makeInputRef(
                        input.getRowType().getFieldList().get(fieldIndex).getType(), absoluteIndex);
    }

    private static RelBuilder newBuilder() {
        final JavaTypeFactoryImpl typeFactory = new JavaTypeFactoryImpl();
        final RelOptCluster cluster =
                RelOptCluster.create(new VolcanoPlanner(), new RexBuilder(typeFactory));
        return RelFactories.LOGICAL_BUILDER.create(cluster, null);
    }

    private static RelationFixture buildFixture(RelBuilder builder, JoinRelType joinType) {
        // The duplicate values make the join inputs non-unique on the join/group keys.
        final RelNode left =
                builder.values(
                                new String[] {"a", "b", "flag"},
                                1,
                                "x",
                                true,
                                1,
                                "x",
                                false,
                                2,
                                "y",
                                true)
                        .build();
        final RelNode right = builder.values(new String[] {"c", "d"}, 1, 10, 1, 20, 2, 30).build();
        final RelNode join =
                builder.push(left)
                        .push(right)
                        .join(joinType, equiCondition(builder, left, right))
                        .build();
        return new RelationFixture(join);
    }

    private static Aggregate createAggregate(
            RelNode input, ImmutableBitSet groupSet, List<AggregateCall> calls) {
        return (Aggregate)
                LogicalAggregate.create(input, groupSet, ImmutableList.of(groupSet), calls);
    }

    private static RelNode fire(RelOptRule rule, Aggregate aggregate, Join join) {
        final CapturingRuleCall call = new CapturingRuleCall(rule, aggregate, join);
        rule.onMatch(call);
        return call.transformed;
    }

    private static boolean containsAuxiliaryGroup(RelNode node) {
        if (node instanceof Aggregate) {
            for (AggregateCall call : ((Aggregate) node).getAggCallList()) {
                if (call.getAggregation() == FlinkSqlOperatorTable.AUXILIARY_GROUP) {
                    return true;
                }
            }
        }
        for (RelNode input : node.getInputs()) {
            if (containsAuxiliaryGroup(input)) {
                return true;
            }
        }
        return false;
    }

    private static void assertRowTypeLike(RelNode expected, RelNode actual) {
        final List<RelDataTypeField> expectedFields = expected.getRowType().getFieldList();
        final List<RelDataTypeField> actualFields = actual.getRowType().getFieldList();
        assertEquals(expectedFields.size(), actualFields.size());
        for (int i = 0; i < expectedFields.size(); i++) {
            final RelDataType expectedType = expectedFields.get(i).getType();
            final RelDataType actualType = actualFields.get(i).getType();
            assertEquals(expectedType.getSqlTypeName(), actualType.getSqlTypeName());
            assertEquals(expectedType.isNullable(), actualType.isNullable());
        }
    }

    private static <T extends RelNode> T findSingleNode(RelNode root, Class<T> type) {
        final List<T> nodes = findNodes(root, type);
        assertEquals(1, nodes.size(), () -> "expected one " + type.getSimpleName());
        return nodes.get(0);
    }

    private static <T extends RelNode> List<T> findNodes(RelNode root, Class<T> type) {
        final List<T> result = new ArrayList<>();
        collectNodes(root, type, result);
        return result;
    }

    private static <T extends RelNode> void collectNodes(
            RelNode node, Class<T> type, List<T> result) {
        if (type.isInstance(node)) {
            result.add(type.cast(node));
        }
        for (RelNode input : node.getInputs()) {
            collectNodes(input, type, result);
        }
    }

    private static final class RelationFixture {
        private final Join join;

        private RelationFixture(RelNode join) {
            this.join = (Join) join;
        }
    }

    private static final class CapturingRuleCall extends RelOptRuleCall {
        private RelNode transformed;

        private CapturingRuleCall(RelOptRule rule, Aggregate aggregate, Join join) {
            super(
                    aggregate.getCluster().getPlanner(),
                    rule.getOperand(),
                    new RelNode[] {aggregate, join},
                    Collections.emptyMap());
        }

        @Override
        public void transformTo(
                RelNode rel, Map<RelNode, RelNode> equiv, RelHintsPropagator relHintsPropagator) {
            transformed = rel;
        }
    }
