/** Tests for {@link SplitAggregateRule#onMatch}. */
class SplitAggregateRuleOnMatchTests {

    @Test
    void testBasicDistinctAggregate() {
        TableConfig tableConfig = createTableConfig(8);
        RelOptCluster cluster = createCluster(tableConfig);
        RelNode input = createInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "cnt"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);
        printPlan("basic", result);
    }

    @Test
    void testSameHashFieldAcrossDistinctAndMinMax() {
        TableConfig tableConfig = createTableConfig(8);
        RelOptCluster cluster = createCluster(tableConfig);
        RelNode input = createInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "cnt"),
                        createAggCall(
                                SqlStdOperatorTable.MAX,
                                false,
                                ImmutableList.of(0),
                                1,
                                input,
                                "max"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);
        printPlan("sameHash", result);
    }

    @Test
    void testDifferentHashFieldsRequireExpand() {
        TableConfig tableConfig = createTableConfig(8);
        RelOptCluster cluster = createCluster(tableConfig);
        RelNode input = createInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "cntA"),
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(1),
                                1,
                                input,
                                "cntB"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);
        printPlan("expand", result);
    }

    @Test
    void testDistinctAvgRequiresOutputMerge() {
        TableConfig tableConfig = createTableConfig(8);
        RelOptCluster cluster = createCluster(tableConfig);
        RelNode input = createInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.AVG,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "avg"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);
        printPlan("avg", result);
    }

    @Test
    void testDistinctOnGroupingFieldDoesNotAddHashField() {
        TableConfig tableConfig = createTableConfig(8);
        RelOptCluster cluster = createCluster(tableConfig);
        RelNode input = createInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(1),
                                1,
                                input,
                                "cntB"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);
        printPlan("groupingField", result);
    }

    private static TableConfig createTableConfig(int buckets) {
        TableConfig tableConfig = TableConfig.getDefault();
        tableConfig.set(
                OptimizerConfigOptions.TABLE_OPTIMIZER_DISTINCT_AGG_SPLIT_BUCKET_NUM, buckets);
        return tableConfig;
    }

    private static RelOptCluster createCluster(TableConfig tableConfig) {
        FlinkTypeFactory typeFactory =
                new FlinkTypeFactory(SplitAggregateRuleOnMatchTests.class.getClassLoader());
        CatalogManager catalogManager = mock(CatalogManager.class);
        when(catalogManager.getDataTypeFactory()).thenReturn(mock(DataTypeFactory.class));
        FlinkContextImpl context =
                new FlinkContextImpl(
                        false,
                        tableConfig,
                        null,
                        null,
                        catalogManager,
                        null,
                        SplitAggregateRuleOnMatchTests.class.getClassLoader());
        VolcanoPlanner planner = new VolcanoPlanner(null, context);
        return RelOptCluster.create(planner, new RexBuilder(typeFactory));
    }

    private static RelNode createInput(RelOptCluster cluster) {
        FlinkTypeFactory typeFactory = (FlinkTypeFactory) cluster.getTypeFactory();
        RelDataType rowType =
                typeFactory
                        .builder()
                        .add("a", SqlTypeName.BIGINT)
                        .add("b", SqlTypeName.INTEGER)
                        .build();
        RexLiteral one = cluster.getRexBuilder().makeExactLiteral(BigDecimal.ONE);
        return FlinkLogicalValues.create(
                cluster,
                cluster.traitSet(),
                rowType,
                ImmutableList.of(ImmutableList.of(one, one), ImmutableList.of(one, one)));
    }

    private static AggregateCall createAggCall(
            SqlAggFunction function,
            boolean distinct,
            List<Integer> args,
            int groupCount,
            RelNode input,
            String name) {
        return AggregateCall.create(
                function,
                distinct,
                false,
                false,
                args,
                -1,
                null,
                RelCollations.EMPTY,
                groupCount,
                input,
                null,
                name);
    }

    private static RelNode runRule(
            RelOptCluster cluster,
            RelNode input,
            ImmutableBitSet groupSet,
            List<AggregateCall> aggCalls) {
        FlinkLogicalAggregate aggregate =
                FlinkLogicalAggregate.create(
                        input, groupSet, ImmutableList.of(groupSet), aggCalls, ImmutableList.of());
        FlinkRelBuilder relBuilder = FlinkRelBuilder.of(cluster, null);
        CapturingRuleCall call = new CapturingRuleCall(aggregate, input, relBuilder, cluster);
        SplitAggregateRule.INSTANCE.onMatch(call);
        assertThat(call.result).isNotNull();
        return call.result;
    }

    private static void printPlan(String marker, RelNode result) {
        System.out.println(
                "PLAN_" + marker + "_START\n" + RelOptUtil.toString(result) + "\nPLAN_END");
    }

    private static class CapturingRuleCall extends RelOptRuleCall {
        private final RelBuilder relBuilder;
        private RelNode result;

        private CapturingRuleCall(
                RelNode aggregate,
                RelNode input,
                RelBuilder relBuilder,
                RelOptCluster cluster) {
            super(
                    cluster.getPlanner(),
                    SplitAggregateRule.INSTANCE.getOperand(),
                    new RelNode[] {aggregate, input},
                    Collections.emptyMap(),
                    Collections.emptyList());
            this.relBuilder = relBuilder;
        }

        @Override
        public RelBuilder builder() {
            return relBuilder;
        }

        @Override
        public void transformTo(
                RelNode rel, Map<RelNode, RelNode> equiv, RelHintsPropagator hintsPropagator) {
            this.result = rel;
        }
    }
}
