                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "cnt"),
                        createAggCall(
                                SqlStdOperatorTable.MAX,
                                false,
                                ImmutableList.of(0),
                                1,
                                input,
                                "max"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);
        printPlan("sameHash", result);
    }

    @Test
    void testDifferentHashFieldsRequireExpand() {
        TableConfig tableConfig = createTableConfig(8);
        RelOptCluster cluster = createCluster(tableConfig);
        RelNode input = createInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
