/** Tests for {@link SplitAggregateRule#onMatch}. */
class SplitAggregateRuleOnMatchTests {

    @Test
    void testBasicDistinctAggregate() {
        RelOptCluster cluster = createCluster(8);
        RelNode input = createTwoFieldInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "cnt"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);

        assertThat(result).isInstanceOf(FlinkLogicalAggregate.class);
        FlinkLogicalAggregate finalAggregate = (FlinkLogicalAggregate) result;
        assertThat(finalAggregate.partialFinalType()).isEqualTo(PartialFinalType.FINAL);
        assertThat(finalAggregate.getGroupSet()).isEqualTo(ImmutableBitSet.of(0));
        assertThat(finalAggregate.getGroupSets()).containsExactly(ImmutableBitSet.of(0));
        assertThat(finalAggregate.getAggCallList()).hasSize(1);
        assertAggCall(
                finalAggregate.getAggCallList().get(0),
                SqlStdOperatorTable.SUM0,
                false,
                2,
                -1);
        assertThat(result.getRowType().getFieldCount()).isEqualTo(2);

        FlinkLogicalAggregate partialAggregate =
                assertThat(finalAggregate.getInput())
                        .isInstanceOfSatisfying(
                                FlinkLogicalAggregate.class,
                                aggregate ->
                                        assertThat(aggregate.partialFinalType())
                                                .isEqualTo(PartialFinalType.PARTIAL))
                        .actual();
        assertThat(partialAggregate.getGroupSet()).isEqualTo(ImmutableBitSet.of(1, 2));
        assertThat(partialAggregate.getGroupSets()).containsExactly(ImmutableBitSet.of(1, 2));
        assertThat(partialAggregate.getAggCallList()).hasSize(1);
        assertAggCall(
                partialAggregate.getAggCallList().get(0),
                SqlStdOperatorTable.COUNT,
                true,
                0,
                -1);

        assertHashProjection(partialAggregate.getInput(), new int[] {0}, new int[] {2}, 8);
        assertThat(findFirstNode(result, LogicalExpand.class)).isNull();
    }

    @Test
    void testDistinctOnGroupingFieldDoesNotAddHashField() {
        RelOptCluster cluster = createCluster(8);
        RelNode input = createTwoFieldInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(1),
                                1,
                                input,
                                "cntB"));

        RelNode result = runRule(cluster, input, groupSet, aggCalls);

        FlinkLogicalAggregate finalAggregate = (FlinkLogicalAggregate) result;
        assertThat(finalAggregate.getGroupSet()).isEqualTo(ImmutableBitSet.of(0));
        assertAggCall(
                finalAggregate.getAggCallList().get(0),
                SqlStdOperatorTable.SUM0,
                false,
                1,
                -1);

        FlinkLogicalAggregate partialAggregate =
                (FlinkLogicalAggregate) finalAggregate.getInput();
        assertThat(partialAggregate.getGroupSet()).isEqualTo(ImmutableBitSet.of(1));
        assertAggCall(
                partialAggregate.getAggCallList().get(0),
                SqlStdOperatorTable.COUNT,
                true,
                1,
                -1);
        assertThat(partialAggregate.getInput()).isInstanceOf(FlinkLogicalValues.class);
        assertThat(findFirstNode(result, LogicalExpand.class)).isNull();
    }

    @Test
    void testSameHashFieldIsReusedWithoutExpand() {
        RelOptCluster cluster = createCluster(8);
        RelNode input = createTwoFieldInput(cluster);
        ImmutableBitSet groupSet = ImmutableBitSet.of(1);
        List<AggregateCall> aggCalls =
                ImmutableList.of(
                        createAggCall(
                                SqlStdOperatorTable.COUNT,
                                true,
                                ImmutableList.of(0),
                                1,
                                input,
                                "cnt"),
                        createAggCall(
                                SqlStdOperatorTable.MAX,
                                false,
                                ImmutableList.of(0),
                                1,
