    private static RelOptCluster createCluster(int buckets) {
        TableConfig tableConfig = TableConfig.getDefault();
        tableConfig.set(
                OptimizerConfigOptions.TABLE_OPTIMIZER_DISTINCT_AGG_SPLIT_BUCKET_NUM, buckets);
        FlinkTypeFactory typeFactory =
                new FlinkTypeFactory(SplitAggregateRuleOnMatchTests.class.getClassLoader());
        CatalogManager catalogManager = mock(CatalogManager.class);
        when(catalogManager.getDataTypeFactory()).thenReturn(mock(DataTypeFactory.class));
        FlinkContextImpl context =
                new FlinkContextImpl(
                        false,
                        tableConfig,
                        null,
                        null,
                        catalogManager,
                        null,
                        SplitAggregateRuleOnMatchTests.class.getClassLoader());
        VolcanoPlanner planner = new VolcanoPlanner(null, context);
        return RelOptCluster.create(planner, new RexBuilder(typeFactory));
    }

    private static RelNode createTwoFieldInput(RelOptCluster cluster) {
        return createInput(
                cluster,
                ImmutableList.of("a", "b"),
                ImmutableList.of(SqlTypeName.BIGINT, SqlTypeName.INTEGER));
    }

    private static RelNode createThreeFieldInput(RelOptCluster cluster) {
        return createInput(
                cluster,
                ImmutableList.of("a", "b", "c"),
                ImmutableList.of(SqlTypeName.BIGINT, SqlTypeName.INTEGER, SqlTypeName.INTEGER));
    }

    private static RelNode createInput(
            RelOptCluster cluster, List<String> fieldNames, List<SqlTypeName> fieldTypes) {
        RelDataTypeFactory.Builder rowTypeBuilder = cluster.getTypeFactory().builder();
        for (int i = 0; i < fieldNames.size(); i++) {
            rowTypeBuilder.add(fieldNames.get(i), fieldTypes.get(i));
        }
        RelDataType rowType = rowTypeBuilder.build();
        RexLiteral one = cluster.getRexBuilder().makeExactLiteral(BigDecimal.ONE);
        ImmutableList<RexLiteral> row =
                ImmutableList.copyOf(Collections.nCopies(fieldNames.size(), one));
        return FlinkLogicalValues.create(
                cluster, cluster.traitSet(), rowType, ImmutableList.of(row, row));
    }

    private static AggregateCall createAggCall(
            SqlAggFunction function,
            boolean distinct,
            List<Integer> args,
            int groupCount,
            RelNode input,
            String name) {
        return AggregateCall.create(
                function,
                distinct,
                false,
                false,
                args,
                -1,
                null,
                RelCollations.EMPTY,
                groupCount,
                input,
                null,
                name);
    }

    private static CapturingRuleCall createRuleCall(
            RelOptCluster cluster,
            RelNode input,
            ImmutableBitSet groupSet,
            List<AggregateCall> aggCalls) {
        FlinkLogicalAggregate aggregate =
                FlinkLogicalAggregate.create(
                        input, groupSet, ImmutableList.of(groupSet), aggCalls, ImmutableList.of());
        return new CapturingRuleCall(
                aggregate, input, FlinkRelBuilder.of(cluster, null), cluster);
    }

    private static RelNode runRule(
            RelOptCluster cluster,
            RelNode input,
            ImmutableBitSet groupSet,
            List<AggregateCall> aggCalls) {
        CapturingRuleCall call = createRuleCall(cluster, input, groupSet, aggCalls);
        SplitAggregateRule.INSTANCE.onMatch(call);
        assertThat(call.result).isNotNull();
        assertThat(call.transformCount).isOne();
        return call.result;
    }

    private static void assertAggCall(
            AggregateCall call,
            SqlAggFunction function,
            boolean distinct,
            int argIndex,
            int filterArg) {
        assertThat(call.getAggregation()).isEqualTo(function);
        assertThat(call.isDistinct()).isEqualTo(distinct);
        assertThat(call.getArgList()).containsExactly(argIndex);
        assertThat(call.filterArg).isEqualTo(filterArg);
    }

    private static Project assertHashProjection(
            RelNode node, int[] hashedFieldIndexes, int[] projectionIndexes, int buckets) {
        assertThat(node).isInstanceOf(Project.class);
        Project project = (Project) node;
        assertThat(hashedFieldIndexes).hasSameSizeAs(projectionIndexes);
        for (int i = 0; i < hashedFieldIndexes.length; i++) {
            RexCall mod =
                    asRexCall(
                            project.getProjects().get(projectionIndexes[i]),
                            SqlStdOperatorTable.MOD);
            assertThat(RexLiteral.intValue(mod.getOperands().get(1))).isEqualTo(buckets);
            RexCall hash =
                    asRexCall(
                            mod.getOperands().get(0), FlinkSqlOperatorTable.HASH_CODE);
            assertInputRef(hash.getOperands().get(0), hashedFieldIndexes[i]);
        }
        return project;
    }

    private static void assertExpandIdFilter(RexCall equals, int expandIdIndex, int expectedId) {
        assertThat(equals.getOperator()).isEqualTo(FlinkSqlOperatorTable.EQUALS);
        assertInputRef(equals.getOperands().get(0), expandIdIndex);
        assertThat(RexLiteral.intValue(equals.getOperands().get(1))).isEqualTo(expectedId);
    }

    private static void assertAvgOutput(
            RexNode expression, int countIndex, int sumIndex, int countOperandIndex) {
        RexCall ifCall = findRexCall(expression, FlinkSqlOperatorTable.IF);
        assertThat(ifCall).isNotNull();
        assertThat(ifCall.getOperands()).hasSize(3);

        RexCall equals = asRexCall(ifCall.getOperands().get(0), FlinkSqlOperatorTable.EQUALS);
        assertInputRef(equals.getOperands().get(0), countIndex);
        assertThat(RexLiteral.longValue(equals.getOperands().get(1))).isZero();
        assertThat(RexLiteral.isNullLiteral(ifCall.getOperands().get(1))).isTrue();

        RexCall divide = asRexCall(ifCall.getOperands().get(2), FlinkSqlOperatorTable.DIVIDE);
        assertInputRef(divide.getOperands().get(0), sumIndex);
        assertInputRef(divide.getOperands().get(1), countOperandIndex);
    }

    private static void assertInputRef(RexNode node, int expectedIndex) {
        assertThat(node).isInstanceOf(RexInputRef.class);
        assertThat(((RexInputRef) node).getIndex()).isEqualTo(expectedIndex);
    }

    private static RexCall asRexCall(RexNode node, SqlOperator expectedOperator) {
        assertThat(node).isInstanceOf(RexCall.class);
        RexCall call = (RexCall) node;
        assertThat(call.getOperator()).isEqualTo(expectedOperator);
        return call;
    }

    private static RexCall findRexCall(RexNode node, SqlOperator operator) {
        if (node instanceof RexCall) {
            RexCall call = (RexCall) node;
            if (call.getOperator().equals(operator)) {
                return call;
            }
            for (RexNode operand : call.getOperands()) {
                RexCall found = findRexCall(operand, operator);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    private static <T extends RelNode> T findFirstNode(RelNode node, Class<T> nodeClass) {
        if (nodeClass.isInstance(node)) {
            return nodeClass.cast(node);
        }
        for (RelNode input : node.getInputs()) {
            T found = findFirstNode(input, nodeClass);
            if (found != null) {
                return found;
            }
        }
        return null;
    }

    private static class CapturingRuleCall extends RelOptRuleCall {
        private final RelBuilder relBuilder;
        private RelNode result;
        private int transformCount;

        private CapturingRuleCall(
                RelNode aggregate,
                RelNode input,
                RelBuilder relBuilder,
                RelOptCluster cluster) {
            super(
                    cluster.getPlanner(),
                    SplitAggregateRule.INSTANCE.getOperand(),
                    new RelNode[] {aggregate, input},
                    Collections.emptyMap(),
                    Collections.emptyList());
            this.relBuilder = relBuilder;
        }

        @Override
        public RelBuilder builder() {
            return relBuilder;
        }

        @Override
        public void transformTo(
                RelNode rel, Map<RelNode, RelNode> equiv, RelHintsPropagator hintsPropagator) {
            this.result = rel;
            this.transformCount++;
        }
    }
