import org.apache.flink.table.api.DataTypes;
import org.apache.flink.table.data.*;
import org.apache.flink.table.data.util.DataFormatConverters;
import org.apache.flink.table.data.util.DataFormatConverters.*;
import org.apache.flink.table.types.DataType;
import org.apache.flink.table.types.logical.*;
import org.apache.flink.api.common.typeinfo.Types;
import java.math.BigDecimal;

public class P4 {
    static void p(String l, Object o) { System.out.println(l + " => " + o); }
    static DataType legacy(LogicalTypeRoot root, org.apache.flink.api.common.typeinfo.TypeInformation<?> ti) {
        return new org.apache.flink.table.types.AtomicDataType(new LegacyTypeInformationType<>(root, ti));
    }
    public static void main(String[] a) throws Exception {
        DataFormatConverter<?, ?> c = DataFormatConverters.getConverterForDataType(legacy(LogicalTypeRoot.DECIMAL, Types.BIG_DEC));
        p("legacy BIG_DEC converter", c.getClass().getName());
        DecimalData dd = (DecimalData) c.toInternal(new BigDecimal("1.5"));
        p("legacy BIG_DEC", dd + " p=" + dd.precision() + " s=" + dd.scale());
        // row data converter arity
        DataType rowT = DataTypes.ROW(DataTypes.FIELD("f0", DataTypes.INT()), DataTypes.FIELD("f1", DataTypes.STRING()));
        DataFormatConverter<?, ?> rdc = DataFormatConverters.getConverterForDataType(rowT.bridgedTo(RowData.class));
        p("rdc arity", field(rdc, "arity"));
        DataFormatConverter<?, ?> rc = DataFormatConverters.getConverterForDataType(rowT);
        Object internal = rc.toInternal(org.apache.flink.types.Row.of(1, "a"));
        RowData rd = (RowData) internal;
        p("row internal field1 class", rd.getField(1).getClass().getName());
        p("row convert back", rc.toExternal(rd));
        // row with nested decimal retrieval? keep simple
        // array with row elements
        DataType arrRow = DataTypes.ARRAY(DataTypes.ROW(DataTypes.FIELD("f0", DataTypes.INT()))).bridgedTo(org.apache.flink.types.Row[].class);
        p("array row conv", DataFormatConverters.getConverterForDataType(arrRow).getClass().getName());
        // MapData bridged for multiset with Integer values
        // TIMESTAMP_LTZ precision 9 with Timestamp
        DataFormatConverter<?, ?> tl = DataFormatConverters.getConverterForDataType(DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(9).bridgedTo(java.sql.Timestamp.class));
        java.sql.Timestamp ts = new java.sql.Timestamp(1600000000123L);
        ts.setNanos(123456789);
        java.sql.Timestamp out = (java.sql.Timestamp) tl.toExternal(tl.toInternal(ts));
        p("ltz ts nanos", out.getTime() + "/" + out.getNanos());
        // time intervall default conversion classes
        p("interval month default", DataTypes.INTERVAL(DataTypes.MONTH()).getConversionClass());
        // decimal data converter identity
        DataFormatConverter<?, ?> ddc = DataFormatConverters.getConverterForDataType(DataTypes.DECIMAL(5,2).bridgedTo(DecimalData.class));
        DecimalData x = DecimalData.fromBigDecimal(new BigDecimal("1.23"), 5, 2);
        p("ddc identity", ddc.toExternal(ddc.toInternal(x)) == x);
        p("decimal rounding", ((DataFormatConverter) DataFormatConverters.getConverterForDataType(DataTypes.DECIMAL(6,2))).toExternal(((DataFormatConverter) DataFormatConverters.getConverterForDataType(DataTypes.DECIMAL(6,2))).toInternal(new BigDecimal("1.235"))));
        // varchar CHAR bridged to StringData
        p("char stringdata", DataFormatConverters.getConverterForDataType(DataTypes.CHAR(3).bridgedTo(StringData.class)).getClass().getName());
        p("binary identity", DataFormatConverters.getConverterForDataType(DataTypes.BINARY(3)).toInternal(new byte[]{1})[0]);
    }
    static Object field(Object target, String name) throws Exception {
        Class<?> c = target.getClass();
        while (c != null) {
            try { java.lang.reflect.Field f = c.getDeclaredField(name); f.setAccessible(true); return f.get(target); }
            catch (NoSuchFieldException e) { c = c.getSuperclass(); }
        }
        return null;
    }
}
