    @Test
    void testVarcharWithStringConversionClass() {
        DataFormatConverter converter = converter(DataTypes.STRING());
        assertEquals(StringConverter.class, converter.getClass());

        // round trip
        Object internal = converter.toInternal("hello");
        assertEquals(StringData.fromString("hello"), internal);
        assertEquals("hello", converter.toExternal(internal));

        // null handling of the generic entry points
        assertNull(converter.toInternal(null));
        assertNull(converter.toExternal((Object) null));

        // row based access
        RowData row = GenericRowData.of(1, StringData.fromString("row-value"), null);
        assertEquals("row-value", converter.toExternal(row, 1));
        assertNull(converter.toExternal(row, 2));
    }

    @Test
