/**
 * Tests for {@link DataFormatConverters#getConverterForDataType(DataType)}.
 *
 * <p>The tests verify which converter implementation is selected for a given {@link DataType} and,
 * for converters that encode type information (precision, scale, element type), that the produced
 * converter actually converts values accordingly.
 */
class DataFormatConvertersGetConverterForDataTypeTests {

    // ----------------------------------------------------------------------------------------
    // Converters that are registered in the static lookup map
    // ----------------------------------------------------------------------------------------

    @Test
    void testNumericConvertersFromStaticLookup() {
        assertSame(BooleanConverter.INSTANCE, converter(DataTypes.BOOLEAN()));
        assertSame(
                BooleanConverter.INSTANCE,
                converter(DataTypes.BOOLEAN().bridgedTo(boolean.class)));

        assertSame(ByteConverter.INSTANCE, converter(DataTypes.TINYINT()));
        assertSame(ByteConverter.INSTANCE, converter(DataTypes.TINYINT().bridgedTo(byte.class)));

        assertSame(ShortConverter.INSTANCE, converter(DataTypes.SMALLINT()));
        assertSame(
                ShortConverter.INSTANCE, converter(DataTypes.SMALLINT().bridgedTo(short.class)));

        assertSame(IntConverter.INSTANCE, converter(DataTypes.INT()));
        assertSame(IntConverter.INSTANCE, converter(DataTypes.INT().bridgedTo(int.class)));

        assertSame(LongConverter.INSTANCE, converter(DataTypes.BIGINT()));
        assertSame(LongConverter.INSTANCE, converter(DataTypes.BIGINT().bridgedTo(long.class)));

        assertSame(FloatConverter.INSTANCE, converter(DataTypes.FLOAT()));
        assertSame(FloatConverter.INSTANCE, converter(DataTypes.FLOAT().bridgedTo(float.class)));

        assertSame(DoubleConverter.INSTANCE, converter(DataTypes.DOUBLE()));
        assertSame(DoubleConverter.INSTANCE, converter(DataTypes.DOUBLE().bridgedTo(double.class)));
    }

    @Test
    void testDateAndTimeConvertersFromStaticLookup() {
        assertSame(LocalDateConverter.INSTANCE, converter(DataTypes.DATE()));
        assertSame(
                LocalDateConverter.INSTANCE,
                converter(DataTypes.DATE().bridgedTo(LocalDate.class)));
        assertSame(
                DateConverter.INSTANCE, converter(DataTypes.DATE().bridgedTo(java.sql.Date.class)));
        assertSame(
                IntConverter.INSTANCE, converter(DataTypes.DATE().bridgedTo(Integer.class)));
        assertSame(IntConverter.INSTANCE, converter(DataTypes.DATE().bridgedTo(int.class)));

        assertSame(LocalTimeConverter.INSTANCE, converter(DataTypes.TIME()));
        assertSame(
                LocalTimeConverter.INSTANCE,
                converter(DataTypes.TIME().bridgedTo(LocalTime.class)));
        assertSame(
                TimeConverter.INSTANCE, converter(DataTypes.TIME().bridgedTo(java.sql.Time.class)));
        assertSame(
                IntConverter.INSTANCE, converter(DataTypes.TIME().bridgedTo(Integer.class)));
        assertSame(IntConverter.INSTANCE, converter(DataTypes.TIME().bridgedTo(int.class)));
    }

    @Test
    void testIntervalAndBitmapConvertersFromStaticLookup() {
        assertSame(
                IntConverter.INSTANCE,
                converter(DataTypes.INTERVAL(DataTypes.MONTH()).bridgedTo(Integer.class)));
        assertSame(
                IntConverter.INSTANCE,
                converter(DataTypes.INTERVAL(DataTypes.MONTH()).bridgedTo(int.class)));

        assertSame(
