    private static void assertInvalidDataType(DataType dataType) {
        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(dataType));
        assertTrue(
                exception.getMessage().startsWith("Not support dataType: "),
                "unexpected message: " + exception.getMessage());
    }

    private static Object readPrivateField(Object target, String fieldName) {
        Class<?> current = target.getClass();
        while (current != null) {
            try {
                Field field = current.getDeclaredField(fieldName);
                field.setAccessible(true);
                return field.get(target);
            } catch (NoSuchFieldException e) {
                current = current.getSuperclass();
            } catch (IllegalAccessException e) {
                throw new IllegalStateException(e);
            }
        }
        throw new IllegalStateException(
                "Could not find field '" + fieldName + "' in " + target.getClass());
    }

