    @Test
    void testDecimalWithBigDecimalConversionClass() {
        DataType dataType = DataTypes.DECIMAL(10, 3);
        DataFormatConverter converter = converter(dataType);
        assertEquals(BigDecimalConverter.class, converter.getClass());

        // the precision and scale of the logical type must be wired into the converter
        DecimalData internal = (DecimalData) converter.toInternal(new BigDecimal("1.234"));
        assertEquals(10, internal.precision());
        assertEquals(3, internal.scale());
        assertEquals(new BigDecimal("1.234"), converter.toExternal(internal));

        // converters are not cached, but created on demand
        assertNotSame(converter, converter(dataType));
    }

    @Test
    void testDecimalConverterRoundsToScaleOfLogicalType() {
        DataFormatConverter converter = converter(DataTypes.DECIMAL(6, 2));
        DecimalData internal = (DecimalData) converter.toInternal(new BigDecimal("1.235"));

        assertEquals(6, internal.precision());
        assertEquals(2, internal.scale());
        assertEquals(new BigDecimal("1.24"), converter.toExternal(internal));
    }

    @Test
    void testDecimalWithDecimalDataConversionClass() {
        DataFormatConverter converter = converter(DataTypes.DECIMAL(5, 2).bridgedTo(DecimalData.class));
        assertEquals(DecimalDataConverter.class, converter.getClass());
        assertEquals(5, readPrivateField(converter, "precision"));
        assertEquals(2, readPrivateField(converter, "scale"));

        DecimalData value = DecimalData.fromBigDecimal(new BigDecimal("1.23"), 5, 2);
        assertSame(value, converter.toExternal(converter.toInternal(value)));
    }

    @Test
    void testDecimalWithLegacyTypeInformation() {
        DataFormatConverter bigDecimalConverter =
                converter(legacyDataType(LogicalTypeRoot.DECIMAL, new BigDecimalTypeInfo(7, 4)));
        assertEquals(BigDecimalConverter.class, bigDecimalConverter.getClass());
        DecimalData internal = (DecimalData) bigDecimalConverter.toInternal(new BigDecimal("1.2345"));
        assertEquals(7, internal.precision());
        assertEquals(4, internal.scale());

        DataFormatConverter decimalDataConverter =
                converter(
                        legacyDataType(LogicalTypeRoot.DECIMAL, new DecimalDataTypeInfo(6, 2))
                                .bridgedTo(DecimalData.class));
        assertEquals(DecimalDataConverter.class, decimalDataConverter.getClass());
        assertEquals(6, readPrivateField(decimalDataConverter, "precision"));
        assertEquals(2, readPrivateField(decimalDataConverter, "scale"));
    }

    @Test
    void testDecimalWithUnknownLegacyTypeInformationUsesSystemDefault() {
        // a legacy type information that is neither a BigDecimalTypeInfo nor a
        // DecimalDataTypeInfo falls back to the system default precision/scale
        DataFormatConverter converter =
                converter(legacyDataType(LogicalTypeRoot.DECIMAL, Types.BIG_DEC));

        assertEquals(BigDecimalConverter.class, converter.getClass());
        DecimalData internal = (DecimalData) converter.toInternal(new BigDecimal("1.5"));
        assertEquals(38, internal.precision());
        assertEquals(18, internal.scale());
    }

