    @Test
    void testTimestampConverters() {
        DataFormatConverter localDateTimeConverter = converter(DataTypes.TIMESTAMP(6));
        assertEquals(LocalDateTimeConverter.class, localDateTimeConverter.getClass());
        assertEquals(6, readPrivateField(localDateTimeConverter, "precision"));
        LocalDateTime localDateTime = LocalDateTime.of(2021, 1, 2, 3, 4, 5, 123456000);
        assertEquals(
                localDateTime,
                localDateTimeConverter.toExternal(localDateTimeConverter.toInternal(localDateTime)));

        DataFormatConverter timestampConverter =
                converter(DataTypes.TIMESTAMP(3).bridgedTo(java.sql.Timestamp.class));
        assertEquals(TimestampConverter.class, timestampConverter.getClass());
        assertEquals(3, readPrivateField(timestampConverter, "precision"));
        java.sql.Timestamp timestamp = java.sql.Timestamp.valueOf("2021-01-02 03:04:05.123");
        assertEquals(
                timestamp.getTime(),
                ((java.sql.Timestamp) timestampConverter.toExternal(timestampConverter.toInternal(timestamp)))
                        .getTime());

        DataFormatConverter timestampDataConverter =
                converter(DataTypes.TIMESTAMP(9).bridgedTo(TimestampData.class));
        assertEquals(TimestampDataConverter.class, timestampDataConverter.getClass());
        assertEquals(9, readPrivateField(timestampDataConverter, "precision"));
        TimestampData timestampData = TimestampData.fromEpochMillis(1000L, 500000);
        assertSame(timestampData, timestampDataConverter.toExternal(timestampDataConverter.toInternal(timestampData)));
    }

    @Test
    void testTimestampConvertersWithLegacyTypeInformation() {
        DataFormatConverter localDateTimeConverter =
                converter(
                        legacyDataType(
                                LogicalTypeRoot.TIMESTAMP_WITHOUT_TIME_ZONE,
                                new LegacyLocalDateTimeTypeInfo(4)));
        assertEquals(LocalDateTimeConverter.class, localDateTimeConverter.getClass());
        assertEquals(4, readPrivateField(localDateTimeConverter, "precision"));

        // only instant and local date time legacy type infos carry a precision, everything else
        // falls back to the default precision of the logical timestamp type
        DataFormatConverter timestampConverter =
                converter(
                        legacyDataType(
                                LogicalTypeRoot.TIMESTAMP_WITHOUT_TIME_ZONE,
                                new LegacyTimestampTypeInfo(5)));
        assertEquals(TimestampConverter.class, timestampConverter.getClass());
        assertEquals(6, readPrivateField(timestampConverter, "precision"));
    }

