    @Test
    void testArrayWithObjectArrayConversionClass() {
        // the element type is bridged to the component type of the array class
        DataFormatConverter stringConverter =
                converter(DataTypes.ARRAY(DataTypes.STRING()).bridgedTo(String[].class));
        assertEquals(ObjectArrayConverter.class, stringConverter.getClass());
        String[] strings = new String[] {"a", null, "c"};
        ArrayData internal = (ArrayData) stringConverter.toInternal(strings);
        assertEquals(3, internal.size());
        assertEquals("a", internal.getString(0).toString());
        assertTrue(internal.isNullAt(1));
        assertArrayEquals(strings, (String[]) stringConverter.toExternal(internal));

        DataFormatConverter integerConverter =
                converter(DataTypes.ARRAY(DataTypes.INT()).bridgedTo(Integer[].class));
        assertEquals(ObjectArrayConverter.class, integerConverter.getClass());
        Integer[] integers = new Integer[] {1, null, 3};
        assertArrayEquals(integers, (Integer[]) integerConverter.toExternal(integerConverter.toInternal(integers)));
    }

    @Test
    void testArrayWithLegacyTypeInformation() {
        // BasicArrayTypeInfo is not a CollectionDataType and takes the legacy branch
        DataType legacyArray =
                new AtomicDataType(
                        new LegacyTypeInformationType<>(
                                LogicalTypeRoot.ARRAY, BasicArrayTypeInfo.STRING_ARRAY_TYPE_INFO));
        DataFormatConverter converter = converter(legacyArray);
        assertEquals(ObjectArrayConverter.class, converter.getClass());
        String[] values = new String[] {"x", "y"};
        assertEquals(values, converter.toExternal(converter.toInternal(values)));

        DataType legacyIntArray =
                new AtomicDataType(
                        new LegacyTypeInformationType<>(
                                LogicalTypeRoot.ARRAY, BasicArrayTypeInfo.INT_ARRAY_TYPE_INFO));
        DataFormatConverter intConverter = converter(legacyIntArray);
        assertEquals(ObjectArrayConverter.class, intConverter.getClass());
        Integer[] intValues = new Integer[] {4, 5};
        assertEquals(intValues, intConverter.toExternal(intConverter.toInternal(intValues)));
    }

