    @Test
    void testMultisetConverters() {
        DataFormatConverter converter = converter(DataTypes.MULTISET(DataTypes.STRING()));
        assertEquals(MapConverter.class, converter.getClass());

        Map<String, Integer> multiset = new LinkedHashMap<>();
        multiset.put("a", 2);
        MapData internal = (MapData) converter.toInternal(multiset);
        assertEquals(1, internal.size());
        assertEquals(multiset, converter.toExternal(internal));

        assertSame(
                MapDataConverter.INSTANCE,
                converter(DataTypes.MULTISET(DataTypes.STRING()).bridgedTo(MapData.class)));
    }

    // ----------------------------------------------------------------------------------------
    // Row types
    // ----------------------------------------------------------------------------------------

    @Test
    void testRowWithRowDataConversionClass() {
        DataType rowType = testRowType();
        DataFormatConverter converter = converter(rowType.bridgedTo(RowData.class));

        assertEquals(RowDataConverter.class, converter.getClass());
        assertEquals(2, readPrivateField(converter, "arity"));

        RowData rowData = GenericRowData.of(1, StringData.fromString("bob"));
        assertSame(rowData, converter.toInternal(rowData));
        assertSame(rowData, converter.toExternal(rowData));
    }

    @Test
    void testRowWithRowConversionClass() {
        DataFormatConverter converter = converter(testRowType());
        assertEquals(RowConverter.class, converter.getClass());

        Row row = Row.of(1, "alice");
        RowData internal = (RowData) converter.toInternal(row);
        assertEquals(1, internal.getInt(0));
        // the field converters of the row are used for the individual fields
        assertEquals(StringData.fromString("alice"), internal.getString(1));
        assertEquals(row, converter.toExternal(internal));
    }

    @Test
    void testRowWithLegacyPojoTypeInformation() {
        DataType pojoType =
                legacyDataType(LogicalTypeRoot.STRUCTURED_TYPE, Types.POJO(TestPojo.class));
        DataFormatConverter converter = converter(pojoType);
        assertEquals(PojoConverter.class, converter.getClass());

        TestPojo pojo = new TestPojo();
        pojo.id = 7;
        pojo.name = "seven";
        RowData internal = (RowData) converter.toInternal(pojo);
        assertEquals(7, internal.getInt(0));
        assertEquals(StringData.fromString("seven"), internal.getString(1));

        TestPojo result = (TestPojo) converter.toExternal(internal);
        assertEquals(7, result.id);
        assertEquals("seven", result.name);
    }

    @Test
    void testRowWithLegacyTupleTypeInformation() {
        DataType tupleType =
                legacyDataType(
                        LogicalTypeRoot.STRUCTURED_TYPE,
                        Types.TUPLE(Types.INT, Types.STRING));
        DataFormatConverter converter = converter(tupleType);
        assertEquals(TupleConverter.class, converter.getClass());

        RowData internal = (RowData) converter.toInternal(Tuple2.of(5, "five"));
        assertEquals(5, internal.getInt(0));
        assertEquals(StringData.fromString("five"), internal.getString(1));
        assertEquals(Tuple2.of(5, "five"), converter.toExternal(internal));
    }

    // ----------------------------------------------------------------------------------------
    // Raw types
    // ----------------------------------------------------------------------------------------

    @Test
    void testRawTypeWithSerializer() {
        DataType rawType = DataTypes.RAW(Integer.class, IntSerializer.INSTANCE);
        DataFormatConverter converter = converter(rawType);
        assertEquals(GenericConverter.class, converter.getClass());

        Object internal = converter.toInternal(42);
        assertTrue(internal instanceof RawValueData);
        assertEquals(42, converter.toExternal(internal));

        assertSame(
                RawValueDataConverter.INSTANCE,
                converter(rawType.bridgedTo(RawValueData.class)));
    }

    @Test
    void testRawTypeWithPlannerTypeInformation() {
        assertSame(
                StringDataConverter.INSTANCE,
                converter(legacyRawType(StringDataTypeInfo.INSTANCE)));

        DataFormatConverter decimalDataConverter =
                converter(legacyRawType(new DecimalDataTypeInfo(5, 2)));
        assertEquals(DecimalDataConverter.class, decimalDataConverter.getClass());
        assertEquals(5, readPrivateField(decimalDataConverter, "precision"));
        assertEquals(2, readPrivateField(decimalDataConverter, "scale"));

        DataFormatConverter bigDecimalConverter =
                converter(legacyRawType(new BigDecimalTypeInfo(6, 3)));
        assertEquals(BigDecimalConverter.class, bigDecimalConverter.getClass());
        DecimalData internal = (DecimalData) bigDecimalConverter.toInternal(new BigDecimal("1.234"));
        assertEquals(6, internal.precision());
        assertEquals(3, internal.scale());

        DataFormatConverter timestampDataConverter =
                converter(legacyRawType(new TimestampDataTypeInfo(7)));
        assertEquals(TimestampDataConverter.class, timestampDataConverter.getClass());
        assertEquals(7, readPrivateField(timestampDataConverter, "precision"));
    }

    @Test
    void testRawTypeWithLegacyDateTimeTypeInformation() {
        DataFormatConverter localDateTimeConverter =
                converter(legacyRawType(new LegacyLocalDateTimeTypeInfo(4)));
        assertEquals(LocalDateTimeConverter.class, localDateTimeConverter.getClass());
        assertEquals(4, readPrivateField(localDateTimeConverter, "precision"));

        DataFormatConverter timestampConverter =
                converter(legacyRawType(new LegacyTimestampTypeInfo(5)));
        assertEquals(TimestampConverter.class, timestampConverter.getClass());
        assertEquals(5, readPrivateField(timestampConverter, "precision"));

        DataFormatConverter instantConverter = converter(legacyRawType(new LegacyInstantTypeInfo(2)));
        assertEquals(InstantConverter.class, instantConverter.getClass());
        assertEquals(2, readPrivateField(instantConverter, "precision"));
    }

    @Test
    void testRawTypeFallbacks() {
        DataFormatConverter genericConverter = converter(legacyRawType(Types.STRING));
        assertEquals(GenericConverter.class, genericConverter.getClass());
        assertEquals("hello", genericConverter.toExternal(genericConverter.toInternal("hello")));

        assertSame(VariantConverter.INSTANCE, converter(legacyRawType(Types.VARIANT)));

        assertSame(
                RawValueDataConverter.INSTANCE,
                converter(legacyRawType(Types.STRING).bridgedTo(RawValueData.class)));
    }

    // ----------------------------------------------------------------------------------------
    // Unsupported types
    // ----------------------------------------------------------------------------------------

    @Test
    void testUnsupportedTypeRootsThrow() {
        assertInvalidDataType(DataTypes.NULL());
        assertInvalidDataType(DataTypes.VARIANT());
        // the default conversion classes of intervals are not supported
        assertInvalidDataType(DataTypes.INTERVAL(DataTypes.MONTH()));
        assertInvalidDataType(DataTypes.INTERVAL(DataTypes.SECOND(3)));
        assertInvalidDataType(DataTypes.INTERVAL(DataTypes.DAY()));
    }

    @Test
    void testNullDataTypeThrows() {
        assertThrows(
                NullPointerException.class,
                () -> DataFormatConverters.getConverterForDataType(null));
    }

    // ----------------------------------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------------------------------

    private static DataType testRowType() {
        return DataTypes.ROW(
                DataTypes.FIELD("id", DataTypes.INT()),
                DataTypes.FIELD("name", DataTypes.STRING()));
    }

    private static DataType legacyDataType(LogicalTypeRoot root, TypeInformation<?> typeInfo) {
        return new AtomicDataType(new LegacyTypeInformationType<>(root, typeInfo));
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    private static DataType legacyRawType(TypeInformation<?> typeInfo) {
        return new AtomicDataType(new TypeInformationRawType(typeInfo));
    }

    private static DataFormatConverter converter(DataType dataType) {
        return DataFormatConverters.getConverterForDataType(dataType);
    }

    private static void assertInvalidDataType(DataType dataType) {
        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(dataType));
        assertTrue(
                exception.getMessage().startsWith("Not support dataType: "),
                "unexpected message: " + exception.getMessage());
    }

    private static Object readPrivateField(Object target, String fieldName) {
        Class<?> current = target.getClass();
        while (current != null) {
            try {
                Field field = current.getDeclaredField(fieldName);
                field.setAccessible(true);
                return field.get(target);
            } catch (NoSuchFieldException e) {
                current = current.getSuperclass();
            } catch (IllegalAccessException e) {
                throw new IllegalStateException(e);
            }
        }
        throw new IllegalStateException(
                "Could not find field '" + fieldName + "' in " + target.getClass());
    }

    /** Test POJO for the legacy POJO type information branch. */
    public static class TestPojo {
        public int id;
        public String name;

        public TestPojo() {}
    }

