@Test
void testCachedConvertersAreUsedForNotNullableDataTypes() {
    // the lookup normalizes the data type to a nullable data type before the map lookup
    assertSame(IntConverter.INSTANCE, converter(DataTypes.INT().notNull()));
    assertSame(LongConverter.INSTANCE, converter(DataTypes.BIGINT().notNull()));
    assertSame(BitmapConverter.INSTANCE, converter(DataTypes.BITMAP().notNull()));
    assertSame(
            LocalDateConverter.INSTANCE,
            converter(DataTypes.DATE().bridgedTo(LocalDate.class).notNull()));
}

@Test
void testIdentityConvertersPassValuesThrough() {
    assertEquals(42, converter(DataTypes.INT()).toInternal(42));
    assertEquals(42, converter(DataTypes.INT()).toExternal(42));
    assertEquals(1600000000123L, converter(DataTypes.BIGINT()).toInternal(1600000000123L));
    assertSame(Boolean.TRUE, converter(DataTypes.BOOLEAN()).toInternal(Boolean.TRUE));
    assertSame(Short.valueOf((short) 3), converter(DataTypes.SMALLINT()).toInternal((short) 3));

    byte[] bytes = new byte[] {1, 2, 3};
    assertSame(bytes, converter(DataTypes.BYTES()).toInternal(bytes));
    assertSame(bytes, converter(DataTypes.BYTES()).toExternal(bytes));
}

