@Test
void testBinaryAndVarBinary() {
    assertSame(PrimitiveByteArrayConverter.INSTANCE, converter(DataTypes.BYTES()));
    assertSame(PrimitiveByteArrayConverter.INSTANCE, converter(DataTypes.BINARY(3)));
    assertSame(PrimitiveByteArrayConverter.INSTANCE, converter(DataTypes.VARBINARY(10)));

    byte[] bytes = new byte[] {10, 20};
    Object internal = converter(DataTypes.BINARY(3)).toInternal(bytes);
