        assertInvalidDataType(DataTypes.INTERVAL(DataTypes.MONTH()));
        assertInvalidDataType(DataTypes.INTERVAL(DataTypes.SECOND(3)));
        assertInvalidDataType(DataTypes.INTERVAL(DataTypes.DAY()));
    }

    @Test
    void testNullDataTypeThrows() {
        assertThrows(
                NullPointerException.class,
                () -> DataFormatConverters.getConverterForDataType(null));
    }

    // ----------------------------------------------------------------------------------------
    // Helpers
    // ----------------------------------------------------------------------------------------

    private static DataType testRowType() {
        return DataTypes.ROW(
                DataTypes.FIELD("id", DataTypes.INT()),
                DataTypes.FIELD("name", DataTypes.STRING()));
    }

    private static DataType legacyDataType(LogicalTypeRoot root, TypeInformation<?> typeInfo) {
        return new AtomicDataType(new LegacyTypeInformationType<>(root, typeInfo));
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    private static DataType legacyRawType(TypeInformation<?> typeInfo) {
        return new AtomicDataType(new TypeInformationRawType(typeInfo));
    }

    private static DataFormatConverter converter(DataType dataType) {
        return DataFormatConverters.getConverterForDataType(dataType);
    }

    private static void assertInvalidDataType(DataType dataType) {
        RuntimeException exception =
                assertThrows(
                        RuntimeException.class,
                        () -> DataFormatConverters.getConverterForDataType(dataType));
        assertTrue(
                exception.getMessage().startsWith("Not support dataType: "),
                "unexpected message: " + exception.getMessage());
    }

    private static Object readPrivateField(Object target, String fieldName) {
        Class<?> current = target.getClass();
        while (current != null) {
            try {
                Field field = current.getDeclaredField(fieldName);
                field.setAccessible(true);
                return field.get(target);
            } catch (NoSuchFieldException e) {
                current = current.getSuperclass();
            } catch (IllegalAccessException e) {
                throw new IllegalStateException(e);
            }
        }
        throw new IllegalStateException(
                "Could not find field '" + fieldName + "' in " + target.getClass());
    }

    /** Test POJO for the legacy POJO type information branch. */
    public static class TestPojo {
        public int id;
        public String name;

        public TestPojo() {}
    }
}

