    // ---------------------------------------------------------------------------------------------
    // Test harness
    // ---------------------------------------------------------------------------------------------

    private static StreamingJoinOperator createOperator(
            boolean leftIsOuter,
            boolean rightIsOuter,
            boolean hasNonEquiCondition,
            JoinInputSideSpec leftSpec,
            JoinInputSideSpec rightSpec,
            RuntimeChangelogMode leftInputChangelogMode,
            RuntimeChangelogMode rightInputChangelogMode,
            JoinCondition condition,
            List<GenericRowData> output)
            throws Exception {
        final StreamingJoinOperator operator =
                new StreamingJoinOperator(
                        LEFT_TYPE,
                        RIGHT_TYPE,
                        new GeneratedJoinCondition("test", "test", new Object[0]),
                        leftSpec,
                        rightSpec,
                        leftIsOuter,
                        rightIsOuter,
                        leftInputChangelogMode,
                        rightInputChangelogMode,
                        hasNonEquiCondition,
                        new boolean[0],
                        -1L,
                        -1L);
        operator.joinCondition = new JoinConditionWithNullFilters(condition, new boolean[0], operator);
        operator.collector = new TimestampedCollector<>(new CollectingOutput(output));
        setField(operator, "outRow", new JoinedRowData());
        setField(operator, "leftNullRow", new GenericRowData(LEFT_TYPE.toRowSize()));
        setField(operator, "rightNullRow", new GenericRowData(RIGHT_TYPE.toRowSize()));
        return operator;
    }

    private static void setField(Object target, String fieldName, Object value) throws Exception {
        final Field field = StreamingJoinOperator.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static JoinCondition joinKeyEquals() {
        return new TestJoinCondition(
                (left, right) -> left.getInt(0) == right.getInt(0));
    }

    private static JoinCondition joinKeyEqualsAndLeftValueAtLeastRightValue() {
        return new TestJoinCondition(
                (left, right) ->
                        left.getInt(0) == right.getInt(0)
                                && left.getInt(1) >= right.getInt(1));
    }

    private static GenericRowData row(RowKind kind, Integer... values) {
        final GenericRowData row = new GenericRowData(kind, values.length);
        for (int i = 0; i < values.length; i++) {
            if (values[i] != null) {
                row.setInt(i, values[i]);
            }
        }
        return row;
    }

    private static GenericRowData row(int id, int value) {
        return row(RowKind.INSERT, id, value);
    }

    private static Tuple2<RowData, Integer> outer(RowData record, int numOfAssociations) {
        return Tuple2.of(record, numOfAssociations);
    }

    private static Update update(RowData record, int numOfAssociations) {
        return new Update(record, numOfAssociations);
    }

    private static void assertOutputs(
            List<GenericRowData> expected, List<GenericRowData> actual) {
        assertEquals(
                expected.size(),
                actual.size(),
                () -> "expected " + render(expected) + " but was " + render(actual));
        for (int i = 0; i < expected.size(); i++) {
            assertRowEquals(expected.get(i), actual.get(i));
        }
    }

    private static void assertRowEquals(GenericRowData expected, GenericRowData actual) {
        assertEquals(expected.getRowKind(), actual.getRowKind());
        assertEquals(expected.getArity(), actual.getArity());
        for (int i = 0; i < expected.getArity(); i++) {
            assertEquals(expected.isNullAt(i), actual.isNullAt(i), "null mismatch at field " + i);
            if (!expected.isNullAt(i)) {
                assertEquals(expected.getInt(i), actual.getInt(i), "value mismatch at field " + i);
            }
        }
    }

    private static String render(List<GenericRowData> rows) {
        final StringBuilder builder = new StringBuilder("[");
        for (int i = 0; i < rows.size(); i++) {
            if (i > 0) {
                builder.append(", ");
            }
            final GenericRowData row = rows.get(i);
            builder.append(row.getRowKind().shortString()).append('(');
            for (int field = 0; field < row.getArity(); field++) {
                if (field > 0) {
                    builder.append(',');
                }
                builder.append(row.isNullAt(field) ? "null" : row.getInt(field));
            }
            builder.append(')');
        }
        return builder.append(']').toString();
    }

    private static void assertAssociationUpdates(
            TestingOuterStateView stateView, Update... expected) {
        assertEquals(expected.length, stateView.updates.size());
        for (int i = 0; i < expected.length; i++) {
            final Update actual = stateView.updates.get(i);
            assertSame(expected[i].record, actual.record);
            assertEquals(expected[i].numOfAssociations, actual.numOfAssociations);
        }
    }

    private static GenericRowData copy(RowData row) {
        final GenericRowData copy = new GenericRowData(row.getRowKind(), row.getArity());
        for (int i = 0; i < row.getArity(); i++) {
            if (!row.isNullAt(i)) {
                copy.setInt(i, row.getInt(i));
            }
        }
        return copy;
    }

    // ---------------------------------------------------------------------------------------------
    // Test doubles
    // ---------------------------------------------------------------------------------------------

    private static final class TestJoinCondition extends AbstractRichFunction
            implements JoinCondition {

        private static final long serialVersionUID = 1L;

        private final BiPredicate<RowData, RowData> predicate;

        private TestJoinCondition(BiPredicate<RowData, RowData> predicate) {
            this.predicate = predicate;
        }

        @Override
        public boolean apply(RowData in1, RowData in2) {
            return predicate.test(in1, in2);
        }
    }

    private static class TestingStateView implements JoinRecordStateView {

        final List<RowData> records = new ArrayList<>();
        final List<RowData> addedRecords = new ArrayList<>();
        final List<RowData> retractedRecords = new ArrayList<>();
        RowData recordToReturn;
        int getRecordCalls;

        TestingStateView(RowData... records) {
            this.records.addAll(Arrays.asList(records));
        }

        @Override
        public void addRecord(RowData record) {
            addedRecords.add(record);
        }

        @Override
        public void retractRecord(RowData record) {
            retractedRecords.add(record);
        }

        @Override
        public Iterable<RowData> getRecords() {
            return records;
        }

        @Override
        public RowData getRecord(RowData record) {
            getRecordCalls++;
            return recordToReturn;
        }
    }

    private static final class TestingOuterStateView extends TestingStateView
            implements OuterJoinRecordStateView {

        final List<Tuple2<RowData, Integer>> recordsWithNumOfAssociations = new ArrayList<>();
        final List<Integer> addedNumOfAssociations = new ArrayList<>();
        final List<Update> updates = new ArrayList<>();

        @SafeVarargs
        TestingOuterStateView(Tuple2<RowData, Integer>... records) {
            this.recordsWithNumOfAssociations.addAll(Arrays.asList(records));
            for (Tuple2<RowData, Integer> record : records) {
                this.records.add(record.f0);
            }
        }

        @Override
        public void addRecord(RowData record, int numOfAssociations) {
            super.addRecord(record);
            addedNumOfAssociations.add(numOfAssociations);
        }

        @Override
        public void updateNumOfAssociations(RowData record, int numOfAssociations) {
            updates.add(new Update(record, numOfAssociations));
        }

        @Override
        public Iterable<Tuple2<RowData, Integer>> getRecordsAndNumOfAssociations() {
            return recordsWithNumOfAssociations;
        }
    }

    private static final class Update {
        private final RowData record;
        private final int numOfAssociations;

        private Update(RowData record, int numOfAssociations) {
            this.record = record;
            this.numOfAssociations = numOfAssociations;
        }
    }

    private static final class CollectingOutput implements Output<StreamRecord<RowData>> {

        private final List<GenericRowData> output;

        private CollectingOutput(List<GenericRowData> output) {
            this.output = output;
        }

        @Override
        public void collect(StreamRecord<RowData> record) {
            output.add(copy(record.getValue()));
        }

        @Override
        public void close() {}

        @Override
        public void emitWatermark(Watermark mark) {}

        @Override
        public void emitWatermarkStatus(WatermarkStatus watermarkStatus) {}

        @Override
        public <X> void collect(OutputTag<X> outputTag, StreamRecord<X> record) {}

        @Override
        public void emitLatencyMarker(LatencyMarker latencyMarker) {}

        @Override
        public void emitRecordAttributes(RecordAttributes recordAttributes) {}

        @Override
        public void emitWatermark(WatermarkEvent watermark) {}
    }
}
