    /** Changelog mode that allows upsert updates and key-only deletes. */
    private static final RuntimeChangelogMode UPSERT_KEY_ONLY =
            new RuntimeChangelogMode(
                    new byte[] {
                        RowKind.INSERT.toByteValue(),
                        RowKind.UPDATE_AFTER.toByteValue(),
                        RowKind.DELETE.toByteValue()
                    },
                    true);

    /** Changelog mode with explicit update-before rows, i.e. no upsert updates. */
    private static final RuntimeChangelogMode ALL_CHANGES =
            new RuntimeChangelogMode(
                    new byte[] {
                        RowKind.INSERT.toByteValue(),
                        RowKind.UPDATE_BEFORE.toByteValue(),
                        RowKind.UPDATE_AFTER.toByteValue(),
                        RowKind.DELETE.toByteValue()
                    },
                    false);

