    @Test
    void testAccumulateOuterInputWithoutMatchesEmitsNullPaddingAndAddsZeroAssociations()
            throws Exception {
        final List<GenericRowData> output = new ArrayList<>();
        final StreamingJoinOperator operator =
                createOperator(
                        true,
                        false,
                        false,
                        JoinInputSideSpec.withoutUniqueKey(),
                        JoinInputSideSpec.withoutUniqueKey(),
                        null,
                        null,
                        joinKeyEquals(),
                        output);

        final GenericRowData input = row(RowKind.UPDATE_AFTER, 1, 10);
        final TestingOuterStateView inputState = new TestingOuterStateView();
        final TestingStateView otherState = new TestingStateView();

        operator.processElement(input, inputState, otherState, true, null);

        assertOutputs(
                Collections.singletonList(row(RowKind.INSERT, 1, 10, null, null)), output);
        assertEquals(1, inputState.addedRecords.size());
        assertSame(input, inputState.addedRecords.get(0));
        assertEquals(Collections.singletonList(0), inputState.addedNumOfAssociations);
        // The RowKind of the input is always erased before updating the state.
        assertEquals(RowKind.INSERT, input.getRowKind());
        assertTrue(inputState.retractedRecords.isEmpty());
    }

