    private static void assertRowEquals(GenericRowData expected, GenericRowData actual) {
        assertEquals(expected.getRowKind(), actual.getRowKind());
        assertEquals(expected.getArity(), actual.getArity());
        for (int i = 0; i < expected.getArity(); i++) {
            assertEquals(expected.isNullAt(i), actual.isNullAt(i), "null mismatch at field " + i);
            if (!expected.isNullAt(i)) {
                assertEquals(expected.getInt(i), actual.getInt(i), "value mismatch at field " + i);
            }
        }
    }

    private static String render(List<GenericRowData> rows) {
        final StringBuilder builder = new StringBuilder("[");
        for (int i = 0; i < rows.size(); i++) {
            if (i > 0) {
                builder.append(", ");
            }
            final GenericRowData row = rows.get(i);
            builder.append(row.getRowKind().shortString()).append('(');
            for (int field = 0; field < row.getArity(); field++) {
                if (field > 0) {
                    builder.append(',');
                }
                builder.append(row.isNullAt(field) ? "null" : row.getInt(field));
            }
            builder.append(')');
        }
        return builder.append(']').toString();
    }

