    @Test
    void testBaseContextContainsCommandResourcesAndEnvironment() throws Exception {
        final String flinkDistJar = descriptor(FLINK_DIST_JAR_KEY, 4711L, 42L);
        final ContainerLaunchContext ctx =
                createContext(createConfiguration(flinkDistJar, "", FLINK_CLASSPATH), "", ".", false);

        // ---- the launch command ----
        assertThat(ctx.getCommands()).hasSize(1);
        final String command = ctx.getCommands().get(0);
        assertThat(command).startsWith("$JAVA_HOME/bin/java");
        assertThat(command).contains(TestTaskExecutorMain.class.getName());
        assertThat(command).contains(ApplicationConstants.LOG_DIR_EXPANSION_VAR);
        assertThat(command).contains("taskmanager.out");
        assertThat(command).contains("taskmanager.err");
        // no log configuration files present in the working directory
        assertThat(command).doesNotContain("logback.configurationFile");
        assertThat(command).doesNotContain("log4j.configuration");
        // no krb5 file shipped
        assertThat(command).doesNotContain("-Djava.security.krb5.conf=krb5.conf");

        // ---- the local resources ----
        final Map<String, LocalResource> resources = ctx.getLocalResources();
        assertThat(resources).containsOnlyKeys(FLINK_DIST_JAR_KEY);
        final LocalResource flinkDist = resources.get(FLINK_DIST_JAR_KEY);
        assertThat(flinkDist.getSize()).isEqualTo(4711L);
        assertThat(flinkDist.getTimestamp()).isEqualTo(42L);
        assertThat(flinkDist.getType()).isEqualTo(LocalResourceType.FILE);
        assertThat(flinkDist.getVisibility()).isEqualTo(LocalResourceVisibility.APPLICATION);
        assertThat(flinkDist.getResource().getPath()).endsWith(FLINK_DIST_JAR_KEY);

        // ---- the environment ----
        final Map<String, String> env = ctx.getEnvironment();
        assertThat(env).containsEntry(YarnConfigKeys.ENV_FLINK_CLASSPATH, FLINK_CLASSPATH);
        assertThat(env.get(ApplicationConstants.Environment.CLASSPATH.name()))
                .startsWith(FLINK_CLASSPATH)
                .contains("$HADOOP_CONF_DIR");
        assertThat(env)
                .containsEntry(
                        YarnConfigKeys.ENV_HADOOP_USER_NAME,
                        UserGroupInformation.getCurrentUser().getUserName());
        // no kerberos related entries because nothing was configured
        assertThat(env).doesNotContainKeys(
                YarnConfigKeys.REMOTE_KEYTAB_PATH,
                YarnConfigKeys.LOCAL_KEYTAB_PATH,
                YarnConfigKeys.KEYTAB_PRINCIPAL);

        // no ACLs configured
        assertThat(ctx.getApplicationACLs()).isNullOrEmpty();
    }

