    @Test
    void testKeytabYarnSiteAndKrb5FilesAreRegisteredAndExported() throws Exception {
        final File keytab = createTempFile("krb5.keytab", 128);
        final File yarnSite = createTempFile("yarn-site.xml", 256);
        final File krb5 = createTempFile("krb5.conf", 512);
        final String principal = "flink@TEST.REALM";

        final Map<String, String> extraEnv = new HashMap<>();
        extraEnv.put(YarnConfigKeys.REMOTE_KEYTAB_PATH, keytab.getAbsolutePath());
        extraEnv.put(YarnConfigKeys.LOCAL_KEYTAB_PATH, "krb5.keytab");
        extraEnv.put(YarnConfigKeys.KEYTAB_PRINCIPAL, principal);
        extraEnv.put(YarnConfigKeys.ENV_YARN_SITE_XML_PATH, yarnSite.getAbsolutePath());
        extraEnv.put(YarnConfigKeys.ENV_KRB5_PATH, krb5.getAbsolutePath());

        final ContainerLaunchContext ctx =
                createContext(
