                .containsEntry(YarnConfigKeys.REMOTE_KEYTAB_PATH, keytab.getAbsolutePath())
                .containsEntry(YarnConfigKeys.LOCAL_KEYTAB_PATH, "krb5.keytab")
                .containsEntry(YarnConfigKeys.KEYTAB_PRINCIPAL, principal);

