    private static final Logger LOG = org.slf4j.LoggerFactory.getLogger(UtilsCreateTaskExecutorContextTests.class);

    /** Dummy main class used as the task manager entry point. */
    static final class TestTaskExecutorMain {}

    private ContaineredTaskManagerParameters createTmParams() {
        return ContaineredTaskManagerParameters.create(flinkConfig, taskExecutorProcessSpec);
    }

    private ContainerLaunchContext createContext(
            YarnResourceManagerDriverConfiguration configuration,
            String dynamicProperties,
            String workingDirectory,
            boolean unused)
            throws Exception {
        return Utils.createTaskExecutorContext(
                flinkConfig,
                yarnConfig,
                configuration,
                createTmParams(),
                dynamicProperties,
                workingDirectory,
                TestTaskExecutorMain.class,
                LOG);
    }

    private File createTempFile(String name, int size) throws Exception {
        final File file = new File(tempFolder, name);
        final byte[] content = new byte[size];
        for (int i = 0; i < size; i++) {
            content[i] = (byte) i;
        }
        Files.write(file.toPath(), content);
        return file;
    }

    private YarnResourceManagerDriverConfiguration createConfiguration(
            String flinkDistJar, String clientShipFiles, String classpath) {
        return createConfiguration(flinkDistJar, clientShipFiles, classpath, new HashMap<>());
    }

    private YarnResourceManagerDriverConfiguration createConfiguration(
            String flinkDistJar,
            String clientShipFiles,
            String classpath,
            Map<String, String> additionalEnv) {
        final Map<String, String> env = new HashMap<>(additionalEnv);
        env.put(YarnConfigKeys.FLINK_YARN_FILES, new File(tempFolder, "files").getAbsolutePath());
        env.put(YarnConfigKeys.ENV_FLINK_CLASSPATH, classpath);
        env.put(YarnConfigKeys.ENV_CLIENT_SHIP_FILES, clientShipFiles);
        env.put(YarnConfigKeys.FLINK_DIST_JAR, flinkDistJar);
        env.put(WORKING_DIR_KEY, tempFolder.getAbsolutePath());
        return new YarnResourceManagerDriverConfiguration(env, "rpc-address", null);
    }

    /**
     * Encodes a local resource descriptor in the format which is produced by {@link
     * YarnLocalResourceDescriptor#toString()} and expected by {@link
     * YarnLocalResourceDescriptor#fromString(String)}.
     */
    private String descriptor(String resourceKey, long size, long modificationTime) {
        return new YarnLocalResourceDescriptor(
                        resourceKey,
                        new Path(new File(tempFolder, resourceKey).toURI()),
                        size,
                        modificationTime,
                        LocalResourceVisibility.APPLICATION,
                        LocalResourceType.FILE)
                .toString();
    }
