import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Tests for {@link Utils#createTaskExecutorContext(org.apache.flink.configuration.Configuration,
 * YarnConfiguration, YarnResourceManagerDriverConfiguration, ContaineredTaskManagerParameters,
 * String, String, Class, Logger)}.
 */
class UtilsCreateTaskExecutorContextTests {

    private static final String FLINK_DIST_JAR_KEY = "flink-dist.jar";
    private static final String SHIPPED_FILE_KEY = "shipped-file.txt";
    private static final String SECOND_SHIPPED_FILE_KEY = "second-shipped-file.txt";
    private static final String FLINK_CLASSPATH = "/opt/flink/lib/*";
    private static final String WORKING_DIR_KEY = ApplicationConstants.Environment.PWD.key();

    @TempDir File tempFolder;

    private org.apache.flink.configuration.Configuration flinkConfig;
    private YarnConfiguration yarnConfig;
    private TaskExecutorProcessSpec taskExecutorProcessSpec;

    @BeforeEach
    void setUp() {
        flinkConfig = new org.apache.flink.configuration.Configuration();
        flinkConfig.set(TaskManagerOptions.TOTAL_PROCESS_MEMORY, MemorySize.parse("1024m"));

        yarnConfig = new YarnConfiguration();
        taskExecutorProcessSpec = TaskExecutorProcessUtils.processSpecFromConfig(flinkConfig);
    }

    // ------------------------------------------------------------------------
    //  Happy path / base contract
    // ------------------------------------------------------------------------

    @Test
    void testBaseContextContainsCommandResourcesAndEnvironment() throws Exception {
        final String flinkDistJar = descriptor(FLINK_DIST_JAR_KEY, 4711L, 42L);
        final ContainerLaunchContext ctx =
                createContext(createConfiguration(flinkDistJar, "", FLINK_CLASSPATH), "", ".");

        // ---- the launch command ----
        assertThat(ctx.getCommands()).hasSize(1);
        final String command = ctx.getCommands().get(0);
        assertThat(command).startsWith("$JAVA_HOME/bin/java");
        assertThat(command).contains(TestTaskExecutorMain.class.getName());
        assertThat(command).contains(ApplicationConstants.LOG_DIR_EXPANSION_VAR);
        assertThat(command).contains("taskmanager.out");
        assertThat(command).contains("taskmanager.err");
        // no log configuration files present in the working directory
        assertThat(command).doesNotContain("logback.configurationFile");
        assertThat(command).doesNotContain("log4j.configuration");
        // no krb5 file shipped
        assertThat(command).doesNotContain("-Djava.security.krb5.conf=krb5.conf");

        // ---- the local resources ----
        final Map<String, LocalResource> resources = ctx.getLocalResources();
        assertThat(resources).containsOnlyKeys(FLINK_DIST_JAR_KEY);

    assertThat(resources).containsOnlyKeys(FLINK_DIST_JAR_KEY);
    final LocalResource flinkDist = resources.get(FLINK_DIST_JAR_KEY);
    assertThat(flinkDist.getSize()).isEqualTo(4711L);
    assertThat(flinkDist.getTimestamp()).isEqualTo(42L);
    assertThat(flinkDist.getType()).isEqualTo(LocalResourceType.FILE);
    assertThat(flinkDist.getVisibility()).isEqualTo(LocalResourceVisibility.APPLICATION);
    assertThat(flinkDist.getResource().getFile()).endsWith(FLINK_DIST_JAR_KEY);

    // ---- the environment ----
    final Map<String, String> env = ctx.getEnvironment();
    assertThat(env).containsEntry(YarnConfigKeys.ENV_FLINK_CLASSPATH, FLINK_CLASSPATH);
    assertThat(env.get(ApplicationConstants.Environment.CLASSPATH.name()))
            .startsWith(FLINK_CLASSPATH)
            .contains("$HADOOP_CONF_DIR");
    assertThat(env)
            .containsEntry(
                    YarnConfigKeys.ENV_HADOOP_USER_NAME,
                    UserGroupInformation.getCurrentUser().getUserName());
    // no kerberos related entries because nothing was configured
    assertThat(env)
            .doesNotContainKeys(
                    YarnConfigKeys.REMOTE_KEYTAB_PATH,
                    YarnConfigKeys.LOCAL_KEYTAB_PATH,
                    YarnConfigKeys.KEYTAB_PRINCIPAL);

    // no ACLs configured
    assertThat(ctx.getApplicationACLs()).isNullOrEmpty();
}

@Test
void testTaskManagerEnvironmentIsPartOfTheContainerEnvironment() throws Exception {
    final ContaineredTaskManagerParameters tmParams =
            ContaineredTaskManagerParameters.create(flinkConfig, taskExecutorProcessSpec);
    tmParams.taskManagerEnv().put("CUSTOM_TM_ENV", "custom-value");

    final ContainerLaunchContext ctx =
            Utils.createTaskExecutorContext(
                    flinkConfig,
                    yarnConfig,
                    createConfiguration(
                            descriptor(FLINK_DIST_JAR_KEY, 1L, 1L), "", FLINK_CLASSPATH),
                    tmParams,
                    "",
                    tempFolder.getAbsolutePath(),
                    TestTaskExecutorMain.class,
                    LOG);

    assertThat(ctx.getEnvironment()).containsEntry("CUSTOM_TM_ENV", "custom-value");
    // the user environment variables are preserved, not replaced
    assertThat(ctx.getEnvironment())
            .containsEntry(YarnConfigKeys.ENV_FLINK_CLASSPATH, FLINK_CLASSPATH);
}

@Test
void testShippedFilesAreAddedAlongsideTheFlinkDistJar() throws Exception {
    final String shipFiles =
            descriptor(SHIPPED_FILE_KEY, 17L, 18L)
                    + YarnConfigKeys.LOCAL_RESOURCE_DESCRIPTOR_SEPARATOR
                    + descriptor(SECOND_SHIPPED_FILE_KEY, 19L, 20L);

    final ContainerLaunchContext ctx =
            createContext(
                    createConfiguration(
                            descriptor(FLINK_DIST_JAR_KEY, 1L, 2L), shipFiles, FLINK_CLASSPATH),
                    "",
                    ".");

    final Map<String, LocalResource> resources = ctx.getLocalResources();
    assertThat(resources)
            .containsOnlyKeys(FLINK_DIST_JAR_KEY, SHIPPED_FILE_KEY, SECOND_SHIPPED_FILE_KEY);
