@Test
void testKeytabYarnSiteAndKrb5FilesAreRegisteredAndExported() throws Exception {
    final File keytab = createTempFile("krb5.keytab", 128);
    final File yarnSite = createTempFile("yarn-site.xml", 256);
    final File krb5 = createTempFile("krb5.conf", 512);
    final String principal = "flink@TEST.REALM";

    final Map<String, String> extraEnv = new HashMap<>();
    extraEnv.put(YarnConfigKeys.REMOTE_KEYTAB_PATH, keytab.getAbsolutePath());
    extraEnv.put(YarnConfigKeys.LOCAL_KEYTAB_PATH, "krb5.keytab");
    extraEnv.put(YarnConfigKeys.KEYTAB_PRINCIPAL, principal);
    extraEnv.put(YarnConfigKeys.ENV_YARN_SITE_XML_PATH, yarnSite.getAbsolutePath());
    extraEnv.put(YarnConfigKeys.ENV_KRB5_PATH, krb5.getAbsolutePath());

    final ContainerLaunchContext ctx =
            createContext(
                    createConfiguration(
                            descriptor(FLINK_DIST_JAR_KEY, 1L, 2L),
                            "",
                            FLINK_CLASSPATH,
                            extraEnv),
                    "",
                    ".");

    final Map<String, LocalResource> resources = ctx.getLocalResources();
    assertThat(resources)
            .containsOnlyKeys(
                    FLINK_DIST_JAR_KEY,
                    Utils.YARN_SITE_FILE_NAME,
                    Utils.KRB5_FILE_NAME,
                    "krb5.keytab");

    final LocalResource keytabResource = resources.get("krb5.keytab");
    assertThat(keytabResource.getSize()).isEqualTo(keytab.length());
    assertThat(keytabResource.getType()).isEqualTo(LocalResourceType.FILE);
    assertThat(keytabResource.getVisibility()).isEqualTo(LocalResourceVisibility.APPLICATION);
    assertThat(keytabResource.getResource().getFile()).endsWith(keytab.getAbsolutePath());
    assertThat(resources.get(Utils.YARN_SITE_FILE_NAME).getSize()).isEqualTo(yarnSite.length());
    assertThat(resources.get(Utils.KRB5_FILE_NAME).getSize()).isEqualTo(krb5.length());

    final Map<String, String> env = ctx.getEnvironment();
    assertThat(env)
            .containsEntry(YarnConfigKeys.REMOTE_KEYTAB_PATH, keytab.getAbsolutePath())
            .containsEntry(YarnConfigKeys.LOCAL_KEYTAB_PATH, "krb5.keytab")
            .containsEntry(YarnConfigKeys.KEYTAB_PRINCIPAL, principal);

    // the krb5.conf file is shipped as a local resource, therefore the JVM flag is added
    assertThat(ctx.getCommands().get(0)).contains("-Djava.security.krb5.conf=krb5.conf");
}

