@Test
void testSecurityTokensAreAddedAndAmrmTokenIsFilteredOut() throws Exception {
    final File tokenFile =
            writeTokenFile(
                    new Token<>(
                            "am-rm-identifier".getBytes(StandardCharsets.UTF_8),
                            "am-rm-password".getBytes(StandardCharsets.UTF_8),
                            AMRMTokenIdentifier.KIND_NAME,
                            new Text("am-rm-service")),
                    new Token<>(
                            "user-identifier".getBytes(StandardCharsets.UTF_8),
                            "user-password".getBytes(StandardCharsets.UTF_8),
                            new Text("TEST_KIND"),
                            new Text("user-service")));

    withTokenFileLocation(
            tokenFile.getAbsolutePath(),
            () -> {
                final ContainerLaunchContext ctx =
                        createContext(
                                createConfiguration(
                                        descriptor(FLINK_DIST_JAR_KEY, 1L, 2L),
                                        "",
                                        FLINK_CLASSPATH),
                                "",
                                ".");

                assertThat(ctx.getTokens()).isNotNull();
                final Credentials storedTokens = readCredentials(ctx.getTokens());
                // the AM/RM token must not be forwarded to the task manager
                assertThat(storedTokens.numberOfTokens()).isEqualTo(1);
                final Token<?> remaining = storedTokens.getAllTokens().iterator().next();
                assertThat(remaining.getKind()).isEqualTo(new Text("TEST_KIND"));
                assertThat(remaining.getService()).isEqualTo(new Text("user-service"));
            });
}

