    // ------------------------------------------------------------------------

    /** Dummy main class used as the task manager entry point. */
    static final class TestTaskExecutorMain {}

    private ContaineredTaskManagerParameters createTmParams() {
        return ContaineredTaskManagerParameters.create(flinkConfig, taskExecutorProcessSpec);
    }

    private ContainerLaunchContext createContext(
            YarnResourceManagerDriverConfiguration configuration,
            String dynamicProperties,
            String workingDirectory)
            throws Exception {
        return Utils.createTaskExecutorContext(
                flinkConfig,
                yarnConfig,
                configuration,
                createTmParams(),
                dynamicProperties,
                workingDirectory,
                TestTaskExecutorMain.class,
                LOG);
    }

    @SafeVarargs
    private final File writeTokenFile(Token<?>... tokens) throws Exception {
        final File tokenFile = new File(tempFolder, "hadoop.tokens");
        final Credentials credentials = new Credentials();
        for (int i = 0; i < tokens.length; i++) {
            credentials.addToken(new Text("alias-" + i), tokens[i]);
        }
        try (DataOutputStream out = new DataOutputStream(new FileOutputStream(tokenFile))) {
            credentials.writeTokenStorageToStream(out);
        }
        return tokenFile;
    }

    private static Credentials readCredentials(ByteBuffer tokens) throws Exception {
        final DataInputByteBuffer input = new DataInputByteBuffer();
        input.reset(tokens);
        final Credentials credentials = new Credentials();
        credentials.readTokenStorageStream(new DataInputStream(input));
        return credentials;
    }

    /** Runs the given runnable with the given value of the hadoop token file location env var. */
    private static void withTokenFileLocation(String value, ThrowingRunnable runnable)
            throws Exception {
        final String originalValue = System.getenv(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION);
        setEnvironmentVariable(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION, value);
        try {
            runnable.run();
        } finally {
            setEnvironmentVariable(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION, originalValue);
        }
    }

    @SuppressWarnings("unchecked")
    private static void setEnvironmentVariable(String name, String value) {
        try {
            final Map<String, String> environment = System.getenv();
            final Field field = environment.getClass().getDeclaredField("m");
            field.setAccessible(true);
            final Map<String, String> map = (Map<String, String>) field.get(environment);
            if (value == null) {
                map.remove(name);
            } else {
                map.put(name, value);
            }
        } catch (Exception e) {
            throw new RuntimeException("Could not modify the environment variable " + name, e);
        }
    }

    /** Runnable which may throw an exception. */
    private interface ThrowingRunnable {
        void run() throws Exception;
    }

    private File createTempFile(String name, int size) throws Exception {
        final File file = new File(tempFolder, name);
        final byte[] content = new byte[size];
        for (int i = 0; i < size; i++) {
            content[i] = (byte) i;
        }
        Files.write(file.toPath(), content);
        return file;
    }

    private YarnResourceManagerDriverConfiguration createConfiguration(
            String flinkDistJar, String clientShipFiles, String classpath) {
        return createConfiguration(flinkDistJar, clientShipFiles, classpath, new HashMap<>());
    }

    private YarnResourceManagerDriverConfiguration createConfiguration(
            String flinkDistJar,
            String clientShipFiles,
            String classpath,
            Map<String, String> additionalEnv) {
        final Map<String, String> env = new HashMap<>(additionalEnv);
        env.put(YarnConfigKeys.FLINK_YARN_FILES, new File(tempFolder, "files").getAbsolutePath());
        env.put(YarnConfigKeys.ENV_FLINK_CLASSPATH, classpath);
        env.put(YarnConfigKeys.ENV_CLIENT_SHIP_FILES, clientShipFiles);
        env.put(YarnConfigKeys.FLINK_DIST_JAR, flinkDistJar);
        env.put(WORKING_DIR_KEY, tempFolder.getAbsolutePath());
        return new YarnResourceManagerDriverConfiguration(env, "rpc-address", null);
    }

    /**
     * Encodes a local resource descriptor in the format which is produced by {@link
     * YarnLocalResourceDescriptor#toString()} and expected by {@link
     * YarnLocalResourceDescriptor#fromString(String)}.
     */
    private String descriptor(String resourceKey, long size, long modificationTime) {
        return new YarnLocalResourceDescriptor(
                        resourceKey,
                        new Path(new File(tempFolder, resourceKey).toURI()),
                        size,
                        modificationTime,
                        LocalResourceVisibility.APPLICATION,
                        LocalResourceType.FILE)
                .toString();
    }
