            assertThat(vector).isInstanceOf(HeapBytesVector.class);
            assertThat(((HeapBytesVector) vector).getLen()).isEqualTo(4);
            assertAllRowsNull(vector, 4);
        }
    }

    @Test
    void testBooleanConstant() {
