            ColumnVector vector = createVectorFromConstant(new BooleanType(), expected, 3);
            assertThat(vector).isInstanceOf(HeapBooleanVector.class);
            HeapBooleanVector booleanVector = (HeapBooleanVector) vector;
            assertThat(booleanVector.getLen()).isEqualTo(3);
            for (int i = 0; i < 3; i++) {
