                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("Unsupported type");
    }

    @Test
    void testBooleanRejectsNonBooleanValue() {
        assertThatThrownBy(() -> createVectorFromConstant(new BooleanType(), 1, 1))
                .isInstanceOf(ClassCastException.class);
    }

    private static void assertByteVector(LogicalType type, Object value, byte[] expected) {
        int batchSize = 3;
        ColumnVector vector = createVectorFromConstant(type, value, batchSize);
        assertThat(vector).isInstanceOf(HeapBytesVector.class);
        HeapBytesVector bytesVector = (HeapBytesVector) vector;
        assertThat(bytesVector.getLen()).isEqualTo(batchSize);
        for (int i = 0; i < batchSize; i++) {
            assertThat(bytesVector.isNullAt(i)).isFalse();
            assertThat(bytesVector.getBytes(i).getBytes()).isEqualTo(expected);
        }
    }

    private static void assertDecimalVector(
            DecimalType type,
            BigDecimal value,
            Class<? extends ColumnVector> expectedInternalClass) {
        int batchSize = 3;
        ColumnVector vector = createVectorFromConstant(type, value, batchSize);
        assertThat(vector).isInstanceOf(ParquetDecimalVector.class);
        ParquetDecimalVector decimalVector = (ParquetDecimalVector) vector;
        assertThat(decimalVector.getVector()).isInstanceOf(expectedInternalClass);
        DecimalData expected =
                DecimalData.fromBigDecimal(value, type.getPrecision(), type.getScale());
        for (int i = 0; i < batchSize; i++) {
            assertThat(decimalVector.isNullAt(i)).isFalse();
            assertThat(decimalVector.getDecimal(i, type.getPrecision(), type.getScale()))
                    .isEqualTo(expected);
        }
    }

    private static void assertDateVector(Date value, int expectedInternalValue) {
        ColumnVector vector = createVectorFromConstant(new DateType(), value, 2);
        assertThat(vector).isInstanceOf(HeapIntVector.class);
        HeapIntVector intVector = (HeapIntVector) vector;
        for (int i = 0; i < 2; i++) {
            assertThat(intVector.isNullAt(i)).isFalse();
            assertThat(intVector.getInt(i)).isEqualTo(expectedInternalValue);
        }
    }

    private static void assertAllRowsNull(ColumnVector vector, int batchSize) {
        for (int i = 0; i < batchSize; i++) {
            assertThat(vector.isNullAt(i)).isTrue();
        }
    }
