    private static final Set<String> INPUT_OUTPUT_CONVERSION =
            conversionSet(Map.class.getName(), MapData.class.getName());

    private static final Class<?> DEFAULT_CONVERSION = Map.class;

    private final LogicalType elementType;

    public MultisetType(boolean isNullable, LogicalType elementType) {
        super(isNullable, LogicalTypeRoot.MULTISET);
        this.elementType =
                Preconditions.checkNotNull(elementType, "Element type must not be null.");

            if (value instanceof ByteBuffer) {
