import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * Tests for {@link InternalTypeConverter#toInternal(Object, LogicalType)}.
 *
 * <p>The tests verify the publicly observable conversion contract: which Java values are passed
 * through unchanged, which are converted to Flink's internal data structures, and which inputs are
 * rejected.
 */
class InternalTypeConverterToInternalTests {

    // ------------------------------------------------------------------------------------------
    // helpers
    // ------------------------------------------------------------------------------------------

    private static Object toInternal(Object value, LogicalType type) {
        return InternalTypeConverter.toInternal(value, type);
    }

    private static StructuredType structuredType() {
        return StructuredType.newBuilder("com.example.Person")
                .attributes(
                        Arrays.asList(
                                new StructuredType.StructuredAttribute("name", VarCharType.STRING_TYPE),
                                new StructuredType.StructuredAttribute("age", new IntType())))
                .build();
    }

    private static Stream<LogicalType> allLogicalTypes() {
        return Stream.of(
                new CharType(10),
                VarCharType.STRING_TYPE,
                new BooleanType(),
                new TinyIntType(),
                new SmallIntType(),
                new IntType(),
                new BigIntType(),
                new FloatType(),
                new DoubleType(),
                new TimeType(),
                new DecimalType(10, 2),
                new DateType(),
                new TimestampType(),
                new ZonedTimestampType(),
                new LocalZonedTimestampType(),
                new YearMonthIntervalType(YearMonthIntervalType.YearMonthResolution.YEAR),
                new DayTimeIntervalType(DayTimeIntervalType.DayTimeResolution.DAY),
                new BinaryType(5),
                new VarBinaryType(5),
                new NullType(),
                RowType.of(new IntType(), VarCharType.STRING_TYPE),
                structuredType(),
                new ArrayType(new IntType()),
                new MapType(VarCharType.STRING_TYPE, new IntType()),
                new MultisetType(VarCharType.STRING_TYPE),
                new VariantType(),
                new UuidType());
    }

    // ------------------------------------------------------------------------------------------
    // null handling
    // ------------------------------------------------------------------------------------------

    @ParameterizedTest
    @MethodSource("allLogicalTypes")
    void nullValueIsConvertedToNullForEveryLogicalType(LogicalType type) {
        assertThat(toInternal(null, type)).isNull();
    }

    @Test
    void nullValueIsConvertedToNullEvenWithoutLogicalType() {
        // the null check happens before the logical type is inspected
        assertThat(toInternal(null, null)).isNull();
    }

    // ------------------------------------------------------------------------------------------
    // CHAR / VARCHAR
    // ------------------------------------------------------------------------------------------

    @Test
    void stringIsConvertedToStringData() {
        Object result = toInternal("hello", VarCharType.STRING_TYPE);

        assertThat(result).isInstanceOf(StringData.class);
        assertThat(((StringData) result).toString()).isEqualTo("hello");
    }

    @Test
    void emptyStringIsConvertedToStringData() {
        Object result = toInternal("", new CharType(1));

        assertThat(result).isInstanceOf(StringData.class);
        assertThat(((StringData) result).toString()).isEmpty();
    }

    @Test
    void stringDataIsPassedThroughUnchanged() {
        StringData value = StringData.fromString("already-internal");

        assertThat(toInternal(value, VarCharType.STRING_TYPE)).isSameAs(value);
        assertThat(toInternal(value, new CharType(20))).isSameAs(value);
    }

    @Test
    void nonStringValueIsConvertedUsingToString() {
        Object result = toInternal(42, VarCharType.STRING_TYPE);

        assertThat(result).isInstanceOf(StringData.class);
        assertThat(((StringData) result).toString()).isEqualTo("42");
    }

    // ------------------------------------------------------------------------------------------
    // pass-through primitives
    // ------------------------------------------------------------------------------------------

    static Stream<Arguments> passThroughValues() {
        return Stream.of(
                Arguments.of(Boolean.TRUE, new BooleanType()),
                Arguments.of((byte) 7, new TinyIntType()),
                Arguments.of((short) 32000, new SmallIntType()),
                Arguments.of(123456, new IntType()),
                Arguments.of(Long.MAX_VALUE, new BigIntType()),
                Arguments.of(1.25f, new FloatType()),
                Arguments.of(-2.5d, new DoubleType()),
                Arguments.of(12345678, new TimeType()),
                Arguments.of(30, new YearMonthIntervalType(YearMonthIntervalType.YearMonthResolution.MONTH)),
                Arguments.of(
                        60_000L, new DayTimeIntervalType(DayTimeIntervalType.DayTimeResolution.DAY_TO_SECOND)));
    }

    @ParameterizedTest
    @MethodSource("passThroughValues")
    void primitiveValuesArePassedThroughUnchanged(Object value, LogicalType type) {
        assertThat(toInternal(value, type)).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // DECIMAL
    // ------------------------------------------------------------------------------------------

    @Test
    void bigDecimalIsConvertedToDecimalDataWithTargetPrecisionAndScale() {
        DecimalType type = new DecimalType(10, 2);
        BigDecimal value = new BigDecimal("123.45");

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(DecimalData.class);
        DecimalData decimal = (DecimalData) result;
        assertThat(decimal.precision()).isEqualTo(10);
        assertThat(decimal.scale()).isEqualTo(2);
        assertThat(decimal.toBigDecimal()).isEqualByComparingTo(value);
    }

    @Test
    void bigDecimalWithMoreFractionDigitsIsRoundedHalfUpToTargetScale() {
        Object result = toInternal(new BigDecimal("1.235"), new DecimalType(5, 2));

        assertThat(result).isInstanceOf(DecimalData.class);
        assertThat(((DecimalData) result).scale()).isEqualTo(2);
        assertThat(((DecimalData) result).toBigDecimal()).isEqualByComparingTo(new BigDecimal("1.24"));
    }

    @Test
    void decimalDataIsPassedThroughUnchanged() {
        DecimalData value = DecimalData.fromUnscaledLong(42L, 10, 1);

        assertThat(toInternal(value, new DecimalType(10, 1))).isSameAs(value);
    }

    @Test
    void byteBufferWithUnscaledValueIsConvertedToDecimalData() {
        DecimalType type = new DecimalType(10, 3);
        ByteBuffer value = ByteBuffer.wrap(new byte[] {1, (byte) 0xE2, 0x40});

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(DecimalData.class);
        DecimalData decimal = (DecimalData) result;
        assertThat(decimal.precision()).isEqualTo(10);
        assertThat(decimal.scale()).isEqualTo(3);
        assertThat(decimal.toBigDecimal()).isEqualByComparingTo(new BigDecimal("123.456"));
    }

    @Test
    void byteArrayWithUnscaledValueIsConvertedToDecimalData() {
        Object result = toInternal(new byte[] {(byte) 0xFE, 0x1D, (byte) 0xC0}, new DecimalType(10, 3));

        assertThat(result).isInstanceOf(DecimalData.class);
        assertThat(((DecimalData) result).toBigDecimal())
                .isEqualByComparingTo(new BigDecimal("-123.456"));
    }

    @Test
    void onlyRemainingBytesOfByteBufferAreUsedForDecimalConversion() {
        // buffer of 5 bytes with 2 leading padding bytes: only 3 bytes remain
        ByteBuffer value = ByteBuffer.wrap(new byte[] {9, 9, 1, (byte) 0xE2, 0x40});

        Object result = toInternal(value.duplicate().position(2), new DecimalType(10, 3));

        assertThat(result).isInstanceOf(DecimalData.class);
        assertThat(((DecimalData) result).toBigDecimal())
                .isEqualByComparingTo(new BigDecimal("123.456"));
    }

    @Test
    void unsupportedDecimalValueIsPassedThroughUnchanged() {
        String value = "not-a-decimal";

        assertThat(toInternal(value, new DecimalType(10, 2))).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // DATE
    // ------------------------------------------------------------------------------------------

    @Test
    void integerDateIsPassedThroughUnchanged() {
        Integer value = 18628;

        assertThat(toInternal(value, new DateType())).isSameAs(value);
    }

    @Test
    void localDateIsConvertedToEpochDay() {
        assertThat(toInternal(LocalDate.of(2021, 1, 1), new DateType())).isEqualTo(18628);
    }

    @Test
    void localDateBeforeEpochIsConvertedToNegativeEpochDay() {
        assertThat(toInternal(LocalDate.of(1969, 12, 31), new DateType())).isEqualTo(-1);
        assertThat(toInternal(LocalDate.of(1970, 1, 2), new DateType())).isEqualTo(1);
    }

    @Test
    void sqlDateIsConvertedToEpochDay() {
        assertThat(toInternal(java.sql.Date.valueOf("2024-02-29"), new DateType())).isEqualTo(19782);
    }

    @Test
    void unsupportedDateValueIsPassedThroughUnchanged() {
        Long value = 1234L;

        assertThat(toInternal(value, new DateType())).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // TIMESTAMP
    // ------------------------------------------------------------------------------------------

    static Stream<LogicalType> timestampTypes() {
        return Stream.of(new TimestampType(), new ZonedTimestampType(), new LocalZonedTimestampType());
    }

    @ParameterizedTest
    @MethodSource("timestampTypes")
    void timestampDataIsPassedThroughUnchanged(LogicalType type) {
        TimestampData value = TimestampData.fromEpochMillis(1_234_567_890L, 123_456);

        assertThat(toInternal(value, type)).isSameAs(value);
    }

    @ParameterizedTest
    @MethodSource("timestampTypes")
    void sqlTimestampIsConvertedToTimestampData(LogicalType type) {
        Timestamp value = Timestamp.valueOf("2021-01-01 12:34:56.789");

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(TimestampData.class);
        TimestampData data = (TimestampData) result;
        assertThat(data.toTimestamp()).isEqualTo(value);
        assertThat(data.getMillisecond()).isEqualTo(value.getTime());
    }

    @ParameterizedTest
    @MethodSource("timestampTypes")
    void instantIsConvertedToTimestampData(LogicalType type) {
        Instant value = Instant.parse("1970-01-01T00:00:01.000000500Z");

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(TimestampData.class);
        TimestampData data = (TimestampData) result;
        assertThat(data.getMillisecond()).isEqualTo(1000L);
        assertThat(data.getNanoOfMillisecond()).isEqualTo(500);
        assertThat(data.toInstant()).isEqualTo(value);
    }

    @ParameterizedTest
    @MethodSource("timestampTypes")
    void localDateTimeIsConvertedToTimestampData(LogicalType type) {
        LocalDateTime value = LocalDateTime.of(1969, 12, 31, 23, 59, 59, 999_999_999);

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(TimestampData.class);
        TimestampData data = (TimestampData) result;
        assertThat(data.getMillisecond()).isEqualTo(-1L);
        assertThat(data.getNanoOfMillisecond()).isEqualTo(999_999);
        assertThat(data.toLocalDateTime()).isEqualTo(value);
    }

    @ParameterizedTest
    @MethodSource("timestampTypes")
    void unsupportedTimestampValueIsPassedThroughUnchanged(LogicalType type) {
        String value = "2021-01-01";

        assertThat(toInternal(value, type)).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // BINARY / VARBINARY
    // ------------------------------------------------------------------------------------------

    @Test
    void byteBufferIsConvertedToByteArray() {
        Object result = toInternal(ByteBuffer.wrap(new byte[] {1, 2, 3}), new BinaryType(10));

        assertThat(result).isInstanceOf(byte[].class);
        assertThat((byte[]) result).containsExactly((byte) 1, (byte) 2, (byte) 3);
    }

    @Test
    void byteBufferIsConvertedToByteArrayForVarBinary() {
        Object result = toInternal(ByteBuffer.wrap(new byte[] {10, 20}), new VarBinaryType(10));

        assertThat(result).isInstanceOf(byte[].class);
        assertThat((byte[]) result).containsExactly((byte) 10, (byte) 20);
    }

    @Test
    void onlyRemainingBytesOfByteBufferAreConverted() {
        ByteBuffer value = ByteBuffer.wrap(new byte[] {0, 0, 7, 8});

        Object result = toInternal(value.duplicate().position(2), new BinaryType(10));

        assertThat((byte[]) result).containsExactly((byte) 7, (byte) 8);
    }

    @Test
    void emptyByteBufferIsConvertedToEmptyByteArray() {
        Object result = toInternal(ByteBuffer.allocate(0), new VarBinaryType(10));

        assertThat((byte[]) result).isEmpty();
    }

    @Test
    void byteArrayIsPassedThroughUnchangedForBinaryTypes() {
        byte[] value = new byte[] {1, 2, 3};

        assertThat(toInternal(value, new BinaryType(10))).isSameAs(value);
        assertThat(toInternal(value, new VarBinaryType(10))).isSameAs(value);
    }

    @Test
    void unsupportedBinaryValueIsPassedThroughUnchanged() {
        String value = "text";

        assertThat(toInternal(value, new VarBinaryType(10))).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // NULL type root
    // ------------------------------------------------------------------------------------------

    @Test
    void nonNullValueIsConvertedToNullForNullType() {
        assertThat(toInternal("ignored", new NullType())).isNull();
    }

    // ------------------------------------------------------------------------------------------
    // ROW / STRUCTURED_TYPE
    // ------------------------------------------------------------------------------------------

    @Test
    void genericRowDataIsPassedThroughUnchanged() {
        GenericRowData value = GenericRowData.of(1, "a");

        assertThat(toInternal(value, RowType.of(new IntType(), VarCharType.STRING_TYPE)))
                .isSameAs(value);
    }

    @Test
    void rowIsConvertedToGenericRowDataWithConvertedFields() {
        RowType type =
                RowType.of(
                        new LogicalType[] {
                            VarCharType.STRING_TYPE, new IntType(), new DecimalType(10, 2)
                        },
                        new String[] {"name", "id", "amount"});
        Row value = Row.of("bob", 7, new BigDecimal("12.30"));

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(GenericRowData.class);
        GenericRowData row = (GenericRowData) result;
        assertThat(row.getArity()).isEqualTo(3);
        assertThat((StringData) row.getField(0)).isEqualTo(StringData.fromString("bob"));
        assertThat(row.getField(1)).isEqualTo(7);
        assertThat((DecimalData) row.getField(2)).isEqualTo(DecimalData.fromBigDecimal(new BigDecimal("12.30"), 10, 2));
    }

    @Test
    void rowConversionKeepsNullFields() {
        RowType type = RowType.of(VarCharType.STRING_TYPE, new IntType());
        Row value = Row.of((Object) null, null);

        GenericRowData row = (GenericRowData) toInternal(value, type);

        assertThat(row.getArity()).isEqualTo(2);
        assertThat(row.getField(0)).isNull();
        assertThat(row.getField(1)).isNull();
    }

    @Test
    void rowConversionKeepsRowKind() {
        RowType type = RowType.of(VarCharType.STRING_TYPE);
        Row value = Row.ofKind(RowKind.UPDATE_BEFORE, "old");

        GenericRowData row = (GenericRowData) toInternal(value, type);

        assertThat(row.getRowKind()).isEqualTo(RowKind.UPDATE_BEFORE);
        assertThat((StringData) row.getField(0)).isEqualTo(StringData.fromString("old"));
    }

    @Test
    void rowFieldsWithoutMatchingLogicalTypeArePassedThroughUnchanged() {
        RowType type = RowType.of(VarCharType.STRING_TYPE, new IntType());
        BigDecimal extra = new BigDecimal("3.14");
        Row value = Row.of("a", 1, extra);

        GenericRowData row = (GenericRowData) toInternal(value, type);

        assertThat(row.getArity()).isEqualTo(3);
        assertThat((StringData) row.getField(0)).isEqualTo(StringData.fromString("a"));
        assertThat(row.getField(1)).isEqualTo(1);
        assertThat(row.getField(2)).isSameAs(extra);
    }

    @Test
    void genericRowDataIsPassedThroughUnchangedForStructuredType() {
        GenericRowData value = GenericRowData.of("bob", 42);

        assertThat(toInternal(value, structuredType())).isSameAs(value);
    }

    @Test
    void unsupportedRowValueIsPassedThroughUnchanged() {
        String value = "not-a-row";

        assertThat(toInternal(value, RowType.of(VarCharType.STRING_TYPE))).isSameAs(value);
        assertThat(toInternal(value, structuredType())).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // ARRAY
    // ------------------------------------------------------------------------------------------

    @Test
    void genericArrayDataIsPassedThroughUnchanged() {
        GenericArrayData value = new GenericArrayData(new Object[] {1, 2});

        assertThat(toInternal(value, new ArrayType(new IntType()))).isSameAs(value);
    }

    @Test
    void objectArrayIsConvertedToGenericArrayData() {
        ArrayType type = new ArrayType(VarCharType.STRING_TYPE);

        Object result = toInternal(new Object[] {"a", "bc"}, type);

        assertThat(result).isInstanceOf(GenericArrayData.class);
        GenericArrayData array = (GenericArrayData) result;
        assertThat(array.size()).isEqualTo(2);
        assertThat(array.getString(0)).isEqualTo(StringData.fromString("a"));
        assertThat(array.getString(1)).isEqualTo(StringData.fromString("bc"));
    }

    @Test
    void emptyObjectArrayIsConvertedToEmptyGenericArrayData() {
        Object result = toInternal(new Object[0], new ArrayType(new IntType()));

        assertThat(result).isInstanceOf(GenericArrayData.class);
        assertThat(((GenericArrayData) result).size()).isEqualTo(0);
    }

    @Test
    void iterableIsConvertedToGenericArrayData() {
        List<Object> value = Arrays.asList(3, 1, 2);

        Object result = toInternal(value, new ArrayType(new IntType()));

        assertThat(result).isInstanceOf(GenericArrayData.class);
        GenericArrayData array = (GenericArrayData) result;
        assertThat(array.size()).isEqualTo(3);
        assertThat(array.getInt(0)).isEqualTo(3);
        assertThat(array.getInt(1)).isEqualTo(1);
        assertThat(array.getInt(2)).isEqualTo(2);
    }

    @Test
    void emptyIterableIsConvertedToEmptyGenericArrayData() {
        Object result =
                toInternal(Collections.emptyList(), new ArrayType(VarCharType.STRING_TYPE));

        assertThat(result).isInstanceOf(GenericArrayData.class);
        assertThat(((GenericArrayData) result).size()).isEqualTo(0);
    }

    @Test
    void nestedArrayElementsAreConvertedRecursively() {
        ArrayType type = new ArrayType(new ArrayType(new IntType()));

        Object result = toInternal(new Object[] {new Integer[] {1, 2}, new Integer[] {3}}, type);

        assertThat(result).isInstanceOf(GenericArrayData.class);
        GenericArrayData outer = (GenericArrayData) result;
        assertThat(outer.size()).isEqualTo(2);
        GenericArrayData first = (GenericArrayData) outer.get(0);
        GenericArrayData second = (GenericArrayData) outer.get(1);
        assertThat(first.size()).isEqualTo(2);
        assertThat(first.getInt(1)).isEqualTo(2);
        assertThat(second.size()).isEqualTo(1);
        assertThat(second.getInt(0)).isEqualTo(3);
    }

    @Test
    void arrayElementsMayBeNull() {
        ArrayType type = new ArrayType(VarCharType.STRING_TYPE);

        GenericArrayData array = (GenericArrayData) toInternal(new Object[] {"a", null}, type);

        assertThat(array.size()).isEqualTo(2);
        assertThat(array.isNullAt(1)).isTrue();
    }

    @Test
    void unsupportedArrayValueIsPassedThroughUnchanged() {
        String value = "not-an-array";

        assertThat(toInternal(value, new ArrayType(VarCharType.STRING_TYPE))).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // MAP
    // ------------------------------------------------------------------------------------------

    @Test
    void genericMapDataIsPassedThroughUnchanged() {
        GenericMapData value = new GenericMapData(new LinkedHashMap<>());

        assertThat(toInternal(value, new MapType(VarCharType.STRING_TYPE, new IntType())))
                .isSameAs(value);
    }

    @Test
    void mapIsConvertedToGenericMapDataWithConvertedKeysAndValues() {
        MapType type = new MapType(VarCharType.STRING_TYPE, new IntType());
        Map<String, Integer> value = new LinkedHashMap<>();
        value.put("a", 1);
        value.put("b", 2);

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(GenericMapData.class);
        GenericMapData map = (GenericMapData) result;
        assertThat(map.size()).isEqualTo(2);
        assertThat(map.get(StringData.fromString("a"))).isEqualTo(1);
        assertThat(map.get(StringData.fromString("b"))).isEqualTo(2);
        assertThat(map.keyArray().toObjectArray())
                .containsExactly(StringData.fromString("a"), StringData.fromString("b"));
    }

    @Test
    void emptyMapIsConvertedToEmptyGenericMapData() {
        Object result =
                toInternal(
                        new LinkedHashMap<>(),
                        new MapType(VarCharType.STRING_TYPE, VarCharType.STRING_TYPE));

        assertThat(result).isInstanceOf(GenericMapData.class);
        assertThat(((GenericMapData) result).size()).isEqualTo(0);
    }

    @Test
    void iterableOfMapEntriesIsConvertedToGenericMapData() {
        MapType type = new MapType(VarCharType.STRING_TYPE, new IntType());
        List<Map.Entry<String, Integer>> value = new ArrayList<>();
        value.add(new AbstractMap.SimpleEntry<>("x", 10));
        value.add(new AbstractMap.SimpleEntry<>("y", 20));

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(GenericMapData.class);
        GenericMapData map = (GenericMapData) result;
        assertThat(map.size()).isEqualTo(2);
        assertThat(map.get(StringData.fromString("x"))).isEqualTo(10);
        assertThat(map.get(StringData.fromString("y"))).isEqualTo(20);
    }

    @Test
    void iterableWithoutMapEntriesIsRejected() {
        MapType type = new MapType(VarCharType.STRING_TYPE, new IntType());
        List<String> value = Arrays.asList("a", "b");

        assertThatThrownBy(() -> toInternal(value, type))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("Map conversion supports only Iterable<Map.Entry>")
                .hasMessageContaining(ArrayList.class.getName());
    }

    @Test
    void unsupportedMapValueIsPassedThroughUnchanged() {
        String value = "not-a-map";

        assertThat(toInternal(value, new MapType(VarCharType.STRING_TYPE, new IntType())))
                .isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // MULTISET
    // ------------------------------------------------------------------------------------------

    @Test
    void mapIsConvertedToGenericMapDataForMultiset() {
        MultisetType type = new MultisetType(VarCharType.STRING_TYPE);
        Map<String, Integer> value = new LinkedHashMap<>();
        value.put("a", 3);

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(GenericMapData.class);
        GenericMapData map = (GenericMapData) result;
        assertThat(map.size()).isEqualTo(1);
        assertThat(map.get(StringData.fromString("a"))).isEqualTo(3);
    }

    @Test
    void iterableOfMapEntriesIsConvertedToGenericMapDataForMultiset() {
        MultisetType type = new MultisetType(new IntType());
        List<Map.Entry<Integer, Integer>> value =
                Collections.singletonList(new AbstractMap.SimpleEntry<>(5, 2));

        Object result = toInternal(value, type);

        assertThat(result).isInstanceOf(GenericMapData.class);
        GenericMapData map = (GenericMapData) result;
        assertThat(map.size()).isEqualTo(1);
        assertThat(map.get(5)).isEqualTo(2);
    }

    @Test
    void genericMapDataIsPassedThroughUnchangedForMultiset() {
        GenericMapData value = new GenericMapData(new LinkedHashMap<>());

        assertThat(toInternal(value, new MultisetType(new IntType()))).isSameAs(value);
    }

    @Test
    void unsupportedMultisetValueIsPassedThroughUnchanged() {
        String value = "not-a-multiset";

        assertThat(toInternal(value, new MultisetType(VarCharType.STRING_TYPE))).isSameAs(value);
    }

    // ------------------------------------------------------------------------------------------
    // unsupported type roots
    // ------------------------------------------------------------------------------------------

    @Test
    void unsupportedTypeRootIsRejectedForVariantType() {
        Object value = new Object();

        assertThatThrownBy(() -> toInternal(value, new VariantType()))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining(Object.class.getName())
                .hasMessageContaining("VARIANT");
    }

    @Test
    void unsupportedTypeRootIsRejectedForUuidType() {
        assertThatThrownBy(() -> toInternal("123e4567-e89b-12d3-a456-426614174000", new UuidType()))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining(String.class.getName())
                .hasMessageContaining("UUID");
    }
}
