import org.apache.calcite.plan.*;
import org.apache.calcite.rel.*;
import org.apache.calcite.rel.core.*;
import org.apache.calcite.rel.logical.*;
import org.apache.calcite.rex.*;
import org.apache.calcite.sql.type.*;
import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.rel.type.*;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableSet;

public class SetupExperiment2 {
  static RelDataType row(RelDataTypeFactory tf, String... names) {
    RelDataTypeFactory.Builder b = tf.builder();
    for (String n : names) b.add(n, SqlTypeName.INTEGER);
    return b.build();
  }
  public static void main(String[] args) {
    RelDataTypeFactory tf = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    RexBuilder rb = new RexBuilder(tf);
    VolcanoPlanner planner = new VolcanoPlanner();
    RelOptCluster cluster = RelOptCluster.create(planner, rb);
    RelNode x = LogicalValues.create(cluster, row(tf, "x0"), ImmutableList.of());
    RelNode y = LogicalValues.create(cluster, row(tf, "y0", "y1"), ImmutableList.of());
    RelNode z = LogicalValues.create(cluster, row(tf, "z0"), ImmutableList.of());
    RexNode condXY = rb.makeCall(SqlStdOperatorTable.EQUALS,
      rb.makeInputRef(x.getRowType().getFieldList().get(0).getType(), 0),
      rb.makeInputRef(y.getRowType().getFieldList().get(0).getType(), 1));
    LogicalJoin inner = LogicalJoin.create(x, y, ImmutableList.of(), condXY, ImmutableSet.of(), JoinRelType.INNER);
    System.out.println("inner type=" + inner.getRowType() + " cond=" + inner.getCondition());
    RexNode condXZ = rb.makeCall(SqlStdOperatorTable.EQUALS,
      rb.makeInputRef(x.getRowType().getFieldList().get(0).getType(), 0),
      rb.makeInputRef(z.getRowType().getFieldList().get(0).getType(), 3));
    LogicalJoin semi = LogicalJoin.create(inner, z, ImmutableList.of(), condXZ, ImmutableSet.of(), JoinRelType.SEMI);
    System.out.println("semi type=" + semi.getRowType() + " cond=" + semi.getCondition());
    System.out.println("plan=" + semi.explain());
  }
