import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link FlinkSemiAntiJoinJoinTransposeRule#onMatch(RelOptRuleCall)}. */
class FlinkSemiAntiJoinJoinTransposeRuleOnMatchTests {

    private final RelDataTypeFactory typeFactory =
            new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    private final RexBuilder rexBuilder = new RexBuilder(typeFactory);
    private final RelOptCluster cluster =
            RelOptCluster.create(new VolcanoPlanner(), rexBuilder);

    @Test
    void testOuterJoinThatIsNotSemiOrAntiIsIgnored() {
        Fixture fixture = fixture(JoinRelType.INNER, JoinRelType.INNER, trueLiteral());

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiOrAntiJoinOverSemiOrAntiJoinIsIgnored() {
        for (JoinRelType outerJoinType :
                new JoinRelType[] {JoinRelType.SEMI, JoinRelType.ANTI}) {
            for (JoinRelType innerJoinType :
                    new JoinRelType[] {JoinRelType.SEMI, JoinRelType.ANTI}) {
                Fixture fixture = fixture(outerJoinType, innerJoinType, trueLiteral());

                CapturingRuleCall call = invoke(fixture);

                assertTrue(
                        call.getTransformedNodes().isEmpty(),
                        () ->
                                "Expected no transformation for "
                                        + outerJoinType
                                        + " over "
                                        + innerJoinType);
            }
        }
    }

    @Test
    void testSemiJoinOverNonInnerJoinIsIgnored() {
        for (JoinRelType innerJoinType :
                new JoinRelType[] {
                    JoinRelType.LEFT, JoinRelType.RIGHT, JoinRelType.FULL
                }) {
            Fixture fixture =
                    fixture(
                            JoinRelType.SEMI,
                            innerJoinType,
                            and(equals(0, 4), equals(1, 5)));

            CapturingRuleCall call = invoke(fixture);

            assertTrue(
                    call.getTransformedNodes().isEmpty(),
                    () -> "Expected no transformation for inner join type " + innerJoinType);
        }
    }

    @Test
    void testSemiJoinWithoutConditionInputsIsIgnored() {
        Fixture fixture = fixture(JoinRelType.SEMI, JoinRelType.INNER, trueLiteral());

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWithoutLeftConditionInputsIsIgnored() {
        // The semi-join condition references only Z, which represents the uncorrelated
        // (NOT) EXISTS case that this rule intentionally leaves alone.
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(4, 5), equals(4, 5)));

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWithoutRightConditionInputsIsIgnored() {
        // The semi-join condition references only Y and therefore cannot be pushed to either
        // side of the input join.
        Fixture fixture =
                fixture(JoinRelType.SEMI, JoinRelType.INNER, equals(2, 3));

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWhoseKeysSpanBothJoinInputsIsIgnored() {
        // One key comes from X and one from Y. The rule supports keys from only one input.
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(0, 4), equals(2, 5)));

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWithKeysFromLeftInputIsTransposedToLeft() {
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(0, 4), equals(1, 5)));

        CapturingRuleCall call = invoke(fixture);

        RelNode transformed = call.getOnlyTransformedNode();
        assertTrue(transformed instanceof LogicalJoin);

        LogicalJoin newTopJoin = (LogicalJoin) transformed;
        assertEquals(JoinRelType.INNER, newTopJoin.getJoinType());
        assertEquals(fixture.innerJoin.getCondition(), newTopJoin.getCondition());
        assertSame(fixture.y, newTopJoin.getInput(1));

        assertTrue(newTopJoin.getInput(0) instanceof LogicalJoin);
        LogicalJoin newSemiJoin = (LogicalJoin) newTopJoin.getInput(0);
        assertEquals(JoinRelType.SEMI, newSemiJoin.getJoinType());
        assertSame(fixture.x, newSemiJoin.getInput(0));
        assertSame(fixture.z, newSemiJoin.getInput(1));

        assertEquals(
                ImmutableBitSet.of(0, 1, 2, 3),
                RelOptUtil.InputFinder.bits(newSemiJoin.getCondition()));
        assertEquals(
                Arrays.asList(Arrays.asList(0, 2), Arrays.asList(1, 3)),
                equalityIndexPairs(newSemiJoin.getCondition()));
        assertEquals(
                Arrays.asList("x0", "x1", "z0", "z1", "y0", "y1"),
                newTopJoin.getRowType().getFieldNames());
    }

    @Test
    void testAntiJoinWithKeysFromLeftInputIsTransposedToLeft() {
        Fixture fixture =
                fixture(
                        JoinRelType.ANTI,
                        JoinRelType.INNER,
                        and(equals(0, 4), equals(1, 5)));

        CapturingRuleCall call = invoke(fixture);

        LogicalJoin newTopJoin = (LogicalJoin) call.getOnlyTransformedNode();
        LogicalJoin newAntiJoin = (LogicalJoin) newTopJoin.getInput(0);

        assertEquals(JoinRelType.INNER, newTopJoin.getJoinType());
        assertEquals(JoinRelType.ANTI, newAntiJoin.getJoinType());
        assertSame(fixture.x, newAntiJoin.getInput(0));
        assertSame(fixture.z, newAntiJoin.getInput(1));
        assertSame(fixture.y, newTopJoin.getInput(1));
        assertEquals(
                Arrays.asList(Arrays.asList(0, 2), Arrays.asList(1, 3)),
                equalityIndexPairs(newAntiJoin.getCondition()));
    }

    @Test
    void testSemiJoinWithKeysFromRightInputIsTransposedToRight() {
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(2, 4), equals(3, 5)));

        CapturingRuleCall call = invoke(fixture);

        RelNode transformed = call.getOnlyTransformedNode();
        LogicalJoin newTopJoin = (LogicalJoin) transformed;

        assertEquals(JoinRelType.INNER, newTopJoin.getJoinType());
        assertEquals(fixture.innerJoin.getCondition(), newTopJoin.getCondition());
        assertSame(fixture.x, newTopJoin.getInput(0));

        assertTrue(newTopJoin.getInput(1) instanceof LogicalJoin);
        LogicalJoin newSemiJoin = (LogicalJoin) newTopJoin.getInput(1);
        assertEquals(JoinRelType.SEMI, newSemiJoin.getJoinType());
        assertSame(fixture.y, newSemiJoin.getInput(0));
        assertSame(fixture.z, newSemiJoin.getInput(1));

        assertEquals(
                ImmutableBitSet.of(0, 1, 2, 3),
                RelOptUtil.InputFinder.bits(newSemiJoin.getCondition()));
        assertEquals(
                Arrays.asList(Arrays.asList(0, 2), Arrays.asList(1, 3)),
                equalityIndexPairs(newSemiJoin.getCondition()));
        assertEquals(
                Arrays.asList("x0", "x1", "y0", "y1"),
                newTopJoin.getRowType().getFieldNames());
    }

    @Test
    void testAntiJoinWithKeysFromRightInputIsTransposedToRight() {
        Fixture fixture =
                fixture(
                        JoinRelType.ANTI,
                        JoinRelType.INNER,
                        and(equals(2, 4), equals(3, 5)));

        CapturingRuleCall call = invoke(fixture);

        LogicalJoin newTopJoin = (LogicalJoin) call.getOnlyTransformedNode();
        LogicalJoin newAntiJoin = (LogicalJoin) newTopJoin.getInput(1);

        assertEquals(JoinRelType.INNER, newTopJoin.getJoinType());
        assertEquals(JoinRelType.ANTI, newAntiJoin.getJoinType());
        assertSame(fixture.x, newTopJoin.getInput(0));
        assertSame(fixture.y, newAntiJoin.getInput(0));
        assertSame(fixture.z, newAntiJoin.getInput(1));
        assertEquals(
                Arrays.asList(Arrays.asList(0, 2), Arrays.asList(1, 3)),
                equalityIndexPairs(newAntiJoin.getCondition()));
    }

    private CapturingRuleCall invoke(Fixture fixture) {
        CapturingRuleCall call =
                new CapturingRuleCall(fixture.semiAntiJoin, fixture.innerJoin);
        FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.onMatch(call);
        return call;
    }

    private Fixture fixture(
            JoinRelType semiAntiJoinType,
            JoinRelType innerJoinType,
            RexNode semiAntiJoinCondition) {
        RelNode x = values("x0", "x1");
        RelNode y = values("y0", "y1");
        RelNode z = values("z0", "z1");
        LogicalJoin innerJoin = join(x, y, equals(0, 2), innerJoinType);
        LogicalJoin semiAntiJoin =
                join(innerJoin, z, semiAntiJoinCondition, semiAntiJoinType);
        return new Fixture(x, y, z, innerJoin, semiAntiJoin);
    }

    private RelNode values(String... fieldNames) {
        RelDataTypeFactory.Builder rowTypeBuilder = typeFactory.builder();
        for (String fieldName : fieldNames) {
            rowTypeBuilder.add(fieldName, SqlTypeName.INTEGER);
        }
        RelDataType rowType = rowTypeBuilder.build();
        return LogicalValues.create(cluster, rowType, ImmutableList.of());
    }

    private LogicalJoin join(
            RelNode left, RelNode right, RexNode condition, JoinRelType joinType) {
        return LogicalJoin.create(
                left, right, ImmutableList.of(), condition, ImmutableSet.of(), joinType);
    }

    private RexNode equals(int leftIndex, int rightIndex) {
        return rexBuilder.makeCall(
                SqlStdOperatorTable.EQUALS, inputRef(leftIndex), inputRef(rightIndex));
    }

    private RexNode and(RexNode... conditions) {
        return rexBuilder.makeCall(SqlStdOperatorTable.AND, conditions);
    }

    private RexNode trueLiteral() {
        return rexBuilder.makeLiteral(true);
    }

    private RexInputRef inputRef(int index) {
        return rexBuilder.makeInputRef(
                typeFactory.createSqlType(SqlTypeName.INTEGER), index);
    }

    private static List<List<Integer>> equalityIndexPairs(RexNode condition) {
        List<List<Integer>> pairs = new ArrayList<>();
        collectEqualityIndexPairs(condition, pairs);
        return pairs;
    }

    private static void collectEqualityIndexPairs(
            RexNode condition, List<List<Integer>> pairs) {
        assertTrue(condition instanceof RexCall, "Expected a RexCall but got " + condition);
        RexCall call = (RexCall) condition;
        if (call.getOperator() == SqlStdOperatorTable.AND) {
            for (RexNode operand : call.getOperands()) {
                collectEqualityIndexPairs(operand, pairs);
            }
        } else {
            assertEquals(SqlStdOperatorTable.EQUALS, call.getOperator());
            pairs.add(
                    Arrays.asList(
                            inputRefIndex(call.getOperands().get(0)),
                            inputRefIndex(call.getOperands().get(1))));
        }
    }

    private static int inputRefIndex(RexNode node) {
        assertTrue(node instanceof RexInputRef, "Expected an input reference but got " + node);
        return ((RexInputRef) node).getIndex();
    }

    private static final class Fixture {
        private final RelNode x;
        private final RelNode y;
        private final RelNode z;
        private final LogicalJoin innerJoin;
        private final LogicalJoin semiAntiJoin;

        private Fixture(
                RelNode x,
                RelNode y,
                RelNode z,
                LogicalJoin innerJoin,
                LogicalJoin semiAntiJoin) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.innerJoin = innerJoin;
            this.semiAntiJoin = semiAntiJoin;
        }
    }

    private static final class CapturingRuleCall extends RelOptRuleCall {
        private final List<RelNode> transformedNodes = new ArrayList<>();

        private CapturingRuleCall(RelNode semiAntiJoin, RelNode innerJoin) {
            super(
                    null,
                    FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.getOperand(),
                    new RelNode[] {semiAntiJoin, innerJoin},
                    ImmutableMap.of());
        }

        @Override
        public void transformTo(RelNode rel, Map<RelNode, RelNode> equiv) {
            transformedNodes.add(rel);
        }

        @Override
        public void transformTo(
                RelNode rel, Map<RelNode, RelNode> equiv, RelHintsPropagator hints) {
            transformedNodes.add(rel);
        }

        private List<RelNode> getTransformedNodes() {
            return transformedNodes;
        }

        private RelNode getOnlyTransformedNode() {
            assertEquals(1, transformedNodes.size());
            return transformedNodes.get(0);
        }
    }
}
