/** Tests for {@link FlinkSemiAntiJoinJoinTransposeRule#onMatch(RelOptRuleCall)}. */
class FlinkSemiAntiJoinJoinTransposeRuleOnMatchTests {

    private final RelDataTypeFactory typeFactory =
            new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    private final RexBuilder rexBuilder = new RexBuilder(typeFactory);
    private final RelOptCluster cluster =
            RelOptCluster.create(new VolcanoPlanner(), rexBuilder);

    @Test
    void testOuterJoinThatIsNotSemiOrAntiIsIgnored() {
        Fixture fixture = fixture(JoinRelType.INNER, JoinRelType.INNER, trueLiteral());

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiOrAntiJoinOverSemiOrAntiJoinIsIgnored() {
        for (JoinRelType outerJoinType :
                new JoinRelType[] {JoinRelType.SEMI, JoinRelType.ANTI}) {
            for (JoinRelType innerJoinType :
                    new JoinRelType[] {JoinRelType.SEMI, JoinRelType.ANTI}) {
                Fixture fixture = fixture(outerJoinType, innerJoinType, trueLiteral());

                CapturingRuleCall call = invoke(fixture);

                assertTrue(
                        call.getTransformedNodes().isEmpty(),
                        () ->
                                "Expected no transformation for "
                                        + outerJoinType
                                        + " over "
                                        + innerJoinType);
            }
        }
    }

    @Test
    void testSemiJoinOverNonInnerJoinIsIgnored() {
        for (JoinRelType innerJoinType :
                new JoinRelType[] {
                    JoinRelType.LEFT, JoinRelType.RIGHT, JoinRelType.FULL
                }) {
            Fixture fixture =
                    fixture(
                            JoinRelType.SEMI,
                            innerJoinType,
                            and(equals(0, 4), equals(1, 5)));

            CapturingRuleCall call = invoke(fixture);

            assertTrue(
                    call.getTransformedNodes().isEmpty(),
                    () -> "Expected no transformation for inner join type " + innerJoinType);
        }
    }

    @Test
    void testSemiJoinWithoutConditionInputsIsIgnored() {
        Fixture fixture = fixture(JoinRelType.SEMI, JoinRelType.INNER, trueLiteral());

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWithoutLeftConditionInputsIsIgnored() {
        // The semi-join condition references only Z, which represents the uncorrelated
        // (NOT) EXISTS case that this rule intentionally leaves alone.
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(4, 5), equals(4, 5)));

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWithoutRightConditionInputsIsIgnored() {
        // The semi-join condition references only Y and therefore cannot be pushed to either
        // side of the input join.
        Fixture fixture =
                fixture(JoinRelType.SEMI, JoinRelType.INNER, equals(2, 3));

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWhoseKeysSpanBothJoinInputsIsIgnored() {
        // One key comes from X and one from Y. The rule supports keys from only one input.
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(0, 4), equals(2, 5)));

        CapturingRuleCall call = invoke(fixture);

        assertTrue(call.getTransformedNodes().isEmpty());
    }

    @Test
    void testSemiJoinWithKeysFromLeftInputIsTransposedToLeft() {
        Fixture fixture =
                fixture(
                        JoinRelType.SEMI,
                        JoinRelType.INNER,
                        and(equals(0, 4), equals(1, 5)));

        CapturingRuleCall call = invoke(fixture);

        RelNode transformed = call.getOnlyTransformedNode();
        assertTrue(transformed instanceof LogicalJoin);

        LogicalJoin newTopJoin = (LogicalJoin) transformed;
        assertEquals(JoinRelType.INNER, newTopJoin.getJoinType());
        assertEquals(fixture.innerJoin.getCondition(), newTopJoin.getCondition());
        assertSame(fixture.y, newTopJoin.getInput(1));

        assertTrue(newTopJoin.getInput(0) instanceof LogicalJoin);
        LogicalJoin newSemiJoin = (LogicalJoin) newTopJoin.getInput(0);
