        LogicalJoin newAntiJoin = (LogicalJoin) newTopJoin.getInput(1);

        assertEquals(JoinRelType.INNER, newTopJoin.getJoinType());
        assertEquals(JoinRelType.ANTI, newAntiJoin.getJoinType());
        assertSame(fixture.x, newTopJoin.getInput(0));
        assertSame(fixture.y, newAntiJoin.getInput(0));
        assertSame(fixture.z, newAntiJoin.getInput(1));
        assertEquals(
                Arrays.asList(Arrays.asList(0, 2), Arrays.asList(1, 3)),
                equalityIndexPairs(newAntiJoin.getCondition()));
    }

    private CapturingRuleCall invoke(Fixture fixture) {
        CapturingRuleCall call = new CapturingRuleCall(fixture.semiAntiJoin, fixture.innerJoin);
        FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.onMatch(call);
        return call;
    }

    private Fixture fixture(
            JoinRelType semiAntiJoinType,
            JoinRelType innerJoinType,
            RexNode semiAntiJoinCondition) {
        RelNode x = values("x0", "x1");
        RelNode y = values("y0", "y1");
        RelNode z = values("z0", "z1");
        LogicalJoin innerJoin = join(x, y, equals(0, 2), innerJoinType);
        LogicalJoin semiAntiJoin = join(innerJoin, z, semiAntiJoinCondition, semiAntiJoinType);
        return new Fixture(x, y, z, innerJoin, semiAntiJoin);
    }

    private RelNode values(String... fieldNames) {
        RelDataTypeFactory.Builder rowTypeBuilder = typeFactory.builder();
        for (String fieldName : fieldNames) {
            rowTypeBuilder.add(fieldName, SqlTypeName.INTEGER);
        }
        RelDataType rowType = rowTypeBuilder.build();
        return LogicalValues.createEmpty(cluster, rowType);
    }

    private LogicalJoin join(RelNode left, RelNode right, RexNode condition, JoinRelType joinType) {
        return LogicalJoin.create(
                left,
                right,
                new ArrayList<RelHint>(),
                condition,
                new HashSet<CorrelationId>(),
                joinType);
    }

    private RexNode equals(int leftIndex, int rightIndex) {
        return rexBuilder.makeCall(
                SqlStdOperatorTable.EQUALS, inputRef(leftIndex), inputRef(rightIndex));
    }

    private RexNode and(RexNode... conditions) {
        return rexBuilder.makeCall(SqlStdOperatorTable.AND, conditions);
    }

    private RexNode trueLiteral() {
        return rexBuilder.makeLiteral(true);
    }

    private RexInputRef inputRef(int index) {
        return rexBuilder.makeInputRef(typeFactory.createSqlType(SqlTypeName.INTEGER), index);
    }

    private static List<List<Integer>> equalityIndexPairs(RexNode condition) {
        List<List<Integer>> pairs = new ArrayList<>();
        collectEqualityIndexPairs(condition, pairs);
        return pairs;
    }

    private static void collectEqualityIndexPairs(RexNode condition, List<List<Integer>> pairs) {
        assertTrue(condition instanceof RexCall, "Expected a RexCall but got " + condition);
        RexCall call = (RexCall) condition;
        if (call.getOperator() == SqlStdOperatorTable.AND) {
            for (RexNode operand : call.getOperands()) {
                collectEqualityIndexPairs(operand, pairs);
            }
        } else {
            assertEquals(SqlStdOperatorTable.EQUALS, call.getOperator());
            pairs.add(
                    Arrays.asList(
                            inputRefIndex(call.getOperands().get(0)),
                            inputRefIndex(call.getOperands().get(1))));
        }
    }

    private static int inputRefIndex(RexNode node) {
        assertTrue(node instanceof RexInputRef, "Expected an input reference but got " + node);
        return ((RexInputRef) node).getIndex();
    }

    private static final class Fixture {
        private final RelNode x;
        private final RelNode y;
        private final RelNode z;
        private final LogicalJoin innerJoin;
        private final LogicalJoin semiAntiJoin;

        private Fixture(
                RelNode x, RelNode y, RelNode z, LogicalJoin innerJoin, LogicalJoin semiAntiJoin) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.innerJoin = innerJoin;
            this.semiAntiJoin = semiAntiJoin;
        }
    }

    private static final class CapturingRuleCall extends RelOptRuleCall {
        private final List<RelNode> transformedNodes = new ArrayList<>();

        private CapturingRuleCall(RelNode semiAntiJoin, RelNode innerJoin) {
            super(
                    null,
                    FlinkSemiAntiJoinJoinTransposeRule.INSTANCE.getOperand(),
                    new RelNode[] {semiAntiJoin, innerJoin},
                    new java.util.HashMap<RelNode, List<RelNode>>());
        }

        @Override
        public void transformTo(RelNode rel, Map<RelNode, RelNode> equiv) {
            transformedNodes.add(rel);
        }

        @Override
        public void transformTo(
                RelNode rel, Map<RelNode, RelNode> equiv, RelHintsPropagator hints) {
            transformedNodes.add(rel);
        }

        private List<RelNode> getTransformedNodes() {
            return transformedNodes;
        }

        private RelNode getOnlyTransformedNode() {
            assertEquals(1, transformedNodes.size());
            return transformedNodes.get(0);
        }
    }
