        Class<?> decorrelatorClass =
                Class.forName(
                        "org.apache.flink.table.planner.plan.rules.logical.SubQueryDecorrelator$SubQueryRelDecorrelator");
        Constructor<?> constructor =
                decorrelatorClass.getDeclaredConstructor(
