    @Test
    void testAggregateOverValuesRewritesGroupKeysAndAggregateCalls() throws Exception {
        RelBuilder relBuilder = newRelBuilder();
        RelOptCluster cluster = relBuilder.getCluster();
        RelDataType inputType = intRowType(cluster.getTypeFactory(), "a");
        RelNode values = LogicalValues.createEmpty(cluster, inputType);
        LogicalAggregate aggregate =
                aggregate(
                        values,
                        ImmutableBitSet.of(0),
                        count(cluster.getTypeFactory()));

        Object decorrelator = newDecorrelator(relBuilder, null);
        Object frame = invokeDecorrelate(decorrelator, aggregate);

        assertNotNull(frame);
        RelNode result = frameRel(frame);
        LogicalAggregate rewritten = assertInstanceOf(LogicalAggregate.class, result);
        assertEquals(2, result.getRowType().getFieldCount());
        assertEquals(ImmutableBitSet.of(0), rewritten.getGroupSet());
        assertEquals(1, rewritten.getAggCallList().size());
        assertTrue(rewritten.getAggCallList().get(0).getArgList().isEmpty());
        assertEquals(Map.of(0, 0, 1, 1), frameMapping(frame));
        assertNull(frameCondition(frame));

        LogicalProject project = assertInstanceOf(LogicalProject.class, rewritten.getInput());
        assertEquals(1, project.getProjects().size());
        assertInputRef(project.getProjects().get(0), 0);
    }

    @Test
    void testAggregatePreservesArgumentAndFilterMappings() throws Exception {
        RelBuilder relBuilder = newRelBuilder();
        RelOptCluster cluster = relBuilder.getCluster();
        RelDataTypeFactory typeFactory = cluster.getTypeFactory();
        RelDataType inputType =
                typeFactory
                        .builder()
                        .add("a", SqlTypeName.INTEGER)
                        .add("predicate", SqlTypeName.BOOLEAN)
                        .build();
        RelNode values = LogicalValues.createEmpty(cluster, inputType);
        AggregateCall filteredSum =
                AggregateCall.create(
                        SqlStdOperatorTable.SUM,
                        false,
                        false,
                        List.of(0),
                        1,
                        typeFactory.createSqlType(SqlTypeName.INTEGER),
                        "total");
        LogicalAggregate aggregate =
                aggregate(values, ImmutableBitSet.of(0), filteredSum);

        Object frame =
                invokeDecorrelate(newDecorrelator(relBuilder, null), aggregate);

        assertNotNull(frame);
        LogicalAggregate rewritten = assertInstanceOf(LogicalAggregate.class, frameRel(frame));
        AggregateCall rewrittenCall = rewritten.getAggCallList().get(0);
        assertEquals(ImmutableBitSet.of(0), rewritten.getGroupSet());
        assertEquals(List.of(0), rewrittenCall.getArgList());
        assertEquals(1, rewrittenCall.filterArg);
        assertEquals(Map.of(0, 0, 1, 1), frameMapping(frame));
        assertNull(frameCondition(frame));
    }

    @Test
    void testAggregateOmitsConstantGroupKeyAndRestoresItAfterAggregateOutputs()
            throws Exception {
        RelBuilder relBuilder = newRelBuilder();
        RelOptCluster cluster = relBuilder.getCluster();
        RelDataTypeFactory typeFactory = cluster.getTypeFactory();
        RelDataType valuesType = intRowType(typeFactory, "a");
        RelNode values = LogicalValues.createEmpty(cluster, valuesType);
        RexLiteral constant = cluster.getRexBuilder().makeLiteral(true);
        LogicalProject inputProject =
                LogicalProject.create(
                        values,
                        Collections.emptyList(),
                        List.of(constant, RexInputRef.of(0, valuesType)),
                        List.of("flag", "a"));
        LogicalAggregate aggregate =
                aggregate(
                        inputProject,
                        ImmutableBitSet.of(0, 1),
                        count(typeFactory),
                        AggregateCall.create(
                                SqlStdOperatorTable.SUM,
                                false,
                                false,
                                List.of(1),
                                -1,
                                typeFactory.createSqlType(SqlTypeName.INTEGER),
                                "total"));

        Object frame =
                invokeDecorrelate(newDecorrelator(relBuilder, null), aggregate);

        assertNotNull(frame);
        RelNode result = frameRel(frame);
        LogicalProject postProject = assertInstanceOf(LogicalProject.class, result);
        assertEquals(4, result.getRowType().getFieldCount());
        assertInputRef(postProject.getProjects().get(0), 0);
        RexLiteral restoredConstant =
                assertInstanceOf(RexLiteral.class, postProject.getProjects().get(1));
        assertEquals(true, restoredConstant.getValueAs(Boolean.class));
        assertInputRef(postProject.getProjects().get(2), 1);
        assertInputRef(postProject.getProjects().get(3), 2);
        assertEquals(Map.of(0, 1, 1, 0, 2, 2, 3, 3), frameMapping(frame));
        assertNull(frameCondition(frame));

        LogicalAggregate rewritten =
                assertInstanceOf(LogicalAggregate.class, postProject.getInput());
        assertEquals(ImmutableBitSet.of(0), rewritten.getGroupSet());
        assertEquals(2, rewritten.getAggCallList().size());
        assertTrue(rewritten.getAggCallList().get(0).getArgList().isEmpty());
        assertEquals(List.of(0), rewritten.getAggCallList().get(1).getArgList());
    }

    @Test
    void testAggregateMovesCorrelatedInputFieldIntoGroupSet() throws Exception {
        RelBuilder relBuilder = newRelBuilder();
        RelOptCluster cluster = relBuilder.getCluster();
        RelDataTypeFactory typeFactory = cluster.getTypeFactory();
        RelDataType valuesType =
                typeFactory
                        .builder()
                        .add("a", SqlTypeName.INTEGER)
                        .add("b", SqlTypeName.INTEGER)
                        .build();
        RelNode values = LogicalValues.createEmpty(cluster, valuesType);
        RexNode correlatedCondition = correlatedEquals(cluster, valuesType, 1, 1);
        CorrelationId correlationId = new CorrelationId(7);
        LogicalFilter filter =
                LogicalFilter.create(
                        values,
                        correlatedCondition,
                        com.google.common.collect.ImmutableSet.of(correlationId));
