    @Test
    void testAggregateReturnsNullWhenInputCannotBeRewritten() throws Exception {
        RelBuilder relBuilder = newRelBuilder();
        RelOptCluster cluster = relBuilder.getCluster();
        RelDataTypeFactory typeFactory = cluster.getTypeFactory();
        RelDataType leftType = intRowType(typeFactory, "a");
        RelDataType rightType = intRowType(typeFactory, "b");
        RelNode leftValues = LogicalValues.createEmpty(cluster, leftType);
        RelNode rightValues = LogicalValues.createEmpty(cluster, rightType);
        CorrelationId correlationId = new CorrelationId(11);
        LogicalFilter correlatedFilter =
                LogicalFilter.create(
                        leftValues,
                        correlatedEquals(cluster, leftType, 0, 0),
                        com.google.common.collect.ImmutableSet.of(correlationId));
        LogicalCorrelate correlate =
                LogicalCorrelate.create(
                        correlatedFilter,
                        rightValues,
                        correlationId,
                        ImmutableBitSet.of(0),
                        JoinRelType.INNER);
        LogicalAggregate aggregate =
                aggregate(correlate, ImmutableBitSet.of(0), count(typeFactory));
        Map<RelNode, Set<CorrelationId>> correlationMap =
                Collections.singletonMap(
                        correlatedFilter, Collections.singleton(correlationId));

        Object frame =
                invokeDecorrelate(
                        newDecorrelator(relBuilder, correlationMap), aggregate);

        assertNull(frame);
    }

    private static LogicalAggregate aggregate(
            RelNode input, ImmutableBitSet groupSet, AggregateCall... aggregateCalls) {
        return LogicalAggregate.create(
                input, groupSet, null, List.of(aggregateCalls));
    }

    private static AggregateCall count(RelDataTypeFactory typeFactory) {
        return AggregateCall.create(
                SqlStdOperatorTable.COUNT,
                false,
                false,
                Collections.emptyList(),
                -1,
                typeFactory.createSqlType(SqlTypeName.BIGINT),
                "cnt");
    }

    private static RexNode correlatedEquals(
            RelOptCluster cluster,
            RelDataType inputType,
            int correlatedField,
            int inputField) {
        RexBuilder rexBuilder = cluster.getRexBuilder();
        CorrelationId id = new CorrelationId(3);
        RexCorrelVariable correlVariable =
                (RexCorrelVariable) rexBuilder.makeCorrel(inputType, id);
        return rexBuilder.makeCall(
                SqlStdOperatorTable.EQUALS,
                rexBuilder.makeFieldAccess(correlVariable, correlatedField),
                RexInputRef.of(inputField, inputType));
    }

    private static void assertInputRef(RexNode node, int expectedIndex) {
        RexInputRef inputRef = assertInstanceOf(RexInputRef.class, node);
        assertEquals(expectedIndex, inputRef.getIndex());
    }

    private static RelBuilder newRelBuilder() {
        RelDataTypeFactory typeFactory = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
        RelOptCluster cluster =
                RelOptCluster.create(
                        new HepPlanner(new HepProgramBuilder().build()),
                        new RexBuilder(typeFactory));
        return RelBuilder.proto(Contexts.of(RelBuilder.Config.DEFAULT)).create(cluster, null);
    }

    private static Object newDecorrelator(
            RelBuilder relBuilder, Map<RelNode, Set<CorrelationId>> corMap)
            throws Exception {
        Class<?> corelMapClass =
                Class.forName(
                        "org.apache.flink.table.planner.plan.rules.logical.SubQueryDecorrelator$CorelMap");
        Method of =
                corelMapClass.getDeclaredMethod(
                        "of",
                        com.google.common.collect.SortedSetMultimap.class,
                        SortedMap.class,
                        Map.class);
        of.setAccessible(true);
        Object corelMap =
                of.invoke(
                        null,
                        com.google.common.collect.TreeMultimap.create(),
                        new TreeMap<>(),
                        corMap == null ? new HashMap<>() : corMap);
        Class<?> decorrelatorClass =
                Class.forName(
                        "org.apache.flink.table.planner.plan.rules.logical.SubQueryDecorrelator$SubQueryRelDecorrelator");
        Constructor<?> constructor =
                decorrelatorClass.getDeclaredConstructor(
                        corelMapClass, RelBuilder.class, RexBuilder.class);
        constructor.setAccessible(true);
        return constructor.newInstance(corelMap, relBuilder, relBuilder.getRexBuilder());
    }

    private static Object invokeDecorrelate(Object decorrelator, LogicalAggregate aggregate)
            throws Exception {
        Method method = decorrelator.getClass().getMethod("decorrelateRel", LogicalAggregate.class);
        return method.invoke(decorrelator, aggregate);
    }

    private static RelNode frameRel(Object frame) throws Exception {
        Field field = frame.getClass().getDeclaredField("r");
        field.setAccessible(true);
        return (RelNode) field.get(frame);
    }

    private static RexNode frameCondition(Object frame) throws Exception {
        Field field = frame.getClass().getDeclaredField("c");
        field.setAccessible(true);
        return (RexNode) field.get(frame);
    }

    @SuppressWarnings("unchecked")
    private static Map<Integer, Integer> frameMapping(Object frame) throws Exception {
        Field field = frame.getClass().getDeclaredField("oldToNewOutputs");
        field.setAccessible(true);
        return (Map<Integer, Integer>) field.get(frame);
    }

    private static RelDataType intRowType(RelDataTypeFactory typeFactory, String name) {
        RelDataTypeFactory.Builder builder = typeFactory.builder();
        builder.add(name, SqlTypeName.INTEGER);
        return builder.build();
    }
}
