/** Tests for {@link RexLiteralUtil#toFlinkInternalValue(Comparable, LogicalType)}. */
class RexLiteralUtilToFlinkInternalValueTests {

    private enum SampleEnum {
        ALPHA,
        BETA
    }

    // ----------------------------------------------------------------------
    // Null handling
    // ----------------------------------------------------------------------

    @Test
    void testNullValueReturnsNullForSupportedType() {
        assertThat(RexLiteralUtil.toFlinkInternalValue(null, new VarCharType(10))).isNull();
        assertThat(RexLiteralUtil.toFlinkInternalValue(null, new IntType())).isNull();
        assertThat(RexLiteralUtil.toFlinkInternalValue(null, new TimestampType())).isNull();
    }

    @Test
    void testNullValueReturnsNullEvenForUnsupportedType() {
        // The null check happens before the type switch, so even unsupported types return null.
        assertThat(RexLiteralUtil.toFlinkInternalValue(null, new ArrayType(new IntType())))
                .isNull();
    }

    // ----------------------------------------------------------------------
    // Character types
    // ----------------------------------------------------------------------

    @Test
    void testNlsStringForCharType() {
        final NlsString nlsString =
                new NlsString("calcite value", "UTF-8", SqlCollation.IMPLICIT);

        final Object result =
                RexLiteralUtil.toFlinkInternalValue(nlsString, new CharType(20));

        assertThat(result).isInstanceOf(BinaryStringData.class);
        assertThat(result.toString()).isEqualTo("calcite value");
    }

    @Test
    void testStringForVarCharType() {
        final Object result =
                RexLiteralUtil.toFlinkInternalValue("flink value", new VarCharType(50));

        assertThat(result).isInstanceOf(BinaryStringData.class);
        assertThat(result).isEqualTo(BinaryStringData.fromString("flink value"));
    }

    @Test
    void testEmptyAndUnicodeStringsForVarCharType() {
        assertThat(RexLiteralUtil.toFlinkInternalValue("", new VarCharType(10)).toString())
                .isEmpty();
        assertThat(
                        RexLiteralUtil.toFlinkInternalValue("\u4f60\u597d\ud83d\ude00", new VarCharType(10))
                                .toString())
                .isEqualTo("\u4f60\u597d\ud83d\ude00");
    }

    @Test
    void testUnsupportedValueClassForCharacterType() {
        assertThatThrownBy(
                        () -> RexLiteralUtil.toFlinkInternalValue(42, new VarCharType(10)))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("Unexpected class");
    }

    // ----------------------------------------------------------------------
    // Boolean
    // ----------------------------------------------------------------------

    @Test
    void testBooleanValues() {
        assertThat(RexLiteralUtil.toFlinkInternalValue(Boolean.TRUE, new BooleanType()))
                .isEqualTo(Boolean.TRUE);
        assertThat(RexLiteralUtil.toFlinkInternalValue(Boolean.FALSE, new BooleanType()))
                .isEqualTo(Boolean.FALSE);
    }

    @Test
    void testUnsupportedValueClassForBooleanType() {
        assertThatThrownBy(
                        () -> RexLiteralUtil.toFlinkInternalValue("true", new BooleanType()))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("Unexpected class");
    }

    // ----------------------------------------------------------------------
    // Binary types
    // ----------------------------------------------------------------------

    @Test
    void testByteStringForBinaryAndVarBinaryTypes() {
        final byte[] bytes = new byte[] {0x00, 0x01, (byte) 0xFF, 0x7F};

        assertThat(
                        (byte[])
                                RexLiteralUtil.toFlinkInternalValue(
                                        new ByteString(bytes), new BinaryType(4)))
                .containsExactly(bytes);

        assertThat(
                        (byte[])
                                RexLiteralUtil.toFlinkInternalValue(
                                        new ByteString(bytes), new VarBinaryType(4)))
                .containsExactly(bytes);
    }

    @Test
    void testEmptyByteString() {
        assertThat(
                        (byte[])
                                RexLiteralUtil.toFlinkInternalValue(
                                        ByteString.EMPTY, new VarBinaryType(10)))
                .isEmpty();
    }

    @Test
    void testUnsupportedValueClassForBinaryType() {
        assertThatThrownBy(
                        () -> RexLiteralUtil.toFlinkInternalValue("bytes", new BinaryType(5)))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("Unexpected class");
    }

    // ----------------------------------------------------------------------
