    // ----------------------------------------------------------------------

    @Test
    void testUuidIsConvertedToCanonicalBigEndianBytes() {
        final UUID uuid = UUID.fromString("123e4567-e89b-12d3-a456-426614174000");

        final Object result = RexLiteralUtil.toFlinkInternalValue(uuid, new UuidType());

        assertThat(result).isInstanceOf(byte[].class);
        final byte[] bytes = (byte[]) result;
        assertThat(bytes).hasSize(16);
        // Independent expectation for the canonical big-endian representation.
        assertThat(bytes)
                .containsExactly(
                        ByteBuffer.allocate(16)
                                .order(ByteOrder.BIG_ENDIAN)
                                .putLong(uuid.getMostSignificantBits())
                                .putLong(uuid.getLeastSignificantBits())
                                .array());
        assertThat(UuidUtils.fromBytes(bytes)).isEqualTo(uuid);
    }

    @Test
