        assertThat(result).isInstanceOf(DecimalData.class);
        final DecimalData decimalData = (DecimalData) result;
        assertThat(decimalData.toBigDecimal()).isEqualTo(new BigDecimal("123.46"));
        assertThat(decimalData.toBigDecimal().scale()).isEqualTo(2);
